INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000001', 'e1000001-0000-4000-8000-000000000001', 'Tes Penempatan Bahasa Inggris (Placement Test)', 'Uji kalibrasi 15 soal adaptif dari tingkat A1 hingga B1 untuk menentukan titik awal belajar American English yang paling tepat.', 'diagnostic_exam', -1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000002', 'e1000001-0000-4000-8000-000000000001', 'Sapaan & Perkenalan Profesional di AS', 'Selamat datang! Mulai langkah pertamamu dengan sapaan hangat khas Amerika, cara memperkenalkan nama dan asal kota, serta pola dasar To Be (am, is, are) di kampus maupun kantor.', 'curriculum', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000003', 'e1000001-0000-4000-8000-000000000001', 'Rutinitas Harian & Waktu Kerja', 'Ceritakan jadwal harian, jam mulai kuliah atau kerja dalam format a.m./p.m. khas AS, serta gunakan Present Simple untuk kebiasaan sehari-hari.', 'curriculum', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000004', 'e1000001-0000-4000-8000-000000000001', 'Angka, Harga Dolar & Belanja Harian', 'Pahami cara orang Amerika menyebut harga dolar dan sen, pajak penjualan (sales tax) di kasir, serta kata tunjuk this/that/these/those saat berbelanja kebutuhan harian.', 'curriculum', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000005', 'e1000001-0000-4000-8000-000000000001', 'Kafe, Restoran & Memesan Makanan', 'Kuasai cara memesan kopi di kafe Amerika, memahami istilah for here vs to go, meminta bon (check), serta budaya pemberian tip di restoran AS.', 'curriculum', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000006', 'e1000001-0000-4000-8000-000000000001', 'Arah Jalan, Subway & Bandara AS', 'Navigasi kota-kota besar Amerika dengan percaya diri: pahami istilah block, subway, downtown, petunjuk arah jalan, serta pengumuman gerbang keberangkatan di bandara AS.', 'curriculum', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000007', 'e1000001-0000-4000-8000-000000000001', 'Keluarga, Profesi & Tempat Kerja', 'Ceritakan latar belakang keluarga, jabatan kerja dengan artikel a/an yang tepat, serta kepemilikan (''s & possessive adjectives) dalam obrolan hangat di AS.', 'curriculum', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000008', 'e1000001-0000-4000-8000-000000000001', 'Kemampuan (Can) & Permintaan Sopan Dasar', 'Jelaskan keahlian kerja atau bahasa yang kamu kuasai dengan modal ''can / can''t'', serta pelajari rahasia pelafalan Amerika yang membedakan keduanya dengan tajam!', 'curriculum', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000009', 'e1000001-0000-4000-8000-000000000001', 'Aktivitas yang Sedang Berlangsung (Present Continuous)', 'Laporkan kegiatan yang sedang terjadi detik ini maupun proyek sementara minggu ini menggunakan am/is/are + verb-ing tanpa terjebak stative verbs!', 'curriculum', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000010', 'e1000001-0000-4000-8000-000000000001', 'Cuaca, Musim & Rencana Akhir Pekan', 'Ngobrol luwes soal empat musim di Amerika (termasuk kata khas ''fall'' dan suhu Fahrenheit!), serta buat ajakan akhir pekan dengan ''Let''s'' dan ''How about''.', 'curriculum', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000011', 'e1000001-0000-4000-8000-000000000001', 'Komunikasi Dasar di Kampus & Kantor', 'Tuntaskan level A1 dengan menguasai cara menulis pesan singkat/email dasar, membaca silabus & jadwal tenggat (deadline), serta kata ganti objek (me, him, her, us, them).', 'curriculum', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000012', 'e1000001-0000-4000-8000-000000000001', 'Ujian Simulasi Kesiapan CEFR A1', 'Evaluasi menyeluruh kemampuan dasar American English tingkat A1 (membaca, menyimak, menyusun kalimat, dan berbicara) dari Unit 1 hingga Unit 10.', 'diagnostic_exam', 99, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000013', 'e1000001-0000-4000-8000-000000000002', 'Menceritakan Pengalaman Masa Lalu (Past Simple)', 'Ceritakan proyek masa lalu, pengalaman kuliah, dan aktivitas kemarin dengan Past Simple (regular -ed, irregular verbs, was/were, dan did).', 'curriculum', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000014', 'e1000001-0000-4000-8000-000000000002', 'Rencana Karier & Studi (Going to vs Will)', 'Bedakan kapan memakai ''be going to'' untuk rencana karier/studi yang sudah matang vs ''will'' untuk keputusan spontan dan janji cepat.', 'curriculum', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000015', 'e1000001-0000-4000-8000-000000000002', 'Mencari Apartemen & Kehidupan Asrama AS', 'Pahami istilah sewa tempat tinggal di AS (lease, security deposit, utilities, studio vs 1-bedroom), serta gunakan kata tanya detail dan quantifiers (much, many, a lot of).', 'curriculum', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000016', 'e1000001-0000-4000-8000-000000000002', 'Belanja, Pengembalian Barang & Layanan Pelanggan', 'Kuasai cara mengembalikan atau menukar barang (return vs exchange) yang sangat mudah di toko AS, menjelaskan cacat produk, serta memahami paket pengiriman online.', 'curriculum', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000017', 'e1000001-0000-4000-8000-000000000002', 'Kesehatan, Apotek & Janji Klinik', 'Jelaskan gejala sakit dengan tepat di klinik kampus atau Urgent Care AS, pahami beda obat resep (prescription) vs obat bebas (OTC) di apotek seperti CVS/Walgreens, dan beri saran dengan ''should''.', 'curriculum', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000018', 'e1000001-0000-4000-8000-000000000002', 'Present Perfect: Pengalaman Hidup & Hasil Kini', 'Ceritakan pengalaman hidup tanpa waktu lampau spesifik (have/has + V3), kabar terbaru (just, already, yet), serta durasi hingga kini (for vs since).', 'curriculum', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000019', 'e1000001-0000-4000-8000-000000000002', 'Kewajiban & Saran di Kampus dan Kantor', 'Pahami perbedaan aturan wajib vs pilihan bebas (have to, don''t have to, must, must not) serta cara memberi saran profesional (should / shouldn''t).', 'curriculum', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000020', 'e1000001-0000-4000-8000-000000000002', 'Permintaan Sopan Profesional di Tempat Kerja', 'Sampaikan permintaan bantuan, izin, dan tawaran kerja sama secara santun dan elegan di kantor atau kampus AS menggunakan Could you, Would you, dan Would you mind + -ing.', 'curriculum', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000021', 'e1000001-0000-4000-8000-000000000002', 'Tujuan & Kata Kerja Benda (Infinitive vs Gerund)', 'Kuasai kapan kata kerja kedua harus berbentuk V-ing (enjoy, finish, avoid, suggest, preposisi + -ing) dan kapan memakai to + V1 (decide, offer, afford, tujuan).', 'curriculum', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000022', 'e1000001-0000-4000-8000-000000000002', 'Urutan Waktu & Kejadian (Time Clauses)', 'Rangkai urutan prosedur, rencana masa depan, dan cerita masa lalu secara runtut menggunakan when, before, after, as soon as, until, dan while.', 'curriculum', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000023', 'e1000001-0000-4000-8000-000000000002', 'Ujian Simulasi Kesiapan CEFR A2', 'Evaluasi menyeluruh kemampuan American English tingkat A2 mencakup Past Simple, rencana masa depan, perbandingan, Present Perfect, dan komunikasi layanan di AS.', 'diagnostic_exam', 99, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000024', 'e1000001-0000-4000-8000-000000000003', 'Present Perfect vs Past Simple: Kini vs Lampau', 'Bedakan secara tajam kapan memakai Present Perfect (periode waktu masih terbuka / dampak kini) dan Past Simple (waktu lampau selesai) dalam rapat, laporan riset, dan wawancara kerja AS.', 'curriculum', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000025', 'e1000001-0000-4000-8000-000000000003', 'Present Perfect Continuous: Durasi hingga Kini', 'Gunakan have/has been + V-ing untuk menonjolkan proses aktivitas berdurasi yang masih berlangsung hingga kini, serta pahami bedanya dengan Present Perfect Simple.', 'curriculum', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000026', 'e1000001-0000-4000-8000-000000000003', 'First & Second Conditionals: Realistis vs Imajiner', 'Kuasai kalimat pengandaian kemungkinan nyata di masa depan (First Conditional & unless) serta skenario hipotesis/strategis masa kini (Second Conditional & If I were).', 'curriculum', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000027', 'e1000001-0000-4000-8000-000000000003', 'Passive Voice: Kalimat Pasif Proses & Laporan', 'Sampaikan prosedur ilmiah, siklus alam TOEFL, dan laporan insiden bisnis secara objektif menggunakan Passive Voice (is/are + V3, was/were + V3, has been + V3, modal + be + V3).', 'curriculum', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000028', 'e1000001-0000-4000-8000-000000000003', 'Defining Relative Clauses: Klausa Penjelas', 'Padatkan dua kalimat terpisah menjadi satu kalimat akademik dan profesional yang tajam menggunakan kata hubung penjelas (''yang''): who, which, that, whose, dan where.', 'curriculum', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000029', 'e1000001-0000-4000-8000-000000000003', 'Kebiasaan Lama vs Adaptasi Luar Negeri', 'Ceritakan kebiasaan masa lalu yang sudah berhenti (used to + V1) dan bedakan secara tuntas dengan proses beradaptasi di negara baru (be used to / get used to + Noun / V-ing).', 'curriculum', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000030', 'e1000001-0000-4000-8000-000000000003', 'Modals of Deduction: Menyimpulkan Bukti Kini', 'Tarik kesimpulan logis berdasarkan bukti yang terlihat saat ini (95% yakin benar: must, 50% mungkin: might/may/could, 95% mustahil: can''t/couldn''t).', 'curriculum', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000031', 'e1000001-0000-4000-8000-000000000003', 'Reported Speech: Kalimat Tak Langsung Kerja', 'Teruskan pesan klien, hasil rapat, pertanyaan wawancara, dan instruksi manajer secara akurat menggunakan Reported Speech (said vs told, tense backshift, asked if/wh-, told to V1).', 'curriculum', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000032', 'e1000001-0000-4000-8000-000000000003', 'Indirect Questions: Pertanyaan Halus Tanpa Inversi', 'Ajukan pertanyaan kepada orang baru, klien, dan profesor secara sangat santun tanpa membalik subjek dan kata kerja (Could you tell me where..., Do you know if..., I was wondering...).', 'curriculum', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e4000001-0000-4000-8000-000000000033', 'e1000001-0000-4000-8000-000000000003', 'Kontras & Sebab Akademik (TOEFL Transition)', 'Kuasai perbedaan struktural konjungsi klausa vs preposisi frasa benda untuk kontras (although/even though vs despite/in spite of) dan sebab-akibat (because/since vs because of/due to).', 'curriculum', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "unit_type" = EXCLUDED."unit_type", "order_index" = EXCLUDED."order_index";
