INSERT INTO lessons ("id", "unit_id", "title", "xp_reward", "order_index", "created_at", "slug", "icon_name", "short_title") VALUES ('e4100001-0000-4000-8000-000000000124', 'e4000001-0000-4000-8000-000000000034', 'Simulasi Ujian Kesiapan Bahasa Inggris B1', 30, 1, '2026-11-27T00:00:00+00:00', 'en-us-b1-readiness-exam', 'trophy', 'Ujian Siap B1') ON CONFLICT ("id") DO UPDATE SET "unit_id" = EXCLUDED."unit_id", "title" = EXCLUDED."title", "xp_reward" = EXCLUDED."xp_reward", "order_index" = EXCLUDED."order_index", "slug" = EXCLUDED."slug", "icon_name" = EXCLUDED."icon_name", "short_title" = EXCLUDED."short_title";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000001', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih kata kerja bantu (to be) yang tepat untuk memperkenalkan diri: Hi, I ___ Dimas, a graphic designer from Bandung.', '{"options":["am","is","are","be"],"translation":"Halo, saya Dimas, seorang desainer grafis dari Bandung.","sentence_template":"Hi, I [blank] Dimas, a graphic designer from Bandung."}'::jsonb, '{"selected":"am"}'::jsonb, NULL, NULL, 'Subjek ''I'' dalam Present Simple selalu berpasangan dengan ''am'' (tidak boleh dihilangkan seperti dalam Bahasa Indonesia).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000002', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat rutinitas kerja harian berikut: Maya ___ the subway to her office in Boston every morning.', '{"options":["takes","take","taking","took"],"translation":"Maya naik kereta bawah tanah (subway) ke kantornya di Boston setiap pagi.","sentence_template":"Maya [blank] the subway to her office in Boston every morning."}'::jsonb, '{"selected":"takes"}'::jsonb, NULL, NULL, 'Untuk subjek orang ketiga tunggal (Maya / she) pada rutinitas rutin (every morning), kata kerja ditambah akhiran -s (''takes'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000003', 'e4100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan pesanan pelanggan di kafe Amerika ini. Minuman ukuran apa yang dipesan?', '{"options":[{"id":"opt_1","text":"Kopi panas ukuran kecil untuk dibawa pulang"},{"id":"opt_2","text":"Es latte ukuran sedang dengan susu gandum untuk diminum di tempat"},{"id":"opt_3","text":"Teh hijau dingin ukuran besar tanpa gula"},{"id":"opt_4","text":"Air mineral dingin dan roti panggang"}],"audio_text":"Hi! Can I get a medium iced latte with oat milk, for here, please?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''A medium iced latte with oat milk, for here'' berarti es latte ukuran sedang dengan susu oat untuk diminum di kafe (''for here'' vs ''to go'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000004', 'e4100001-0000-4000-8000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun kalimat tanya petunjuk arah: "Permisi, di mana stasiun kereta bawah tanah terdekat?"', '{"romaji":"/ɪkˈskjuːz miː, wer ɪz ðə ˈnɪrɪst ˈsʌbweɪ ˈsteɪʃən/","tokens":["Excuse me,","the nearest","subways","subway station?","where is","where are"],"target_translation":"Permisi, di mana stasiun kereta bawah tanah terdekat?"}'::jsonb, '["Excuse me,","where is","the nearest","subway station?"]'::jsonb, NULL, NULL, 'Gunakan ''Excuse me'' untuk membuka pertanyaan sopan, diikuti ''where is'' karena ''subway station'' berbentuk tunggal.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000005', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk kegiatan yang sedang berlangsung sekarang: Listen! Prof. Miller ___ the scholarship requirements right now.', '{"options":["is explaining","explains","explain","explained"],"translation":"Dengarkan! Prof. Miller sedang menjelaskan persyaratan beasiswa sekarang.","sentence_template":"Listen! Prof. Miller [blank] the scholarship requirements right now."}'::jsonb, '{"selected":"is explaining"}'::jsonb, NULL, NULL, 'Penanda ''Listen!'' dan ''right now'' menunjukkan Present Continuous (am/is/are + verb-ing).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000006', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi cerita pengalaman masa lampau berikut: Last semester, Kevin ___ for three summer internships in Austin.', '{"options":["applied","applies","applying","has apply"],"translation":"Semester lalu, Kevin melamar tiga program magang musim panas di Austin.","sentence_template":"Last semester, Kevin [blank] for three summer internships in Austin."}'::jsonb, '{"selected":"applied"}'::jsonb, NULL, NULL, 'Keterangan waktu lampau yang spesifik (''Last semester'') mewajibkan Past Simple (''apply'' berubah menjadi ''applied'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000007', 'e4100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di klinik kampus ini. Apa saran apoteker kepada pasien?', '{"options":[{"id":"opt_1","text":"Minum dua tablet sebelum sarapan pagi saat perut kosong"},{"id":"opt_2","text":"Minum satu tablet setelah makan malam dan hindari menyetir karena menyebabkan kantuk"},{"id":"opt_3","text":"Segera pergi ke unit gawat darurat rumah sakit malam ini"},{"id":"opt_4","text":"Olahraga ringan selama tiga puluh menit sebelum tidur"}],"audio_text":"You should take one tablet after dinner and drink plenty of water. Avoid driving because it may cause drowsiness."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Take one tablet after dinner'' dan ''avoid driving because it may cause drowsiness'' memperingatkan efek mengantuk obat.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000008', 'e4100001-0000-4000-8000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengalaman hidup (Present Perfect): "Saya belum pernah mengunjungi Kota New York sebelumnya."', '{"romaji":"/aɪ hæv ˈnevər ˈvɪzɪtɪd nuː jɔːrk ˈsɪti bɪˈfɔːr/","tokens":["New York City","visited","I have","never","before.","did not","visiting"],"target_translation":"Saya belum pernah mengunjungi Kota New York sebelumnya."}'::jsonb, '["I have","never","visited","New York City","before."]'::jsonb, NULL, NULL, 'Pengalaman hidup sampai saat ini tanpa waktu lampau spesifik menggunakan Present Perfect: ''have/has + never + past participle (V3)''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000009', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih perbandingan yang tepat untuk dua kota di AS: Renting an apartment in San Francisco is much ___ than in Dallas.', '{"options":["more expensive","expensiver","most expensive","expensive"],"translation":"Menyewa apartemen di San Francisco jauh lebih mahal daripada di Dallas.","sentence_template":"Renting an apartment in San Francisco is much [blank] than in Dallas."}'::jsonb, '{"selected":"more expensive"}'::jsonb, NULL, NULL, 'Kata sifat panjang (3 suku kata: ex-pen-sive) menggunakan ''more ... than'' untuk bentuk komparatif.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000010', 'e4100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan permintaan sopan di kantor ini. Apa yang diminta rekan kerja Anda?', '{"options":[{"id":"opt_1","text":"Membatalkan panggilan telepon dengan klien jam dua siang"},{"id":"opt_2","text":"Memesan ruang rapat di lantai empat untuk besok"},{"id":"opt_3","text":"Memeriksa draf materi presentasi sebelum panggilan klien jam dua"},{"id":"opt_4","text":"Mengirimkan faktur pembayaran kepada bagian keuangan"}],"audio_text":"Hey Rina, would you mind looking over my slide deck before the two o''clock client call?"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Pola sopan ''Would you mind + verb-ing'' (''looking over my slide deck'') berarti meminta tolong mengecek slide presentasi.', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000011', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pengandaian (Second Conditional) dalam negosiasi jadwal tim: If we ___ two more QA engineers, we would launch the app next Friday.', '{"options":["had","have","will have","would have"],"translation":"Seandainya kita memiliki dua insinyur QA lagi sekarang, kita akan meluncurkan aplikasinya Jumat depan.","sentence_template":"If we [blank] two more QA engineers, we would launch the app next Friday."}'::jsonb, '{"selected":"had"}'::jsonb, NULL, NULL, 'Second Conditional (situasi hipotesis saat ini) menggunakan rumus ''If + Past Simple (had), Subject + would + V1''.', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000012', 'e4100001-0000-4000-8000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif yang tepat untuk laporan prosedur: All scholarship applications ___ by the admission committee in March.', '{"options":["are reviewed","review","is reviewed","reviewing"],"translation":"Seluruh dokumen pendaftaran beasiswa ditinjau oleh komite admisi pada bulan Maret.","sentence_template":"All scholarship applications [blank] by the admission committee in March."}'::jsonb, '{"selected":"are reviewed"}'::jsonb, NULL, NULL, 'Subjek jamak (''All scholarship applications'') yang dikenai tindakan rutin membutuhkan Passive Voice jamak: ''are + V3 (reviewed)''.', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000013', 'e4100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan pembaruan dalam rapat Daily Standup berikut. Kendala teknis (blocker) apa yang sedang dihadapi pembicara?', '{"options":[{"id":"opt_1","text":"Desain antarmuka halaman pembayaran belum selesai dibuat"},{"id":"opt_2","text":"Kredensial akses server staging kedaluwarsa sehingga integrasi API tertahan"},{"id":"opt_3","text":"Klien meminta perubahan warna tombol pada aplikasi seluler"},{"id":"opt_4","text":"Koneksi internet di kantor cabang sedang mati total"}],"audio_text":"Yesterday I finished the payment UI, and today I''m integrating the checkout API. However, I''m currently blocked because the staging server credentials expired."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Frasa ''currently blocked because the staging server credentials expired'' menjelaskan penghambat kerja (blocker) secara lugas.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000014', 'e4100001-0000-4000-8000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun pembuka email profesional: "Saya menulis email ini untuk menindaklanjuti diskusi kita kemarin."', '{"romaji":"/aɪ æm ˈraɪtɪŋ tə ˈfɑːloʊ ʌp ɑːn ˈaʊər dɪˈskʌʃən ˈjestərdeɪ/","tokens":["to follow up","for","follow","discussion","on our","I am writing","yesterday."],"target_translation":"Saya menulis email ini untuk menindaklanjuti diskusi kita kemarin."}'::jsonb, '["I am writing","to follow up","on our","discussion","yesterday."]'::jsonb, NULL, NULL, 'Idiom bisnis standar AS adalah ''follow up on (something)'' — bukan ''follow up for''.', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000015', 'e4100001-0000-4000-8000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah pengantar kampus AS (setara TOEFL B1) ini. Mengapa profesor menyarankan mahasiswa mengunjungi Writing Center?', '{"options":[{"id":"opt_1","text":"Untuk mencetak makalah secara gratis menggunakan printer kampus"},{"id":"opt_2","text":"Untuk meminta perpanjangan batas waktu pengumpulan tugas tengah semester"},{"id":"opt_3","text":"Agar tutor dapat membantu memeriksa sitasi dan struktur argumen sebelum makalah dikumpulkan"},{"id":"opt_4","text":"Untuk mendaftar kelas tambahan bahasa asing semester depan"}],"audio_text":"Before submitting your midterm research paper next Tuesday, I strongly encourage you to book a session at the campus Writing Center so a tutor can check your citations and thesis structure."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Profesor menekankan manfaat praktis Writing Center: ''so a tutor can check your citations and thesis structure''.', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000016', 'e4100001-0000-4000-8000-000000000002', NULL, 'reading', 'fill_blank', 'Pilih ungkapan paling alami saat baru pertama kali berkenalan di kantor: Hi, I''m Clara. ___ to meet you!', '{"options":["Nice","Fine","Well","Welcome"],"translation":"Halo, saya Clara. Senang bertemu dengan Anda!","sentence_template":"Hi, I''m Clara. [blank] to meet you!"}'::jsonb, '{"selected":"Nice"}'::jsonb, NULL, NULL, '''Nice to meet you'' (atau ''Great to meet you'') adalah salam perkenalan standar saat bertemu seseorang untuk pertama kali.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000017', 'e4100001-0000-4000-8000-000000000002', NULL, 'reading', 'fill_blank', 'Lengkapi formulir pendaftaran kampus AS berikut: Please write your first name and your ___ name clearly.', '{"options":["last","end","back","behind"],"translation":"Mohon tuliskan nama depan dan nama belakang Anda dengan jelas.","sentence_template":"Please write your first name and your [blank] name clearly."}'::jsonb, '{"selected":"last"}'::jsonb, NULL, NULL, 'Dalam American English, pasangan dari ''first name'' (nama depan) adalah ''last name'' (nama belakang/keluarga).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000018', 'e4100001-0000-4000-8000-000000000002', NULL, 'reading', 'fill_blank', 'Pilih balasan yang tepat ketika rekan baru berkata ''Nice to meet you!'': Nice to meet you, ___!', '{"options":["too","two","to","very"],"translation":"Senang bertemu dengan Anda juga!","sentence_template":"Nice to meet you, [blank]!"}'::jsonb, '{"selected":"too"}'::jsonb, NULL, NULL, 'Kata ''too'' (dengan dua huruf ''o'') di akhir kalimat berarti ''juga''. Jangan tertukar ejaannya dengan ''to'' atau angka ''two''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000019', 'e4100001-0000-4000-8000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan sambutan rekan kerja di hari pertamamu bekerja di kantor Seattle. Apa maksud ucapan ''Welcome aboard!''?', '{"options":[{"id":"opt_1","text":"Selamat bergabung di tim atau perusahaan kami"},{"id":"opt_2","text":"Silakan naik ke pesawat sekarang juga"},{"id":"opt_3","text":"Sampai jumpa pada rapat minggu depan"},{"id":"opt_4","text":"Terima kasih sudah mengirimkan berkas lamaran"}],"audio_text":"Hi Raka! I''m Megan from HR. Welcome aboard!"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Idiom ramah ''Welcome aboard!'' sangat lazim di dunia kerja AS untuk menyambut anggota tim atau karyawan baru.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000020', 'e4100001-0000-4000-8000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan sapaan santai teman sekelas di kampus ini. Bagaimana kondisi pembicara kedua?', '{"options":[{"id":"opt_1","text":"Sedang sakit demam dan tidak bisa masuk kelas"},{"id":"opt_2","text":"Kabarnya cukup baik dan ia balik menanyakan kabar temannya"},{"id":"opt_3","text":"Sedang terburu-buru mengejar bus kampus"},{"id":"opt_4","text":"Baru saja kehilangan kartu mahasiswanya"}],"audio_text":"Hey Sam, how''s it going? — Pretty good, thanks! How about you?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Pretty good, thanks!'' berarti ''Kabar cukup baik, terima kasih!''—respons paling alami terhadap ''How''s it going?''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000021', 'e4100001-0000-4000-8000-000000000002', NULL, 'writing', 'sentence_builder', 'Susun kalimat perkenalan hangat ini: "Halo, saya Bima. Senang bertemu dengan Anda!"', '{"romaji":"/haɪ, aɪm ˈbiːmə. naɪs tə miːt juː/","tokens":["am I","meet you!","Hi,","I''m Bima.","Nice to","meeting"],"target_translation":"Halo, saya Bima. Senang bertemu dengan Anda!"}'::jsonb, '["Hi,","I''m Bima.","Nice to","meet you!"]'::jsonb, NULL, NULL, 'Mulai dengan sapaan ''Hi, I''m Bima.'' lalu sambung dengan ''Nice to meet you!''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000022', 'e4100001-0000-4000-8000-000000000002', NULL, 'writing', 'sentence_builder', 'Susun sapaan akrab khas Amerika: "Hai Taylor, bagaimana kabarmu hari ini?"', '{"romaji":"/heɪ ˈteɪlər, haʊz ɪt ˈɡoʊɪŋ təˈdeɪ/","tokens":["how''s","today?","how are","go","Hey Taylor,","it going"],"target_translation":"Hai Taylor, bagaimana kabarmu hari ini?"}'::jsonb, '["Hey Taylor,","how''s","it going","today?"]'::jsonb, NULL, NULL, '''How''s it going'' adalah singkatan dari ''How is it going'', sapaan ramah paling populer di AS.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000023', 'e4100001-0000-4000-8000-000000000002', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan ucapkan perkenalan pertamamu dengan percaya diri: "Halo, saya Nadia. Senang bertemu dengan Anda!"', '{"romaji":"/haɪ, aɪm ˈnɑːdiə. naɪs tə miːt juː/","display_text":"Hi, I''m Nadia. Nice to meet you!","phonetic_breakdown":["haɪ","aɪm","ˈnɑː-di-ə","naɪs","tə","miːt","juː"]}'::jsonb, '{"expected_transcript":"Hi, I''m Nadia. Nice to meet you!"}'::jsonb, NULL, NULL, 'Ucapkan ''I''m'' (/aɪm/) dengan merapatkan bibir di bunyi /m/, dan sambung ''meet you'' dengan ringan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000024', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Pilih pasangan To Be yang tepat untuk subjek tunggal orang ketiga: Mr. Miller ___ our academic advisor at Boston University.', '{"options":["is","am","are","be"],"translation":"Pak Miller adalah pembimbing akademik kami di Boston University.","sentence_template":"Mr. Miller [blank] our academic advisor at Boston University."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Mr. Miller setara dengan kata ganti tunggal ''he'', sehingga wajib menggunakan ''is''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000025', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat untuk subjek jamak berikut: Tari and Dimas ___ scholarship awardees from Indonesia.', '{"options":["are","is","am","be"],"translation":"Tari dan Dimas adalah penerima beasiswa dari Indonesia.","sentence_template":"Tari and Dimas [blank] scholarship awardees from Indonesia."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Dua orang (''Tari and Dimas'' = they) merupakan subjek jamak, sehingga menggunakan ''are''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000026', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat negatif To Be berikut: No, I''m ___ from Malaysia; I''m from Jakarta, Indonesia.', '{"options":["not","no","don''t","aren''t"],"translation":"Bukan, saya bukan dari Malaysia; saya dari Jakarta, Indonesia.","sentence_template":"No, I''m [blank] from Malaysia; I''m from Jakarta, Indonesia."}'::jsonb, '{"selected":"not"}'::jsonb, NULL, NULL, 'Untuk membuat kalimat sangkal dengan To Be, cukup tambahkan ''not'' tepat setelah am/is/are (''I''m not'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000027', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'listening', 'listening_choice', 'Dengarkan perkenalan singkat di orientasi kampus AS ini. Dari kota manakah pembicara berasal?', '{"options":[{"id":"opt_1","text":"Dari Kuala Lumpur, Malaysia"},{"id":"opt_2","text":"Dari Yogyakarta, Indonesia"},{"id":"opt_3","text":"Dari Chicago, Amerika Serikat"},{"id":"opt_4","text":"Dari Tokyo, Jepang"}],"audio_text":"Hi everyone! I''m Laras, and I''m an international student from Yogyakarta, Indonesia."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pembicara memperkenalkan diri dengan jelas: ''I''m an international student from Yogyakarta, Indonesia.''', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000028', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'listening', 'listening_choice', 'Dengarkan percakapan singkat di lobi kantor ini. Apakah ruang rapat mereka berada di lantai tiga?', '{"options":[{"id":"opt_1","text":"Ya, ruang rapatnya tepat di lantai tiga"},{"id":"opt_2","text":"Tidak, ruang rapat mereka berada di lantai lima"},{"id":"opt_3","text":"Ruang rapatnya berada di gedung seberang jalan"},{"id":"opt_4","text":"Rapat hari ini dibatalkan oleh manajer"}],"audio_text":"Excuse me, are we in Conference Room B on the third floor? — No, our meeting room is on the fifth floor."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Lawan bicara mengoreksi lokasi dengan kalimat ''No, our meeting room is on the fifth floor'' (lantai lima).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000029', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat identitas diri yang benar: "Saya seorang mahasiswa pertukaran dari Bandung."', '{"romaji":"/aɪ æm ən ɪksˈtʃeɪndʒ ˈstuːdənt frʌm ˈbɑːndʊŋ/","tokens":["students","from Bandung.","I am","an exchange","I is","student"],"target_translation":"Saya seorang mahasiswa pertukaran dari Bandung."}'::jsonb, '["I am","an exchange","student","from Bandung."]'::jsonb, NULL, NULL, 'Gunakan ''I am'' diikuti ''an exchange student'' (pakai ''an'' karena ''exchange'' diawali bunyi vokal /ɪ/).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000030', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat tanya To Be berikut: "Apakah kamu mahasiswa baru di departemen ini?"', '{"romaji":"/ɑːr juː ə nuː ˈstuːdənt ɪn ðɪs dɪˈpɑːrtmənt/","tokens":["student in","Are you","this department?","is","You are","a new"],"target_translation":"Apakah kamu mahasiswa baru di departemen ini?"}'::jsonb, '["Are you","a new","student in","this department?"]'::jsonb, NULL, NULL, 'Untuk membuat pertanyaan Ya/Tidak dengan To Be, pindahkan ''Are'' ke depan subjek ''you'' (''Are you...?'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000031', 'e4100001-0000-4000-8000-000000000003', 'e2000001-0000-4000-8000-000000000001', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan asal negara ini dengan pelafalan US yang jelas: "Saya berasal dari Indonesia, dan saya senang berada di sini."', '{"romaji":"/aɪm frʌm ˌɪndəˈniːʒə, ænd aɪm ˈhæpi tə biː hɪr/","display_text":"I''m from Indonesia, and I''m happy to be here.","phonetic_breakdown":["aɪm","frʌm","ˌɪn-də-ˈniː-ʒə","ænd","aɪm","ˈhæ-pi","tə","biː","hɪr"]}'::jsonb, '{"expected_transcript":"I''m from Indonesia, and I''m happy to be here."}'::jsonb, NULL, NULL, 'Lafalkan ''Indonesia'' ala Amerika /ˌɪndəˈniːʒə/ dan bunyi ''r'' di akhir kata ''here'' /hɪr/ dengan jelas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000032', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Pilih kata tanya yang tepat untuk menanyakan kota/negara asal: ___ are you from originally?', '{"options":["Where","What","Who","How"],"translation":"Dari mana asal daerah Anda sebenarnya?","sentence_template":"[blank] are you from originally?"}'::jsonb, '{"selected":"Where"}'::jsonb, NULL, NULL, 'Kata tanya ''Where'' digunakan untuk menanyakan tempat atau asal daerah (''Where ... from?'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000033', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Lengkapi kalimat untuk memberi tahu nama panggilan akrab: My first name is Rahmat, but everyone calls ___ Rama.', '{"options":["me","I","my","mine"],"translation":"Nama depan saya Rahmat, tetapi semua orang memanggil saya Rama.","sentence_template":"My first name is Rahmat, but everyone calls [blank] Rama."}'::jsonb, '{"selected":"me"}'::jsonb, NULL, NULL, 'Setelah kata kerja (''calls'' / ''call''), gunakan kata ganti objek ''me'' (''Please call me Rama''), bukan subjek ''I''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000034', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Pilih kata tanya yang tepat untuk menanyakan jurusan kuliah teman baru di kampus AS: ___ is your major at NYU?', '{"options":["What","Where","Who","When"],"translation":"Apa jurusan kuliahmu di NYU?","sentence_template":"[blank] is your major at NYU?"}'::jsonb, '{"selected":"What"}'::jsonb, NULL, NULL, '''What''s your major?'' adalah pertanyaan paling populer antar-mahasiswa di universitas Amerika.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000035', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'listening', 'listening_choice', 'Dengarkan percakapan di meja registrasi seminar ini. Bagaimana peserta mengeja nama depannya?', '{"options":[{"id":"opt_1","text":"N-A-D-Y-A menggunakan huruf Y"},{"id":"opt_2","text":"N-A-D-I-A menggunakan huruf I"},{"id":"opt_3","text":"M-A-R-I-A diawali huruf M"},{"id":"opt_4","text":"D-I-A-N-A diawali huruf D"}],"audio_text":"Could you spell your first name for your badge? — Sure, it''s N-A-D-I-A, Nadia."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Peserta mengeja tiap huruf dengan jelas: ''N-A-D-I-A'' (huruf ''I'' dilafalkan /aɪ/ dalam bahasa Inggris).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000036', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'listening', 'listening_choice', 'Dengarkan obrolan networking dua profesional muda di Austin berikut. Apa bidang kerja Jordan?', '{"options":[{"id":"opt_1","text":"Dosen ekonomi di universitas negeri"},{"id":"opt_2","text":"Analis keamanan cloud di perusahaan teknologi finansial di Austin"},{"id":"opt_3","text":"Fotografer lepas untuk majalah perjalanan"},{"id":"opt_4","text":"Manajer restoran makanan laut di pusat kota"}],"audio_text":"Hi Jordan, nice to meet you! What do you do? — I''m a cloud security analyst at a fintech company here in Austin."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Jordan menjawab ''What do you do?'' dengan menyebutkan perannya: ''a cloud security analyst at a fintech company''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000037', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat ramah untuk memberi tahu nama panggilan: "Nama saya Bagaskara, tetapi panggil saja saya Bagas."', '{"romaji":"/maɪ neɪm ɪz bɑːɡɑːsˈkɑːrə, bʌt pliːz kɔːl miː ˈbɑːɡɑːs/","tokens":["call me","My name","Bagas.","my","but please","is Bagaskara,","calls I"],"target_translation":"Nama saya Bagaskara, tetapi panggil saja saya Bagas."}'::jsonb, '["My name","is Bagaskara,","but please","call me","Bagas."]'::jsonb, NULL, NULL, 'Ungkapan ''please call me [Nickname]'' sangat membantu rekan Amerika melafalkan namamu dengan mudah.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
