INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000039', 'e4100001-0000-4000-8000-000000000004', 'e2000001-0000-4000-8000-000000000001', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan dua arah ini dengan ramah: "Halo! Saya Dito dari Jakarta. Dari mana asalmu?"', '{"romaji":"/haɪ! aɪm ˈdiːtoʊ frʌm dʒəˈkɑːrtə. wer ɑːr juː frʌm/","display_text":"Hi! I''m Dito from Jakarta. Where are you from?","phonetic_breakdown":["haɪ","aɪm","ˈdiː-toʊ","frʌm","dʒə-ˈkɑːr-tə","wer","ɑːr","juː","frʌm"]}'::jsonb, '{"expected_transcript":"Hi! I''m Dito from Jakarta. Where are you from?"}'::jsonb, NULL, NULL, 'Beri jeda singkat setelah ''Jakarta'', lalu turunkan intonasi dengan lembut di kata akhir ''from?''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000040', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Lengkapi perkenalan di rapat tim perdana: Hello everyone, I ___ Putra, the new frontend intern.', '{"options":["am","is","are","be"],"translation":"Halo semuanya, saya Putra, anak magang frontend yang baru.","sentence_template":"Hello everyone, I [blank] Putra, the new frontend intern."}'::jsonb, '{"selected":"am"}'::jsonb, NULL, NULL, 'Subjek ''I'' wajib berpasangan dengan ''am''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000041', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Pilih kata ganti kepemilikan yang tepat: She is from Seattle, and ___ first name is Hannah.', '{"options":["her","she","his","hers"],"translation":"Dia berasal dari Seattle, dan nama depannya adalah Hannah.","sentence_template":"She is from Seattle, and [blank] first name is Hannah."}'::jsonb, '{"selected":"her"}'::jsonb, NULL, NULL, 'Sebelum kata benda (''first name''), gunakan possessive adjective perempuan ''her'' (bukan subjek ''she'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000042', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'reading', 'fill_blank', 'Pilih respons paling tepat ketika bertemu kembali rekan kerja yang sudah dikenal kemarin: Nice to ___ you again, Kevin!', '{"options":["see","meet","look","watch"],"translation":"Senang bertemu denganmu lagi, Kevin!","sentence_template":"Nice to [blank] you again, Kevin!"}'::jsonb, '{"selected":"see"}'::jsonb, NULL, NULL, 'Untuk orang yang sudah pernah dikenal sebelumnya, gunakan ''Nice to see you again!'' (bukan ''meet'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000043', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'listening', 'listening_choice', 'Dengarkan perkenalan singkat mahasiswa di kelas ini. Apa jurusan dan kota asal Alicia?', '{"options":[{"id":"opt_1","text":"Jurusan bisnis internasional dari Miami"},{"id":"opt_2","text":"Jurusan ilmu komputer dari Denver, Colorado"},{"id":"opt_3","text":"Jurusan arsitektur dari Seattle, Washington"},{"id":"opt_4","text":"Jurusan kedokteran dari Los Angeles"}],"audio_text":"Hi class! I''m Alicia Gomez. I''m from Denver, Colorado, and my major is computer science."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Alicia menyebutkan ''from Denver, Colorado'' dan ''my major is computer science''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
