INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000045', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'writing', 'sentence_builder', 'Susun kalimat sangkal To Be berikut: "Kami bukan wisatawan; kami mahasiswa beasiswa."', '{"romaji":"/wiː ɑːr nɑːt ˈtʊrɪsts; wiː ɑːr ˈskɑːlərʃɪp ˈstuːdənts/","tokens":["students.","no","not tourists;","We are","scholarship","We is","we are"],"target_translation":"Kami bukan wisatawan; kami mahasiswa beasiswa."}'::jsonb, '["We are","not tourists;","we are","scholarship","students."]'::jsonb, NULL, NULL, 'Gunakan ''We are not'' untuk menyangkal status subjek jamak ''we''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000046', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'writing', 'sentence_builder', 'Susun pertanyaan sopan untuk mengeja nama: "Bagaimana cara Anda mengeja nama belakang Anda?"', '{"romaji":"/haʊ də juː spel jʊr læst neɪm/","tokens":["spelling","you are","you spell","your","How do","last name?"],"target_translation":"Bagaimana cara Anda mengeja nama belakang Anda?"}'::jsonb, '["How do","you spell","your","last name?"]'::jsonb, NULL, NULL, 'Pola baku menanyakan ejaan dalam bahasa Inggris adalah ''How do you spell ...?''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000047', 'e4100001-0000-4000-8000-000000000005', 'e2000001-0000-4000-8000-000000000001', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup perkenalan profesional ini: "Senang bertemu dengan Anda, Pak Carter. Sampai jumpa besok!"', '{"romaji":"/ɪts ɡreɪt tə miːt juː, ˈmɪstər ˈkɑːrtər. siː juː təˈmɑːroʊ/","display_text":"It''s great to meet you, Mr. Carter. See you tomorrow!","phonetic_breakdown":["ɪts","ɡreɪt","tə","miːt","juː","ˈmɪs-tər","ˈkɑːr-tər","siː","juː","tə-ˈmɑːr-oʊ"]}'::jsonb, '{"expected_transcript":"It''s great to meet you, Mr. Carter. See you tomorrow!"}'::jsonb, NULL, NULL, 'Perhatikan lafal US ''tomorrow'' /təˈmɑːroʊ/ dengan bunyi tengah /ɑːr/.Selamat menyelesaikan Unit 1!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000048', 'e4100001-0000-4000-8000-000000000006', NULL, 'reading', 'fill_blank', 'Pilih preposisi waktu yang tepat untuk jam spesifik: Our morning standup starts ___ 9:15 a.m. sharp.', '{"options":["at","on","in","to"],"translation":"Rapat pagi kami dimulai tepat pukul 09.15 pagi.","sentence_template":"Our morning standup starts [blank] 9:15 a.m. sharp."}'::jsonb, '{"selected":"at"}'::jsonb, NULL, NULL, 'Untuk angka jam spesifik (''9:15 a.m.''), selalu gunakan preposisi ''at''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
