INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000050', 'e4100001-0000-4000-8000-000000000006', NULL, 'reading', 'fill_blank', 'Pilih ungkapan alami AS yang berarti ''selesai jam kerja'': What time do you usually ___ work?', '{"options":["get off","get out","turn off","take off"],"translation":"Jam berapa kamu biasanya selesai kerja?","sentence_template":"What time do you usually [blank] work?"}'::jsonb, '{"selected":"get off"}'::jsonb, NULL, NULL, '''Get off work'' adalah ungkapan sehari-hari orang Amerika untuk mengakhiri shift atau jam kerja kantor.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000051', 'e4100001-0000-4000-8000-000000000006', NULL, 'listening', 'listening_choice', 'Dengarkan cerita rutinitas pagi mahasiswa di Boston ini. Berapa lama perjalanan (commute) yang ia tempuh ke kampus?', '{"options":[{"id":"opt_1","text":"Sekitar sepuluh menit jalan kaki"},{"id":"opt_2","text":"Sekitar dua puluh lima menit naik bus"},{"id":"opt_3","text":"Satu jam penuh naik kereta antarkota"},{"id":"opt_4","text":"Empat puluh lima menit mengendarai sepeda"}],"audio_text":"I wake up at seven, make coffee, and take the bus. My morning commute to campus takes about twenty-five minutes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kalimat ''take the bus'' dan ''takes about twenty-five minutes'' menunjukkan durasi perjalanan pagi 25 menit.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000052', 'e4100001-0000-4000-8000-000000000006', NULL, 'listening', 'listening_choice', 'Dengarkan ajakan rekan sekantor berikut. Kapan mereka akan makan siang bersama?', '{"options":[{"id":"opt_1","text":"Pukul 12.00 malam (midnight)"},{"id":"opt_2","text":"Pukul 12.00 siang (noon)"},{"id":"opt_3","text":"Pukul 09.00 pagi sebelum rapat"},{"id":"opt_4","text":"Pukul 06.00 sore sepulang kerja"}],"audio_text":"Are you free at noon? Let''s grab lunch at the Thai place downstairs."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dalam bahasa Inggris, ''at noon'' selalu berarti pukul 12.00 siang tepat.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000053', 'e4100001-0000-4000-8000-000000000006', NULL, 'writing', 'sentence_builder', 'Susun kalimat rutinitas pagi ini: "Saya memulai kerja pukul sembilan pagi pada hari kerja."', '{"romaji":"/aɪ stɑːrt wɜːrk æt naɪn eɪˈem ɑːn ˈwiːkdeɪz/","tokens":["work at","nine a.m.","I start","in weekdays.","at weekdays.","on weekdays."],"target_translation":"Saya memulai kerja pukul sembilan pagi pada hari kerja."}'::jsonb, '["I start","work at","nine a.m.","on weekdays."]'::jsonb, NULL, NULL, 'Kombinasikan ''at nine a.m.'' (jam) dengan ''on weekdays'' (hari kerja Senin–Jumat).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
