INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000075', 'e4100001-0000-4000-8000-000000000009', 'e2000001-0000-4000-8000-000000000002', 'listening', 'listening_choice', 'Dengarkan jadwal harian perawat rumah sakit di Houston ini. Jam berapa shift kerjanya berakhir?', '{"options":[{"id":"opt_1","text":"Mulai pukul 8 pagi dan selesai pukul 5 sore"},{"id":"opt_2","text":"Mulai pukul 6 pagi dan selesai pukul 2.30 siang"},{"id":"opt_3","text":"Mulai pukul 2.30 siang dan selesai pukul 11 malam"},{"id":"opt_4","text":"Bekerja hanya pada akhir pekan"}],"audio_text":"I work the early shift at Houston General. I clock in at six a.m. and get off work at two-thirty p.m."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Clock in at six a.m.'' berarti absen masuk jam 6 pagi, dan ''get off work at two-thirty p.m.'' berarti selesai pukul 14.30.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
