INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000088', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih kata tunjuk yang tepat untuk benda jamak yang sedang Anda pegang: Excuse me, how much are ___ wireless earbuds?', '{"options":["these","this","that","it"],"translation":"Permisi, berapa harga earbud nirkabel ini?","sentence_template":"Excuse me, how much are [blank] wireless earbuds?"}'::jsonb, '{"selected":"these"}'::jsonb, NULL, NULL, '''Earbuds'' berbentuk jamak (dua unit kiri-kanan) dan ada kata ''are'', sehingga wajib memakai ''these''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
