INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000090', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih frasa yang berarti ''sedang diskon 30%'': Good news! All campus hoodies are ___ for thirty percent off this week.', '{"options":["on sale","for rent","in cash","by card"],"translation":"Kabar gembira! Semua jaket hoodie kampus sedang diskon 30% minggu ini.","sentence_template":"Good news! All campus hoodies are [blank] for thirty percent off this week."}'::jsonb, '{"selected":"on sale"}'::jsonb, NULL, NULL, '''On sale'' adalah idiom tepat untuk barang yang sedang mendapat potongan harga.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000091', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan percakapan pembeli dan pramuniaga di toko pakaian Seattle ini. Mengapa celana jin tersebut harganya lebih murah?', '{"options":[{"id":"opt_1","text":"Karena ada kerusakan resleting pada celana tersebut"},{"id":"opt_2","text":"Karena sedang diskon hari ini dari $60 menjadi $42"},{"id":"opt_3","text":"Karena pembeli menukarkan kupon ulang tahun"},{"id":"opt_4","text":"Karena itu celana bekas pakai"}],"audio_text":"How much are these dark blue jeans? — They''re normally sixty dollars, but they''re on sale for forty-two dollars today."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pramuniaga menjelaskan ''normally sixty dollars, but they''re on sale for forty-two dollars today''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000092', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan obrolan di toko elektronik kampus berikut. Barang mana yang akhirnya dipilih mahasiswa?', '{"options":[{"id":"opt_1","text":"Membeli papan ketik (keyboard) dan tetikus sekaligus"},{"id":"opt_2","text":"Hanya membeli tetikus (mouse) seharga $25 hari ini"},{"id":"opt_3","text":"Membeli monitor komputer bekas"},{"id":"opt_4","text":"Tidak jadi membeli apa-apa"}],"audio_text":"This keyboard is eighty dollars, and that mouse is twenty-five. I''ll just take the mouse today, thanks."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''ll just take the mouse today'' adalah ungkapan alami saat memutuskan barang yang jadi dibeli.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000093', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun pertanyaan harga barang jamak ini: "Berapa harga sepatu lari yang di sana itu?"', '{"romaji":"/haʊ mʌtʃ ɑːr ðoʊz ˈrʌnɪŋ ʃuːz ˈoʊvər ðer/","tokens":["How much","is that","are those","running shoes","over there?","shoe"],"target_translation":"Berapa harga sepatu lari yang di sana itu?"}'::jsonb, '["How much","are those","running shoes","over there?"]'::jsonb, NULL, NULL, '''Over there'' menunjukkan jarak jauh, dan ''running shoes'' jamak sehingga memakai ''are those''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000094', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat keputusan membeli barang: "Saya ambil buku catatan biru ini, terima kasih."', '{"romaji":"/aɪl teɪk ðɪs bluː ˈnoʊtbʊk, θæŋks/","tokens":["thanks.","taking","I''ll take","notebook,","these","this blue"],"target_translation":"Saya ambil buku catatan biru ini, terima kasih."}'::jsonb, '["I''ll take","this blue","notebook,","thanks."]'::jsonb, NULL, NULL, 'Di toko AS, katakan ''I''ll take [item]'' (bukan ''I buy this'') saat memutuskan membeli suatu barang.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000095', 'e4100001-0000-4000-8000-000000000011', 'e2000001-0000-4000-8000-000000000003', 'speaking', 'speaking_repeat', 'Latih perbedaan bunyi /ðɪs/ dan /ðiːz/ dalam kalimat belanja ini: "Kemeja ini pas, tetapi celana panjang ini terlalu panjang."', '{"romaji":"/ðɪs ʃɜːrt fɪts wel, bʌt ðiːz pænts ɑːr tuː lɔːŋ/","display_text":"This shirt fits well, but these pants are too long.","phonetic_breakdown":["ðɪs","ʃɜːrt","fɪts","wel","bʌt","ðiːz","pænts","ɑːr","tuː","lɔːŋ"]}'::jsonb, '{"expected_transcript":"This shirt fits well, but these pants are too long."}'::jsonb, NULL, NULL, 'Di AS, ''pants'' berarti celana panjang luar (bukan pakaian dalam seperti di Inggris) dan selalu berpasangan dengan ''these ... are''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000096', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih kata yang tepat untuk kalimat negatif belanjaan dapur: We don''t have ___ rice left at the apartment.', '{"options":["any","a","an","many"],"translation":"Kita tidak punya beras tersisa sama sekali di apartemen.","sentence_template":"We don''t have [blank] rice left at the apartment."}'::jsonb, '{"selected":"any"}'::jsonb, NULL, NULL, '''Rice'' adalah uncountable noun pada kalimat negatif (''don''t have''), sehingga memakai ''any''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000097', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih kosakata lorong supermarket untuk menanyakan letak barang: Excuse me, which ___ is the peanut butter in?', '{"options":["aisle","island","stairs","seat"],"translation":"Permisi, selai kacang berada di lorong nomor berapa?","sentence_template":"Excuse me, which [blank] is the peanut butter in?"}'::jsonb, '{"selected":"aisle"}'::jsonb, NULL, NULL, '''Aisle'' (/aɪl/) adalah lorong di antara rak-rak barang di supermarket maupun kursi pesawat.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000098', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Lengkapi daftar belanja berikut dengan satuan takaran cair khas AS: Can you pick up a ___ of milk on your way home?', '{"options":["gallon","meter","piece","slice"],"translation":"Bisakah kamu sekalian membeli satu galon susu dalam perjalanan pulang?","sentence_template":"Can you pick up a [blank] of milk on your way home?"}'::jsonb, '{"selected":"gallon"}'::jsonb, NULL, NULL, 'Susu segar di grocery store Amerika umumnya dijual dalam kemasan ''a gallon'' atau ''a half-gallon''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000099', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan petunjuk staf supermarket berikut. Di mana pembeli bisa menemukan kopi bubuk?', '{"options":[{"id":"opt_1","text":"Di dekat kasir pintu keluar utama"},{"id":"opt_2","text":"Di Lorong 7, tepat di sebelah teh dan sereal"},{"id":"opt_3","text":"Di lemari pendingin bagian produk susu"},{"id":"opt_4","text":"Stok kopi bubuk sedang habis hari ini"}],"audio_text":"Excuse me, where can I find ground coffee? — It''s in Aisle Seven, right next to the tea and cereal."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Staf mengarahkan dengan tepat: ''It''s in Aisle Seven, right next to the tea and cereal.''', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000100', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan percakapan teman sekamar sebelum belanja mingguan. Apa dua barang yang perlu mereka beli?', '{"options":[{"id":"opt_1","text":"Apel merah dan pisang"},{"id":"opt_2","text":"Pasta dan minyak zaitun untuk makan malam"},{"id":"opt_3","text":"Daging sapi dan kentang goreng"},{"id":"opt_4","text":"Sabun cuci piring dan tisu dapur"}],"audio_text":"Do we need any apples? — No, we still have plenty, but we need some pasta and olive oil for dinner."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Apel masih banyak (''still have plenty''), yang dibutuhkan adalah ''some pasta and olive oil''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000101', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun pertanyaan sopan di supermarket ini: "Permisi, di mana saya bisa menemukan roti gandum?"', '{"romaji":"/ɪkˈskjuːz miː, wer kæn aɪ faɪnd hoʊl wiːt bred/","tokens":["finding","bread?","I find","whole wheat","where can","breads?","Excuse me,"],"target_translation":"Permisi, di mana saya bisa menemukan roti gandum?"}'::jsonb, '["Excuse me,","where can","I find","whole wheat","bread?"]'::jsonb, NULL, NULL, 'Pola ''Where can I find [item]?'' adalah kalimat paling sopan dan alami kepada staf grocery store AS.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000102', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat belanjaan ini: "Saya butuh beberapa apel dan sebotol air."', '{"romaji":"/aɪ niːd sʌm ˈæpəlz ænd ə ˈbɑːtəl ʌv ˈwɔːtər/","tokens":["and a","waters.","some apples","bottle of","water.","any apples","I need"],"target_translation":"Saya butuh beberapa apel dan sebotol air."}'::jsonb, '["I need","some apples","and a","bottle of","water."]'::jsonb, NULL, NULL, 'Gunakan ''some apples'' untuk kalimat positif jamak dan ''a bottle of water'' untuk takaran air.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000103', 'e4100001-0000-4000-8000-000000000012', 'e2000001-0000-4000-8000-000000000003', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan lokasi barang di supermarket ini (ingat huruf s pada aisle senyap!): "Apakah sereal berada di Lorong Lima?"', '{"romaji":"/ɪz ðə ˈsɪriəl ɪn aɪl faɪv/","display_text":"Is the cereal in Aisle Five?","phonetic_breakdown":["ɪz","ðə","ˈsɪr-i-əl","ɪn","aɪl","faɪv"]}'::jsonb, '{"expected_transcript":"Is the cereal in Aisle Five?"}'::jsonb, NULL, NULL, 'Lafalkan ''Aisle Five'' persis seperti /aɪl faɪv/ tanpa membunyikan huruf ''s''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000104', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih kata tunjuk yang tepat untuk kacamata di dekatmu: How much are ___ reading glasses?', '{"options":["these","this","that","a"],"translation":"Berapa harga kacamata baca ini?","sentence_template":"How much are [blank] reading glasses?"}'::jsonb, '{"selected":"these"}'::jsonb, NULL, NULL, '''Glasses'' (kacamata berlensa dua) selalu jamak dalam bahasa Inggris sehingga memakai ''these''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000105', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih penentu jumlah yang tepat untuk kalimat tanya di toko: Do you have ___ oat milk in stock?', '{"options":["any","an","many","these"],"translation":"Apakah Anda memiliki stok susu oat?","sentence_template":"Do you have [blank] oat milk in stock?"}'::jsonb, '{"selected":"any"}'::jsonb, NULL, NULL, 'Pertanyaan ketersediaan untuk uncountable noun (''oat milk'') memakai ''any''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000106', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'reading', 'fill_blank', 'Pilih kata yang tepat untuk pembayaran tunai: Sorry, our card reader is down—can you pay ___ cash?', '{"options":["in","on","at","from"],"translation":"Maaf, mesin pembaca kartu kami sedang gangguan—bisakah Anda membayar tunai?","sentence_template":"Sorry, our card reader is down—can you pay [blank] cash?"}'::jsonb, '{"selected":"in"}'::jsonb, NULL, NULL, 'Kolokasi standar untuk membayar tunai adalah ''pay in cash'' (atau ''pay cash'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000107', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan pengumuman singkat di kasir toko buku kampus ini. Berapa harga buku bekas setelah diskon?', '{"options":[{"id":"opt_1","text":"Seratus dolar ($100)"},{"id":"opt_2","text":"Lima puluh dolar ($50), separuh dari harga buku baru"},{"id":"opt_3","text":"Lima belas dolar ($15)"},{"id":"opt_4","text":"Dua puluh lima dolar ($25)"}],"audio_text":"This used biology textbook is fifty dollars, which is half the price of a new copy."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Fifty dollars'' ($50) dengan tekanan pada suku kata pertama ''FIF-ty'', setengah harga dari buku baru.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000108', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'listening', 'listening_choice', 'Dengarkan dialog di bagian buah supermarket AS. Berapa berat pisang yang dibeli pelanggan?', '{"options":[{"id":"opt_1","text":"Sekitar dua pon (two pounds) pisang organik"},{"id":"opt_2","text":"Tujuh puluh sembilan buah pisang"},{"id":"opt_3","text":"Dua kilogram apel hijau"},{"id":"opt_4","text":"Satu galon jus pisang kemasan"}],"audio_text":"These organic bananas are seventy-nine cents a pound. Let''s get about two pounds for smoothies."}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Harga buah di AS dihitung per pon (''seventy-nine cents a pound''), dan pelanggan membeli ''two pounds''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000109', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat informasi diskon berikut: "Sepatu kets itu sedang diskon hari ini."', '{"romaji":"/ðoʊz ˈsniːkərz ɑːr ɑːn seɪl təˈdeɪ/","tokens":["sneakers","sale today.","is on","Those","That","are on"],"target_translation":"Sepatu kets itu sedang diskon hari ini."}'::jsonb, '["Those","sneakers","are on","sale today."]'::jsonb, NULL, NULL, 'Di AS, sepatu olahraga kasual disebut ''sneakers'' (jamak -> ''Those sneakers are on sale'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000110', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'writing', 'sentence_builder', 'Susun kalimat permintaan struk belanja: "Bolehkah saya minta struknya dikirim ke email?"', '{"romaji":"/kæn aɪ ɡet ðə rɪˈsiːt baɪ ˈiːmeɪl/","tokens":["by email?","get the","in email?","recipe","receipt","Can I"],"target_translation":"Bolehkah saya minta struknya dikirim ke email?"}'::jsonb, '["Can I","get the","receipt","by email?"]'::jsonb, NULL, NULL, 'Gunakan ''receipt'' untuk bukti bayar dan preposisi ''by email''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000111', 'e4100001-0000-4000-8000-000000000013', 'e2000001-0000-4000-8000-000000000003', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembayaran kasir ini dengan jelas: "Totalnya sembilan belas dolar lima puluh sen termasuk pajak."', '{"romaji":"/ðə ˈtoʊtəl ɪz ˌnaɪnˈtiːn ˈfɪfti ɪnˈkluːdɪŋ tæks/","display_text":"The total is nineteen fifty including tax.","phonetic_breakdown":["ðə","ˈtoʊ-təl","ɪz","ˌnaɪn-ˈtiːn","ˈfɪf-ti","ɪn-ˈkluː-dɪŋ","tæks"]}'::jsonb, '{"expected_transcript":"The total is nineteen fifty including tax."}'::jsonb, NULL, NULL, 'Kontraskan tekanan akhir ''nine-TEEN'' (19) dengan tekanan awal ''FIF-ty'' (50) secara tajam!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000112', 'e4100001-0000-4000-8000-000000000014', NULL, 'reading', 'fill_blank', 'Pilih jawaban khas Amerika jika Anda ingin membawa pulang pesanan kopi Anda: For here or ___? — To go, please.', '{"options":["to go","go home","out","bring"],"translation":"Makan di sini atau dibawa pulang? — Dibawa pulang, tolong.","sentence_template":"For here or [blank]? — To go, please."}'::jsonb, '{"selected":"to go"}'::jsonb, NULL, NULL, 'Pasangan tetap di kafe dan restoran AS adalah ''for here'' (makan di tempat) atau ''to go'' (bungkus).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000113', 'e4100001-0000-4000-8000-000000000014', NULL, 'reading', 'fill_blank', 'Pilih kata yang digunakan orang Amerika untuk meminta bon/tagihan selesai makan malam: Excuse me, could we get the ___, please?', '{"options":["check","note","paper","coin"],"translation":"Permisi, bolehkah kami meminta bon tagihannya?","sentence_template":"Excuse me, could we get the [blank], please?"}'::jsonb, '{"selected":"check"}'::jsonb, NULL, NULL, 'Di restoran AS, bon tagihan makan disebut ''the check''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000114', 'e4100001-0000-4000-8000-000000000014', NULL, 'reading', 'fill_blank', 'Pada buku menu restoran Amerika, bagian hidangan utama (main course) sering diberi judul ___.', '{"options":["Entrees","Appetizers","Beverages","Sides"],"translation":"Pada menu restoran Amerika, bagian hidangan utama sering disebut Entrees.","sentence_template":"On an American restaurant menu, the main course section is often called [blank]."}'::jsonb, '{"selected":"Entrees"}'::jsonb, NULL, NULL, 'Khusus di AS dan Kanada, ''Entrees'' merujuk pada hidangan utama, sedangkan makanan pembuka disebut ''Appetizers''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000115', 'e4100001-0000-4000-8000-000000000014', NULL, 'listening', 'listening_choice', 'Dengarkan pertanyaan barista di kedai kopi Portland ini. Apa kustomisasi minuman yang diminta pelanggan?', '{"options":[{"id":"opt_1","text":"Es kopi susu ukuran besar dengan ekstra karamel"},{"id":"opt_2","text":"Cappuccino panas ukuran kecil dengan susu almon tanpa gula"},{"id":"opt_3","text":"Teh hitam panas dengan irisan lemon dan madu"},{"id":"opt_4","text":"Cokelat panas dengan krim kocok untuk dua orang"}],"audio_text":"What can I get started for you? — Hi! Can I get a small hot cappuccino with almond milk, no sugar?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Barista membuka dengan kalimat khas AS ''What can I get started for you?'', dijawab ''a small hot cappuccino with almond milk, no sugar''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000116', 'e4100001-0000-4000-8000-000000000014', NULL, 'listening', 'listening_choice', 'Dengarkan pelayan restoran makan siang berikut. Hidangan pendamping (side) apa yang dipilih tamu?', '{"options":[{"id":"opt_1","text":"Sup tomat hangat"},{"id":"opt_2","text":"Kentang goreng renyah"},{"id":"opt_3","text":"Salad segar khas restoran (house salad)"},{"id":"opt_4","text":"Nasi merah kukus"}],"audio_text":"Your grilled salmon comes with soup or a house salad. Which side would you like? — I''ll have the house salad, please."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Tamu menjawab pilihan pendamping dengan ''I''ll have the house salad, please.''', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000117', 'e4100001-0000-4000-8000-000000000014', NULL, 'writing', 'sentence_builder', 'Susun kalimat meminta tagihan makan di restoran AS: "Bolehkah kami meminta bon tagihannya, tolong?"', '{"romaji":"/kʊd wiː ɡet ðə tʃek, pliːz/","tokens":["getting","Could we","checks","please?","get the","check,"],"target_translation":"Bolehkah kami meminta bon tagihannya, tolong?"}'::jsonb, '["Could we","get the","check,","please?"]'::jsonb, NULL, NULL, 'Ungkapan sopan standar seusai bersantap di restoran AS adalah ''Could we get the check, please?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000118', 'e4100001-0000-4000-8000-000000000014', NULL, 'writing', 'sentence_builder', 'Susun kalimat pesanan bawa pulang: "Dua es teh tanpa manis untuk dibawa pulang."', '{"romaji":"/tuː ʌnˈswiːtənd aɪst tiːz tə ɡoʊ, pliːz/","tokens":["for go,","iced teas","Two unsweetened","ice","please.","to go,"],"target_translation":"Dua es teh tanpa manis untuk dibawa pulang."}'::jsonb, '["Two unsweetened","iced teas","to go,","please."]'::jsonb, NULL, NULL, 'Di AS, es teh tawar disebut ''unsweetened iced tea'' (sedangkan ''sweet tea'' rasanya sangat manis).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000119', 'e4100001-0000-4000-8000-000000000014', NULL, 'speaking', 'speaking_repeat', 'Tirukan pelafalan kata dessert (hidangan penutup, tekanan di suku kata kedua!): "Apakah Anda ingin melihat menu hidangan penutup?"', '{"romaji":"/wʊd juː laɪk tə siː ðə dɪˈzɜːrt ˈmenjuː/","display_text":"Would you like to see the dessert menu?","phonetic_breakdown":["wʊd","juː","laɪk","tə","siː","ðə","dɪ-ˈzɜːrt","ˈmen-juː"]}'::jsonb, '{"expected_transcript":"Would you like to see the dessert menu?"}'::jsonb, NULL, NULL, 'Tekan suku kata kedua pada ''dessert'' (/dɪˈzɜːrt/ = makanan manis) agar tidak terdengar seperti ''desert'' (/ˈdezərt/ = gurun pasir)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000120', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Pilih pola paling sopan dan alami saat memesan kepada pelayan restoran: Are you ready to order? — Yes, ___ the grilled chicken salad, please.', '{"options":["I''ll have","I eat","Give me","I am like"],"translation":"Apakah Anda siap memesan? — Ya, saya pesan salad ayam panggang, tolong.","sentence_template":"Are you ready to order? — Yes, [blank] the grilled chicken salad, please."}'::jsonb, '{"selected":"I''ll have"}'::jsonb, NULL, NULL, '''I''ll have + [menu]'' adalah cara paling lazim penutur asli AS menyampaikan pesanan di meja makan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000121', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Bedakan tawaran saat ini dengan pertanyaan selera umum: ___ you like some extra napkins with your burger?', '{"options":["Would","Do","Are","Can"],"translation":"Apakah Anda ingin tambahan tisu makan untuk burger Anda?","sentence_template":"[blank] you like some extra napkins with your burger?"}'::jsonb, '{"selected":"Would"}'::jsonb, NULL, NULL, 'Untuk menawarkan sesuatu saat itu juga (''some extra napkins''), gunakan ''Would you like...?'' (bukan ''Do you like'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000122', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Lengkapi pesanan sopan menggunakan singkatan ''would'': ___ like to reserve a table for four at 7:00 p.m.', '{"options":["I''d","I''m","I''ve","I''ll"],"translation":"Saya ingin memesan meja untuk empat orang pada pukul 7 malam.","sentence_template":"[blank] like to reserve a table for four at 7:00 p.m."}'::jsonb, '{"selected":"I''d"}'::jsonb, NULL, NULL, '''I''d like to + V1'' adalah singkatan dari ''I would like to reserve''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000123', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan percakapan pelanggan yang memiliki pantangan makanan (dietary restriction) ini. Bahan apa yang tidak boleh ada di makanannya?', '{"options":[{"id":"opt_1","text":"Produk susu sapi (dairy)"},{"id":"opt_2","text":"Kacang tanah karena pelanggan alergi kacang"},{"id":"opt_3","text":"Tepung gandum dan gluten"},{"id":"opt_4","text":"Makanan laut seperti udang"}],"audio_text":"Excuse me, does the Thai noodle salad contain peanuts? I''m allergic to nuts. — Yes, it has crushed peanuts on top, but we can make it without them."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pelanggan menjelaskan ''I''m allergic to nuts'', dan pelayan menawarkan membuatnya tanpa taburan kacang (''without them'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000124', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan obrolan teman saat membayar makan siang bersama di AS. Bagaimana cara mereka membayar tagihannya?', '{"options":[{"id":"opt_1","text":"Satu orang mentraktir seluruh makanan"},{"id":"opt_2","text":"Membagi tagihan sama rata (split evenly), masing-masing $18 per kartu"},{"id":"opt_3","text":"Membayar menggunakan kupon diskon kantor"},{"id":"opt_4","text":"Meminta tagihan dikirim ke kamar hotel"}],"audio_text":"The check is thirty-six dollars total. Should we split it evenly? — Sure, let''s put eighteen dollars on each card."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Split the check'' (patungan bayar masing-masing) sangat wajar dan lazim di kalangan teman maupun rekan kerja di AS.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000125', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat pemesanan sopan di konter kafe: "Bolehkah saya pesan teh hijau dingin ukuran sedang?"', '{"romaji":"/kæn aɪ ɡet ə ˈmiːdiəm aɪst ɡriːn tiː, pliːz/","tokens":["getting","for get","green tea,","please?","medium iced","get a","Can I"],"target_translation":"Bolehkah saya pesan teh hijau dingin ukuran sedang?"}'::jsonb, '["Can I","get a","medium iced","green tea,","please?"]'::jsonb, NULL, NULL, 'Urutan ukuran + suhu + jenis minuman: ''a medium iced green tea''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000126', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun pertanyaan alergi/preferensi makanan: "Apakah sup hari ini mengandung produk susu?"', '{"romaji":"/dʌz təˈdeɪz suːp hæv ˈeni ˈderi ɪn ɪt/","tokens":["any dairy","in it?","soup have","some","has","Does today''s"],"target_translation":"Apakah sup hari ini mengandung produk susu?"}'::jsonb, '["Does today''s","soup have","any dairy","in it?"]'::jsonb, NULL, NULL, 'Istilah ''dairy'' di menu AS mencakup susu sapi, keju, mentega, dan krim.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000127', 'e4100001-0000-4000-8000-000000000015', 'e2000001-0000-4000-8000-000000000004', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pemesanan restoran ini dengan lancar: "Saya pesan pasta tomat dengan salad pendamping, tolong."', '{"romaji":"/aɪl hæv ðə təˈmeɪtoʊ ˈpɑːstə wɪð ə saɪd ˈsæləd, pliːz/","display_text":"I''ll have the tomato pasta with a side salad, please.","phonetic_breakdown":["aɪl","hæv","ðə","tə-ˈmeɪ-toʊ","ˈpɑːs-tə","wɪð","ə","saɪd","ˈsæ-ləd","pliːz"]}'::jsonb, '{"expected_transcript":"I''ll have the tomato pasta with a side salad, please."}'::jsonb, NULL, NULL, 'Perhatikan lafal khas Amerika untuk ''tomato'': /təˈmeɪtoʊ/ (bunyi tengah /eɪ/, bukan /ɑː/ seperti di Inggris)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000128', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Pilih frasa yang tepat agar saus salad disajikan terpisah di wadah kecil: Could I get the Caesar salad with the dressing ___?', '{"options":["on the side","in the bag","at the door","by cash"],"translation":"Bolehkah saya pesan salad Caesar dengan saus terpisah?","sentence_template":"Could I get the Caesar salad with the dressing [blank]?"}'::jsonb, '{"selected":"on the side"}'::jsonb, NULL, NULL, '''On the side'' berarti disajikan terpisah di piring/mangkuk kecil di samping hidangan utama.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000129', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Pilih preposisi yang tepat untuk menghilangkan bahan makanan tertentu: I''d like a cheeseburger ___ onions, please.', '{"options":["without","with no any","not","outside"],"translation":"Saya ingin burger keju tanpa bawang bombai, tolong.","sentence_template":"I''d like a cheeseburger [blank] onions, please."}'::jsonb, '{"selected":"without"}'::jsonb, NULL, NULL, 'Preposisi ''without + kata benda'' adalah cara tercepat menyampaikan bahan yang tidak diinginkan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000130', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Porsi pasta Anda masih tersisa setengah dan ingin dibawa pulang. Anda meminta: Could I get a ___ box, please?', '{"options":["to-go","check","refill","tip"],"translation":"Bolehkah saya minta kotak bungkus untuk dibawa pulang?","sentence_template":"Could I get a [blank] box, please?"}'::jsonb, '{"selected":"to-go"}'::jsonb, NULL, NULL, '''A to-go box'' (atau ''container'') digunakan untuk mengemas sisa hidangan restoran.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000131', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan percakapan makan siang tim kantor di Chicago ini. Apa preferensi menu rekan kerja dari Indonesia?', '{"options":[{"id":"opt_1","text":"Ia hanya makan roti manis dan kopi"},{"id":"opt_2","text":"Ia menanyakan pilihan menu halal atau hidangan laut (seafood)"},{"id":"opt_3","text":"Ia memesan steik daging sapi setengah matang"},{"id":"opt_4","text":"Ia sudah membawa bekal sendiri dari rumah"}],"audio_text":"Does this restaurant have halal or seafood dishes? — Yes! Their grilled salmon and shrimp tacos are super popular."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pertanyaan ''Does this restaurant have halal or seafood dishes?'' sangat wajar dan sopan saat makan bersama rekan kerja di AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000132', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan pelayan kafe memanggil pesanan pelanggan berikut. Pesanan siapa yang sudah siap di meja pengambilan?', '{"options":[{"id":"opt_1","text":"Kopi hitam panas milik Ryan di meja nomor empat"},{"id":"opt_2","text":"Es matcha latte besar dengan susu oat dan sedikit es milik Rina di konter pengambilan"},{"id":"opt_3","text":"Jus jeruk segar milik Nina untuk diantar ke luar"},{"id":"opt_4","text":"Teh chamomile hangat tanpa es milik Tina"}],"audio_text":"Order for Rina! One large iced matcha latte with oat milk and light ice at the pickup counter!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di kafe AS, barista memanggil nama depan pelanggan (''Order for Rina!'') di area ''pickup counter''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000133', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun pertanyaan sopan menanyakan menu vegetarian: "Apakah Anda memiliki pilihan menu vegetarian hari ini?"', '{"romaji":"/də juː hæv ˈeni ˌvedʒəˈteriən ˈɑːpʃənz təˈdeɪ/","tokens":["option","have any","some","Do you","vegetarian","options today?"],"target_translation":"Apakah Anda memiliki pilihan menu vegetarian hari ini?"}'::jsonb, '["Do you","have any","vegetarian","options today?"]'::jsonb, NULL, NULL, 'Gunakan ''Do you have any [plural noun]?'' untuk menanyakan ketersediaan pilihan menu.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000134', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat kustomisasi minuman es: "Bolehkah saya pesan es kopi dengan sedikit es?"', '{"romaji":"/kæn aɪ ɡet ən aɪst ˈkɔːfi wɪð laɪt aɪs/","tokens":["with light","lights","Can I","get an","a iced","ice?","iced coffee"],"target_translation":"Bolehkah saya pesan es kopi dengan sedikit es?"}'::jsonb, '["Can I","get an","iced coffee","with light","ice?"]'::jsonb, NULL, NULL, 'Pakai artikel ''an'' sebelum ''iced coffee'' karena diawali bunyi vokal /aɪ/, dan ''light ice'' untuk es sedikit.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000135', 'e4100001-0000-4000-8000-000000000016', 'e2000001-0000-4000-8000-000000000004', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup makan bersama rekan kerja ini: "Apakah kita bagi rata saja tagihan makannya?"', '{"romaji":"/ʃʊd wiː dʒʌst splɪt ðə tʃek ˈiːvənli/","display_text":"Should we just split the check evenly?","phonetic_breakdown":["ʃʊd","wiː","dʒʌst","splɪt","ðə","tʃek","ˈiː-vən-li"]}'::jsonb, '{"expected_transcript":"Should we just split the check evenly?"}'::jsonb, NULL, NULL, 'Huruf ''l'' pada ''should'' (/ʃʊd/) tidak dibunyikan sama sekali!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000136', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Pilih kalimat pemesanan paling alami kepada pelayan restoran: ___ the mushroom risotto and iced water, please.', '{"options":["I''ll have","I am want","Give to me","I having"],"translation":"Saya pesan risotto jamur dan air es, tolong.","sentence_template":"[blank] the mushroom risotto and iced water, please."}'::jsonb, '{"selected":"I''ll have"}'::jsonb, NULL, NULL, '''I''ll have...'' adalah standar kesopanan alami saat memesan di restoran AS.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000137', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Pilih istilah AS untuk isi ulang minuman gratis di restoran kasual: Good news—iced tea comes with free ___ here!', '{"options":["refills","receipts","checks","tips"],"translation":"Kabar baik—es teh di sini mendapat isi ulang gratis!","sentence_template":"Good news—iced tea comes with free [blank] here!"}'::jsonb, '{"selected":"refills"}'::jsonb, NULL, NULL, '''Free refills'' berarti gelas minuman Anda bisa diisi penuh kembali tanpa biaya tambahan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000138', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'reading', 'fill_blank', 'Lengkapi tawaran sopan tuan rumah makan malam: ___ you like a cup of decaf coffee after dinner?', '{"options":["Would","Do","Are","Have"],"translation":"Apakah Anda ingin secangkir kopi tanpa kafein setelah makan malam?","sentence_template":"[blank] you like a cup of decaf coffee after dinner?"}'::jsonb, '{"selected":"Would"}'::jsonb, NULL, NULL, '''Would you like...?'' menawarkan sesuatu saat ini (''decaf'' = kopi rendah/tanpa kafein).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000139', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan percakapan pelanggan saat membayar di layar tablet kasir AS. Berapa persen tip yang dipilih?', '{"options":[{"id":"opt_1","text":"Tidak memberi tip sama sekali"},{"id":"opt_2","text":"Memberi tip sebesar dua puluh persen (20%) karena pelayanannya memuaskan"},{"id":"opt_3","text":"Meminta diskon dua puluh persen kepada manajer"},{"id":"opt_4","text":"Membayar denda keterlambatan reservasi"}],"audio_text":"The food and service were awesome! Let''s leave a twenty percent tip on the check."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di restoran meja AS, tip 18%–20% diberikan ketika pelayanan dinilai sangat baik.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000140', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'listening', 'listening_choice', 'Dengarkan pesanan sarapan di diner Amerika ini. Bagaimana cara telur dimasak sesuai permintaan pelanggan?', '{"options":[{"id":"opt_1","text":"Telur rebus bulat dan roti putih dibungkus pulang"},{"id":"opt_2","text":"Dua telur orak-arik (scrambled eggs), roti panggang gandum, dan kopi hitam makan di tempat"},{"id":"opt_3","text":"Panekuk manis dengan sirup maple dan susu dingin"},{"id":"opt_4","text":"Bubur gandum dengan potongan buah beri"}],"audio_text":"I''d like two scrambled eggs, whole wheat toast, and black coffee for here, please."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Scrambled eggs'' berarti telur orak-arik, disajikan ''for here'' (makan di tempat).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000141', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat kustomisasi saus terpisah: "Saya ingin pesan salad ayam dengan saus terpisah."', '{"romaji":"/aɪd laɪk ðə ˈtʃɪkɪn ˈsæləd wɪð ˈdresɪŋ ɑːn ðə saɪd/","tokens":["would","dressing on","I''d like","the side.","the chicken","in the side.","salad with"],"target_translation":"Saya ingin pesan salad ayam dengan saus terpisah."}'::jsonb, '["I''d like","the chicken","salad with","dressing on","the side."]'::jsonb, NULL, NULL, 'Kombinasikan ''I''d like'' dengan frasa ''dressing on the side''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000142', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'writing', 'sentence_builder', 'Susun kalimat meminta kotak bungkus dan bon sekaligus: "Bolehkah kami minta kotak bungkus dan bon tagihannya?"', '{"romaji":"/kʊd wiː ɡet ə təˈɡoʊ bɑːks ænd ðə tʃek/","tokens":["check?","and the","to-go box","get a","Could we","bill","for-go"],"target_translation":"Bolehkah kami minta kotak bungkus dan bon tagihannya?"}'::jsonb, '["Could we","get a","to-go box","and the","check?"]'::jsonb, NULL, NULL, 'Menggabungkan permintaan ''a to-go box and the check'' menghemat waktu pelayan di akhir makan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000143', 'e4100001-0000-4000-8000-000000000017', 'e2000001-0000-4000-8000-000000000004', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konfirmasi alergi makanan ini dengan tegas dan sopan: "Saya alergi kacang, jadi mohon tanpa saus kacang."', '{"romaji":"/aɪm əˈlɜːrdʒɪk tə ˈpiːnʌts, soʊ noʊ ˈpiːnʌt sɔːs, pliːz/","display_text":"I''m allergic to peanuts, so no peanut sauce, please.","phonetic_breakdown":["aɪm","ə-ˈlɜːr-dʒɪk","tə","ˈpiː-nʌts","soʊ","noʊ","ˈpiː-nʌt","sɔːs","pliːz"]}'::jsonb, '{"expected_transcript":"I''m allergic to peanuts, so no peanut sauce, please."}'::jsonb, NULL, NULL, 'Tekankan suku kata kedua pada ''allergic'' (/əˈlɜːrdʒɪk/) agar staf dapur menangkap pesan keselamatanmu dengan jelas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000144', 'e4100001-0000-4000-8000-000000000018', NULL, 'reading', 'fill_blank', 'Pilih kosakata khas Amerika untuk ''trotoar tempat pejalan kaki'': Please stay on the ___ because the bike lane is busy.', '{"options":["sidewalk","elevator","highway","runway"],"translation":"Mohon tetap berjalan di trotoar karena jalur sepedanya sedang ramai.","sentence_template":"Please stay on the [blank] because the bike lane is busy."}'::jsonb, '{"selected":"sidewalk"}'::jsonb, NULL, NULL, '''Sidewalk'' adalah trotoar pejalan kaki di pinggir jalan raya dalam American English.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000145', 'e4100001-0000-4000-8000-000000000018', NULL, 'reading', 'fill_blank', 'Pilih preposisi khas AS yang berarti ''di seberang'': The subway entrance is right ___ from the public library.', '{"options":["across","next","between","under"],"translation":"Pintu masuk kereta bawah tanah berada tepat di seberang perpustakaan umum.","sentence_template":"The subway entrance is right [blank] from the public library."}'::jsonb, '{"selected":"across"}'::jsonb, NULL, NULL, 'Pasangan preposisi ''across from'' berarti ''berhadapan / di seberang jalan dari''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000146', 'e4100001-0000-4000-8000-000000000018', NULL, 'reading', 'fill_blank', 'Pilih satuan jarak jalan kaki yang lazim dipakai warga kota AS: The hotel isn''t far—it''s just three ___ down this avenue.', '{"options":["blocks","floors","gates","aisles"],"translation":"Hotelnya tidak jauh—hanya tiga blok menyusuri jalan raya ini.","sentence_template":"The hotel isn''t far—it''s just three [blank] down this avenue."}'::jsonb, '{"selected":"blocks"}'::jsonb, NULL, NULL, 'Warga kota AS mengukur jarak jalan kaki antar-perempatan jalan dengan satuan ''blocks''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000147', 'e4100001-0000-4000-8000-000000000018', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perubahan gerbang di Bandara Internasional Los Angeles (LAX) ini. Ke gerbang manakah penumpang tujuan Seattle harus pindah?', '{"options":[{"id":"opt_1","text":"Tetap menunggu di Gate A8"},{"id":"opt_2","text":"Pindah ke Gate B19 untuk penerbangan 402 tujuan Seattle"},{"id":"opt_3","text":"Menuju area pengambilan bagasi di lantai satu"},{"id":"opt_4","text":"Penerbangan 402 ditunda hingga besok pagi"}],"audio_text":"Attention passengers on Flight 402 to Seattle: your departure gate has changed from Gate A8 to Gate B19."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Frasa ''changed from Gate A8 to Gate B19'' memberi tahu gerbang keberangkatan baru yaitu B19.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000148', 'e4100001-0000-4000-8000-000000000018', NULL, 'listening', 'listening_choice', 'Dengarkan petunjuk arah dari petugas keamanan kampus berikut. Bagaimana cara menuju Gedung Sains?', '{"options":[{"id":"opt_1","text":"Belok kiri sebelum air mancur lalu naik bus"},{"id":"opt_2","text":"Jalan lurus melewati air mancur sejauh dua blok; gedungnya di sebelah kanan dekat toko buku"},{"id":"opt_3","text":"Naik lift ke lantai empat gedung perpustakaan"},{"id":"opt_4","text":"Keluar gerbang utama dan menyeberangi jembatan"}],"audio_text":"Go straight past the fountain, walk two blocks, and the Science Building will be on your right, next to the bookstore."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Past the fountain, walk two blocks, on your right, next to the bookstore'' merinci rute langkah demi langkah.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
