INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000150', 'e4100001-0000-4000-8000-000000000018', NULL, 'writing', 'sentence_builder', 'Susun kalimat petunjuk arah jalan ini: "Jalan lurus dua blok lalu belok kiri."', '{"romaji":"/wɔːk streɪt tuː blɑːks ænd tɜːrn left/","tokens":["turns","block","Walk straight","two blocks","and turn","left."],"target_translation":"Jalan lurus dua blok lalu belok kiri."}'::jsonb, '["Walk straight","two blocks","and turn","left."]'::jsonb, NULL, NULL, 'Kalimat petunjuk arah menggunakan bentuk perintah dasar (imperative V1: ''Walk straight ... and turn left'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000151', 'e4100001-0000-4000-8000-000000000018', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan arah di gedung kantor AS ini: "Di mana letak lift menuju lantai dua?"', '{"romaji":"/wer ɪz ðə ˈelɪveɪtər tə ðə ˈsekənd flɔːr/","display_text":"Where is the elevator to the second floor?","phonetic_breakdown":["wer","ɪz","ðə","ˈe-lɪ-veɪ-tər","tə","ðə","ˈse-kənd","flɔːr"]}'::jsonb, '{"expected_transcript":"Where is the elevator to the second floor?"}'::jsonb, NULL, NULL, 'Gunakan kata AS ''elevator'' (/ˈelɪveɪtər/) dengan tekanan kuat di suku kata pertama ''EL-''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000152', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'reading', 'fill_blank', 'Pilih pola keberadaan yang tepat untuk menanyakan satu fasilitas tunggal: Excuse me, ___ there an ATM inside this terminal?', '{"options":["is","are","have","do"],"translation":"Permisi, apakah ada mesin ATM di dalam terminal ini?","sentence_template":"Excuse me, [blank] there an ATM inside this terminal?"}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, '''An ATM'' berbentuk tunggal, sehingga pertanyaan keberadaannya dimulai dengan ''Is there...?''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000153', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'reading', 'fill_blank', 'Pilih preposisi yang benar saat turun dari kereta bawah tanah: Take the Red Line for three stops and get ___ at Harvard Square.', '{"options":["off","out","down","away"],"translation":"Naik Jalur Merah selama tiga pemberhentian lalu turun di Harvard Square.","sentence_template":"Take the Red Line for three stops and get [blank] at Harvard Square."}'::jsonb, '{"selected":"off"}'::jsonb, NULL, NULL, 'Untuk kereta, bus, dan pesawat, ''turun dari kendaraan'' selalu memakai phrasal verb ''get off''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000154', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'reading', 'fill_blank', 'Lengkapi kalimat keberadaan jamak di bandara: ___ several charging stations right next to Gate D5.', '{"options":["There are","There is","It has","They is"],"translation":"Ada beberapa stasiun pengisian daya tepat di sebelah Gate D5.","sentence_template":"[blank] several charging stations right next to Gate D5."}'::jsonb, '{"selected":"There are"}'::jsonb, NULL, NULL, 'Kata benda jamak ''several charging stations'' membutuhkan ''There are''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000155', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'listening', 'listening_choice', 'Dengarkan saran penumpang lokal di stasiun subway New York ini. Mengapa pembicara menyarankan naik kereta ekspres (express train)?', '{"options":[{"id":"opt_1","text":"Karena kereta lokal sedang mogok total"},{"id":"opt_2","text":"Karena kereta A Express jauh lebih cepat sampai ke Midtown hanya dalam 10 menit"},{"id":"opt_3","text":"Karena tiket kereta ekspres gratis hari ini"},{"id":"opt_4","text":"Karena stasiun Midtown sedang ditutup sementara"}],"audio_text":"Don''t get on the local train—it stops at every station. Take the A Express train across the platform; it gets to Midtown in ten minutes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di NYC Subway, ''local train'' berhenti di tiap stasiun kecil, sedangkan ''express train'' melompati stasiun kecil sehingga tiba jauh lebih cepat.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000156', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'listening', 'listening_choice', 'Dengarkan percakapan pengemudi rideshare (Uber/Lyft) lewat telepon di bandara. Di mana titik penjemputannya?', '{"options":[{"id":"opt_1","text":"Di lantai Keberangkatan dekat konter tiket maskapai"},{"id":"opt_2","text":"Di lantai Kedatangan (Arrivals level), tepat di dekat Pilar Empat"},{"id":"opt_3","text":"Di lapangan parkir gedung seberang jalan tol"},{"id":"opt_4","text":"Di dalam stasiun kereta bawah tanah"}],"audio_text":"Hi, I''m your driver in a silver Toyota Prius. Rideshare pickup is on the Arrivals level, right by Pillar Four."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Bandara AS memiliki zona khusus ''Rideshare pickup''; pengemudi menunggu ''on the Arrivals level, right by Pillar Four''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000157', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'writing', 'sentence_builder', 'Susun pertanyaan mencari apotek terdekat: "Apakah ada apotek di sekitar sini?"', '{"romaji":"/ɪz ðer ə ˈfɑːrməsi əˈraʊnd hɪr/","tokens":["here?","a pharmacy","Is there","Have","around","Are there"],"target_translation":"Apakah ada apotek di sekitar sini?"}'::jsonb, '["Is there","a pharmacy","around","here?"]'::jsonb, NULL, NULL, '''Is there a [place] around here?'' wajib dikuasai saat bepergian di kota mana pun di AS.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000158', 'e4100001-0000-4000-8000-000000000019', 'e2000001-0000-4000-8000-000000000005', 'writing', 'sentence_builder', 'Susun instruksi naik jalur kereta ke pusat kota: "Naik Jalur Hijau ke pusat kota lalu turun di Park Street."', '{"romaji":"/teɪk ðə ɡriːn laɪn ˈdaʊntaʊn ænd ɡet ɔːf æt pɑːrk striːt/","tokens":["get out","takes","Take the","Green Line","get off","at Park Street.","downtown and"],"target_translation":"Naik Jalur Hijau ke pusat kota lalu turun di Park Street."}'::jsonb, '["Take the","Green Line","downtown and","get off","at Park Street."]'::jsonb, NULL, NULL, 'Perhatikan kata ''downtown'' langsung mengikuti kata kerja gerak tanpa preposisi ''to'' (''go downtown'' / ''take the train downtown'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
