INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000163', 'e4100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000005', 'listening', 'listening_choice', 'Dengarkan pertanyaan petugas imigrasi AS di Bandara JFK ini. Untuk keperluan apa mahasiswa tersebut datang ke AS?', '{"options":[{"id":"opt_1","text":"Berlibur musim dingin selama satu minggu"},{"id":"opt_2","text":"Memulai kuliah tahun pertama (freshman year) di Columbia University dengan dokumen I-20"},{"id":"opt_3","text":"Menghadiri pameran otomotif internasional"},{"id":"opt_4","text":"Transit tiga jam sebelum terbang ke Kanada"}],"audio_text":"Welcome to New York. What''s the purpose of your visit today? — I''m starting my freshman year at Columbia University. Here is my I-20 form."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di AS, mahasiswa S1 tahun pertama disebut ''freshman'', dan ''I-20 form'' adalah dokumen resmi visa pelajar F-1 di AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000164', 'e4100001-0000-4000-8000-000000000020', 'e2000001-0000-4000-8000-000000000005', 'listening', 'listening_choice', 'Dengarkan instruksi petugas keamanan TSA di jalur pemindai sinar-X berikut. Apa dua benda yang harus dilepas atau diletakkan ke baki (bin)?', '{"options":[{"id":"opt_1","text":"Kacamata baca dan paspor"},{"id":"opt_2","text":"Ikat pinggang (belt) dan laptop diletakkan mendatar di baki abu-abu"},{"id":"opt_3","text":"Kaos kaki dan topi musim dingin"},{"id":"opt_4","text":"Buku catatan kertas dan bantal leher"}],"audio_text":"Folks, please empty your pockets and place your belt and laptop flat in a gray bin!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Petugas TSA sering menyapa antrean dengan kata akrab ''Folks'' dan meminta ''place your belt and laptop flat in a gray bin''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
