INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000177', 'e4100001-0000-4000-8000-000000000022', NULL, 'reading', 'fill_blank', 'Hati-hati dengan bunyi awal kata ''university'': Her brother is a professor at ___ university in Michigan.', '{"options":["a","an","any","these"],"translation":"Saudara laki-lakinya adalah seorang profesor di sebuah universitas di Michigan.","sentence_template":"Her brother is a professor at [blank] university in Michigan."}'::jsonb, '{"selected":"a"}'::jsonb, NULL, NULL, 'Meskipun diawali huruf u, ''university'' berbunyi awal konsonan /juː/, sehingga memakai ''a university''!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000178', 'e4100001-0000-4000-8000-000000000022', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang mencakup kakak maupun adik kandung: Do you have any ___, or are you an only child?', '{"options":["siblings","coworkers","neighbors","managers"],"translation":"Apakah kamu punya saudara kandung, atau kamu anak tunggal?","sentence_template":"Do you have any [blank], or are you an only child?"}'::jsonb, '{"selected":"siblings"}'::jsonb, NULL, NULL, '''Siblings'' merujuk pada saudara kandung, sedangkan ''an only child'' berarti anak tunggal.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000179', 'e4100001-0000-4000-8000-000000000022', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan santai saat makan siang tim berikut. Apa pekerjaan istri Pak Ramirez?', '{"options":[{"id":"opt_1","text":"Arsitek lanskap di balai kota"},{"id":"opt_2","text":"Dokter gigi anak di Rumah Sakit Anak Seattle"},{"id":"opt_3","text":"Analis keuangan di bank investasi"},{"id":"opt_4","text":"Guru musik di sekolah dasar"}],"audio_text":"What does your wife do, Carlos? — She''s a pediatric dentist at Seattle Children''s Hospital."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Pediatric dentist'' berarti dokter gigi spesialis anak.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000180', 'e4100001-0000-4000-8000-000000000022', NULL, 'listening', 'listening_choice', 'Dengarkan cerita mahasiswa tentang keluarganya di Indonesia. Berapa saudara kandung yang ia miliki?', '{"options":[{"id":"opt_1","text":"Ia adalah anak tunggal tanpa saudara kandung"},{"id":"opt_2","text":"Dua saudara kandung: satu kakak laki-laki dan satu adik perempuan"},{"id":"opt_3","text":"Tiga kakak laki-laki yang tinggal di Amerika"},{"id":"opt_4","text":"Dua adik laki-laki kembar"}],"audio_text":"I have one older brother who works in Jakarta and one younger sister who''s still in high school."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''One older brother'' (1 kakak laki-laki) + ''one younger sister'' (1 adik perempuan) = 2 saudara kandung.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000181', 'e4100001-0000-4000-8000-000000000022', NULL, 'writing', 'sentence_builder', 'Susun kalimat profesi dengan artikel yang benar: "Paman saya adalah seorang insinyur perangkat lunak di Austin."', '{"romaji":"/maɪ ˈʌŋkəl ɪz ə ˈsɔːftwer ˌendʒɪˈnɪr ɪn ˈɔːstɪn/","tokens":["is an","My uncle","software engineer","in Austin.","engineers","is a"],"target_translation":"Paman saya adalah seorang insinyur perangkat lunak di Austin."}'::jsonb, '["My uncle","is a","software engineer","in Austin."]'::jsonb, NULL, NULL, 'Karena kata sifat/benda pertama setelah artikel adalah ''software'' (bunyi konsonan /s/), gunakan ''a software engineer''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000182', 'e4100001-0000-4000-8000-000000000022', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan tentang saudara kandung: "Apakah kamu punya kakak atau adik?"', '{"romaji":"/də juː hæv ˈeni ˈsɪblɪŋz/","tokens":["Are you","siblings?","sibling?","have","any","Do you"],"target_translation":"Apakah kamu punya kakak atau adik?"}'::jsonb, '["Do you","have","any","siblings?"]'::jsonb, NULL, NULL, 'Pola alami menanyakan jumlah saudara kandung adalah ''Do you have any siblings?''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000183', 'e4100001-0000-4000-8000-000000000022', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat tempat kerja ini dengan artikulasi jelas: "Kakak perempuan saya bekerja di perusahaan teknologi di Seattle."', '{"romaji":"/maɪ ˈoʊldər ˈsɪstər wɜːrks fɔːr ə tek ˈkʌmpəni ɪn siˈætəl/","display_text":"My older sister works for a tech company in Seattle.","phonetic_breakdown":["maɪ","ˈoʊl-dər","ˈsɪs-tər","wɜːrks","fɔːr","ə","tek","ˈkʌm-pə-ni","ɪn","si-ˈæ-təl"]}'::jsonb, '{"expected_transcript":"My older sister works for a tech company in Seattle."}'::jsonb, NULL, NULL, 'Gunakan ''works for + [jenis/nama perusahaan]'' dan ''in + [nama kota]''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000184', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih kata tanya kepemilikan yang tepat saat menemukan pengisi daya di ruang rapat: ___ laptop charger is this?', '{"options":["Whose","Who''s","Who","Where"],"translation":"Pengisi daya laptop milik siapa ini?","sentence_template":"[blank] laptop charger is this?"}'::jsonb, '{"selected":"Whose"}'::jsonb, NULL, NULL, '''Whose'' digunakan sebelum kata benda (''laptop charger'') untuk menanyakan pemilik, sedangkan ''Who''s'' adalah singkatan ''Who is''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000185', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih ejaan kepemilikan yang tepat untuk perusahaan/benda (tanpa apostrof!): The startup launched ___ new mobile app this morning.', '{"options":["its","it''s","his","their''s"],"translation":"Perusahaan rintisan itu meluncurkan aplikasi seluler barunya pagi ini.","sentence_template":"The startup launched [blank] new mobile app this morning."}'::jsonb, '{"selected":"its"}'::jsonb, NULL, NULL, 'Kepemilikan untuk benda/entitas tunggal menggunakan ''its'' (tanpa tanda petik); ''it''s'' selalu berarti ''it is'' atau ''it has''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000186', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih bentuk kepemilikan apostrof yang benar: Have you seen ___ presentation slides?', '{"options":["Maya''s","Mayas","of Maya","slides Maya"],"translation":"Apakah kamu sudah melihat slide presentasi milik Maya?","sentence_template":"Have you seen [blank] presentation slides?"}'::jsonb, '{"selected":"Maya''s"}'::jsonb, NULL, NULL, 'Nama pemilik tunggal diikuti `''s` sebelum benda yang dimiliki (''Maya''s presentation slides'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000187', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan kerja yang merapikan ruang rapat. Buku catatan milik siapakah yang tertinggal di meja?', '{"options":[{"id":"opt_1","text":"Milik Sam karena bukunya berwarna hitam"},{"id":"opt_2","text":"Milik Rachel dari rapat pukul sepuluh tadi"},{"id":"opt_3","text":"Milik petugas kebersihan gedung"},{"id":"opt_4","text":"Buku inventaris gratis milik ruang rapat"}],"audio_text":"Is this your black notebook, Sam? — No, mine is blue. I think that''s Rachel''s notebook from the ten o''clock meeting."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Sam menjelaskan bukunya biru (''mine is blue'') dan buku hitam itu adalah ''Rachel''s notebook''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000188', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan penjelasan struktur tim di kantor cabang Denver ini. Siapa nama manajer pemasaran mereka?', '{"options":[{"id":"opt_1","text":"Ibu Rachel di kantor pusat New York"},{"id":"opt_2","text":"Pak Brooks di kantor cabang Denver"},{"id":"opt_3","text":"Pak Sam di kantor San Jose"},{"id":"opt_4","text":"Posisi manajer pemasaran masih kosong"}],"audio_text":"Our engineering lead is based in San Jose, and our team''s marketing manager is Mr. Brooks here in Denver."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Our team''s marketing manager is Mr. Brooks here in Denver'' menyebutkan peran dan lokasinya dengan jelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000189', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat kepemilikan keluarga ini: "Kantor saudara laki-laki saya berada di dekat Central Park."', '{"romaji":"/maɪ ˈbrʌðərz ˈɔːfɪs ɪz nɪr ˈsentrəl pɑːrk/","tokens":["is near","are near","My brother''s","office","office brother","Central Park."],"target_translation":"Kantor saudara laki-laki saya berada di dekat Central Park."}'::jsonb, '["My brother''s","office","is near","Central Park."]'::jsonb, NULL, NULL, 'Taruh pemilik + ''s di depan benda (''My brother''s office'') dan gunakan kata kerja tunggal ''is''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000190', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun pertanyaan menanyakan pemilik kartu identitas: "Kartu mahasiswa milik siapa yang ada di meja ini?"', '{"romaji":"/huːz ˈstuːdənt ˌaɪˈdiː ɪz ɑːn ðɪs desk/","tokens":["Who''s","this desk?","is on","Whose","student ID","are on"],"target_translation":"Kartu mahasiswa milik siapa yang ada di meja ini?"}'::jsonb, '["Whose","student ID","is on","this desk?"]'::jsonb, NULL, NULL, '''Whose student ID'' adalah satu kesatuan frasa tanya diikuti ''is on this desk?''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000191', 'e4100001-0000-4000-8000-000000000023', 'e2000001-0000-4000-8000-000000000006', 'speaking', 'speaking_repeat', 'Ucapkan kalimat ini untuk membedakan bunyi kepemilikan: " itu meja kerja rekan saya, dan meja saya di sebelah jendela."', '{"romaji":"/ðæts maɪ ˈkoʊwɜːrkərz desk, ænd maɪn ɪz baɪ ðə ˈwɪndoʊ/","display_text":"That''s my coworker''s desk, and mine is by the window.","phonetic_breakdown":["ðæts","maɪ","ˈkoʊ-wɜːr-kərz","desk","ænd","maɪn","ɪz","baɪ","ðə","ˈwɪn-doʊ"]}'::jsonb, '{"expected_transcript":"That''s my coworker''s desk, and mine is by the window."}'::jsonb, NULL, NULL, 'Kata ''mine'' (milikku, berdiri sendiri tanpa benda sesudahnya) menghindari pengulangan kata ''my desk''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000192', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih preposisi khas AS untuk menyatakan keanggotaan dalam suatu tim kerja: Hi Leo! What team are you ___ here at Stripe?', '{"options":["on","at","by","to"],"translation":"Hai Leo! Kamu berada di tim apa di Stripe?","sentence_template":"Hi Leo! What team are you [blank] here at Stripe?"}'::jsonb, '{"selected":"on"}'::jsonb, NULL, NULL, 'Dalam American English, preposisi standar untuk ''team'' adalah ''on'' (''on the design team'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000193', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Lengkapi kalimat untuk menyatakan kota tempat Anda berkantor: Our product designer is ___ in Austin, Texas.', '{"options":["based","basing","base","bases"],"translation":"Desainer produk kami berbasis di Austin, Texas.","sentence_template":"Our product designer is [blank] in Austin, Texas."}'::jsonb, '{"selected":"based"}'::jsonb, NULL, NULL, 'Frasa ''is based in [City]'' adalah cara paling profesional menjelaskan lokasi kerja.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000194', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih ungkapan ramah untuk menanyakan kesan seseorang sejauh ini: You moved here last month, right? How do you like Seattle ___?', '{"options":["so far","until","very","ago"],"translation":"Kamu pindah ke sini bulan lalu, kan? Bagaimana kesanmu tentang Seattle sejauh ini?","sentence_template":"You moved here last month, right? How do you like Seattle [blank]?"}'::jsonb, '{"selected":"so far"}'::jsonb, NULL, NULL, '''How do you like [X] so far?'' berarti ''Bagaimana pendapat/kesanmu tentang [X] sejauh ini?''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000195', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan perkenalan lintas negara di panggilan Zoom ini. Di kota mana saja anggota tim mereka tersebar?', '{"options":[{"id":"opt_1","text":"Semuanya wajib bekerja di satu gedung di New York"},{"id":"opt_2","text":"Tersebar di San Francisco, serta bekerja jarak jauh dari Toronto dan Jakarta"},{"id":"opt_3","text":"Hanya berkantor di London dan Singapura"},{"id":"opt_4","text":"Seluruhnya sedang cuti liburan musim panas"}],"audio_text":"Welcome to the cloud team! Half of our engineers are based in San Francisco, and three of us work remotely from Toronto and Jakarta."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Based in San Francisco, and three of us work remotely from Toronto and Jakarta'' menggambarkan tim global terdistribusi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000196', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan jawaban anak magang baru ketika ditanya kesannya bekerja di kantor tersebut. Apa hal yang paling ia sukai?', '{"options":[{"id":"opt_1","text":"Ia merasa tugasnya terlalu membingungkan"},{"id":"opt_2","text":"Ia sangat menyukainya karena semua anggota tim sangat suportif dan ramah"},{"id":"opt_3","text":"Ia ingin segera pindah ke departemen keuangan"},{"id":"opt_4","text":"Ia mengeluhkan jarak kantor yang terlalu jauh"}],"audio_text":"How do you like your internship so far, Maya? — I love it! Everyone on my team is super helpful and welcoming."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I love it! Everyone on my team is super helpful and welcoming'' menunjukkan kesan positif yang antusias.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000197', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat perkenalan divisi kerja ini: "Saya berada di tim riset pengguna di sini."', '{"romaji":"/aɪm ɑːn ðə ˈjuːzər ˈriːsɜːrtʃ tiːm hɪr/","tokens":["at the","I''m on","research team","the user","here.","teams"],"target_translation":"Saya berada di tim riset pengguna di sini."}'::jsonb, '["I''m on","the user","research team","here."]'::jsonb, NULL, NULL, 'Ingat kolokasi khas AS: ''I''m on the [X] team''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000198', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun pertanyaan small talk yang sopan: "Bagaimana kesanmu terhadap kelas barumu sejauh ini?"', '{"romaji":"/haʊ də juː laɪk jʊr nuː klæs soʊ fɑːr/","tokens":["liking","are you","class so far?","How do","your new","you like"],"target_translation":"Bagaimana kesanmu terhadap kelas barumu sejauh ini?"}'::jsonb, '["How do","you like","your new","class so far?"]'::jsonb, NULL, NULL, '''How do you like ... so far?'' memakai kata tanya ''How'' (bukan ''What'') ketika ada kata kerja ''like''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000199', 'e4100001-0000-4000-8000-000000000024', 'e2000001-0000-4000-8000-000000000006', 'speaking', 'speaking_repeat', 'Ucapkan kalimat profil profesional ini dengan percaya diri: "Saya seorang analis data, dan saya berbasis di Jakarta."', '{"romaji":"/aɪm ə ˈdeɪtə ˈænəlɪst, ænd aɪm beɪst ɪn dʒəˈkɑːrtə/","display_text":"I''m a data analyst, and I''m based in Jakarta.","phonetic_breakdown":["aɪm","ə","ˈdeɪ-tə","ˈæ-nə-lɪst","ænd","aɪm","beɪst","ɪn","dʒə-ˈkɑːr-tə"]}'::jsonb, '{"expected_transcript":"I''m a data analyst, and I''m based in Jakarta."}'::jsonb, NULL, NULL, 'Di AS, kata ''data'' paling sering dilafalkan /ˈdeɪtə/ (seperti kata ''day'').', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000200', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih artikel yang tepat untuk singkatan gelar yang diawali bunyi vokal /em/: Her older brother has ___ MBA from Stanford.', '{"options":["an","a","any","these"],"translation":"Kakak laki-lakinya memiliki gelar MBA dari Stanford.","sentence_template":"Her older brother has [blank] MBA from Stanford."}'::jsonb, '{"selected":"an"}'::jsonb, NULL, NULL, 'Huruf ''M'' dieja /em/ (diawali bunyi vokal /e/), sehingga wajib memakai ''an MBA''!', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000201', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih kata ganti kepemilikan berdiri sendiri (possessive pronoun): My laptop is gray, and ___ is silver.', '{"options":["hers","her","she","she''s"],"translation":"Laptop saya berwarna abu-abu, dan milik dia (perempuan) berwarna perak.","sentence_template":"My laptop is gray, and [blank] is silver."}'::jsonb, '{"selected":"hers"}'::jsonb, NULL, NULL, 'Tanpa kata benda sesudahnya, gunakan ''hers'' (= her laptop), bukan ''her''. Perhatikan ejaan AS ''gray'' (dengan huruf a)!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000202', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'reading', 'fill_blank', 'Pilih bentuk kepemilikan jamak yang benar untuk kata ''students'': The ___ lounge is on the third floor.', '{"options":["students''","student''s of","students''s","student"],"translation":"Ruang santai para mahasiswa berada di lantai tiga.","sentence_template":"The [blank] lounge is on the third floor."}'::jsonb, '{"selected":"students''"}'::jsonb, NULL, NULL, 'Untuk kata benda jamak berakhiran -s (''students''), tanda apostrof diletakkan tepat setelah huruf s (''students'' lounge'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000203', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan perkenalan singkat pembicara tamu di kampus ini. Di mana ia bekerja sekarang?', '{"options":[{"id":"opt_1","text":"Dosen tetap sastra di Boston"},{"id":"opt_2","text":"Peneliti UX senior di Google yang berbasis di Mountain View, California"},{"id":"opt_3","text":"Dokter bedah di rumah sakit Chicago"},{"id":"opt_4","text":"Konsultan pajak independen di Miami"}],"audio_text":"Please welcome Elena Park! She''s a senior UX researcher at Google, and she''s based in Mountain View, California."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Senior UX researcher at Google'' dan ''based in Mountain View, California'' merangkum jabatan serta lokasinya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000204', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'listening', 'listening_choice', 'Dengarkan percakapan mencari pemilik barang di kelas berikut. Siapa pemilik payung kuning itu?', '{"options":[{"id":"opt_1","text":"Milik ketua kelas"},{"id":"opt_2","text":"Milik Profesor Kim yang tertinggal seusai kelas"},{"id":"opt_3","text":"Milik petugas perpustakaan"},{"id":"opt_4","text":"Payung pinjaman dari asrama"}],"audio_text":"Whose yellow umbrella is by the door? — Oh, that''s Professor Kim''s umbrella! She left it after class."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''That''s Professor Kim''s umbrella'' menjawab pertanyaan kepemilikan ''Whose...?'' dengan tepat.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000205', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun kalimat cerita keluarga ini: "Adik laki-laki saya adalah seorang mahasiswa kedokteran."', '{"romaji":"/maɪ ˈjʌŋɡər ˈbrʌðər ɪz ə ˈmedɪkəl ˈstuːdənt/","tokens":["an medical","My younger","student.","brother is","brothers","a medical"],"target_translation":"Adik laki-laki saya adalah seorang mahasiswa kedokteran."}'::jsonb, '["My younger","brother is","a medical","student."]'::jsonb, NULL, NULL, 'Gunakan ''younger brother'' untuk adik laki-laki dan artikel ''a'' sebelum ''medical student''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000206', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'writing', 'sentence_builder', 'Susun pertanyaan menanyakan divisi rekan baru: "Kamu berada di tim apa di kantor ini?"', '{"romaji":"/wʌt tiːm ɑːr juː ɑːn æt ðɪs ˈɔːfɪs/","tokens":["are you","you are","is","this office?","What team","on at"],"target_translation":"Kamu berada di tim apa di kantor ini?"}'::jsonb, '["What team","are you","on at","this office?"]'::jsonb, NULL, NULL, 'Pola ''What team are you on...?'' sangat lazim pada minggu pertama kerja di perusahaan AS.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000207', 'e4100001-0000-4000-8000-000000000025', 'e2000001-0000-4000-8000-000000000006', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan rekan tim ini dengan lancar: "Ini rekan kerja saya, Maya, dan dia berada di tim produk."', '{"romaji":"/ðɪs ɪz maɪ ˈkoʊwɜːrkər ˈmaɪə, ænd ʃiːz ɑːn ðə ˈprɑːdʌkt tiːm/","display_text":"This is my coworker Maya, and she''s on the product team.","phonetic_breakdown":["ðɪs","ɪz","maɪ","ˈkoʊ-wɜːr-kər","ˈmaɪ-ə","ænd","ʃiːz","ɑːn","ðə","ˈprɑː-dʌkt","tiːm"]}'::jsonb, '{"expected_transcript":"This is my coworker Maya, and she''s on the product team."}'::jsonb, NULL, NULL, 'Sambungkan ''she''s on'' (/ʃiːz ɑːn/) secara mengalir agar terdengar natural.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000208', 'e4100001-0000-4000-8000-000000000026', NULL, 'reading', 'fill_blank', 'Perhatikan aturan kata kerja setelah modal ''can'': Nadia can ___ three languages: Indonesian, English, and Japanese.', '{"options":["speak","speaks","to speak","speaking"],"translation":"Nadia bisa berbicara tiga bahasa: Bahasa Indonesia, Inggris, dan Jepang.","sentence_template":"Nadia can [blank] three languages: Indonesian, English, and Japanese."}'::jsonb, '{"selected":"speak"}'::jsonb, NULL, NULL, 'Setelah modal ''can'', kata kerja wajib berbentuk dasar V1 murni (''speak''—tanpa ''-s'' dan tanpa ''to'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000209', 'e4100001-0000-4000-8000-000000000026', NULL, 'reading', 'fill_blank', 'Pilih ungkapan idiom AS yang berarti ''tidak bisa hadir ke acara/rapat'': Sorry, I have a dentist appointment at two, so I ___ make it to the meeting.', '{"options":["can''t","don''t","amn''t","not"],"translation":"Maaf, saya ada janji dokter gigi jam dua, jadi saya tidak bisa hadir ke rapat.","sentence_template":"Sorry, I have a dentist appointment at two, so I [blank] make it to the meeting."}'::jsonb, '{"selected":"can''t"}'::jsonb, NULL, NULL, '''I can''t make it'' adalah cara paling alami dan sopan memberi kabar tidak bisa datang ke suatu acara/pertemuan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000210', 'e4100001-0000-4000-8000-000000000026', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat rapat daring saat mikrofon rekan kerja tidak mengeluarkan suara: Hey Ben, we can''t ___ you—I think you''re on mute!', '{"options":["hear","listen","look","watch"],"translation":"Hai Ben, kami tidak bisa mendengarmu—sepertinya mikrofonmu masih di-mute!","sentence_template":"Hey Ben, we can''t [blank] you—I think you''re on mute!"}'::jsonb, '{"selected":"hear"}'::jsonb, NULL, NULL, '''Hear'' berarti menangkap suara dengan telinga tanpa preposisi ''to'' (''hear you''), sedangkan ''listen'' wajib memakai ''to'' (''listen to you'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000211', 'e4100001-0000-4000-8000-000000000026', NULL, 'listening', 'listening_choice', 'Dengarkan baik-baik tekanan vokal pembicara Amerika ini: apakah ia BISA atau TIDAK BISA menghadiri makan malam tim?', '{"options":[{"id":"opt_1","text":"Ia bisa ikut makan malam tim tepat waktu"},{"id":"opt_2","text":"Ia tidak bisa ikut makan malam tim malam ini karena ada tenggat tugas"},{"id":"opt_3","text":"Ia yang mengundang seluruh tim makan malam"},{"id":"opt_4","text":"Makan malam tim diundur ke minggu depan"}],"audio_text":"Thanks for inviting me, but I CAN''T join the team dinner tonight—I have a deadline."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Konteks ''but... I have a deadline'' dan tekanan kuat pada /kænt/ menegaskan ketidaksanggupan hadir.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000212', 'e4100001-0000-4000-8000-000000000026', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan keahlian teknis pelamar magang ini. Alat desain apa yang bisa ia gunakan?', '{"options":[{"id":"opt_1","text":"Hanya bisa mengedit video film dokumenter"},{"id":"opt_2","text":"Bisa merancang prototipe interaktif di Figma serta menulis HTML dan CSS dasar"},{"id":"opt_3","text":"Belum pernah menggunakan perangkat lunak desain sama sekali"},{"id":"opt_4","text":"Khusus mengelola pembukuan pajak perusahaan"}],"audio_text":"I can design interactive prototypes in Figma, and I can also write basic HTML and CSS."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pelamar menyebutkan dua keahlian jelas: ''design interactive prototypes in Figma'' dan ''write basic HTML and CSS''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000213', 'e4100001-0000-4000-8000-000000000026', NULL, 'writing', 'sentence_builder', 'Susun kalimat kemampuan teknis ini: "Dia bisa menganalisis data besar menggunakan Python."', '{"romaji":"/ʃiː kən ˈænəlaɪz lɑːrdʒ ˈdeɪtəsets ˈjuːzɪŋ ˈpaɪθɑːn/","tokens":["large datasets","to analyze","analyzes","analyze","using Python.","She can"],"target_translation":"Dia bisa menganalisis data besar menggunakan Python."}'::jsonb, '["She can","analyze","large datasets","using Python."]'::jsonb, NULL, NULL, 'Perhatikan ejaan Amerika ''analyze'' memakai huruf ''z'' (sedangkan British memakai ''analyse''), diikuti objek.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000214', 'e4100001-0000-4000-8000-000000000026', NULL, 'writing', 'sentence_builder', 'Susun kalimat pemberitahuan tidak bisa hadir yang sopan: "Maaf, saya tidak bisa hadir pada panggilan telepon besok."', '{"romaji":"/ˈsɑːri, aɪ kænt meɪk ɪt tə təˈmɑːroʊz kɔːl/","tokens":["making","can''t to","make it","I can''t","call.","to tomorrow''s","Sorry,"],"target_translation":"Maaf, saya tidak bisa hadir pada panggilan telepon besok."}'::jsonb, '["Sorry,","I can''t","make it","to tomorrow''s","call."]'::jsonb, NULL, NULL, 'Idiom ''make it to [event]'' sangat sering dipakai di email maupun Slack kerja di AS.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000215', 'e4100001-0000-4000-8000-000000000026', NULL, 'speaking', 'speaking_repeat', 'Latih kontras reduksi /kən/ (lemah) dan /kænt/ (kuat) dalam satu kalimat ini: "Saya bisa rapat hari Selasa, tetapi saya tidak bisa hari Rabu."', '{"romaji":"/aɪ kən miːt ɑːn ˈtuːzdeɪ, bʌt aɪ kænt ɑːn ˈwenzdeɪ/","display_text":"I can meet on Tuesday, but I can''t on Wednesday.","phonetic_breakdown":["aɪ","kən","miːt","ɑːn","ˈtuːz-deɪ","bʌt","aɪ","kænt","ɑːn","ˈwenz-deɪ"]}'::jsonb, '{"expected_transcript":"I can meet on Tuesday, but I can''t on Wednesday."}'::jsonb, NULL, NULL, 'Ucapkan ''can meet'' cepat seperti ''kn MEET'', lalu tekan lebar ''CAN''T'' pada bagian kedua!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000216', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat jika ANDA yang butuh memakai pulpen teman sebentar: Excuse me, can I ___ your pen for a second?', '{"options":["borrow","lend","teach","bring"],"translation":"Permisi, bolehkah saya meminjam pulpenmu sebentar?","sentence_template":"Excuse me, can I [blank] your pen for a second?"}'::jsonb, '{"selected":"borrow"}'::jsonb, NULL, NULL, 'Subjek ''I'' menerima pinjaman dari orang lain, sehingga memakai ''borrow'' (bukan ''lend'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000217', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih respons paling alami saat rekan bertanya ''Can I use this empty chair?'': Sure, ___ ahead!', '{"options":["go","come","walk","run"],"translation":"Tentu, silakan dipakai!","sentence_template":"Sure, [blank] ahead!"}'::jsonb, '{"selected":"go"}'::jsonb, NULL, NULL, '''Sure, go ahead!'' (atau ''Go right ahead!'') adalah ungkapan persetujuan izin paling ramah di AS.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000218', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Lengkapi idiom sehari-hari untuk meminta bantuan mengangkat kotak: Hey Josh, can you give me a ___ with this heavy monitor?', '{"options":["hand","foot","head","back"],"translation":"Hai Josh, bisakah kamu membantuku mengangkat monitor berat ini?","sentence_template":"Hey Josh, can you give me a [blank] with this heavy monitor?"}'::jsonb, '{"selected":"hand"}'::jsonb, NULL, NULL, '''Give someone a hand'' adalah idiom populer yang berarti memberi bantuan praktis.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000219', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan dua mahasiswa di perpustakaan kampus ini. Bantuan apa yang diminta pembicara pertama?', '{"options":[{"id":"opt_1","text":"Meminta temannya mengetikkan laporan praktikum dari awal"},{"id":"opt_2","text":"Meminta tolong menjaga tas ranselnya selama dua menit selagi ia mencetak laporan di lantai bawah"},{"id":"opt_3","text":"Meminjam uang koin untuk membeli minuman"},{"id":"opt_4","text":"Menanyakan jawaban soal ujian kimia"}],"audio_text":"Excuse me, I need to print my lab report downstairs. Can you watch my backpack for two minutes? — Sure, no problem!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Can you watch my backpack for two minutes?'' adalah permintaan umum menjaga barang sebentar di perpustakaan.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000220', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan obrolan di rapat daring berikut. Mengapa pembicara meminta izin mematikan kamera?', '{"options":[{"id":"opt_1","text":"Karena lampu kamarnya sedang padam"},{"id":"opt_2","text":"Karena koneksi Wi-Fi rumahnya agak tidak stabil saat presentasi berlangsung"},{"id":"opt_3","text":"Karena ia sedang menyetir mobil di jalan raya"},{"id":"opt_4","text":"Karena kamera laptopnya pecah kemarin"}],"audio_text":"Hey everyone, my home Wi-Fi is a little unstable right now—can I turn off my camera during the presentation?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Alasan jelas disebutkan di awal: ''my home Wi-Fi is a little unstable right now''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000221', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat meminta bantuan cepat ke rekan tim: "Bisakah kamu memeriksa tautan ini sebentar?"', '{"romaji":"/kæn juː tʃek ðɪs lɪŋk riːl kwɪk/","tokens":["checks","Can you","real quick?","to check","this link","check"],"target_translation":"Bisakah kamu memeriksa tautan ini sebentar?"}'::jsonb, '["Can you","check","this link","real quick?"]'::jsonb, NULL, NULL, '''Real quick'' di akhir kalimat adalah ciri khas bahasa lisan akrab di kantor AS.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000222', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat meminta izin mengisi daya baterai: "Bolehkah saya mencolokkan pengisi daya laptop saya di sini?"', '{"romaji":"/kæn aɪ plʌɡ ɪn maɪ ˈlæptɑːp ˈtʃɑːrdʒər hɪr/","tokens":["my laptop","for plug","charger here?","Can I","plugs in","plug in"],"target_translation":"Bolehkah saya mencolokkan pengisi daya laptop saya di sini?"}'::jsonb, '["Can I","plug in","my laptop","charger here?"]'::jsonb, NULL, NULL, 'Phrasal verb ''plug in'' berarti mencolokkan kabel listrik ke stopkontak (''outlet'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000223', 'e4100001-0000-4000-8000-000000000027', 'e2000001-0000-4000-8000-000000000007', 'speaking', 'speaking_repeat', 'Ucapkan permintaan bantuan sopan di panggilan video ini: "Bisakah Anda berbicara sedikit lebih keras, tolong?"', '{"romaji":"/kæn juː spiːk ə ˈlɪtəl ˈlaʊdər, pliːz/","display_text":"Can you speak a little louder, please?","phonetic_breakdown":["kæn","juː","spiːk","ə","ˈlɪ-təl","ˈlaʊ-dər","pliːz"]}'::jsonb, '{"expected_transcript":"Can you speak a little louder, please?"}'::jsonb, NULL, NULL, 'Lafalkan ''little'' ala Amerika dengan flap-t lembut (/ˈlɪɾəl/).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000224', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Ingat aturan setelah ''Let me'': I know where the campus clinic is—let me ___ you on the map!', '{"options":["show","to show","shows","showing"],"translation":"Saya tahu di mana klinik kampus berada—biar saya tunjukkan di peta!","sentence_template":"I know where the campus clinic is—let me [blank] you on the map!"}'::jsonb, '{"selected":"show"}'::jsonb, NULL, NULL, 'Struktur kausatif/tawaran ''Let + objek + V1'' selalu memakai kata kerja dasar tanpa ''to'' (''let me show'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000225', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih kata yang alami saat kurang jelas mendengar ucapan lawan bicara di telepon: Sorry, the line was noisy—I didn''t ___ your last name.', '{"options":["catch","throw","run","make"],"translation":"Maaf, sambungan teleponnya berisik—saya kurang menangkap nama belakang Anda.","sentence_template":"Sorry, the line was noisy—I didn''t [blank] your last name."}'::jsonb, '{"selected":"catch"}'::jsonb, NULL, NULL, 'Idiom ''I didn''t catch that'' sangat sopan dan alami untuk mengatakan ''Saya tadi kurang jelas mendengar ucapan Anda''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000226', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih kalimat sapaan staf meja informasi kampus: Good morning! How ___ I help you today?', '{"options":["can","am","do","have"],"translation":"Selamat pagi! Ada yang bisa saya bantu hari ini?","sentence_template":"Good morning! How [blank] I help you today?"}'::jsonb, '{"selected":"can"}'::jsonb, NULL, NULL, '''How can I help you today?'' adalah kalimat pembuka layanan nomor satu di AS.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000227', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan di koridor kantor ini. Bantuan apa yang ditawarkan Maya kepada rekan barunya?', '{"options":[{"id":"opt_1","text":"Meminjamkan laptop cadangan dari ruang IT"},{"id":"opt_2","text":"Mengantarkan rekannya berjalan menuju Ruang 402 karena searah"},{"id":"opt_3","text":"Meminta rekannya menunggu di lantai dasar sendirian"},{"id":"opt_4","text":"Membatalkan rapat di Ruang 402"}],"audio_text":"You look a little lost! Are you looking for Room 402? Let me walk you there—I''m heading that way too."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Let me walk you there—I''m heading that way too'' berarti menawarkan mengantar bersama karena jalurnya searah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000228', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan dialog di meja bantuan IT kampus berikut. Apa solusi cepat yang diberikan staf IT?', '{"options":[{"id":"opt_1","text":"Membeli tablet baru di toko buku kampus"},{"id":"opt_2","text":"Masuk (sign in) menggunakan alamat email mahasiswa pada pengaturan jaringan"},{"id":"opt_3","text":"Menghapus seluruh aplikasi di dalam tablet"},{"id":"opt_4","text":"Menunggu sampai semester depan"}],"audio_text":"I can''t connect to the campus Wi-Fi on my tablet. — Let me check your network settings real quick. Oh, you need to sign in with your student email."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Staf IT mengecek lalu menemukan solusinya: ''you need to sign in with your student email''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000229', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat inisiatif bantuan ini: "Tunggu sebentar—biar saya periksakan jadwalnya untuk Anda."', '{"romaji":"/wʌn ˈmoʊmənt—let miː tʃek ðə ˈskedʒuːl fɔːr juː/","tokens":["schedule","let me","One moment—","to check","checks","check the","for you."],"target_translation":"Tunggu sebentar—biar saya periksakan jadwalnya untuk Anda."}'::jsonb, '["One moment—","let me","check the","schedule","for you."]'::jsonb, NULL, NULL, 'Lafal Amerika untuk ''schedule'' adalah /ˈskedʒuːl/ (diawali bunyi /sk/, bukan /ʃ/!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000230', 'e4100001-0000-4000-8000-000000000028', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat meminta pengulangan dengan sopan: "Maaf, bisakah Anda mengulangi angka terakhirnya?"', '{"romaji":"/ˈsɑːri, kæn juː rɪˈpiːt ðə læst ˈnʌmbər, pliːz/","tokens":["repeat the","last number,","to repeat","repeats","please?","Sorry,","can you"],"target_translation":"Maaf, bisakah Anda mengulangi angka terakhirnya?"}'::jsonb, '["Sorry,","can you","repeat the","last number,","please?"]'::jsonb, NULL, NULL, 'Meminta konfirmasi ulang angka telepon/harga dengan ''can you repeat the last number?'' mencegah salah catat.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
