INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000233', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat jika Anda MEMINJAMKAN barang milik Anda ke orang lain: Sure, I can ___ you my umbrella until tomorrow.', '{"options":["lend","borrow","renting","takes"],"translation":"Tentu, saya bisa meminjamkan payung saya kepadamu sampai besok.","sentence_template":"Sure, I can [blank] you my umbrella until tomorrow."}'::jsonb, '{"selected":"lend"}'::jsonb, NULL, NULL, 'Karena payung itu milik ''I'' yang dipinjamkan kepada ''you'', kata kerja yang tepat adalah ''lend''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000234', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'reading', 'fill_blank', 'Pilih bentuk kata kerja setelah ''Let me'': Let me ___ my screen so everyone can see the chart.', '{"options":["share","to share","sharing","shares"],"translation":"Biar saya bagikan layar saya agar semua orang bisa melihat grafiknya.","sentence_template":"Let me [blank] my screen so everyone can see the chart."}'::jsonb, '{"selected":"share"}'::jsonb, NULL, NULL, 'Setelah ''Let me'', gunakan kata kerja dasar tanpa ''to'' (''share'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000235', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan pesan suara rekan kerja berikut. Kapan ia BISA melakukan panggilan singkat?', '{"options":[{"id":"opt_1","text":"Pada pukul dua siang tepat"},{"id":"opt_2","text":"Tidak bisa bicara sepanjang hari ini"},{"id":"opt_3","text":"Pada pukul empat sore setelah lokakarya klien selesai"},{"id":"opt_4","text":"Besok pagi pukul delapan"}],"audio_text":"Hi Clara! I can''t talk at two p.m. because I''m in a client workshop, but I can call you right at four."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Kontras jelas antara ''I can''t talk at two p.m.'' dan ''I can call you right at four''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000236', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'listening', 'listening_choice', 'Dengarkan percakapan tamu di lobi hotel AS ini. Apa fasilitas gratis yang bisa digunakan tamu?', '{"options":[{"id":"opt_1","text":"Layanan antar-jemput limosin pribadi gratis"},{"id":"opt_2","text":"Pusat kebugaran di lantai dua buka 24 jam sehari, 7 hari seminggu dengan kunci kamar"},{"id":"opt_3","text":"Makan malam gratis sepuasnya di restoran atap"},{"id":"opt_4","text":"Pencucian pakaian kering tanpa batas"}],"audio_text":"Excuse me, can guests use the fitness center on the second floor for free? — Yes, you can access it twenty-four seven with your room key."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Ungkapan AS ''twenty-four seven'' (24/7) berarti buka 24 jam sehari selama 7 hari seminggu.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000237', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun pertanyaan kemampuan bahasa ini: "Bisakah kamu membaca artikel akademik dalam bahasa Inggris?"', '{"romaji":"/kæn juː riːd ˌækəˈdemɪk ˈɑːrtɪkəlz ɪn ˈɪŋɡlɪʃ/","tokens":["to read","in English?","academic articles","Can you","read","reads"],"target_translation":"Bisakah kamu membaca artikel akademik dalam bahasa Inggris?"}'::jsonb, '["Can you","read","academic articles","in English?"]'::jsonb, NULL, NULL, 'Pertanyaan kemampuan menggunakan ''Can + Subject + V1 (read) ...?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000238', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'writing', 'sentence_builder', 'Susun kalimat meminta tolong di kantor: "Bisakah kamu membantuku menyiapkan proyektor ini?"', '{"romaji":"/kæn juː help miː set ʌp ðɪs prəˈdʒektər/","tokens":["help me","set up","setting","helps","Can you","this projector?"],"target_translation":"Bisakah kamu membantuku menyiapkan proyektor ini?"}'::jsonb, '["Can you","help me","set up","this projector?"]'::jsonb, NULL, NULL, 'Setelah ''help me'', orang Amerika langsung memakai V1 (''help me set up'')—ringkas dan alami!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000239', 'e4100001-0000-4000-8000-000000000029', 'e2000001-0000-4000-8000-000000000007', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konfirmasi visual saat presentasi Zoom ini: "Bisakah semua orang melihat layar saya dengan jelas?"', '{"romaji":"/kæn ˈevriwʌn siː maɪ skriːn ˈklɪrli/","display_text":"Can everyone see my screen clearly?","phonetic_breakdown":["kæn","ˈev-ri-wʌn","siː","maɪ","skriːn","ˈklɪr-li"]}'::jsonb, '{"expected_transcript":"Can everyone see my screen clearly?"}'::jsonb, NULL, NULL, 'Naikkan intonasi di akhir kalimat ''clearly?'' karena ini pertanyaan Ya/Tidak!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000240', 'e4100001-0000-4000-8000-000000000030', NULL, 'reading', 'fill_blank', 'Pilih pasangan lengkap untuk kalimat ''sedang mengerjakan'' sekarang: Please don''t turn off the server—our engineers ___ testing a new update right now.', '{"options":["are","is","do","can"],"translation":"Mohon jangan matikan servernya—para insinyur kami sedang menguji pembaruan baru sekarang.","sentence_template":"Please don''t turn off the server—our engineers [blank] testing a new update right now."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Subjek jamak ''our engineers'' membutuhkan ''are'' sebelum ''testing'' dalam Present Continuous.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000241', 'e4100001-0000-4000-8000-000000000030', NULL, 'reading', 'fill_blank', 'Pilih ejaan Verb-ing yang benar dari kata ''write'': Prof. Adams is ___ a recommendation letter for my scholarship.', '{"options":["writing","writeing","writting","writes"],"translation":"Prof. Adams sedang menulis surat rekomendasi untuk beasiswa saya.","sentence_template":"Prof. Adams is [blank] a recommendation letter for my scholarship."}'::jsonb, '{"selected":"writing"}'::jsonb, NULL, NULL, '''Write'' membuang huruf ''-e'' menjadi ''writing'' (dengan SATU huruf ''t'', berbeda dengan ''written'' yang dua ''t''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000242', 'e4100001-0000-4000-8000-000000000030', NULL, 'reading', 'fill_blank', 'Jangan lupakan preposisi wajib setelah kata kerja ''waiting'': Hi! I''m standing outside the lobby, waiting ___ my ride.', '{"options":["for","to","at","with"],"translation":"Halo! Saya sedang berdiri di luar lobi, menunggu jemputan saya.","sentence_template":"Hi! I''m standing outside the lobby, waiting [blank] my ride."}'::jsonb, '{"selected":"for"}'::jsonb, NULL, NULL, 'Menunggu seseorang atau sesuatu dalam Bahasa Inggris selalu memakai ''wait for''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000243', 'e4100001-0000-4000-8000-000000000030', NULL, 'listening', 'listening_choice', 'Dengarkan pesan suara singkat teman sekamarmu ini. Di mana ia berada sekarang?', '{"options":[{"id":"opt_1","text":"Baru saja bangun tidur di kamarnya"},{"id":"opt_2","text":"Sedang berjalan keluar dari supermarket dan akan tiba di apartemen dalam 10 menit"},{"id":"opt_3","text":"Sedang duduk di ruang kuliah hingga malam"},{"id":"opt_4","text":"Sedang mengantre di kantor pos pusat"}],"audio_text":"Hey! I''m walking out of the grocery store right now, so I''ll be back at the apartment in ten minutes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''m walking out of the grocery store right now'' menggambarkan aksi yang sedang berlangsung detik ini.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000244', 'e4100001-0000-4000-8000-000000000030', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan resepsionis kantor berikut. Mengapa Ibu Davis belum bisa ditemui sekarang?', '{"options":[{"id":"opt_1","text":"Ibu Davis sedang berlibur ke luar negeri"},{"id":"opt_2","text":"Ibu Davis sedang mewawancarai kandidat pelamar kerja di Ruang 3B saat ini"},{"id":"opt_3","text":"Ibu Davis sudah pindah ke perusahaan lain"},{"id":"opt_4","text":"Ibu Davis belum datang ke kantor hari ini"}],"audio_text":"Ms. Davis is interviewing a job candidate in Room 3B at the moment. Would you like to wait in the lounge?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Is interviewing a job candidate ... at the moment'' menjelaskan aktivitas yang sedang berlangsung.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000245', 'e4100001-0000-4000-8000-000000000030', NULL, 'writing', 'sentence_builder', 'Susun kalimat laporan progres kerja ini: "Saya sedang mengerjakan anggaran kuartalan minggu ini."', '{"romaji":"/aɪ æm ˈwɜːrkɪŋ ɑːn ðə ˈkwɔːrtərli ˈbʌdʒɪt ðɪs wiːk/","tokens":["this week.","work on","I am","working on","budget","is working","the quarterly"],"target_translation":"Saya sedang mengerjakan anggaran kuartalan minggu ini."}'::jsonb, '["I am","working on","the quarterly","budget","this week."]'::jsonb, NULL, NULL, 'Present Continuous juga dipakai untuk proyek sementara yang sedang digarap ''this week'' atau ''this semester''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000246', 'e4100001-0000-4000-8000-000000000030', NULL, 'writing', 'sentence_builder', 'Susun kalimat perjalanan khas AS menggunakan heading: "Kami sedang menuju ke kantin kampus sekarang."', '{"romaji":"/wiː ɑːr ˈhedɪŋ tə ðə ˈkæmpəs ˌkæfəˈtɪriə naʊ/","tokens":["We are","we heading","heading to","now.","cafeteria","the campus","heads"],"target_translation":"Kami sedang menuju ke kantin kampus sekarang."}'::jsonb, '["We are","heading to","the campus","cafeteria","now."]'::jsonb, NULL, NULL, '''We are heading to...'' adalah ungkapan sehari-hari warga AS untuk ''Kami sedang berjalan/berangkat menuju...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000247', 'e4100001-0000-4000-8000-000000000030', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat status perjalanan ini dengan alami: "Saya sedang menunggu kereta di peron sekarang."', '{"romaji":"/aɪm ˈweɪtɪŋ fɔːr ðə treɪn ɑːn ðə ˈplætfɔːrm raɪt naʊ/","display_text":"I''m waiting for the train on the platform right now.","phonetic_breakdown":["aɪm","ˈweɪ-tɪŋ","fɔːr","ðə","treɪn","ɑːn","ðə","ˈplæt-fɔːrm","raɪt","naʊ"]}'::jsonb, '{"expected_transcript":"I''m waiting for the train on the platform right now."}'::jsonb, NULL, NULL, 'Akhiran ''-ing'' dalam percakapan standar AS dilafalkan jelas dengan bunyi sengau /ɪŋ/.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000248', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Hati-hati dengan Stative Verb meskipun ada kata ''right now'': Excuse me, I ___ some help with the printer right now.', '{"options":["need","am needing","needing","needs"],"translation":"Permisi, saya sedang membutuhkan bantuan dengan mesin cetak ini sekarang.","sentence_template":"Excuse me, I [blank] some help with the printer right now."}'::jsonb, '{"selected":"need"}'::jsonb, NULL, NULL, '''Need'' adalah stative verb (kebutuhan), sehingga tetap menggunakan Present Simple (''I need'') walaupun terjadi ''right now''!', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000249', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Kontraskan kebiasaan tetap dengan aksi khusus hari ini: Maya usually takes the subway, but today she ___ an Uber because of the heavy snow.', '{"options":["is taking","takes","take","taking"],"translation":"Maya biasanya naik subway, tetapi hari ini dia sedang naik Uber karena salju lebat.","sentence_template":"Maya usually takes the subway, but today she [blank] an Uber because of the heavy snow."}'::jsonb, '{"selected":"is taking"}'::jsonb, NULL, NULL, 'Bagian pertama rutin (''usually takes''), sedangkan situasi sementara khusus hari ini (''today'') memakai ''is taking''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000250', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Pilih bentuk yang benar untuk kata kerja pikiran ''understand'': Thanks for explaining the chart—I ___ the main trend now!', '{"options":["understand","am understanding","understands","understanding"],"translation":"Terima kasih sudah menjelaskan grafiknya—saya mengerti tren utamanya sekarang!","sentence_template":"Thanks for explaining the chart—I [blank] the main trend now!"}'::jsonb, '{"selected":"understand"}'::jsonb, NULL, NULL, '''Understand'' tidak digunakan dalam bentuk Continuous; gunakan ''I understand now''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000251', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan di dapur kantor berikut. Proyek apa yang sedang dikerjakan Leo bulan ini?', '{"options":[{"id":"opt_1","text":"Ia sedang mengambil cuti panjang selama sebulan"},{"id":"opt_2","text":"Ia sedang merancang ulang halaman pembayaran seluler bersama tim pembayaran"},{"id":"opt_3","text":"Ia sedang melatih karyawan baru di divisi HR"},{"id":"opt_4","text":"Ia sedang memperbaiki mesin kopi kantor"}],"audio_text":"Hey Leo, what are you working on this month? — I''m redesigning the mobile checkout page with the payment team."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Leo menjawab dengan Present Continuous untuk proyek bulan berjalan: ''I''m redesigning the mobile checkout page''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000252', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan panggilan telepon singkat di stasiun ini. Mengapa pembicara belum bisa mengobrol panjang?', '{"options":[{"id":"opt_1","text":"Baterai ponselnya tinggal satu persen"},{"id":"opt_2","text":"Keretanya sedang masuk ke peron stasiun saat ini juga, jadi ia akan menelepon balik 15 menit lagi"},{"id":"opt_3","text":"Ia sedang mengikuti ujian akhir di kelas"},{"id":"opt_4","text":"Ia salah menekan nomor telepon"}],"audio_text":"Hey Sara, sorry, my train is pulling into the station right now—can I call you back in fifteen minutes?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''My train is pulling into the station right now'' berarti keretanya tepat sedang merapat masuk ke stasiun.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000253', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun pertanyaan menanyakan fokus kerja rekan hari ini: "Apa yang sedang kamu kerjakan hari ini?"', '{"romaji":"/wʌt ɑːr juː ˈwɜːrkɪŋ ɑːn təˈdeɪ/","tokens":["works on","today?","What do","What are","you","working on"],"target_translation":"Apa yang sedang kamu kerjakan hari ini?"}'::jsonb, '["What are","you","working on","today?"]'::jsonb, NULL, NULL, 'Susunan tanya Present Continuous: ''What + are + you + working on + today?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000254', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat kontras kebiasaan vs hari ini: "Dia biasanya mengajar hari Senin, tetapi hari ini dia sedang beristirahat."', '{"romaji":"/hiː ˈjuːʒuəli ˈtiːtʃɪz ˈmʌndeɪz, bʌt təˈdeɪ hiːz ˈrestɪŋ/","tokens":["is teaching","teaches Mondays,","he''s resting.","He usually","but today","rests."],"target_translation":"Dia biasanya mengajar hari Senin, tetapi hari ini dia sedang beristirahat."}'::jsonb, '["He usually","teaches Mondays,","but today","he''s resting."]'::jsonb, NULL, NULL, 'Dalam American English lisan/tulisan ringkas, ''Mondays'' juga kerap dipakai setara ''on Mondays'', dikontraskan dengan ''today he''s resting''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000255', 'e4100001-0000-4000-8000-000000000031', 'e2000001-0000-4000-8000-000000000008', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras ini dengan jelas: "Saya biasanya bekerja di kantor, tetapi hari ini saya bekerja dari rumah."', '{"romaji":"/aɪ ˈjuːʒuəli wɜːrk æt ðə ˈɔːfɪs, bʌt təˈdeɪ aɪm ˈwɜːrkɪŋ frʌm hoʊm/","display_text":"I usually work at the office, but today I''m working from home.","phonetic_breakdown":["aɪ","ˈjuː-ʒu-ə-li","wɜːrk","æt","ðə","ˈɔː-fɪs","bʌt","tə-ˈdeɪ","aɪm","ˈwɜːr-kɪŋ","frʌm","hoʊm"]}'::jsonb, '{"expected_transcript":"I usually work at the office, but today I''m working from home."}'::jsonb, NULL, NULL, 'Beri sedikit penekanan pada kata kontras ''usually'' dan ''today'' agar maksud kalimat langsung tertangkap.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000256', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Pilih idiom paling alami di AS untuk memberi kabar bahwa Anda sedang sedikit terlambat di jalan: Hi team! My bus is delayed, so I''m ___ five minutes late.', '{"options":["running","walking","sitting","standing"],"translation":"Hai tim! Bus saya tertunda, jadi saya terlambat lima menit.","sentence_template":"Hi team! My bus is delayed, so I''m [blank] five minutes late."}'::jsonb, '{"selected":"running"}'::jsonb, NULL, NULL, '''Running [X minutes] late'' adalah frasa baku bahasa Inggris Amerika untuk mengabarkan keterlambatan saat masih di perjalanan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000257', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Pilih cara alami melaporkan mesin kantor yang sedang error: Excuse me, the card reader ___ working right now.', '{"options":["isn''t","doesn''t","don''t","aren''t"],"translation":"Permisi, mesin pembaca kartunya sedang tidak berfungsi sekarang.","sentence_template":"Excuse me, the card reader [blank] working right now."}'::jsonb, '{"selected":"isn''t"}'::jsonb, NULL, NULL, 'Untuk alat yang sedang mengalami gangguan saat ini, gunakan ''isn''t working'' (''is not working'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000258', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Pilih phrasal verb yang berarti ''suara telepon/Zoom putus-putus'': Sorry Tom, you''re ___ up—could you repeat the last sentence?', '{"options":["breaking","making","taking","waking"],"translation":"Maaf Tom, suara Anda putus-putus—bisakah Anda mengulangi kalimat terakhir?","sentence_template":"Sorry Tom, you''re [blank] up—could you repeat the last sentence?"}'::jsonb, '{"selected":"breaking"}'::jsonb, NULL, NULL, '''You''re breaking up'' adalah ungkapan standar saat sinyal suara lawan bicara terputus-putus.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000259', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan pesan singkat mahasiswa kepada rekan kelompok labnya ini. Mengapa ia sedikit terlambat?', '{"options":[{"id":"opt_1","text":"Ia ketiduran di asrama kampus"},{"id":"opt_2","text":"Ia masih mencetak lembar materi lab di perpustakaan karena antreannya panjang"},{"id":"opt_3","text":"Ia salah masuk ke gedung olahraga"},{"id":"opt_4","text":"Kelas praktikum hari ini dibatalkan oleh dosen"}],"audio_text":"Hey! I''m still printing our lab handouts at the library because there''s a long line. I''m running about five minutes late!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Still printing our lab handouts ... because there''s a long line'' menjelaskan penyebab keterlambatan 5 menit tersebut.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000260', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan kendala yang terjadi di tengah panggilan video wawancara ini. Apa yang dilakukan pewawancara untuk mengatasinya?', '{"options":[{"id":"opt_1","text":"Mengakhiri wawancara dan menolak pelamar"},{"id":"opt_2","text":"Mematikan kamera video bersama-sama agar kualitas suara tetap jernih"},{"id":"opt_3","text":"Meminta pelamar terbang langsung ke kantor hari ini"},{"id":"opt_4","text":"Mengganti bahasa wawancara ke bahasa Jepang"}],"audio_text":"Oh, your video is freezing on my end. Let''s turn off our cameras so the audio stays clear."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Ungkapan ''on my end'' (di sisi layar saya) + solusi ''turn off our cameras so the audio stays clear'' sangat umum di Zoom.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000261', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun pesan sopan saat terlambat karena macet: "Maaf, saya terlambat sepuluh menit karena macet."', '{"romaji":"/ˈsɑːri, aɪm ˈrʌnɪŋ ten ˈmɪnɪts leɪt duː tə ˈtræfɪk/","tokens":["I''m running","to traffic.","am run","traffics.","ten minutes","late due","Sorry,"],"target_translation":"Maaf, saya terlambat sepuluh menit karena macet."}'::jsonb, '["Sorry,","I''m running","ten minutes","late due","to traffic."]'::jsonb, NULL, NULL, 'Ingat: ''traffic'' juga uncountable noun (tidak pernah ''traffics''), dan ''due to'' berarti ''dikarenakan''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000262', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat melaporkan kendala lift gedung: "Lift sebelah kiri sedang tidak berfungsi hari ini."', '{"romaji":"/ðə left ˈelɪveɪtər ˈɪzənt ˈwɜːrkɪŋ təˈdeɪ/","tokens":["isn''t working","doesn''t working","today.","aren''t","elevator","The left"],"target_translation":"Lift sebelah kiri sedang tidak berfungsi hari ini."}'::jsonb, '["The left","elevator","isn''t working","today."]'::jsonb, NULL, NULL, '''The left elevator'' tunggal + ''isn''t working today''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000263', 'e4100001-0000-4000-8000-000000000032', 'e2000001-0000-4000-8000-000000000008', 'speaking', 'speaking_repeat', 'Ucapkan pemberitahuan sopan saat gangguan sinyal Zoom ini: "Maaf, suara Anda agak putus-putus di tempat saya."', '{"romaji":"/ˈsɑːri, jʊr ˈbreɪkɪŋ ʌp ə ˈlɪtəl ɑːn maɪ end/","display_text":"Sorry, you''re breaking up a little on my end.","phonetic_breakdown":["ˈsɑː-ri","jʊr","ˈbreɪ-kɪŋ","ʌp","ə","ˈlɪ-təl","ɑːn","maɪ","end"]}'::jsonb, '{"expected_transcript":"Sorry, you''re breaking up a little on my end."}'::jsonb, NULL, NULL, 'Menambahkan ''on my end'' terdengar sangat sopan karena tidak menyalahkan koneksi lawan bicara!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000264', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Pilih ejaan Verb-ing yang benar untuk kata satu suku kata ''sit'': Are you ___ in the campus coffee shop right now?', '{"options":["sitting","siting","siteing","sits"],"translation":"Apakah kamu sedang duduk di kedai kopi kampus sekarang?","sentence_template":"Are you [blank] in the campus coffee shop right now?"}'::jsonb, '{"selected":"sitting"}'::jsonb, NULL, NULL, 'Kata 1 suku kata berpola konsonan-vokal-konsonan (''s-i-t'') menggandakan konsonan akhir menjadi ''sitting''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000265', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Ingat aturan Stative Verb untuk kata ''know'': Do you ___ the Wi-Fi password for this conference room?', '{"options":["know","knowing","are knowing","knows"],"translation":"Apakah kamu tahu kata sandi Wi-Fi untuk ruang rapat ini?","sentence_template":"Do you [blank] the Wi-Fi password for this conference room?"}'::jsonb, '{"selected":"know"}'::jsonb, NULL, NULL, '''Know'' adalah kata kerja keadaan mental (stative verb) yang menggunakan Present Simple (''Do you know...?'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000266', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'reading', 'fill_blank', 'Lengkapi pertanyaan Present Continuous untuk subjek jamak: Why ___ all the students standing outside the building?', '{"options":["are","is","do","does"],"translation":"Mengapa semua mahasiswa sedang berdiri di luar gedung?","sentence_template":"Why [blank] all the students standing outside the building?"}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, 'Subjek jamak ''all the students'' + ''standing'' membutuhkan To Be jamak ''are''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000267', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan pengumuman di gedung kampus berikut. Mengapa semua orang diminta keluar gedung sebentar?', '{"options":[{"id":"opt_1","text":"Gedung kampus sudah tutup untuk liburan musim panas"},{"id":"opt_2","text":"Keamanan kampus sedang mengadakan latihan evakuasi kebakaran rutin selama 10 menit"},{"id":"opt_3","text":"Ada konser musik gratis di halaman depan"},{"id":"opt_4","text":"Lift gedung baru saja selesai diperbaiki"}],"audio_text":"Attention everyone: campus safety is conducting a routine ten-minute fire drill right now. Please exit calmly using the stairs."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Is conducting a routine ten-minute fire drill right now'' menjelaskan simulasi evakuasi kebakaran rutin.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000268', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja di Slack Huddle ini. Mengapa Sarah bekerja dari perpustakaan kota hari ini?', '{"options":[{"id":"opt_1","text":"Karena apartemennya sedang dicat ulang"},{"id":"opt_2","text":"Karena teknisi sedang memperbaiki kabel internet di jalannya, sehingga ia bekerja dari perpustakaan umum"},{"id":"opt_3","text":"Karena ia bekerja paruh waktu sebagai pustakawan"},{"id":"opt_4","text":"Karena kantor pusat pindah ke perpustakaan"}],"audio_text":"Are you working from home today, Sarah? — Actually, technicians are fixing the internet cables on my street, so I''m working from the public library."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dua aksi sementara hari ini: ''technicians are fixing...'' dan ''I''m working from the public library''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000269', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun pertanyaan telepon singkat ini: "Apakah kamu sedang menunggu di luar pintu masuk utama?"', '{"romaji":"/ɑːr juː ˈweɪtɪŋ ˈaʊtsaɪd ðə meɪn ˈentrəns/","tokens":["Are you","Do you","main entrance?","outside the","waits","waiting"],"target_translation":"Apakah kamu sedang menunggu di luar pintu masuk utama?"}'::jsonb, '["Are you","waiting","outside the","main entrance?"]'::jsonb, NULL, NULL, 'Pertanyaan Ya/Tidak Present Continuous: ''Are you waiting ...?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000270', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat penjelasan proyek semester ini: "Semester ini saya sedang mengambil empat mata kuliah ilmu komputer."', '{"romaji":"/ðɪs səˈmestər aɪm ˈteɪkɪŋ fɔːr kəmˈpjuːtər ˈsaɪəns ˈkɔːrsɪz/","tokens":["I taking","four computer","science courses.","I''m taking","takes","This semester"],"target_translation":"Semester ini saya sedang mengambil empat mata kuliah ilmu komputer."}'::jsonb, '["This semester","I''m taking","four computer","science courses."]'::jsonb, NULL, NULL, 'Di universitas AS, mengambil mata kuliah selalu menggunakan kolokasi ''take courses / take classes''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000271', 'e4100001-0000-4000-8000-000000000033', 'e2000001-0000-4000-8000-000000000008', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kabar keterlambatan ini dengan sopan dan jelas: "Hai semuanya, saya terlambat sekitar lima menit!"', '{"romaji":"/haɪ ˈevriwʌn, aɪm ˈrʌnɪŋ əˈbaʊt faɪv ˈmɪnɪts leɪt/","display_text":"Hi everyone, I''m running about five minutes late!","phonetic_breakdown":["haɪ","ˈev-ri-wʌn","aɪm","ˈrʌ-nɪŋ","ə-ˈbaʊt","faɪv","ˈmɪ-nɪts","leɪt"]}'::jsonb, '{"expected_transcript":"Hi everyone, I''m running about five minutes late!"}'::jsonb, NULL, NULL, 'Kalimat penyelamat terbaik di dunia profesional AS saat terjebak macet atau antrean!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000272', 'e4100001-0000-4000-8000-000000000034', NULL, 'reading', 'fill_blank', 'Pilih nama musim gugur yang paling lazim dipakai di Amerika Serikat: New semester classes usually begin in the ___.', '{"options":["fall","rain","heat","wind"],"translation":"Perkuliahan semester baru biasanya dimulai pada musim gugur.","sentence_template":"New semester classes usually begin in the [blank]."}'::jsonb, '{"selected":"fall"}'::jsonb, NULL, NULL, 'Di universitas AS, semester ganjil (Agustus/September–Desember) resmi disebut ''Fall Semester''!', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000273', 'e4100001-0000-4000-8000-000000000034', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang benar setelah ''It is'' untuk menyatakan sedang turun salju sekarang: Look out the window—it''s ___ for the first time this year!', '{"options":["snowing","snow","snows","a snow"],"translation":"Lihat keluar jendela—sedang turun salju untuk pertama kalinya tahun ini!","sentence_template":"Look out the window—it''s [blank] for the first time this year!"}'::jsonb, '{"selected":"snowing"}'::jsonb, NULL, NULL, 'Setelah ''it''s'' (''it is'') untuk kejadian cuaca yang sedang berlangsung, gunakan Verb-ing (''snowing'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000274', 'e4100001-0000-4000-8000-000000000034', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan standar untuk menanyakan kondisi cuaca: What''s the weather ___ in San Diego today?', '{"options":["like","look","same","as"],"translation":"Bagaimana cuaca di San Diego hari ini?","sentence_template":"What''s the weather [blank] in San Diego today?"}'::jsonb, '{"selected":"like"}'::jsonb, NULL, NULL, '''What''s the weather like...?'' adalah pola tetap menanyakan kondisi cuaca.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000275', 'e4100001-0000-4000-8000-000000000034', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan pagi dua mahasiswa di Boston dengan suhu Fahrenheit ini. Bagaimana kondisi udara di luar?', '{"options":[{"id":"opt_1","text":"Sangat panas terik seperti pantai tropis"},{"id":"opt_2","text":"Dingin di bawah titik beku (30°F ≈ -1°C) dan berangin sehingga harus memakai mantel tebal"},{"id":"opt_3","text":"Hangat nyaman cocok untuk memakai celana pendek"},{"id":"opt_4","text":"Badai pasir di tengah gurun"}],"audio_text":"Check the weather app before you leave—it''s thirty degrees Fahrenheit and windy this morning, so wear your heavy winter coat!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dalam skala Fahrenheit AS, 30°F berada di bawah titik beku air (32°F = 0°C), sehingga sangat dingin!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000276', 'e4100001-0000-4000-8000-000000000034', NULL, 'listening', 'listening_choice', 'Dengarkan cerita warga Seattle tentang kotanya. Kapan waktu terbaik mengunjungi Seattle menurutnya?', '{"options":[{"id":"opt_1","text":"Pada pertengahan musim dingin bulan Januari"},{"id":"opt_2","text":"Pada musim panas karena kering, cerah, dan bersuhu nyaman 75°F (~24°C)"},{"id":"opt_3","text":"Saat hujan lebat sepanjang musim semi"},{"id":"opt_4","text":"Tidak pernah ada matahari sepanjang tahun"}],"audio_text":"It rains a lot here in the winter and spring, but summers in Seattle are dry, sunny, and seventy-five degrees."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Summers in Seattle are dry, sunny, and seventy-five degrees'' menunjukkan cuaca terbaik pada musim panas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000277', 'e4100001-0000-4000-8000-000000000034', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan menanyakan kondisi cuaca: "Bagaimana cuaca di Jakarta hari ini?"', '{"romaji":"/wʌts ðə ˈweðər laɪk ɪn dʒəˈkɑːrtə təˈdeɪ/","tokens":["weather","How''s like","Jakarta today?","like in","What''s the","weathers"],"target_translation":"Bagaimana cuaca di Jakarta hari ini?"}'::jsonb, '["What''s the","weather","like in","Jakarta today?"]'::jsonb, NULL, NULL, 'Ingat: pakai ''What''s the weather like?'' ATAU ''How''s the weather?'' (jangan digabung menjadi ''How''s the weather like''!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000278', 'e4100001-0000-4000-8000-000000000034', NULL, 'writing', 'sentence_builder', 'Susun kalimat deskripsi cuaca pagi: "Udara agak dingin pagi ini, jadi bawalah jaket."', '{"romaji":"/ɪts ˈtʃɪli ðɪs ˈmɔːrnɪŋ, soʊ brɪŋ ə ˈdʒækɪt/","tokens":["jackets.","this morning,","a jacket.","It''s chilly","chilling","so bring"],"target_translation":"Udara agak dingin pagi ini, jadi bawalah jaket."}'::jsonb, '["It''s chilly","this morning,","so bring","a jacket."]'::jsonb, NULL, NULL, '''Chilly'' sangat tepat menggambarkan udara sejuk-dingin yang membutuhkan jaket atau sweater.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000279', 'e4100001-0000-4000-8000-000000000034', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat kekaguman musim gugur di kampus Timur Laut AS ini: "Pepohonan di kampus tampak indah pada musim gugur."', '{"romaji":"/ðə triːz ɑːn ˈkæmpəs lʊk ˈbjuːtɪfəl ɪn ðə fɔːl/","display_text":"The trees on campus look beautiful in the fall.","phonetic_breakdown":["ðə","triːz","ɑːn","ˈkæm-pəs","lʊk","ˈbjuː-tɪ-fəl","ɪn","ðə","fɔːl"]}'::jsonb, '{"expected_transcript":"The trees on campus look beautiful in the fall."}'::jsonb, NULL, NULL, 'Lafalkan ''beautiful'' ala Amerika dengan flap-t halus (/ˈbjuːɾɪfəl/).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000280', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Ingat aturan kata kerja setelah preposisi ''about'': How about ___ out that new taco place after class?', '{"options":["trying","try","to try","tries"],"translation":"Bagaimana kalau kita mencoba tempat taco baru itu sepulang kelas?","sentence_template":"How about [blank] out that new taco place after class?"}'::jsonb, '{"selected":"trying"}'::jsonb, NULL, NULL, 'Setelah ''How about'' atau ''What about'', kata kerja selalu berbentuk ''-ing'' (''trying out'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000281', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang tepat setelah ''Let''s'': The weather is gorgeous today—let''s ___ by the river!', '{"options":["walk","walking","to walk","walks"],"translation":"Cuacanya cerah indah sekali hari ini—ayo jalan-jalan di tepi sungai!","sentence_template":"The weather is gorgeous today—let''s [blank] by the river!"}'::jsonb, '{"selected":"walk"}'::jsonb, NULL, NULL, '''Let''s'' (''Let us'') selalu diikuti kata kerja dasar V1 tanpa ''to'' dan tanpa ''-ing'' (''walk'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000282', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih pola hobi luar ruang yang alami dalam bahasa Inggris: Do you want to go ___ in the mountains this weekend?', '{"options":["hiking","to hike","hikes","for hike"],"translation":"Apakah kamu mau pergi mendaki di pegunungan akhir pekan ini?","sentence_template":"Do you want to go [blank] in the mountains this weekend?"}'::jsonb, '{"selected":"hiking"}'::jsonb, NULL, NULL, 'Aktivitas rekreasi olahraga memakai kolokasi ''go + Verb-ing'' (''go hiking'', ''go swimming'', ''go camping'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000283', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan percakapan dua teman sekamar merencanakan hari Sabtu. Mengapa mereka mengubah rencana dari piknik ke arena boling?', '{"options":[{"id":"opt_1","text":"Karena Central Park ditutup selamanya"},{"id":"opt_2","text":"Karena prakiraan cuaca memprediksi badai petir sepanjang sore, jadi mereka memilih boling di dalam ruangan"},{"id":"opt_3","text":"Karena mereka tidak punya keranjang makanan"},{"id":"opt_4","text":"Karena mereka harus mengikuti ujian hari Sabtu sore"}],"audio_text":"Let''s have a picnic in Central Park tomorrow! — Oh, the forecast says thunderstorms all afternoon. How about going bowling indoors instead?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''The forecast says thunderstorms all afternoon'' membuat mereka mengganti rencana luar ruang menjadi ''going bowling indoors''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000284', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan ajakan rekan kerja pada Jumat sore ini. Jam berapa mereka sepakat bertemu di pasar petani (farmers market)?', '{"options":[{"id":"opt_1","text":"Jumat malam pukul sembilan"},{"id":"opt_2","text":"Sabtu pagi pukul 09.30 di pasar petani pusat kota"},{"id":"opt_3","text":"Minggu sore pukul lima"},{"id":"opt_4","text":"Senin pagi sebelum masuk kantor"}],"audio_text":"Are you doing anything Saturday morning? Let''s visit the downtown farmers market! — Sounds fun! How about meeting at nine-thirty?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Respons antusias ''Sounds fun!'' diikuti usulan waktu ''How about meeting at nine-thirty?'' pada Sabtu pagi.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000285', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat ajakan akhir pekan dengan How about: "Bagaimana kalau kita mengunjungi museum sains hari Minggu?"', '{"romaji":"/haʊ əˈbaʊt ˈvɪzɪtɪŋ ðə ˈsaɪəns mjuˈziːəm ɑːn ˈsʌndeɪ/","tokens":["How about","visiting","museum on","Sunday?","the science","to visit","visit"],"target_translation":"Bagaimana kalau kita mengunjungi museum sains hari Minggu?"}'::jsonb, '["How about","visiting","the science","museum on","Sunday?"]'::jsonb, NULL, NULL, 'Perhatikan tekanan kata ''museum'' berada di suku kata kedua: /mjuˈziːəm/!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000286', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat ajakan dengan Let''s: "Ayo kita makan siang santai (brunch) setelah lari pagi."', '{"romaji":"/lets ɡræb brʌntʃ ˈæftər ˈaʊər ˈmɔːrnɪŋ rʌn/","tokens":["after our","to grab","Let''s grab","morning","grabbing","run.","brunch"],"target_translation":"Ayo kita makan siang santai (brunch) setelah lari pagi."}'::jsonb, '["Let''s grab","brunch","after our","morning","run."]'::jsonb, NULL, NULL, '''Let''s grab brunch'' adalah ajakan sosial akhir pekan paling autentik di kota-kota Amerika.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000287', 'e4100001-0000-4000-8000-000000000035', 'e2000001-0000-4000-8000-000000000009', 'speaking', 'speaking_repeat', 'Ucapkan respons antusias menerima ajakan teman ini: "Kedengarannya seru! Ayo kita bertemu di depan gerbang taman pukul sepuluh."', '{"romaji":"/saʊndz fʌn! lets miːt ˈaʊtsaɪd ðə pɑːrk ɡeɪt æt ten/","display_text":"Sounds fun! Let''s meet outside the park gate at ten.","phonetic_breakdown":["saʊndz","fʌn","lets","miːt","ˈaʊt-saɪd","ðə","pɑːrk","ɡeɪt","æt","ten"]}'::jsonb, '{"expected_transcript":"Sounds fun! Let''s meet outside the park gate at ten."}'::jsonb, NULL, NULL, 'Ungkapan singkat ''Sounds fun!'' atau ''Sounds great!'' langsung membuatmu terdengar akrab dan suportif.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000288', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Ingat aturan khusus setelah kata kerja ''enjoy'': My roommates and I really enjoy ___ board games on rainy Sundays.', '{"options":["playing","to play","play","plays"],"translation":"Teman-teman sekamar saya dan saya sangat gemar bermain permainan papan pada hari Minggu yang hujan.","sentence_template":"My roommates and I really enjoy [blank] board games on rainy Sundays."}'::jsonb, '{"selected":"playing"}'::jsonb, NULL, NULL, 'Kata kerja ''enjoy'' wajib diikuti gerund (''Verb-ing'': ''playing''), tidak pernah diikuti ''to play''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000289', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih balasan singkat paling alami ketika kasir atau rekan kerja berkata ''Have a great weekend!'': Thanks, ___!', '{"options":["you too","me too","also I","for you"],"translation":"Terima kasih, kamu juga!","sentence_template":"Thanks, [blank]!"}'::jsonb, '{"selected":"you too"}'::jsonb, NULL, NULL, 'Untuk membalas doa/harapan baik (''Have a nice day/weekend!''), gunakan ''You too!'' (JANGAN pakai ''Me too!'', karena ''Me too'' berarti ''Semoga aku juga menyenangkan''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000290', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih idiom yang berarti ''bersantai beristirahat tanpa agenda berat'': After a busy exam week, I just want to ___ it easy this weekend.', '{"options":["take","make","do","put"],"translation":"Setelah pekan ujian yang padat, saya hanya ingin bersantai akhir pekan ini.","sentence_template":"After a busy exam week, I just want to [blank] it easy this weekend."}'::jsonb, '{"selected":"take"}'::jsonb, NULL, NULL, '''Take it easy'' adalah idiom populer yang berarti beristirahat dengan santai.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000291', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan percakapan Jumat sore di dekat lift kantor ini. Apa rencana akhir pekan Hannah?', '{"options":[{"id":"opt_1","text":"Lembur mengerjakan laporan pajak di kantor"},{"id":"opt_2","text":"Berkendara ke Danau Tahoe bersama teman-temannya untuk berkemah"},{"id":"opt_3","text":"Pindah apartemen ke pusat kota"},{"id":"opt_4","text":"Menjaga keponakannya di rumah sepanjang akhir pekan"}],"audio_text":"Any plans for the long weekend, Hannah? — Yeah! My friends and I are driving up to Lake Tahoe to go camping."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Present Continuous ''are driving up to Lake Tahoe'' juga lazim digunakan untuk rencana dekat yang sudah pasti diatur bersama teman!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000292', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan salam perpisahan barista kafe di Amerika ini. Apa arti ungkapan ''Have a good one!''?', '{"options":[{"id":"opt_1","text":"Barista meminta pelanggan membeli satu minuman lagi"},{"id":"opt_2","text":"Ucapan ramah yang mendoakan semoga hari pelanggan menyenangkan"},{"id":"opt_3","text":"Peringatan bahwa cokelatnya sudah dingin"},{"id":"opt_4","text":"Pemberitahuan bahwa kafe akan tutup selamanya"}],"audio_text":"Here''s your hot chocolate. Stay warm out there, and have a good one! — Thanks, you too!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Have a good one!'' adalah salam perpisahan kasual khas AS yang berarti ''Semoga harimu menyenangkan!''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000293', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun pertanyaan obrolan Jumat sore ini: "Apakah kamu punya rencana untuk akhir pekan ini?"', '{"romaji":"/də juː hæv ˈeni plænz fɔːr ðɪs ˈwiːkend/","tokens":["Do you","plans for","this weekend?","plan","Are you","have any"],"target_translation":"Apakah kamu punya rencana untuk akhir pekan ini?"}'::jsonb, '["Do you","have any","plans for","this weekend?"]'::jsonb, NULL, NULL, 'Di AS digunakan ''for this weekend'' atau ''on the weekend'' (di Inggris sering ''at the weekend'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000294', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat menceritakan hobi santai: "Saya gemar memasak masakan Indonesia pada akhir pekan."', '{"romaji":"/aɪ ɪnˈdʒɔɪ ˈkʊkɪŋ ˌɪndəˈniːʒən fuːd ɑːn ˈwiːkendz/","tokens":["I enjoy","to cook","foods","on weekends.","cooking","Indonesian food"],"target_translation":"Saya gemar memasak masakan Indonesia pada akhir pekan."}'::jsonb, '["I enjoy","cooking","Indonesian food","on weekends."]'::jsonb, NULL, NULL, 'Perhatikan preposisi khas AS: ''on weekends'' / ''on the weekend''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000295', 'e4100001-0000-4000-8000-000000000036', 'e2000001-0000-4000-8000-000000000009', 'speaking', 'speaking_repeat', 'Ucapkan salam perpisahan Jumat sore ini dengan hangat: "Sampai jumpa hari Senin! Selamat berakhir pekan!"', '{"romaji":"/siː juː ɑːn ˈmʌndeɪ! hæv ə ɡreɪt ˈwiːkend/","display_text":"See you on Monday! Have a great weekend!","phonetic_breakdown":["siː","juː","ɑːn","ˈmʌn-deɪ","hæv","ə","ɡreɪt","ˈwiː-kend"]}'::jsonb, '{"expected_transcript":"See you on Monday! Have a great weekend!"}'::jsonb, NULL, NULL, 'Kalimat ramah ini selalu meninggalkan kesan hangat di setiap akhir pekan kerja.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000296', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''How about'': It''s super hot outside—how about ___ iced coffee and studying in the library?', '{"options":["getting","get","to get","gets"],"translation":"Di luar panas sekali—bagaimana kalau kita membeli es kopi dan belajar di perpustakaan?","sentence_template":"It''s super hot outside—how about [blank] iced coffee and studying in the library?"}'::jsonb, '{"selected":"getting"}'::jsonb, NULL, NULL, 'Preposisi ''about'' mewajibkan Verb-ing (''getting ... and studying'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000297', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih preposisi akhir pekan yang standar dalam American English: Most campus offices are closed ___ the weekend.', '{"options":["on","in","to","from"],"translation":"Sebagian besar kantor administrasi kampus tutup pada akhir pekan.","sentence_template":"Most campus offices are closed [blank] the weekend."}'::jsonb, '{"selected":"on"}'::jsonb, NULL, NULL, 'American English menggunakan ''on the weekend'' / ''on weekends'' (berbeda dengan British ''at the weekend'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000298', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'reading', 'fill_blank', 'Pilih kalimat cuaca Present Simple untuk fakta musiman: It ___ almost every week in Minneapolis from December to February.', '{"options":["snows","snowing","is snow","snowy"],"translation":"Salju turun hampir setiap minggu di Minneapolis dari Desember hingga Februari.","sentence_template":"It [blank] almost every week in Minneapolis from December to February."}'::jsonb, '{"selected":"snows"}'::jsonb, NULL, NULL, 'Fakta musiman berulang (''every week'') dengan subjek tunggal ''It'' menggunakan Present Simple + -s (''It snows'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000299', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan prakiraan cuaca radio pagi di Denver ini. Pakaian apa yang disarankan pembawa acara untuk sore nanti?', '{"options":[{"id":"opt_1","text":"Cukup memakai kaos tanpa lengan sepanjang malam"},{"id":"opt_2","text":"Membawa pakaian renang ke pantai"},{"id":"opt_3","text":"Membawa sweater hangat untuk perjalanan pulang sore/malam karena suhu akan turun cepat"},{"id":"opt_4","text":"Tidak boleh keluar rumah selama tiga hari"}],"audio_text":"Good morning, Denver! It''s sunny and sixty-eight degrees right now, but temperatures are dropping fast tonight, so pack a warm sweater for your evening commute."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Cuaca pagi sejuk 68°F (~20°C), namun malam akan turun drastis (''temperatures are dropping fast tonight, so pack a warm sweater'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000300', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'listening', 'listening_choice', 'Dengarkan obrolan Senin pagi dua rekan kerja ini. Apa yang dilakukan Kevin selama akhir pekan kemarin?', '{"options":[{"id":"opt_1","text":"Terbang ke Florida untuk urusan bisnis mendadak"},{"id":"opt_2","text":"Sangat santai di rumah, memasak rendang, dan menonton bola basket"},{"id":"opt_3","text":"Ikut lomba lari maraton sejauh empat puluh kilometer"},{"id":"opt_4","text":"Lembur memperbaiki server kantor seharian"}],"audio_text":"Morning, Kevin! How was your weekend? — Super relaxing! I just stayed in, cookedrendang, and watched basketball."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Phrasal verb ''stayed in'' berarti menghabiskan waktu di rumah (lawan dari ''went out'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000301', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat ajakan olahraga akhir pekan: "Ayo kita bersepeda mengelilingi danau Sabtu pagi ini."', '{"romaji":"/lets ɡoʊ ˈbaɪkɪŋ əˈraʊnd ðə leɪk ðɪs ˈsætərdeɪ/","tokens":["bikes","to bike","around the","Let''s go","lake this","Saturday.","biking"],"target_translation":"Ayo kita bersepeda mengelilingi danau Sabtu pagi ini."}'::jsonb, '["Let''s go","biking","around the","lake this","Saturday."]'::jsonb, NULL, NULL, 'Kombinasikan ''Let''s + V1 (go)'' dengan aktivitas rekreasi ''go biking''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000302', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'writing', 'sentence_builder', 'Susun respons sopan terhadap ucapan selamat berakhir pekan: "Terima kasih banyak! Semoga akhir pekanmu menyenangkan juga."', '{"romaji":"/θæŋks soʊ mʌtʃ! hæv ə ɡreɪt ˈwiːkend, tuː/","tokens":["Thanks so","weekends,","a great","Me too.","weekend,","much! Have","too."],"target_translation":"Terima kasih banyak! Semoga akhir pekanmu menyenangkan juga."}'::jsonb, '["Thanks so","much! Have","a great","weekend,","too."]'::jsonb, NULL, NULL, 'Menutup Jumat sore dengan ''Have a great weekend, too!'' sangat alami.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000303', 'e4100001-0000-4000-8000-000000000037', 'e2000001-0000-4000-8000-000000000009', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan cuaca dan ajakan ini dengan lancar: "Di luar cerah dan hangat—ayo kita makan siang di taman!"', '{"romaji":"/ɪts ˈsʌni ænd wɔːrm ˈaʊtsaɪd—lets iːt lʌntʃ ɪn ðə pɑːrk/","display_text":"It''s sunny and warm outside—let''s eat lunch in the park!","phonetic_breakdown":["ɪts","ˈsʌ-ni","ænd","wɔːrm","ˈaʊt-saɪd","lets","iːt","lʌntʃ","ɪn","ðə","pɑːrk"]}'::jsonb, '{"expected_transcript":"It''s sunny and warm outside—let''s eat lunch in the park!"}'::jsonb, NULL, NULL, 'Pastikan vokal /ɑːr/ pada ''warm'' (/wɔːrm/) dan ''park'' (/pɑːrk/) terdengar bulat khas Amerika.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000304', 'e4100001-0000-4000-8000-000000000038', NULL, 'reading', 'fill_blank', 'Pilih preposisi batas waktu yang berarti ''paling lambat sebelum pukul 5 sore'': Please upload your scholarship essay ___ 5:00 p.m. on Friday.', '{"options":["by","since","from","during"],"translation":"Mohon unggah esai beasiswa Anda paling lambat pukul 5 sore hari Jumat.","sentence_template":"Please upload your scholarship essay [blank] 5:00 p.m. on Friday."}'::jsonb, '{"selected":"by"}'::jsonb, NULL, NULL, 'Preposisi ''by + waktu'' menyatakan batas akhir tenggat (deadline).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000305', 'e4100001-0000-4000-8000-000000000038', NULL, 'reading', 'fill_blank', 'Pilih kata sifat standar kampus AS untuk menyatakan ''jatuh tempo pengumpulan'': Excuse me, Professor—when is our first homework assignment ___?', '{"options":["due","done","late","open"],"translation":"Permisi, Profesor—kapan batas waktu pengumpulan tugas pertama kita?","sentence_template":"Excuse me, Professor—when is our first homework assignment [blank]?"}'::jsonb, '{"selected":"due"}'::jsonb, NULL, NULL, '''When is [assignment] due?'' adalah kalimat tanya nomor satu mahasiswa di kampus AS.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000306', 'e4100001-0000-4000-8000-000000000038', NULL, 'reading', 'fill_blank', 'Pilih istilah untuk jadwal konsultasi mingguan dosen dengan mahasiswa: If you have questions about the exam, stop by my ___ hours on Thursday.', '{"options":["office","school","desk","class"],"translation":"Jika Anda memiliki pertanyaan tentang ujian, mampirlah ke jam konsultasi (office hours) saya hari Kamis.","sentence_template":"If you have questions about the exam, stop by my [blank] hours on Thursday."}'::jsonb, '{"selected":"office"}'::jsonb, NULL, NULL, '''Office hours'' adalah sesi konsultasi akademik terbuka milik profesor atau asisten dosen (TA).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000307', 'e4100001-0000-4000-8000-000000000038', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman asisten dosen di akhir sesi praktikum ini. Di mana mahasiswa dapat mengunduh silabus terbaru?', '{"options":[{"id":"opt_1","text":"Mengambil cetakan kertas di kantor rektor"},{"id":"opt_2","text":"Mengunduh silabus terbaru di portal Canvas karena tanggal ujian tengah semester berubah ke 18 Oktober"},{"id":"opt_3","text":"Membelinya di toko buku kota"},{"id":"opt_4","text":"Tidak ada ujian tengah semester sama sekali"}],"audio_text":"Before you leave, make sure you download the updated course syllabus on Canvas—the midterm date is now October eighteenth."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Canvas (dan Blackboard) adalah platform manajemen belajar online utama di universitas-universitas AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000308', 'e4100001-0000-4000-8000-000000000038', NULL, 'listening', 'listening_choice', 'Dengarkan pesan suara rekan kerja tentang jadwal rapat satu-lawan-satu (one-on-one) berikut. Ke hari apa ia meminta pindah jadwal?', '{"options":[{"id":"opt_1","text":"Membatalkan rapat untuk selamanya"},{"id":"opt_2","text":"Menjadwalkan ulang (reschedule) ke besok pagi pukul sepuluh"},{"id":"opt_3","text":"Memajukan rapat ke pukul enam pagi hari ini"},{"id":"opt_4","text":"Menggantinya menjadi acara makan malam minggu depan"}],"audio_text":"Hi Ari, something urgent came up with a client today. Can we reschedule our one-on-one for tomorrow morning at ten?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Something urgent came up'' (ada urusan mendadak) diikuti ''reschedule ... for tomorrow morning at ten''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000309', 'e4100001-0000-4000-8000-000000000038', NULL, 'writing', 'sentence_builder', 'Susun kalimat informasi tenggat tugas: "Laporan akhir jatuh tempo pada hari Jumat tengah malam."', '{"romaji":"/ðə ˈfaɪnəl rɪˈpɔːrt ɪz duː ɑːn ˈfraɪdeɪ æt ˈmɪdnaɪt/","tokens":["due in","due on","report is","midnight.","reports","Friday at","The final"],"target_translation":"Laporan akhir jatuh tempo pada hari Jumat tengah malam."}'::jsonb, '["The final","report is","due on","Friday at","midnight."]'::jsonb, NULL, NULL, 'Kombinasikan ''is due on Friday'' + ''at midnight''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
