INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000320', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'reading', 'fill_blank', 'Pilih sapaan pembuka email paling tepat untuk dosen bernama Dr. Rebecca Chen: ___ Professor Chen,', '{"options":["Dear","Hey yo","To","Miss"],"translation":"Yth. Profesor Chen,","sentence_template":"[blank] Professor Chen,"}'::jsonb, '{"selected":"Dear"}'::jsonb, NULL, NULL, '''Dear Professor [Last Name],'' (atau ''Hello Professor [Last Name],'') adalah standar kesopanan email akademik di AS.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000321', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat pembuka hangat di baris pertama email: Hi Marcus, I ___ you''re having a good week!', '{"options":["hope","hoping","am hope","hopes"],"translation":"Halo Marcus, semoga minggu Anda berjalan menyenangkan!","sentence_template":"Hi Marcus, I [blank] you''re having a good week!"}'::jsonb, '{"selected":"hope"}'::jsonb, NULL, NULL, 'Subjek ''I'' diikuti kata kerja Present Simple ''hope'' (''I hope you''re doing well / having a good week'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000322', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'reading', 'fill_blank', 'Pilih salam penutup email profesional yang lazim dipakai di AS sebelum tanda tangan nama Anda: ___ regards, Dimas Pratama', '{"options":["Best","Good","Nice","Well"],"translation":"Salam hormat, Dimas Pratama","sentence_template":"[blank] regards, Dimas Pratama"}'::jsonb, '{"selected":"Best"}'::jsonb, NULL, NULL, '''Best regards,'' (atau cukup ''Best,'' / ''Sincerely,'') adalah penutup email standar internasional.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000323', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'listening', 'listening_choice', 'Dengarkan isi pesan email singkat mahasiswa kepada dosennya ini. Apa tujuan mahasiswa mengirim email tersebut?', '{"options":[{"id":"opt_1","text":"Meminta nilai tambahan tanpa mengikuti ujian akhir"},{"id":"opt_2","text":"Memberi kabar sopan bahwa ia tidak bisa hadir kuliah hari ini karena demam tinggi dan akan menyalin catatan teman"},{"id":"opt_3","text":"Mengundang profesor makan siang di kantin"},{"id":"opt_4","text":"Mendaftar sebagai asisten laboratorium tahun depan"}],"audio_text":"Dear Professor Patel, I''m in your Tuesday morning statistics class. I have a high fever today, so I can''t attend lecture. I''ll get the notes from a classmate."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Email yang baik menyebutkan kelas mana yang diikuti (''Tuesday morning statistics class''), alasan singkat, dan tanggung jawab mandiri.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000324', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'listening', 'listening_choice', 'Dengarkan balasan singkat manajer atas email anggota timnya. Kapan mereka akan membahas draf proposal tersebut?', '{"options":[{"id":"opt_1","text":"Draf proposal ditolak seluruhnya hari ini"},{"id":"opt_2","text":"Mereka akan meninjau tabel anggaran bersama pada Rabu pagi"},{"id":"opt_3","text":"Manajer meminta Tari menghapus semua tabel"},{"id":"opt_4","text":"Pembahasan ditunda sampai bulan Desember"}],"audio_text":"Hi Tari, thanks for sending the draft! Everything looks clear so far—let''s go over the budget table together on Wednesday morning."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Phrasal verb ''go over'' berarti memeriksa/membahas secara rinci bersama-sama.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000325', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'writing', 'sentence_builder', 'Susun baris pembuka email yang ramah dan profesional: "Semoga kabar Anda baik minggu ini."', '{"romaji":"/aɪ hoʊp jʊr ˈduːɪŋ wel ðɪs wiːk/","tokens":["this week.","you doing","I hope","you''re","doing well","wells"],"target_translation":"Semoga kabar Anda baik minggu ini."}'::jsonb, '["I hope","you''re","doing well","this week."]'::jsonb, NULL, NULL, 'Ingat gunakan kata keterangan ''well'' pada ''doing well'' (dalam konteks kesehatan/kabar formal).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000326', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat penutup email ucapan terima kasih: "Terima kasih banyak atas waktu dan bantuan Anda."', '{"romaji":"/θæŋk juː soʊ mʌtʃ fɔːr jʊr taɪm ænd help/","tokens":["time and","Thank you","so much","for you","for your","help.","helps."],"target_translation":"Terima kasih banyak atas waktu dan bantuan Anda."}'::jsonb, '["Thank you","so much","for your","time and","help."]'::jsonb, NULL, NULL, 'Kalimat apresiasi penutup yang sopan sebelum menulis ''Best regards,''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000327', 'e4100001-0000-4000-8000-000000000040', 'e2000001-0000-4000-8000-000000000010', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konfirmasi di telepon/rapat ini dengan mantap: "Terima kasih atas bantuan Anda—saya akan memberi tahu Anda besok!"', '{"romaji":"/θæŋk juː fɔːr jʊr help—aɪl let juː noʊ təˈmɑːroʊ/","display_text":"Thank you for your help—I''ll let you know tomorrow!","phonetic_breakdown":["θæŋk","juː","fɔːr","jʊr","help","aɪl","let","juː","noʊ","tə-ˈmɑːr-oʊ"]}'::jsonb, '{"expected_transcript":"Thank you for your help—I''ll let you know tomorrow!"}'::jsonb, NULL, NULL, 'Bunyikan konsonan awal ''th'' pada ''Thank'' (/θæŋk/) dengan ujung lidah ringan di antara gigi, bukan /t/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000328', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'reading', 'fill_blank', 'Pilih kata ganti objek yang tepat setelah preposisi ''for'': Mr. Evans is busy today, so can you answer these emails for ___?', '{"options":["him","he","his","himselfs"],"translation":"Pak Evans sedang sibuk hari ini, jadi bisakah kamu membalas email-email ini untuk beliau?","sentence_template":"Mr. Evans is busy today, so can you answer these emails for [blank]?"}'::jsonb, '{"selected":"him"}'::jsonb, NULL, NULL, 'Setelah preposisi ''for'', kata ganti untuk ''Mr. Evans'' (he) adalah ''him''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
