INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000330', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'reading', 'fill_blank', 'Lengkapi idiom menanyakan kecocokan jadwal rapat: ___ 10:30 tomorrow morning work for everyone?', '{"options":["Does","Is","Are","Do"],"translation":"Apakah pukul 10.30 besok pagi cocok untuk jadwal semua orang?","sentence_template":"[blank] 10:30 tomorrow morning work for everyone?"}'::jsonb, '{"selected":"Does"}'::jsonb, NULL, NULL, 'Waktu spesifik ''10:30 tomorrow morning'' diperlakukan sebagai subjek tunggal + kata kerja ''work'', sehingga memakai ''Does''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000331', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'listening', 'listening_choice', 'Dengarkan pesan asisten administrasi jurusan ini. Apa dokumen yang masih kurang dari berkas pendaftaran beasiswa Bima?', '{"options":[{"id":"opt_1","text":"Formulir biodata dan paspor asli"},{"id":"opt_2","text":"Satu surat rekomendasi lagi paling lambat Kamis sore"},{"id":"opt_3","text":"Sertifikat kesehatan dari rumah sakit daerah"},{"id":"opt_4","text":"Bukti pembayaran uang asrama"}],"audio_text":"Hi Bima! We received your application form and essay, but we still need one recommendation letter by Thursday afternoon."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Still need one recommendation letter by Thursday afternoon'' menyebutkan berkas yang kurang beserta tenggatnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000332', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'listening', 'listening_choice', 'Dengarkan diskusi singkat dua anggota tim produk berikut. Bagaimana mereka membagi tugas sebelum presentasi?', '{"options":[{"id":"opt_1","text":"Satu orang mengerjakan semuanya sendirian malam ini"},{"id":"opt_2","text":"Rekan pertama menyelesaikan slide pembuka dan mengirimkannya malam ini, lalu pembicara kedua menambahkan grafik penjualan besok pagi"},{"id":"opt_3","text":"Presentasi dibatalkan karena data penjualan hilang"},{"id":"opt_4","text":"Mereka menyerahkan tugas pembuatan slide kepada tim HR"}],"audio_text":"Can you finish the intro slides today? If you email them to me tonight, I can add the sales charts tomorrow morning."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pembagian kerja jelas: ''email them to me tonight'' -> ''I can add the sales charts tomorrow morning''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000333', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat menanyakan jam konsultasi dosen: "Kapan jam konsultasi Profesor Lin pada hari Selasa?"', '{"romaji":"/wen ɑːr prəˈfesər lɪnz ˈɔːfɪs ˈaʊərz ɑːn ˈtuːzdeɪz/","tokens":["When are","hour","When is","Professor Lin''s","office hours","on Tuesdays?"],"target_translation":"Kapan jam konsultasi Profesor Lin pada hari Selasa?"}'::jsonb, '["When are","Professor Lin''s","office hours","on Tuesdays?"]'::jsonb, NULL, NULL, 'Karena ''office hours'' berbentuk jamak, gunakan ''When are...?''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000334', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat konfirmasi penerimaan dokumen tunggal: "Saya sudah menerima berkasnya—terima kasih sudah mengirimkannya!"', '{"romaji":"/aɪ ɡɑːt ðə faɪl—θæŋks fɔːr ˈsendɪŋ ɪt/","tokens":["send it!","sending it!","thanks for","the file—","sending them!","I got"],"target_translation":"Saya sudah menerima berkasnya—terima kasih sudah mengirimkannya!"}'::jsonb, '["I got","the file—","thanks for","sending it!"]'::jsonb, NULL, NULL, 'Setelah preposisi ''for'' gunakan Verb-ing (''sending''), dan ''the file'' tunggal dirujuk dengan ''it''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000335', 'e4100001-0000-4000-8000-000000000041', 'e2000001-0000-4000-8000-000000000010', 'speaking', 'speaking_repeat', 'Selamat di puncak Level A1! Ucapkan kalimat profesional ini dengan penuh percaya diri: "Mohon beri tahu saya jika hari Rabu cocok dengan jadwal Anda."', '{"romaji":"/pliːz let miː noʊ ɪf ˈwenzdeɪ wɜːrks fɔːr juː/","display_text":"Please let me know if Wednesday works for you.","phonetic_breakdown":["pliːz","let","miː","noʊ","ɪf","ˈwenz-deɪ","wɜːrks","fɔːr","juː"]}'::jsonb, '{"expected_transcript":"Please let me know if Wednesday works for you."}'::jsonb, NULL, NULL, 'Ingat ''Wednesday'' cukup 2 suku kata (/ˈwenz-deɪ/)! Kamu siap menghadapi Ujian Simulasi Kesiapan A1!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000336', 'e4100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Lengkapi perkenalan profesional berikut: Hello, my name is Clara, and I ___ an international student at UCLA.', '{"options":["am","is","are","be"],"translation":"Halo, nama saya Clara, dan saya seorang mahasiswa internasional di UCLA.","sentence_template":"Hello, my name is Clara, and I [blank] an international student at UCLA."}'::jsonb, '{"selected":"am"}'::jsonb, NULL, NULL, 'Subjek ''I'' selalu menggunakan kata kerja bantu ''am'' dalam kalimat nominal Present Simple.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000337', 'e4100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Pilih kata kerja rutinitas yang tepat: Our product team ___ a quick morning meeting at 9:00 a.m. every weekday.', '{"options":["has","have","having","is have"],"translation":"Tim produk kami mengadakan rapat pagi singkat pukul 09.00 setiap hari kerja.","sentence_template":"Our product team [blank] a quick morning meeting at 9:00 a.m. every weekday."}'::jsonb, '{"selected":"has"}'::jsonb, NULL, NULL, 'Dalam American English, kata benda kolektif tunggal seperti ''Our product team'' diperlakukan tunggal sehingga memakai ''has''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000338', 'e4100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat aktivitas yang sedang berlangsung: Please be quiet—the students ___ a listening quiz right now.', '{"options":["are taking","take","takes","is taking"],"translation":"Harap tenang—para mahasiswa sedang mengerjakan kuis menyimak sekarang.","sentence_template":"Please be quiet—the students [blank] a listening quiz right now."}'::jsonb, '{"selected":"are taking"}'::jsonb, NULL, NULL, 'Subjek jamak ''the students'' + penanda waktu ''right now'' membutuhkan Present Continuous ''are taking''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000339', 'e4100001-0000-4000-8000-000000000042', NULL, 'reading', 'fill_blank', 'Pilih modal dasar yang tepat untuk menanyakan kemampuan: ___ you share your screen on Zoom, please?', '{"options":["Can","Are","Do","Am"],"translation":"Bisakah Anda membagikan layar Anda di Zoom?","sentence_template":"[blank] you share your screen on Zoom, please?"}'::jsonb, '{"selected":"Can"}'::jsonb, NULL, NULL, '''Can you + V1, please?'' adalah pola permintaan sopan sekaligus menanyakan kemampuan langsung.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000340', 'e4100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan kasir toko buku kampus ini. Berapa total harga yang harus dibayar pembeli?', '{"options":[{"id":"opt_1","text":"Dua puluh empat dolar ($24.00)"},{"id":"opt_2","text":"Tiga puluh dua dolar ($32.00)"},{"id":"opt_3","text":"Empat puluh dolar pas ($40.00)"},{"id":"opt_4","text":"Empat puluh delapan dolar ($48.00)"}],"audio_text":"Your notebook is eight dollars, and the campus hoodie is thirty-two dollars, so your total comes to forty dollars even."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Forty dollars even'' ($8 + $32 = $40) berarti empat puluh dolar bulat tanpa sen tambahan.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000341', 'e4100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan petunjuk arah di bandara AS ini. Di mana letak area pengambilan bagasi (Baggage Claim)?', '{"options":[{"id":"opt_1","text":"Di lantai atas tepat di sebelah ruang tunggu VIP"},{"id":"opt_2","text":"Di lantai bawah setelah turun eskalator, tepat di samping pangkalan taksi"},{"id":"opt_3","text":"Di seberang toko bebas bea dekat Gate A1"},{"id":"opt_4","text":"Di luar gedung terminal tiga dekat halte bus"}],"audio_text":"Go straight past Gate B12 and take the escalator down to the lower level. Baggage Claim is right next to the taxi stand."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Frasa ''take the escalator down to the lower level'' dan ''right next to the taxi stand'' menunjukkan lokasi di lantai bawah.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000342', 'e4100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan rencana akhir pekan di Chicago berikut. Mengapa mereka memilih pergi ke museum hari Minggu?', '{"options":[{"id":"opt_1","text":"Karena tiket danau sudah habis terjual"},{"id":"opt_2","text":"Karena prakiraan cuaca hari Minggu akan hujan sepanjang hari"},{"id":"opt_3","text":"Karena museum tutup pada hari Sabtu"},{"id":"opt_4","text":"Karena mereka harus bekerja lembur di kantor"}],"audio_text":"It''s supposed to rain all day Sunday, so let''s visit the Art Institute instead of walking by the lake."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''It''s supposed to rain all day Sunday'' berarti prakiraan cuaca memprediksi hujan seharian pada hari Minggu.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000343', 'e4100001-0000-4000-8000-000000000042', NULL, 'listening', 'listening_choice', 'Dengarkan pesan singkat rekan sekantor ini. Di mana mereka akan bertemu untuk makan siang?', '{"options":[{"id":"opt_1","text":"Di ruang rapat lantai lima pukul satu siang"},{"id":"opt_2","text":"Di lobi gedung pukul 12.00 siang lalu membeli roti lapis di seberang jalan"},{"id":"opt_3","text":"Di stasiun kereta bawah tanah pukul tujuh malam"},{"id":"opt_4","text":"Di perpustakaan kampus setelah jam makan malam"}],"audio_text":"Hey! Let''s meet in the lobby at noon and grab sandwiches at the deli across the street."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''At noon'' berarti pukul 12.00 siang tepat, dan ''across the street'' berarti di seberang jalan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000344', 'e4100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat pemesanan sopan di restoran AS: "Saya ingin memesan burger ayam panggang dan air putih."', '{"romaji":"/aɪd laɪk ə ɡrɪld ˈtʃɪkɪn ˈbɜːrɡər ænd ˈwɔːtər, pliːz/","tokens":["I''d like","chicken burger","and water,","I liking","please.","waters","a grilled"],"target_translation":"Saya ingin memesan burger ayam panggang dan air putih."}'::jsonb, '["I''d like","a grilled","chicken burger","and water,","please."]'::jsonb, NULL, NULL, 'Gunakan ''I''d like'' (I would like) saat memesan makanan agar terdengar jauh lebih sopan daripada ''I want''.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000345', 'e4100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat informasi keluarga & profesi: "Kakak perempuan saya bekerja sebagai perawat di Seattle."', '{"romaji":"/maɪ ˈoʊldər ˈsɪstər wɜːrks æz ə nɜːrs ɪn siˈætəl/","tokens":["My older sister","works as","working","in Seattle.","a nurse","work"],"target_translation":"Kakak perempuan saya bekerja sebagai perawat di Seattle."}'::jsonb, '["My older sister","works as","a nurse","in Seattle."]'::jsonb, NULL, NULL, 'Gunakan pola ''works as + a/an + profesi'' untuk subjek tunggal orang ketiga (''My older sister'').', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000346', 'e4100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat tanya jadwal kelas: "Jam berapa kelas bahasa Inggris kita dimulai hari Senin?"', '{"romaji":"/wʌt taɪm dʌz ˈaʊər ˈɪŋɡlɪʃ klæs stɑːrt ɑːn ˈmʌndeɪ/","tokens":["does our","starts","start on","What time","do our","English class","Monday?"],"target_translation":"Jam berapa kelas bahasa Inggris kita dimulai hari Senin?"}'::jsonb, '["What time","does our","English class","start on","Monday?"]'::jsonb, NULL, NULL, 'Karena ''our English class'' tunggal, gunakan kata bantu tanya ''does'' + kata kerja dasar ''start'' (tanpa -s).', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000347', 'e4100001-0000-4000-8000-000000000042', NULL, 'writing', 'sentence_builder', 'Susun kalimat komunikasi dasar di kantor: "Bisakah Anda mengeja nama belakang Anda untuk saya?"', '{"romaji":"/kæn juː spel jʊr læst neɪm fɔːr miː, pliːz/","tokens":["spell your","names","Can you","for me,","please?","spelling","last name"],"target_translation":"Bisakah Anda mengeja nama belakang Anda untuk saya?"}'::jsonb, '["Can you","spell your","last name","for me,","please?"]'::jsonb, NULL, NULL, 'Dalam American English, nama keluarga/marga sehari-hari disebut ''last name'' (lebih umum dibanding ''surname'').', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000348', 'e4100001-0000-4000-8000-000000000042', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan profesional ini dengan jelas: "Halo, saya Raka dari tim desain produk di Jakarta."', '{"romaji":"/haɪ, aɪm ˈrɑːkə frʌm ðə ˈprɑːdʌkt dɪˈzaɪn tiːm ɪn dʒəˈkɑːrtə/","display_text":"Hi, I''m Raka from the product design team in Jakarta.","phonetic_breakdown":["haɪ","aɪm","ˈrɑː-kə","frʌm","ðə","ˈprɑː-dʌkt","dɪ-ˈzaɪn","tiːm","ɪn","dʒə-ˈkɑːr-tə"]}'::jsonb, '{"expected_transcript":"Hi, I''m Raka from the product design team in Jakarta."}'::jsonb, NULL, NULL, 'Perhatikan lafal US ''product'' /ˈprɑːdʌkt/ dengan bunyi vokal terbuka /ɑː/ seperti kata ''father''.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000349', 'e4100001-0000-4000-8000-000000000042', NULL, 'speaking', 'speaking_repeat', 'Tirukan kalimat memesan kopi ala Amerika berikut: "Bolehkah saya pesan kopi hitam ukuran kecil untuk dibawa pulang?"', '{"romaji":"/kæn aɪ ɡet ə smɔːl blæk ˈkɔːfi tə ɡoʊ, pliːz/","display_text":"Can I get a small black coffee to go, please?","phonetic_breakdown":["kæn","aɪ","ɡet","ə","smɔːl","blæk","ˈkɔː-fi","tə","ɡoʊ","pliːz"]}'::jsonb, '{"expected_transcript":"Can I get a small black coffee to go, please?"}'::jsonb, NULL, NULL, 'Istilah ''to go'' adalah ungkapan standar Amerika untuk makanan/minuman yang dibawa pulang (bukan ''take away'').', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000350', 'e4100001-0000-4000-8000-000000000042', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan petunjuk arah ini dengan intonasi natural: "Permisi, di mana letak toilet terdekat?"', '{"romaji":"/ɪkˈskjuːz miː, wer ɪz ðə ˈnɪrɪst ˈrestruːm/","display_text":"Excuse me, where is the nearest restroom?","phonetic_breakdown":["ɪk-ˈskjuːz","miː","wer","ɪz","ðə","ˈnɪr-ɪst","ˈrest-ruːm"]}'::jsonb, '{"expected_transcript":"Excuse me, where is the nearest restroom?"}'::jsonb, NULL, NULL, 'Di tempat umum AS (kafe, bandara, kantor), gunakan kata sopan ''restroom'' alih-alih ''toilet''.', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000351', 'e4100001-0000-4000-8000-000000000042', NULL, 'speaking', 'speaking_repeat', 'Tirukan kalimat laporan aktivitas ini: "Saya sedang menunggu kereta bawah tanah di peron sekarang."', '{"romaji":"/aɪ æm ˈweɪtɪŋ fɔːr ðə ˈsʌbweɪ ɑːn ðə ˈplætfɔːrm raɪt naʊ/","display_text":"I am waiting for the subway on the platform right now.","phonetic_breakdown":["aɪ","æm","ˈweɪ-tɪŋ","fɔːr","ðə","ˈsʌb-weɪ","ɑːn","ðə","ˈplæt-fɔːrm","raɪt","naʊ"]}'::jsonb, '{"expected_transcript":"I am waiting for the subway on the platform right now."}'::jsonb, NULL, NULL, 'Dalam aksen Amerika, huruf ''t'' di tengah kata ''waiting'' diucapkan lembut seperti flap /ɾ/ (''weiring'').', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000352', 'e4100001-0000-4000-8000-000000000043', NULL, 'reading', 'fill_blank', 'Pilih penanda waktu yang alami dalam bahasa Inggris untuk ''tadi malam'': Our team deployed the website update ___ night.', '{"options":["last","yesterday","ago","before"],"translation":"Tim kami menerapkan pembaruan situs web tadi malam.","sentence_template":"Our team deployed the website update [blank] night."}'::jsonb, '{"selected":"last"}'::jsonb, NULL, NULL, 'Pasangan baku untuk malam kemarin adalah ''last night'' (bukan ''yesterday night'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000353', 'e4100001-0000-4000-8000-000000000043', NULL, 'reading', 'fill_blank', 'Pilih ejaan Past Simple yang benar untuk kata berakhiran konsonan + y (''apply''): Rina ___ for a Fulbright scholarship in May.', '{"options":["applied","applyed","applies","applying"],"translation":"Rina melamar beasiswa Fulbright pada bulan Mei lalu.","sentence_template":"Rina [blank] for a Fulbright scholarship in May."}'::jsonb, '{"selected":"applied"}'::jsonb, NULL, NULL, 'Kata kerja berakhiran konsonan + y (''apply'') mengubah ''y'' menjadi ''i'' sebelum ''-ed'' (''applied'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000354', 'e4100001-0000-4000-8000-000000000043', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk melengkapi frasa ''tiga tahun yang lalu'': My brother moved to Chicago three years ___.', '{"options":["ago","last","before","past"],"translation":"Kakak laki-laki saya pindah ke Chicago tiga tahun yang lalu.","sentence_template":"My brother moved to Chicago three years [blank]."}'::jsonb, '{"selected":"ago"}'::jsonb, NULL, NULL, 'Pola hitungan mundur dari sekarang selalu memakai ''[durasi] + ago'' (''three years ago'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000355', 'e4100001-0000-4000-8000-000000000043', NULL, 'listening', 'listening_choice', 'Dengarkan cerita karyawan baru tentang latar belakang kuliahnya. Kapan dan dari mana ia lulus?', '{"options":[{"id":"opt_1","text":"Masih kuliah semester satu sekarang"},{"id":"opt_2","text":"Lulus dari Universitas Gadjah Mada tahun 2023 lalu bekerja di startup fintech selama setahun"},{"id":"opt_3","text":"Pindah kerja ke bank pada tahun 2018"},{"id":"opt_4","text":"Lulus SMA di Boston bulan lalu"}],"audio_text":"I graduated from Gadjah Mada University in twenty twenty-three, and then I worked at a fintech startup for a year."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Tahun 2023 lazim dibaca dua pasang angka ''twenty twenty-three'' dalam American English.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000356', 'e4100001-0000-4000-8000-000000000043', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan Senin pagi di kantor ini. Apa yang dilakukan Marcus pada Sabtu sore lalu?', '{"options":[{"id":"opt_1","text":"Tidur sepanjang akhir pekan karena flu"},{"id":"opt_2","text":"Membersihkan apartemen dan membantu temannya pindahan ke asrama baru"},{"id":"opt_3","text":"Menonton pertandingan bisbol di stadion"},{"id":"opt_4","text":"Mengerjakan lembur laporan keuangan"}],"audio_text":"How was your Saturday, Marcus? — Really productive! I cleaned my apartment and helped my friend move into his new dorm."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Cleaned'' (/kliːnd/) dan ''helped'' (/helpt/) menceritakan dua kegiatan selesai di hari Sabtu.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000357', 'e4100001-0000-4000-8000-000000000043', NULL, 'writing', 'sentence_builder', 'Susun kalimat masa lampau ini: "Saya menyelesaikan draf presentasinya tadi malam."', '{"romaji":"/aɪ ˈfɪnɪʃt ðə ˌprezənˈteɪʃən dræft læst naɪt/","tokens":["finishes","last night.","yesterday night.","I finished","the presentation","draft"],"target_translation":"Saya menyelesaikan draf presentasinya tadi malam."}'::jsonb, '["I finished","the presentation","draft","last night."]'::jsonb, NULL, NULL, 'Lafalkan ''finished'' satu hembusan /ˈfɪnɪʃt/ diikuti ''last night''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000358', 'e4100001-0000-4000-8000-000000000043', NULL, 'writing', 'sentence_builder', 'Susun kalimat riwayat pendidikan ini: "Dia lulus kuliah dua tahun yang lalu."', '{"romaji":"/ʃiː ˈɡrædʒueɪtɪd frʌm ˈkɑːlɪdʒ tuː jɪrz əˈɡoʊ/","tokens":["She graduated","last two","from college","graduates","ago.","two years"],"target_translation":"Dia lulus kuliah dua tahun yang lalu."}'::jsonb, '["She graduated","from college","two years","ago."]'::jsonb, NULL, NULL, 'Perhatikan di AS: kita mengatakan ''graduate FROM college'' (wajib pakai ''from''!).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000359', 'e4100001-0000-4000-8000-000000000043', NULL, 'speaking', 'speaking_repeat', 'Latih ketiga variasi bunyi -ed (/d/, /t/, /ɪd/) dalam satu kalimat ini: "Saya menelepon klien, menyelesaikan berkasnya, dan memulai proyek baru."', '{"romaji":"/aɪ kɔːld ðə ˈklaɪənt, ˈfɪnɪʃt ðə faɪl, ænd ˈstɑːrtɪd ə nuː ˈprɑːdʒekt/","display_text":"I called the client, finished the file, and started a new project.","phonetic_breakdown":["aɪ","kɔːld","ðə","ˈklaɪ-ənt","ˈfɪ-nɪʃt","ðə","faɪl","ænd","ˈstɑːr-tɪd","ə","nuː","ˈprɑː-dʒekt"]}'::jsonb, '{"expected_transcript":"I called the client, finished the file, and started a new project."}'::jsonb, NULL, NULL, 'Rasakan bedanya: ''called'' (/d/), ''finished'' (/t/), dan ''started'' (/ɪd/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000360', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Perhatikan bentuk kata kerja setelah ''didn''t'': Sorry I missed your call—I didn''t ___ my phone on my desk.', '{"options":["have","had","has","having"],"translation":"Maaf saya melewatkan teleponmu—tadi saya tidak menaruh ponsel di meja saya.","sentence_template":"Sorry I missed your call—I didn''t [blank] my phone on my desk."}'::jsonb, '{"selected":"have"}'::jsonb, NULL, NULL, 'Setelah ''didn''t'', kata kerja wajib kembali ke bentuk dasar V1 (''have'', bukan ''had'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000361', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih To Be lampau yang tepat untuk menanyakan kondisi perjalanan (tanpa kata kerja aksi!): How ___ your flight from Jakarta to Los Angeles?', '{"options":["was","did","were","had"],"translation":"Bagaimana penerbanganmu dari Jakarta ke Los Angeles?","sentence_template":"How [blank] your flight from Jakarta to Los Angeles?"}'::jsonb, '{"selected":"was"}'::jsonb, NULL, NULL, 'Karena tidak ada kata kerja aksi dan ''your flight'' tunggal, gunakan To Be lampau ''was'' (''How was your flight?'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000362', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih bentuk V2 tak beraturan dari ''write'': Two weeks ago, Elena ___ an article about clean energy.', '{"options":["wrote","writed","written","writes"],"translation":"Dua minggu lalu, Elena menulis sebuah artikel tentang energi bersih.","sentence_template":"Two weeks ago, Elena [blank] an article about clean energy."}'::jsonb, '{"selected":"wrote"}'::jsonb, NULL, NULL, 'Bentuk Past Simple (V2) dari ''write'' adalah ''wrote'' (sedangkan ''written'' adalah V3).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000363', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan percakapan rekan tim tentang rapat klien kemarin. Mengapa klien tampak sangat senang?', '{"options":[{"id":"opt_1","text":"Rapat dibatalkan karena badai salju"},{"id":"opt_2","text":"Berjalan sangat lancar; klien menyukai prototipenya dan langsung menandatangani kesepakatan"},{"id":"opt_3","text":"Prototipe aplikasi mengalami gagal muat saat demo"},{"id":"opt_4","text":"Klien meminta waktu berpikir enam bulan lagi"}],"audio_text":"How did the client pitch go yesterday? — It went really well! They loved our prototype and signed the agreement right away."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''It went really well!'' (V2 dari ''go'') + ''signed the agreement right away'' menunjukkan kesuksesan penuh.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000364', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan obrolan dua mahasiswa seusai ujian tengah semester. Mengapa pembicara kedua tidak sempat menjawab soal esai terakhir?', '{"options":[{"id":"opt_1","text":"Karena pena tintanya habis di tengah ujian"},{"id":"opt_2","text":"Karena ia kehabisan waktu (''ran out of time'') sehingga tidak menyelesaikan esai terakhir"},{"id":"opt_3","text":"Karena ia salah menghafal bab buku"},{"id":"opt_4","text":"Karena ia datang terlambat satu jam"}],"audio_text":"Were the midterm questions tough? — Not really, but I ran out of time, so I didn''t finish the last essay."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Idiom ''ran out of time'' (lampau dari ''run out of time'') berarti kehabisan alokasi waktu.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000365', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun pertanyaan lampau menggunakan Did: "Apakah kamu menerima email konfirmasinya tadi pagi?"', '{"romaji":"/dɪd juː ɡet ðə ˌkɑːnfərˈmeɪʃən ˈiːmeɪl ðɪs ˈmɔːrnɪŋ/","tokens":["email this","Were you","confirmation","got","get the","Did you","morning?"],"target_translation":"Apakah kamu menerima email konfirmasinya tadi pagi?"}'::jsonb, '["Did you","get the","confirmation","email this","morning?"]'::jsonb, NULL, NULL, 'Jika pagi sudah lewat (misalnya sekarang siang/sore), ''this morning'' menggunakan Past Simple ''Did you get...?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000366', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat cerita masa lalu dengan To Be jamak: "Tiket konsernya terjual habis dalam lima menit."', '{"romaji":"/ðə ˈkɑːnsərt ˈtɪkɪts wɜːr soʊld aʊt ɪn faɪv ˈmɪnɪts/","tokens":["five minutes.","tickets","were sold","was sold","The concert","out in","did sold"],"target_translation":"Tiket konsernya terjual habis dalam lima menit."}'::jsonb, '["The concert","tickets","were sold","out in","five minutes."]'::jsonb, NULL, NULL, 'Subjek jamak ''tickets'' memakai ''were'' (''sold out'' = terjual habis).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000367', 'e4100001-0000-4000-8000-000000000044', 'e2000001-0000-4000-8000-000000000011', 'speaking', 'speaking_repeat', 'Ucapkan cerita pengalaman singkat ini dengan intonasi mengalir: "Kami pergi ke Seattle bulan lalu dan bersenang-senang di sana."', '{"romaji":"/wiː went tə siˈætəl læst mʌnθ ænd hæd ə ɡreɪt taɪm/","display_text":"We went to Seattle last month and had a great time.","phonetic_breakdown":["wiː","went","tə","si-ˈæ-təl","læst","mʌnθ","ænd","hæd","ə","ɡreɪt","taɪm"]}'::jsonb, '{"expected_transcript":"We went to Seattle last month and had a great time."}'::jsonb, NULL, NULL, '''Had a great time'' adalah idiom paling alami untuk mengatakan ''sangat menikmati waktu / bersenang-senang''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000368', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih antara ''during'' dan ''for'' sebelum kata benda peristiwa ''my exchange semester'': I met friends from twenty countries ___ my exchange semester in Michigan.', '{"options":["during","for","ago","while"],"translation":"Saya bertemu teman-teman dari dua puluh negara selama semester pertukaran saya di Michigan.","sentence_template":"I met friends from twenty countries [blank] my exchange semester in Michigan."}'::jsonb, '{"selected":"during"}'::jsonb, NULL, NULL, '''My exchange semester'' adalah nama periode/peristiwa (bukan angka durasi), sehingga memakai ''during''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000369', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih preposisi yang selalu berpasangan dengan kata kerja ''majored'': In college, Bagas ___ in mechanical engineering.', '{"options":["majored","graduated","worked","studied at"],"translation":"Saat kuliah, Bagas mengambil jurusan teknik mesin.","sentence_template":"In college, Bagas [blank] in mechanical engineering."}'::jsonb, '{"selected":"majored"}'::jsonb, NULL, NULL, 'Ungkapan standar akademik AS untuk menyebutkan jurusan masa S1 adalah ''majored in [bidang studi]''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000370', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih V2 tak beraturan dari kata kerja ''build'': Last summer, we ___ an automated dashboard for the sales team.', '{"options":["built","builded","building","builds"],"translation":"Musim panas lalu, kami membangun dasbor otomatis untuk tim penjualan.","sentence_template":"Last summer, we [blank] an automated dashboard for the sales team."}'::jsonb, '{"selected":"built"}'::jsonb, NULL, NULL, 'Bentuk Past Simple dari ''build'' adalah ''built'' (/bɪlt/, huruf d berubah menjadi t).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000371', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan kisah singkat awal karier desainer produk ini. Bagaimana ia mendapatkan pekerjaan tetap pertamanya?', '{"options":[{"id":"opt_1","text":"Ia langsung mendirikan perusahaan sendiri sebelum lulus"},{"id":"opt_2","text":"Ia magang di studio desain di Portland selama 3 bulan, lalu ditawari posisi penuh waktu di bulan September"},{"id":"opt_3","text":"Ia pindah bidang menjadi koki restoran"},{"id":"opt_4","text":"Ia belum pernah magang sama sekali"}],"audio_text":"I interned at a design studio in Portland for three months after graduation, and then they offered me a full-time role in September."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Alur kronologisnya sangat jelas: ''interned ... for three months'' -> ''and then they offered me a full-time role''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000372', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan pengalaman mahasiswa yang pertama kali mengalami musim dingin di Chicago. Apa kesalahan lucu yang ia lakukan di hari pertama turun salju?', '{"options":[{"id":"opt_1","text":"Ia lupa membawa tas kuliah ke kampus"},{"id":"opt_2","text":"Ia memakai sepatu kanvas biasa alih-alih sepatu bot tahan air sehingga kaus kakinya basah kuyup"},{"id":"opt_3","text":"Ia naik bus ke arah kota yang salah"},{"id":"opt_4","text":"Ia tertidur di perpustakaan sampai pagi"}],"audio_text":"On my first snowy day in Chicago, I wore regular canvas sneakers instead of waterproof boots, so my socks got completely soaked!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Wore'' (V2 dari ''wear'') dan ''got completely soaked'' (basah kuyup) menghidupkan cerita pengalaman pribadi.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000373', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat riwayat kuliah ini: "Saya mengambil jurusan ilmu komputer di universitas."', '{"romaji":"/aɪ ˈmeɪdʒərd ɪn kəmˈpjuːtər ˈsaɪəns ɪn ˈkɑːlɪdʒ/","tokens":["majoring","I majored","at science","in college.","in computer","science"],"target_translation":"Saya mengambil jurusan ilmu komputer di universitas."}'::jsonb, '["I majored","in computer","science","in college."]'::jsonb, NULL, NULL, 'Di AS dikatakan ''in college'' (tanpa ''the'') ketika merujuk masa kuliah secara umum.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000374', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat durasi magang masa lalu: "Dia menjalani magang di rumah sakit selama empat bulan."', '{"romaji":"/ʃiː ˈɪntɜːrnd æt ə ˈhɑːspɪtəl fɔːr fɔːr mʌnθs/","tokens":["hospital for","at a","interns","She interned","four months.","during four"],"target_translation":"Dia menjalani magang di rumah sakit selama empat bulan."}'::jsonb, '["She interned","at a","hospital for","four months."]'::jsonb, NULL, NULL, 'Angka durasi ''four months'' selalu didahului oleh ''for'' (bukan ''during'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000375', 'e4100001-0000-4000-8000-000000000045', 'e2000001-0000-4000-8000-000000000011', 'speaking', 'speaking_repeat', 'Ucapkan kalimat refleksi pengalaman belajar ini dengan mantap: "Saya belajar banyak dari mentor saya selama masa magang."', '{"romaji":"/aɪ lɜːrnd ə lɑːt frʌm maɪ ˈmentɔːr ˈdʊrɪŋ maɪ ˈɪntɜːrnʃɪp/","display_text":"I learned a lot from my mentor during my internship.","phonetic_breakdown":["aɪ","lɜːrnd","ə","lɑːt","frʌm","maɪ","ˈmen-tɔːr","ˈdʊr-ɪŋ","maɪ","ˈɪn-tɜːrn-ʃɪp"]}'::jsonb, '{"expected_transcript":"I learned a lot from my mentor during my internship."}'::jsonb, NULL, NULL, 'Kalimat bernada positif yang sangat disukai pewawancara kerja di AS!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000376', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''Did'' dalam kalimat tanya: Where ___ you stay when you visited Washington, D.C.?', '{"options":["did","were","was","had"],"translation":"Di mana kamu menginap saat mengunjungi Washington, D.C.?","sentence_template":"Where [blank] you stay when you visited Washington, D.C.?"}'::jsonb, '{"selected":"did"}'::jsonb, NULL, NULL, 'Karena ada kata kerja dasar ''stay'', pertanyaan Past Simple membutuhkan kata bantu ''did''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000377', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih bentuk V2 tak beraturan dari ''take'': It ___ us two hours to get through airport customs yesterday.', '{"options":["took","taked","taken","takes"],"translation":"Butuh waktu dua jam bagi kami untuk melewati bea cukai bandara kemarin.","sentence_template":"It [blank] us two hours to get through airport customs yesterday."}'::jsonb, '{"selected":"took"}'::jsonb, NULL, NULL, 'Pola durasi lampau menggunakan V2 dari ''take'': ''It took us [time] to [verb]''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000378', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'reading', 'fill_blank', 'Pilih To Be lampau negatif yang tepat: Fortunately, the subway ___ crowded this morning.', '{"options":["wasn''t","didn''t","weren''t","don''t"],"translation":"Untungnya, kereta bawah tanahnya tidak penuh sesak tadi pagi.","sentence_template":"Fortunately, the subway [blank] crowded this morning."}'::jsonb, '{"selected":"wasn''t"}'::jsonb, NULL, NULL, '''Crowded'' adalah kata sifat (ramai/penuh sesak) dan ''the subway'' tunggal, sehingga memakai ''wasn''t''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000379', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan percakapan tentang lokakarya beasiswa pekan lalu. Mengapa Dito tidak hadir secara langsung?', '{"options":[{"id":"opt_1","text":"Ia lupa mendaftar acara lokakarya tersebut"},{"id":"opt_2","text":"Ia terkena flu ringan (''caught a cold'') sehingga menonton siaran langsungnya dari rumah"},{"id":"opt_3","text":"Ia sedang berlibur ke luar kota"},{"id":"opt_4","text":"Acara lokakaryanya dibatalkan panitia"}],"audio_text":"Hey Dito, I didn''t see you at the scholarship workshop last Friday! — Oh, I caught a cold, so I watched the live stream from home instead."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Caught a cold'' (V2 dari ''catch a cold'' = kena pilek/flu ringan) menjelaskan alasannya menonton dari rumah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000380', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'listening', 'listening_choice', 'Dengarkan cerita singkat lulusan baru ini. Kapan ia mulai belajar pemrograman?', '{"options":[{"id":"opt_1","text":"Sejak duduk di bangku sekolah dasar"},{"id":"opt_2","text":"Pada tahun kedua kuliah (sophomore year)"},{"id":"opt_3","text":"Setelah bekerja lima tahun di kantor"},{"id":"opt_4","text":"Belum pernah menulis kode sama sekali"}],"audio_text":"Did you study coding in high school? — No, I actually wrote my first line of Python during my sophomore year of college."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Istilah tingkat kuliah S1 di AS wajib diingat: freshman (tahun 1), sophomore (tahun 2), junior (tahun 3), senior (tahun 4)!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000381', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat negatif masa lampau yang benar: "Kami tidak naik taksi; kami naik kereta."', '{"romaji":"/wiː ˈdɪdənt teɪk ə ˈtæksi; wiː tʊk ðə treɪn/","tokens":["take a","We didn''t","taked","didn''t took","taxi; we","took the","train."],"target_translation":"Kami tidak naik taksi; kami naik kereta."}'::jsonb, '["We didn''t","take a","taxi; we","took the","train."]'::jsonb, NULL, NULL, 'Perhatikan kontras emas dalam satu kalimat: negatif memakai ''didn''t take'' (V1), positif memakai ''took'' (V2)!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000382', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'writing', 'sentence_builder', 'Susun pertanyaan lampau dengan To Be: "Apakah instruksi ujiannya jelas bagi semua orang?"', '{"romaji":"/wɜːr ðə ɪɡˈzæm ɪnˈstrʌkʃənz klɪr tə ˈevriwʌn/","tokens":["clear to","Did the","everyone?","instructions","exam","Were the","Was the"],"target_translation":"Apakah instruksi ujiannya jelas bagi semua orang?"}'::jsonb, '["Were the","exam","instructions","clear to","everyone?"]'::jsonb, NULL, NULL, 'Subjek jamak ''the exam instructions'' + kata sifat ''clear'' memakai ''Were''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000383', 'e4100001-0000-4000-8000-000000000046', 'e2000001-0000-4000-8000-000000000011', 'speaking', 'speaking_repeat', 'Ucapkan kalimat rangkuman pencapaian pekan lalu ini: "Kami menyelesaikan risetnya minggu lalu dan mempresentasikan hasilnya kemarin."', '{"romaji":"/wiː ˈfɪnɪʃt ðə ˈriːsɜːrtʃ læst wiːk ænd prɪˈzentɪd ðə rɪˈzʌlts ˈjestərdeɪ/","display_text":"We finished the research last week and presented the results yesterday.","phonetic_breakdown":["wiː","ˈfɪ-nɪʃt","ðə","ˈriː-sɜːrtʃ","læst","wiːk","ænd","prɪ-ˈzen-tɪd","ðə","rɪ-ˈzʌlts","ˈjes-tər-deɪ"]}'::jsonb, '{"expected_transcript":"We finished the research last week and presented the results yesterday."}'::jsonb, NULL, NULL, '''Finished'' berbunyi /t/, sedangkan ''presented'' berbunyi /ɪd/ karena berakhiran bunyi /t/.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000384', 'e4100001-0000-4000-8000-000000000047', NULL, 'reading', 'fill_blank', 'Pilih kata kerja kolokasi yang benar untuk ''mengikuti ujian sertifikasi'': Next month, I''m going to ___ the AWS cloud certification exam.', '{"options":["take","follow","join in","make"],"translation":"Bulan depan, saya berencana mengikuti ujian sertifikasi cloud AWS.","sentence_template":"Next month, I''m going to [blank] the AWS cloud certification exam."}'::jsonb, '{"selected":"take"}'::jsonb, NULL, NULL, 'Dalam bahasa Inggris, kita selalu mengatakan ''take a test / take an exam'' (bukan ''follow'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000385', 'e4100001-0000-4000-8000-000000000047', NULL, 'reading', 'fill_blank', 'Pilih preposisi yang tepat saat mendaftar KE sebuah institusi universitas: Are you going to apply ___ Boston University for grad school?', '{"options":["to","for","at","with"],"translation":"Apakah kamu berencana mendaftar ke Boston University untuk kuliah S2?","sentence_template":"Are you going to apply [blank] Boston University for grad school?"}'::jsonb, '{"selected":"to"}'::jsonb, NULL, NULL, 'Ingat rumus: ''apply TO [institusi/universitas/perusahaan]'' dan ''apply FOR [posisi/beasiswa]''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000386', 'e4100001-0000-4000-8000-000000000047', NULL, 'reading', 'fill_blank', 'Jangan lupakan To Be pada pola ''going to'': My coworkers and I ___ going to attend a tech summit in Austin next spring.', '{"options":["are","is","will","do"],"translation":"Rekan-rekan kerja saya dan saya berencana menghadiri konferensi teknologi di Austin musim semi depan.","sentence_template":"My coworkers and I [blank] going to attend a tech summit in Austin next spring."}'::jsonb, '{"selected":"are"}'::jsonb, NULL, NULL, '''My coworkers and I'' (= we, jamak) membutuhkan To Be ''are'' sebelum ''going to attend''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000387', 'e4100001-0000-4000-8000-000000000047', NULL, 'listening', 'listening_choice', 'Dengarkan rencana studi lanjut Raka setelah lulus S1 ini. Mengapa ia memilih bekerja satu tahun dulu sebelum mendaftar S2?', '{"options":[{"id":"opt_1","text":"Ia tidak tertarik melanjutkan kuliah sama sekali"},{"id":"opt_2","text":"Ia berencana bekerja sebagai asisten peneliti selama setahun untuk menabung dan mencari pengalaman lab"},{"id":"opt_3","text":"Ia akan langsung memulai kuliah S3 bulan depan"},{"id":"opt_4","text":"Ia berencana keliling Eropa selama dua tahun"}],"audio_text":"Are you going to go straight to grad school, Raka? — Not right away. I''m going to work as a research assistant for a year to save money and gain lab experience."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Work as a research assistant for a year to save money and gain lab experience'' adalah rencana bertahap yang matang.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000388', 'e4100001-0000-4000-8000-000000000047', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi bimbingan karier di kampus ini. Sertifikasi apa yang rencananya akan diambil Maya musim panas ini?', '{"options":[{"id":"opt_1","text":"Kursus memasak kue Prancis"},{"id":"opt_2","text":"Sertifikat manajemen proyek daring demi melamar posisi Junior PM di musim gugur"},{"id":"opt_3","text":"SIM mengemudi truk besar"},{"id":"opt_4","text":"Pelatihan fotografi bawah air"}],"audio_text":"This summer, I''m going to complete a project management certificate online so I can apply for junior PM roles in the fall."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''PM'' dalam dunia teknologi AS adalah singkatan populer dari ''Product Manager'' atau ''Project Manager''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000389', 'e4100001-0000-4000-8000-000000000047', NULL, 'writing', 'sentence_builder', 'Susun kalimat rencana ujian ini: "Saya berencana mengikuti ujian TOEFL pada bulan Oktober."', '{"romaji":"/aɪm ˈɡoʊɪŋ tə teɪk ðə ˈtoʊfəl ɪɡˈzæm ɪn ɑːkˈtoʊbər/","tokens":["to take","October.","the TOEFL","follow","on October.","I''m going","exam in"],"target_translation":"Saya berencana mengikuti ujian TOEFL pada bulan Oktober."}'::jsonb, '["I''m going","to take","the TOEFL","exam in","October."]'::jsonb, NULL, NULL, 'Gunakan ''take the TOEFL exam'' + preposisi bulan ''in October''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000390', 'e4100001-0000-4000-8000-000000000047', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan rencana karier teman: "Apakah kamu berencana melamar posisi magang itu?"', '{"romaji":"/ɑːr juː ˈɡoʊɪŋ tə əˈplaɪ fɔːr ðæt ˈɪntɜːrnʃɪp/","tokens":["going to","Do you","apply for","apply to","Are you","that internship?"],"target_translation":"Apakah kamu berencana melamar posisi magang itu?"}'::jsonb, '["Are you","going to","apply for","that internship?"]'::jsonb, NULL, NULL, '''That internship'' adalah program/posisi, sehingga memakai ''apply for''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000391', 'e4100001-0000-4000-8000-000000000047', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat target studi ini dengan jelas: "Saya berencana mendaftar kuliah pascasarjana di Amerika Serikat tahun depan."', '{"romaji":"/aɪm ˈɡoʊɪŋ tə əˈplaɪ tə ɡræd skuːl ɪn ðə juˈnaɪtɪd steɪts nekst jɪr/","display_text":"I''m going to apply to grad school in the United States next year.","phonetic_breakdown":["aɪm","ˈɡoʊ-ɪŋ","tə","ə-ˈplaɪ","tə","ɡræd","skuːl","ɪn","ðə","ju-ˈnaɪ-tɪd","steɪts","nekst","jɪr"]}'::jsonb, '{"expected_transcript":"I''m going to apply to grad school in the United States next year."}'::jsonb, NULL, NULL, 'Selalu gunakan artikel ''the'' di depan ''the United States'' (atau ''the US'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000392', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk masa depan untuk keputusan spontan saat baru diberi tahu suatu masalah detik ini: We''re out of coffee filters. — No problem, ___ pick some up on my way back from lunch!', '{"options":["I''ll","I going to","I''m","I did"],"translation":"Kita kehabisan saringan kopi. — Tidak masalah, biar saya belikan nanti sepulang makan siang!","sentence_template":"We''re out of coffee filters. — No problem, [blank] pick some up on my way back from lunch!"}'::jsonb, '{"selected":"I''ll"}'::jsonb, NULL, NULL, 'Karena pembicara kedua baru tahu kertas saringan habis detik itu juga, tawaran spontan memakai ''I''ll'' (''I will'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000393', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk masa depan untuk rencana yang SUDAH disiapkan sejak bulan lalu: I already paid the registration fee—I ___ run the Chicago Half Marathon in October!', '{"options":["am going to","will to","going to","was going"],"translation":"Saya sudah membayar biaya pendaftarannya—saya akan mengikuti lari Chicago Half Marathon bulan Oktober!","sentence_template":"I already paid the registration fee—I [blank] run the Chicago Half Marathon in October!"}'::jsonb, '{"selected":"am going to"}'::jsonb, NULL, NULL, 'Bukti persiapan sebelumnya (''already paid the registration fee'') mewajibkan ''am going to''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000394', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih singkatan negatif dari ''will not'' untuk membuat janji: Don''t worry, this survey ___ take more than two minutes.', '{"options":["won''t","willn''t","don''t","isn''t"],"translation":"Jangan khawatir, survei ini tidak akan memakan waktu lebih dari dua menit.","sentence_template":"Don''t worry, this survey [blank] take more than two minutes."}'::jsonb, '{"selected":"won''t"}'::jsonb, NULL, NULL, 'Bentuk negatif dari ''will'' adalah ''won''t'' (tidak ada kata ''willn''t'' dalam bahasa Inggris!).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000395', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan di ruang rapat ini. Apa yang spontan dilakukan Jordan ketika spidol papan tulis habis?', '{"options":[{"id":"opt_1","text":"Membatalkan rapat selama seminggu"},{"id":"opt_2","text":"Langsung menawarkan diri mengambil spidol baru dari meja resepsionis"},{"id":"opt_3","text":"Meminta semua peserta pulang"},{"id":"opt_4","text":"Membeli papan tulis digital baru bulan depan"}],"audio_text":"Oh no, this whiteboard marker is completely dry. — Hang on, I''ll grab a new one from the front desk!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Hang on'' (tunggu sebentar) diikuti keputusan spontan ''I''ll grab a new one from the front desk!''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000396', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan prediksi analis teknologi tentang tren perangkat lunak tahun depan. Apa yang menurutnya mungkin terjadi?', '{"options":[{"id":"opt_1","text":"Semua bisnis kecil akan berhenti memakai internet"},{"id":"opt_2","text":"Lebih banyak bisnis kecil kemungkinan akan mengadopsi alat layanan pelanggan berbasis AI tahun depan"},{"id":"opt_3","text":"Biaya pemasangan perangkat lunak naik sepuluh kali lipat"},{"id":"opt_4","text":"Perusahaan besar menutup situs web mereka"}],"audio_text":"I think more small businesses will adopt AI customer support tools next year because setup costs are dropping."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Prediksi berbasis opini (''I think...'') menggunakan ''will adopt''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000397', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat janji cepat lewat chat: "Saya berjanji saya akan mengirimkan laporannya sebelum pukul lima."', '{"romaji":"/aɪ ˈprɑːmɪs aɪl send ðə rɪˈpɔːrt bɪˈfɔːr faɪv əˈklɑːk/","tokens":["I promise","I''ll send","five o''clock.","the report","I going","before","sends"],"target_translation":"Saya berjanji saya akan mengirimkan laporannya sebelum pukul lima."}'::jsonb, '["I promise","I''ll send","the report","before","five o''clock."]'::jsonb, NULL, NULL, 'Janji (''I promise...'') selalu berpasangan alami dengan ''I''ll + V1''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000398', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat rencana kepindahan yang sudah pasti: "Kami akan pindah ke apartemen yang lebih besar bulan depan."', '{"romaji":"/wɪr ˈɡoʊɪŋ tə muːv ˈɪntə ə ˈbɪɡər əˈpɑːrtmənt nekst mʌnθ/","tokens":["next month.","bigger apartment","We will to","We''re going","to move","moves","into a"],"target_translation":"Kami akan pindah ke apartemen yang lebih besar bulan depan."}'::jsonb, '["We''re going","to move","into a","bigger apartment","next month."]'::jsonb, NULL, NULL, 'Pindah apartemen adalah rencana besar yang sudah disiapkan (''We''re going to move into...'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000399', 'e4100001-0000-4000-8000-000000000048', 'e2000001-0000-4000-8000-000000000012', 'speaking', 'speaking_repeat', 'Latih perbedaan vokal /wɑːnt/ (want) dan /woʊnt/ (won''t) dalam kalimat ini: "Saya ingin membantu, dan ini tidak akan memakan waktu lama."', '{"romaji":"/aɪ wɑːnt tə help, ænd ɪt woʊnt teɪk lɔːŋ/","display_text":"I want to help, and it won''t take long.","phonetic_breakdown":["aɪ","wɑːnt","tə","help","ænd","ɪt","woʊnt","teɪk","lɔːŋ"]}'::jsonb, '{"expected_transcript":"I want to help, and it won''t take long."}'::jsonb, NULL, NULL, 'Buka rahang lebar untuk ''want'' (/wɑːnt/), dan bulatkan bibir ke depan untuk ''won''t'' (/woʊnt/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000400', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Ingat perbedaan ''to + V1'' vs ''for + Noun'': Adi is practicing mock interviews every evening ___ prepare for tech recruiting.', '{"options":["to","for","by","at"],"translation":"Adi berlatih simulasi wawancara setiap malam untuk mempersiapkan rekrutmen teknologi.","sentence_template":"Adi is practicing mock interviews every evening [blank] prepare for tech recruiting."}'::jsonb, '{"selected":"to"}'::jsonb, NULL, NULL, 'Karena diikuti kata kerja dasar ''prepare'', tujuan tindakan wajib memakai ''to'' (''to prepare'', bukan ''for prepare'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000401', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih kosakata khas Amerika untuk dokumen ringkas 1 halaman saat melamar kerja di perusahaan: I''m going to update my ___ before the campus career fair.', '{"options":["resume","receipt","syllabus","prescription"],"translation":"Saya akan memperbarui resume (CV kerja) saya sebelum bursa karier kampus.","sentence_template":"I''m going to update my [blank] before the campus career fair."}'::jsonb, '{"selected":"resume"}'::jsonb, NULL, NULL, 'Di dunia kerja AS, dokumen lamaran kerja 1–2 halaman disebut ''resume'' (/ˈrezəmeɪ/).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000402', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk kata kerja setelah ''hope'': After finishing my master''s degree, I hope ___ in clean-tech research.', '{"options":["to work","working","for work","worked"],"translation":"Setelah menyelesaikan gelar magister, saya berharap bekerja di bidang riset teknologi bersih.","sentence_template":"After finishing my master''s degree, I hope [blank] in clean-tech research."}'::jsonb, '{"selected":"to work"}'::jsonb, NULL, NULL, 'Kata kerja ''hope'', ''plan'', dan ''decide'' selalu diikuti ''to + V1'' (''hope to work'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000403', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan penjelasan peserta pameran karier kampus (career fair) ini. Mengapa ia datang ke stan perusahaan tersebut?', '{"options":[{"id":"opt_1","text":"Untuk menjual perlengkapan kantor kepada perusahaan"},{"id":"opt_2","text":"Mahasiswa tingkat akhir (senior) jurusan statistik ini mampir untuk mencari tahu lebih lanjut tentang program fellowship analis data musim panas"},{"id":"opt_3","text":"Untuk melamar posisi petugas keamanan gedung"},{"id":"opt_4","text":"Karena tersesat mencari ruang olahraga"}],"audio_text":"Hi! I''m a senior majoring in statistics, and I stopped by your booth to learn more about your summer data analyst fellowship."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Senior'' = mahasiswa tingkat akhir (tahun ke-4), dan ''to learn more about...'' menunjukkan tujuan kunjungannya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000404', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan visi jangka panjang pelamar beasiswa berikut. Apa rencana kontribusinya setelah lulus dari AS?', '{"options":[{"id":"opt_1","text":"Menetap di New York untuk membuka toko pakaian"},{"id":"opt_2","text":"Kembali ke Indonesia untuk membantu memodernisasi logistik rantai dingin bagi petani dan nelayan lokal"},{"id":"opt_3","text":"Beralih profesi menjadi kritikus film"},{"id":"opt_4","text":"Belum memiliki rencana apa pun setelah lulus"}],"audio_text":"In the long run, I plan to return to Indonesia to help modernize cold-chain logistics for local farmers and fishermen."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Ungkapan ''In the long run, I plan to return to Indonesia to help modernize...'' sangat kuat untuk wawancara LPDP/Fulbright!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000405', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat tujuan belajar ini: "Saya menggunakan aplikasi ini untuk memperlancar bahasa Inggris profesional saya."', '{"romaji":"/aɪm ˈjuːzɪŋ ðɪs æp tə ɪmˈpruːv maɪ prəˈfeʃənəl ˈɪŋɡlɪʃ/","tokens":["to improve","I''m using","for improve","improves","English.","my professional","this app"],"target_translation":"Saya menggunakan aplikasi ini untuk memperlancar bahasa Inggris profesional saya."}'::jsonb, '["I''m using","this app","to improve","my professional","English."]'::jsonb, NULL, NULL, 'Tujuan tindakan menggunakan ''to improve'' (bukan ''for improve'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000406', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat harapan karier jangka panjang: "Dalam jangka panjang, saya berencana memimpin tim teknik."', '{"romaji":"/ɪn ðə lɔːŋ rʌn, aɪ plæn tə liːd ən ˌendʒɪˈnɪrɪŋ tiːm/","tokens":["In the","an engineering team.","to lead","planning lead","I plan","in long","long run,"],"target_translation":"Dalam jangka panjang, saya berencana memimpin tim teknik."}'::jsonb, '["In the","long run,","I plan","to lead","an engineering team."]'::jsonb, NULL, NULL, '''In the long run'' + ''I plan to lead...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000407', 'e4100001-0000-4000-8000-000000000049', 'e2000001-0000-4000-8000-000000000012', 'speaking', 'speaking_repeat', 'Ucapkan kalimat persiapan karier ini dengan lafal US kata resume (/ˈrezəmeɪ/): "Saya akan memperbarui resume saya untuk bursa karier besok."', '{"romaji":"/aɪm ˈɡoʊɪŋ tə ʌpˈdeɪt maɪ ˈrezəmeɪ fɔːr təˈmɑːroʊz kəˈrɪr fer/","display_text":"I''m going to update my resume for tomorrow''s career fair.","phonetic_breakdown":["aɪm","ˈɡoʊ-ɪŋ","tə","ʌp-ˈdeɪt","maɪ","ˈre-zə-meɪ","fɔːr","tə-ˈmɑːr-oʊz","kə-ˈrɪr","fer"]}'::jsonb, '{"expected_transcript":"I''m going to update my resume for tomorrow''s career fair."}'::jsonb, NULL, NULL, 'Hati-hati: kata benda ''resume'' (CV) dibaca /ˈrezəmeɪ/, berbeda dari kata kerja ''resume'' (melanjutkan) yang dibaca /rɪˈzuːm/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000408', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk masa depan untuk bantuan spontan saat rekan menjatuhkan berkas: Oh, you dropped your folders—___ help you pick them up!', '{"options":["I''ll","I''m going","I did","I am"],"translation":"Oh, map berkasmu terjatuh—biar saya bantu memungutnya!","sentence_template":"Oh, you dropped your folders—[blank] help you pick them up!"}'::jsonb, '{"selected":"I''ll"}'::jsonb, NULL, NULL, 'Respons spontan di tempat kejadian selalu memakai ''I''ll'' (''I will'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000409', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih penghubung tujuan yang benar sebelum kata kerja ''get'': Laras moved to San Jose ___ get hands-on experience in semiconductor engineering.', '{"options":["to","for","by","with"],"translation":"Laras pindah ke San Jose untuk mendapatkan pengalaman praktik langsung di bidang teknik semikonduktor.","sentence_template":"Laras moved to San Jose [blank] get hands-on experience in semiconductor engineering."}'::jsonb, '{"selected":"to"}'::jsonb, NULL, NULL, 'Sebelum kata kerja dasar ''get'', gunakan infinitive of purpose ''to''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000410', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'reading', 'fill_blank', 'Pilih preposisi yang tepat untuk objek berupa nama beasiswa: Thousands of students apply ___ this international scholarship every spring.', '{"options":["for","to","on","in"],"translation":"Ribuan mahasiswa melamar beasiswa internasional ini setiap musim semi.","sentence_template":"Thousands of students apply [blank] this international scholarship every spring."}'::jsonb, '{"selected":"for"}'::jsonb, NULL, NULL, 'Kita mengatakan ''apply FOR a scholarship / job'' (dan ''apply TO a university'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000411', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan percakapan dengan pembimbing akademik ini. Kapan mahasiswa tersebut berencana mengambil ujian GRE?', '{"options":[{"id":"opt_1","text":"Ia memutuskan membatalkan ujiannya tadi pagi"},{"id":"opt_2","text":"Pada tanggal 10 November karena ia sudah resmi terdaftar"},{"id":"opt_3","text":"Tiga tahun lagi setelah bekerja"},{"id":"opt_4","text":"Minggu lalu di pusat ujian Jakarta"}],"audio_text":"When are you going to take the GRE? — I already registered for the November tenth test date, so I''m studying every evening now."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Karena sudah mendaftar (''already registered''), pertanyaan dan rencana memakai ''going to'' untuk tanggal 10 November.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000412', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'listening', 'listening_choice', 'Dengarkan penutup rapat tim berikut. Siapa yang menyanggupi mengirim rangkuman rapat?', '{"options":[{"id":"opt_1","text":"Tidak ada seorang pun yang bersedia menulis rangkuman"},{"id":"opt_2","text":"Pembicara kedua menyanggupi secara spontan dan berjanji mengunggahnya ke kanal Slack sebelum jam 4 sore"},{"id":"opt_3","text":"Manajer menugaskan klien untuk menulis rangkuman"},{"id":"opt_4","text":"Rangkuman baru akan dikirim bulan depan"}],"audio_text":"Who wants to send out the action items after this call? — I''ll do it! I''ll post them in the Slack channel by four p.m."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''ll do it! I''ll post them...'' menunjukkan kesediaan spontan (''volunteer on the spot'') dan janji waktu.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000413', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat rencana belajar kelompok: "Kami berencana meninjau contoh soal TOEFL malam ini."', '{"romaji":"/wɪr ˈɡoʊɪŋ tə rɪˈvjuː ˈsæmpəl ˈtoʊfəl ˈkwestʃənz təˈnaɪt/","tokens":["to review","sample TOEFL","for review","tonight.","We''re going","will to","questions"],"target_translation":"Kami berencana meninjau contoh soal TOEFL malam ini."}'::jsonb, '["We''re going","to review","sample TOEFL","questions","tonight."]'::jsonb, NULL, NULL, '''We''re going to review...'' menyampaikan agenda belajar malam ini yang sudah disepakati.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000414', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat prediksi positif: "Saya yakin presentasimu akan berjalan sangat lancar besok."', '{"romaji":"/aɪm ʃʊr jʊr ˌprezənˈteɪʃən wɪl ɡoʊ ˈriːəli wel təˈmɑːroʊ/","tokens":["your presentation","going","I''m sure","will go","good","tomorrow.","really well"],"target_translation":"Saya yakin presentasimu akan berjalan sangat lancar besok."}'::jsonb, '["I''m sure","your presentation","will go","really well","tomorrow."]'::jsonb, NULL, NULL, 'Keyakinan/prediksi masa depan setelah ''I''m sure'' memakai ''will + V1'' (''will go really well'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000415', 'e4100001-0000-4000-8000-000000000050', 'e2000001-0000-4000-8000-000000000012', 'speaking', 'speaking_repeat', 'Ucapkan kalimat tekad karier ini dengan jelas: "Saya sedang mengambil kursus ini untuk mempersiapkan wawancara kerja global."', '{"romaji":"/aɪm ˈteɪkɪŋ ðɪs kɔːrs tə prɪˈper fɔːr ˈɡloʊbəl dʒɑːb ˈɪntərvjuːz/","display_text":"I''m taking this course to prepare for global job interviews.","phonetic_breakdown":["aɪm","ˈteɪ-kɪŋ","ðɪs","kɔːrs","tə","prɪ-ˈper","fɔːr","ˈɡloʊ-bəl","dʒɑːb","ˈɪn-tər-vjuːz"]}'::jsonb, '{"expected_transcript":"I''m taking this course to prepare for global job interviews."}'::jsonb, NULL, NULL, 'Perhatikan gabungan cantik keduanya: ''TO prepare'' (+ kata kerja) lalu ''FOR global job interviews'' (+ kata benda)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000416', 'e4100001-0000-4000-8000-000000000051', NULL, 'reading', 'fill_blank', 'Pilih istilah untuk uang jaminan yang dikembalikan di akhir masa sewa apartemen jika tidak ada kerusakan: You get your ___ deposit back when you move out.', '{"options":["security","utility","furniture","laundry"],"translation":"Anda mendapatkan kembali uang jaminan (security deposit) Anda saat pindah keluar.","sentence_template":"You get your [blank] deposit back when you move out."}'::jsonb, '{"selected":"security"}'::jsonb, NULL, NULL, '''Security deposit'' adalah uang jaminan standar dalam kontrak sewa (''lease'') di AS.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000417', 'e4100001-0000-4000-8000-000000000051', NULL, 'reading', 'fill_blank', 'Pilih istilah untuk apartemen yang disewakan TANPA kasur, sofa, atau meja belajar: Most off-campus apartments in the US come ___, so students buy used desks online.', '{"options":["unfurnished","unlocked","unpaid","unopened"],"translation":"Sebagian besar apartemen luar kampus di AS disewakan tanpa perabot, sehingga mahasiswa membeli meja bekas secara daring.","sentence_template":"Most off-campus apartments in the US come [blank], so students buy used desks online."}'::jsonb, '{"selected":"unfurnished"}'::jsonb, NULL, NULL, '''Unfurnished'' berarti belum dilengkapi perabot tempat tidur/meja/kursi.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000418', 'e4100001-0000-4000-8000-000000000051', NULL, 'reading', 'fill_blank', 'Hati-hati dengan kata uncountable ''furniture'': We need to buy ___ furniture for our living room this weekend.', '{"options":["some","many","a","three"],"translation":"Kita perlu membeli beberapa perabot untuk ruang tamu kita akhir pekan ini.","sentence_template":"We need to buy [blank] furniture for our living room this weekend."}'::jsonb, '{"selected":"some"}'::jsonb, NULL, NULL, '''Furniture'' tidak bisa dihitung satuan dalam bahasa Inggris, sehingga memakai ''some furniture'' (bukan ''many/a'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000419', 'e4100001-0000-4000-8000-000000000051', NULL, 'listening', 'listening_choice', 'Dengarkan agen properti menjelaskan unit apartemen dekat kampus Boston ini. Fasilitas apa yang berada langsung di dalam gedung (in-building)?', '{"options":[{"id":"opt_1","text":"Kolam renang air hangat di atap gedung"},{"id":"opt_2","text":"Ruang cuci pakaian (laundry room) berbasis kartu tepat di lantai bawah tanah gedung"},{"id":"opt_3","text":"Restoran cepat saji buka 24 jam"},{"id":"opt_4","text":"Stasiun pengisian mobil listrik gratis"}],"audio_text":"This two-bedroom apartment is a ten-minute walk from campus, and there''s a card-operated laundry room right in the basement."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Fasilitas mesin cuci di dalam gedung (''in-building'' atau ''in-unit laundry'') sangat penting saat musim dingin di AS agar tidak perlu keluar membawa pakaian kotor!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000420', 'e4100001-0000-4000-8000-000000000051', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan calon penyewa dan pemilik apartemen (landlord) berikut. Kapan penyewa bisa mulai pindah masuk (move in)?', '{"options":[{"id":"opt_1","text":"Hari ini juga"},{"id":"opt_2","text":"Tanggal 25 Agustus pagi"},{"id":"opt_3","text":"Tanggal 1 September setelah penyewa lama pindah keluar"},{"id":"opt_4","text":"Bulan Januari tahun depan"}],"audio_text":"Is the studio apartment available right now? — The current tenant is moving out on August twenty-fifth, so you can move in on September first."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Di kota pelajar AS (seperti Boston!), tanggal 1 September (''September first'') adalah hari pindah masuk tahunan terbesar.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000421', 'e4100001-0000-4000-8000-000000000051', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan wajib saat survei apartemen: "Apakah tagihan listrik dan air sudah termasuk dalam uang sewa?"', '{"romaji":"/ɑːr juːˈtɪlətiz ɪnˈkluːdɪd ɪn ðə ˈmʌnθli rent/","tokens":["Are utilities","in the","included","monthly rent?","includes","Is utilities"],"target_translation":"Apakah tagihan listrik dan air sudah termasuk dalam uang sewa?"}'::jsonb, '["Are utilities","included","in the","monthly rent?"]'::jsonb, NULL, NULL, '''Utilities'' berbentuk jamak -> ''Are utilities included in the monthly rent?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000422', 'e4100001-0000-4000-8000-000000000051', NULL, 'writing', 'sentence_builder', 'Susun kalimat kontrak sewa ini: "Kami menandatangani kontrak sewa dua belas bulan kemarin."', '{"romaji":"/wiː saɪnd ə twelv mʌnθ liːs ˈjestərdeɪ/","tokens":["twelve-months","leases","a twelve-month","yesterday.","We signed","lease"],"target_translation":"Kami menandatangani kontrak sewa dua belas bulan kemarin."}'::jsonb, '["We signed","a twelve-month","lease","yesterday."]'::jsonb, NULL, NULL, 'Perhatikan aturan kata sifat majemuk berhubung tanda strip: ''a twelve-month lease'' (kata ''month'' tetap TUNGGAL tanpa -s karena berfungsi menjelaskan ''lease''!).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000423', 'e4100001-0000-4000-8000-000000000051', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan jarak apartemen ke kampus ini: "Seberapa jauh apartemen ini dari halte bus kampus?"', '{"romaji":"/haʊ fɑːr ɪz ðɪs əˈpɑːrtmənt frʌm ðə ˈkæmpəs bʌs stɑːp/","display_text":"How far is this apartment from the campus bus stop?","phonetic_breakdown":["haʊ","fɑːr","ɪz","ðɪs","ə-ˈpɑːrt-mənt","frʌm","ðə","ˈkæm-pəs","bʌs","stɑːp"]}'::jsonb, '{"expected_transcript":"How far is this apartment from the campus bus stop?"}'::jsonb, NULL, NULL, '''How far is [A] from [B]?'' menanyakan jarak tempuh antara dua lokasi.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000424', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'reading', 'fill_blank', 'Perhatikan posisi kata ''enough'' dengan kata sifat ''quiet'': I really like this dorm floor because it''s ___ to sleep early.', '{"options":["quiet enough","enough quiet","too much quiet","many quiet"],"translation":"Saya sangat menyukai lantai asrama ini karena cukup tenang untuk tidur lebih awal.","sentence_template":"I really like this dorm floor because it''s [blank] to sleep early."}'::jsonb, '{"selected":"quiet enough"}'::jsonb, NULL, NULL, 'Dengan kata sifat (''quiet''), kata ''enough'' wajib diletakkan DI BELAKANG kata sifat (''quiet enough'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000425', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'reading', 'fill_blank', 'Pilih antara ''too much'' dan ''too many'' untuk kata tak terhitung ''noise'': We didn''t rent the first-floor unit because there was ___ noise from the highway.', '{"options":["too much","too many","a few","many"],"translation":"Kami tidak menyewa unit lantai satu karena terlalu banyak suara bising dari jalan raya.","sentence_template":"We didn''t rent the first-floor unit because there was [blank] noise from the highway."}'::jsonb, '{"selected":"too much"}'::jsonb, NULL, NULL, '''Noise'' (kebisingan) adalah uncountable noun, sehingga berpasangan dengan ''too much''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000426', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'reading', 'fill_blank', 'Pilih penentu jumlah untuk benda jamak ''boxes'': Moving day was exhausting because we had ___ heavy boxes!', '{"options":["too many","too much","a little","much"],"translation":"Hari pindahan sangat melelahkan karena kami membawa terlalu banyak kardus berat!","sentence_template":"Moving day was exhausting because we had [blank] heavy boxes!"}'::jsonb, '{"selected":"too many"}'::jsonb, NULL, NULL, '''Boxes'' adalah kata benda jamak yang dapat dihitung, sehingga menggunakan ''too many''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000427', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'listening', 'listening_choice', 'Dengarkan kesan mahasiswa setelah meninjau kamar apartemen kedua ini. Mengapa ia lebih menyukai apartemen kedua?', '{"options":[{"id":"opt_1","text":"Karena apartemen pertama jauh lebih luas"},{"id":"opt_2","text":"Karena apartemen kedua mendapat banyak cahaya matahari alami dan dapurnya sangat luas"},{"id":"opt_3","text":"Karena apartemen kedua gratis tanpa biaya sewa"},{"id":"opt_4","text":"Karena apartemen kedua tidak memiliki jendela"}],"audio_text":"The first apartment was dark and cramped, but this second one has plenty of natural sunlight and a huge kitchen!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kata sifat ''cramped'' berarti sempit sesak, dikontraskan dengan ''plenty of natural sunlight and a huge kitchen''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000428', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'listening', 'listening_choice', 'Dengarkan keluhan penghuni asrama kepada pengelola gedung ini. Apa masalah di ruang belajar asrama?', '{"options":[{"id":"opt_1","text":"Pendingin ruangan di ruang belajar terlalu dingin"},{"id":"opt_2","text":"Jumlah stopkontak listrik (''power outlets'') tidak cukup untuk dua puluh mahasiswa"},{"id":"opt_3","text":"Lampu ruang belajar terlalu terang"},{"id":"opt_4","text":"Kursi di ruang belajar terlalu banyak"}],"audio_text":"There aren''t enough power outlets in the dorm study lounge—twenty students have to share just four plugs!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Enough + noun'' (''enough power outlets'') menjelaskan kurangnya colokan listrik di ruang belajar.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000429', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat penilaian ukuran meja: "Apakah meja ini cukup besar untuk dua monitor?"', '{"romaji":"/ɪz ðɪs desk bɪɡ ɪˈnʌf fɔːr tuː ˈmɑːnɪtərz/","tokens":["desk","for two","monitors?","big enough","Is this","monitor?","enough big"],"target_translation":"Apakah meja ini cukup besar untuk dua monitor?"}'::jsonb, '["Is this","desk","big enough","for two","monitors?"]'::jsonb, NULL, NULL, 'Kata sifat ''big'' diletakkan sebelum ''enough'' (''big enough'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
