INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000431', 'e4100001-0000-4000-8000-000000000052', 'e2000001-0000-4000-8000-000000000013', 'speaking', 'speaking_repeat', 'Ucapkan kalimat evaluasi tempat tinggal ini dengan jelas: "Apartemennya bagus, tetapi tidak ada ruang penyimpanan yang cukup."', '{"romaji":"/ðə əˈpɑːrtmənt ɪz naɪs, bʌt ðer ˈɪzənt ɪˈnʌf ˈstɔːrɪdʒ speɪs/","display_text":"The apartment is nice, but there isn''t enough storage space.","phonetic_breakdown":["ðə","ə-ˈpɑːrt-mənt","ɪz","naɪs","bʌt","ðer","ˈɪ-zənt","ɪ-ˈnʌf","ˈstɔːr-ɪdʒ","speɪs"]}'::jsonb, '{"expected_transcript":"The apartment is nice, but there isn''t enough storage space."}'::jsonb, NULL, NULL, 'Di sini ''storage space'' adalah kata benda, sehingga ''enough'' berada di depannya (''enough storage space'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
