INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000435', 'e4100001-0000-4000-8000-000000000053', 'e2000001-0000-4000-8000-000000000013', 'listening', 'listening_choice', 'Dengarkan obrolan dua teman sekamar baru saat menyusun kesepakatan apartemen (roommate agreement). Bagaimana aturan tamu menginap yang mereka sepakati?', '{"options":[{"id":"opt_1","text":"Dilarang menerima teman berkunjung sama sekali sepanjang tahun"},{"id":"opt_2","text":"Memberi tahu dan meminta persetujuan minimal sehari sebelumnya sebelum mengajak tamu menginap, terutama saat pekan ujian"},{"id":"opt_3","text":"Bebas mengadakan pesta musik keras setiap tengah malam"},{"id":"opt_4","text":"Tamu harus membayar seratus dolar kepada pemilik gedung"}],"audio_text":"Let''s check with each other at least a day in advance before having overnight guests, especially during exam weeks. — Totally fair, I agree!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Check with each other at least a day in advance'' menunjukkan komunikasi respek antar-roommate.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
