INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000447', 'e4100001-0000-4000-8000-000000000054', 'e2000001-0000-4000-8000-000000000013', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan penting kepada pemilik apartemen ini: "Apakah pemanas dan air sudah termasuk dalam sewa bulanan?"', '{"romaji":"/ɑːr hiːt ænd ˈwɔːtər ɪnˈkluːdɪd ɪn ðə ˈmʌnθli rent/","display_text":"Are heat and water included in the monthly rent?","phonetic_breakdown":["ɑːr","hiːt","ænd","ˈwɔː-tər","ɪn-ˈkluː-dɪd","ɪn","ðə","ˈmʌnθ-li","rent"]}'::jsonb, '{"expected_transcript":"Are heat and water included in the monthly rent?"}'::jsonb, NULL, NULL, 'Pertanyaan wajib yang bisa menghemat ratusan dolar tagihan musim dinginmu di AS!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000448', 'e4100001-0000-4000-8000-000000000055', NULL, 'reading', 'fill_blank', 'Pilih kata kerja yang tepat jika Anda ingin MENUKAR jaket ukuran S dengan ukuran M yang sama: Hi, can I ___ this small jacket for a medium?', '{"options":["exchange","refund","borrow","receipt"],"translation":"Halo, bolehkah saya menukar jaket ukuran kecil ini dengan ukuran sedang?","sentence_template":"Hi, can I [blank] this small jacket for a medium?"}'::jsonb, '{"selected":"exchange"}'::jsonb, NULL, NULL, 'Pola ''exchange [item A] for [item B]'' digunakan saat menukar ukuran atau warna barang.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000449', 'e4100001-0000-4000-8000-000000000055', NULL, 'reading', 'fill_blank', 'Pilih kata sifat untuk barang elektronik baru yang rusak/cacat fungsi sejak dibuka dari kotak: I bought this mouse yesterday, but the scroll wheel is ___.', '{"options":["defective","delicious","crowded","chilly"],"translation":"Saya membeli tetikus ini kemarin, tetapi roda penggulungnya cacat/tidak berfungsi.","sentence_template":"I bought this mouse yesterday, but the scroll wheel is [blank]."}'::jsonb, '{"selected":"defective"}'::jsonb, NULL, NULL, '''Defective'' adalah istilah resmi layanan pelanggan untuk produk cacat pabrik.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000450', 'e4100001-0000-4000-8000-000000000055', NULL, 'reading', 'fill_blank', 'Pilih kata kerja untuk menyatakan ukuran sepatu pas/tidak pas di kaki: These running shoes don''t ___ me—they''re a little too tight.', '{"options":["fit","match","wear","dress"],"translation":"Sepatu lari ini tidak pas ukurannya di kaki saya—agak terlalu sempit.","sentence_template":"These running shoes don''t [blank] me—they''re a little too tight."}'::jsonb, '{"selected":"fit"}'::jsonb, NULL, NULL, '''Fit'' merujuk pada kecocokan ukuran di tubuh/kaki, sedangkan ''match'' merujuk pada keserasian warna/gaya.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000451', 'e4100001-0000-4000-8000-000000000055', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan staf Customer Service toko ritel ini. Berapa lama waktu yang dibutuhkan hingga dana retur masuk kembali ke kartu pembeli?', '{"options":[{"id":"opt_1","text":"Uang tunai langsung diberikan detik itu juga"},{"id":"opt_2","text":"Dana penuh $48 akan muncul kembali di kartu debit dalam 3 hingga 5 hari kerja"},{"id":"opt_3","text":"Pengembalian dana ditolak karena sudah lewat setahun"},{"id":"opt_4","text":"Harus menunggu enam bulan penuh"}],"audio_text":"I''ve processed your return! The full refund of forty-eight dollars will appear on your debit card within three to five business days."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Within three to five business days'' (dalam 3–5 hari kerja bank) adalah standar pengembalian dana kartu di AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000452', 'e4100001-0000-4000-8000-000000000055', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dengan agen obrolan layanan pengiriman paket berikut. Di mana kurir meletakkan paket pembeli?', '{"options":[{"id":"opt_1","text":"Masih berada di gudang bandara"},{"id":"opt_2","text":"Di dalam loker ruang surat (mailroom lockers) apartemen pada pukul 14.15"},{"id":"opt_3","text":"Dikembalikan ke penjual karena alamat salah"},{"id":"opt_4","text":"Dititipkan ke kantor polisi terdekat"}],"audio_text":"According to the delivery photo, the driver left your package inside the apartment mailroom lockers at two-fifteen p.m."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Apartemen modern di AS umumnya menyediakan loker paket otomatis (''mailroom lockers'' seperti Amazon Hub/Parcel Pending).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000453', 'e4100001-0000-4000-8000-000000000055', NULL, 'writing', 'sentence_builder', 'Susun kalimat alasan mengembalikan barang: "Saya ingin mengembalikan headphone ini karena sebelah sisinya rusak."', '{"romaji":"/aɪd laɪk tə rɪˈtɜːrn ðiːz ˈhedfoʊnz bɪˈkɔːz wʌn saɪd ɪz ˈbroʊkən/","tokens":["to return","these headphones","headphone","side is broken.","I''d like","because one","returns"],"target_translation":"Saya ingin mengembalikan headphone ini karena sebelah sisinya rusak."}'::jsonb, '["I''d like","to return","these headphones","because one","side is broken."]'::jsonb, NULL, NULL, '''Headphones'' selalu jamak (''these headphones''), sedangkan satu sisinya tunggal (''one side is broken'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000454', 'e4100001-0000-4000-8000-000000000055', NULL, 'writing', 'sentence_builder', 'Susun kalimat menukar ukuran pakaian: "Kemeja ini terlalu sempit—bolehkah saya menukarnya?"', '{"romaji":"/ðɪs ʃɜːrt ɪz tuː taɪt—kæn aɪ ɪksˈtʃeɪndʒ ɪt/","tokens":["is too","tight—can I","it?","This shirt","exchange","so tight—","exchange them?"],"target_translation":"Kemeja ini terlalu sempit—bolehkah saya menukarnya?"}'::jsonb, '["This shirt","is too","tight—can I","exchange","it?"]'::jsonb, NULL, NULL, '''This shirt'' tunggal -> kata ganti objek di akhir kalimat adalah ''it''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000455', 'e4100001-0000-4000-8000-000000000055', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat klaim pengembalian barang beserta struk ini: "Saya ingin mengembalikan lampu meja ini, dan ini struk aslinya."', '{"romaji":"/aɪd laɪk tə rɪˈtɜːrn ðɪs desk læmp, ænd hɪr ɪz ðə rɪˈsiːt/","display_text":"I''d like to return this desk lamp, and here is the receipt.","phonetic_breakdown":["aɪd","laɪk","tə","rɪ-ˈtɜːrn","ðɪs","desk","læmp","ænd","hɪr","ɪz","ðə","rɪ-ˈsiːt"]}'::jsonb, '{"expected_transcript":"I''d like to return this desk lamp, and here is the receipt."}'::jsonb, NULL, NULL, 'Ingat kembali: ''receipt'' dilafalkan /rɪˈsiːt/ tanpa bunyi /p/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000456', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Ingat larangan menggabungkan ''because'' dan ''so''! Pilih kata sambung yang tepat: Because the laptop screen had dead pixels, ___ I returned it to the store.', '{"options":["so","because","when","although"],"translation":"Layar laptop itu memiliki piksel mati, jadi saya mengembalikannya ke toko.","sentence_template":"The laptop screen had dead pixels, [blank] I returned it to the store."}'::jsonb, '{"selected":"so"}'::jsonb, NULL, NULL, 'Klausa pertama adalah sebab dan klausa kedua adalah akibat setelah koma, sehingga memakai ''so''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000457', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih klausa waktu yang tepat saat menemukan cacat barang: ___ I plugged in the blender, it didn''t turn on at all.', '{"options":["When","So","Because of","During"],"translation":"Ketika saya mencolokkan blender tersebut, alatnya sama sekali tidak menyala.","sentence_template":"[blank] I plugged in the blender, it didn''t turn on at all."}'::jsonb, '{"selected":"When"}'::jsonb, NULL, NULL, '''When + Subject + Past Verb'' menandai momen terjadinya peristiwa kedua.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000458', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih kata benda untuk barang baru pengganti barang yang rusak saat pengiriman: The ceramic plate arrived broken—can you ship a ___?', '{"options":["replacement","receipt","discount","fitting"],"translation":"Piring keramiknya tiba dalam keadaan pecah—bisakah Anda mengirimkan barang pengganti?","sentence_template":"The ceramic plate arrived broken—can you ship a [blank]?"}'::jsonb, '{"selected":"replacement"}'::jsonb, NULL, NULL, '''A replacement'' adalah unit produk pengganti baru atas barang yang rusak atau hilang.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000459', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan panggilan pelanggan ke layanan dukungan toko buku online ini. Apa kesalahan pada paket yang ia terima?', '{"options":[{"id":"opt_1","text":"Kotak paketnya kosong tidak berisi buku apa pun"},{"id":"opt_2","text":"Ia memesan buku Mikroekonomi, tetapi yang dikirim di dalam paket justru buku panduan praktikum Kimia"},{"id":"opt_3","text":"Buku Mikroekonominya basah terkena air hujan"},{"id":"opt_4","text":"Paketnya dikirim ke kota yang salah"}],"audio_text":"Hi, I ordered an Introduction to Microeconomics textbook, but when I opened the package today, there was a chemistry lab manual inside instead."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kronologi jelas dengan ''when I opened the package today, there was a chemistry lab manual inside instead''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000460', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan solusi ramah dari agen layanan pelanggan berikut. Apakah pelanggan harus membayar ongkos kirim pengembalian barang?', '{"options":[{"id":"opt_1","text":"Pelanggan wajib membayar biaya kirim dua puluh dolar"},{"id":"opt_2","text":"Gratis—agen telah mengirim label pengiriman retur prabayar (prepaid return label) untuk diserahkan di gerai UPS mana saja"},{"id":"opt_3","text":"Pelanggan harus mengantar sendiri ke gudang pusat di luar kota"},{"id":"opt_4","text":"Barang yang salah tidak boleh dikembalikan"}],"audio_text":"I''m so sorry about the mix-up! I just emailed you a prepaid return shipping label, so you can drop the box off at any UPS store for free."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Prepaid return shipping label'' adalah sistem retur online paling praktis di seluruh AS.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000461', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat kronologi saat membuka paket: "Ketika saya membuka kotaknya, layarnya retak."', '{"romaji":"/wen aɪ ˈoʊpənd ðə bɑːks, ðə skriːn wʌz krækt/","tokens":["the box,","opened","When I","so the","the screen","was cracked.","opening"],"target_translation":"Ketika saya membuka kotaknya, layarnya retak."}'::jsonb, '["When I","opened","the box,","the screen","was cracked."]'::jsonb, NULL, NULL, 'Jangan tambahkan ''so'' atau ''then'' setelah koma pada kalimat yang diawali ''When...''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000462', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat menjelaskan alasan penukaran: "Saya menukar sepatunya karena mereka mengirim ukuran yang salah."', '{"romaji":"/aɪ ɪksˈtʃeɪndʒd ðə ʃuːz bɪˈkɔːz ðeɪ sent ðə rɔːŋ saɪz/","tokens":["because they","I exchanged","wrong size.","the shoes","sended","because of","sent the"],"target_translation":"Saya menukar sepatunya karena mereka mengirim ukuran yang salah."}'::jsonb, '["I exchanged","the shoes","because they","sent the","wrong size."]'::jsonb, NULL, NULL, 'V2 dari ''send'' adalah ''sent'' (bukan ''sended''), dan huruf ''w'' pada ''wrong'' (/rɔːŋ/) senyap!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000463', 'e4100001-0000-4000-8000-000000000056', 'e2000001-0000-4000-8000-000000000014', 'speaking', 'speaking_repeat', 'Ucapkan kalimat klaim paket online ini dengan tenang dan sopan: "Pesanan saya tiba hari ini, tetapi satu barang hilang."', '{"romaji":"/maɪ ˈɔːrdər əˈraɪvd təˈdeɪ, bʌt wʌn ˈaɪtəm ɪz ˈmɪsɪŋ/","display_text":"My order arrived today, but one item is missing.","phonetic_breakdown":["maɪ","ˈɔːr-dər","ə-ˈraɪvd","tə-ˈdeɪ","bʌt","wʌn","ˈaɪ-təm","ɪz","ˈmɪ-sɪŋ"]}'::jsonb, '{"expected_transcript":"My order arrived today, but one item is missing."}'::jsonb, NULL, NULL, 'Lafalkan ''item'' ala Amerika dengan flap-t lembut (/ˈaɪɾəm/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000464', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Ingat posisi kata ganti ''them'' pada phrasal verb ''try on'': I really like these winter boots—can I ___?', '{"options":["try them on","try on them","trying them","to try on it"],"translation":"Saya sangat suka sepatu bot musim dingin ini—bolehkah saya mencobanya?","sentence_template":"I really like these winter boots—can I [blank]?"}'::jsonb, '{"selected":"try them on"}'::jsonb, NULL, NULL, '''These winter boots'' jamak (''them'') dan wajib diletakkan di tengah ''try ... on'' (''try them on'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000465', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih preposisi tetap untuk menyatakan barang masih dilindungi masa garansi: Good news—your monitor is still ___ warranty, so the repair is free.', '{"options":["under","above","between","across"],"translation":"Kabar baik—monitor Anda masih dalam masa garansi, jadi perbaikannya gratis.","sentence_template":"Good news—your monitor is still [blank] warranty, so the repair is free."}'::jsonb, '{"selected":"under"}'::jsonb, NULL, NULL, 'Idiom baku untuk masa garansi adalah ''under warranty''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000466', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih kata yang tepat ketika kartu kredit Anda terpotong dua kali untuk transaksi yang sama: Excuse me, I checked my bank app and noticed I was ___ twice for one coffee.', '{"options":["charged","returned","borrowed","fitted"],"translation":"Permisi, saya mengecek aplikasi bank saya dan melihat kartu saya terpotong dua kali untuk satu kopi.","sentence_template":"Excuse me, I checked my bank app and noticed I was [blank] twice for one coffee."}'::jsonb, '{"selected":"charged"}'::jsonb, NULL, NULL, '''Be charged [amount / twice]'' berarti dikenai penarikan/tagihan biaya pada rekening/kartu.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000467', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan percakapan pelanggan yang mengambil pesanan belanja daring di konter toko (''curbside / in-store pickup''). Apa dua hal yang diminta petugas?', '{"options":[{"id":"opt_1","text":"Kartu perpustakaan dan koin parkir"},{"id":"opt_2","text":"Kode batang pesanan (order barcode) di ponsel dan kartu identitas berfoto"},{"id":"opt_3","text":"Surat pengantar dari kampus"},{"id":"opt_4","text":"Kotak kemasan lama dari rumah"}],"audio_text":"Hi! I placed an online order for store pickup under Nadia Putri. — Sure! Could I see the order barcode on your phone and a photo ID?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Layanan ''store pickup'' (beli online, ambil di toko tanpa antre) meminta kode pesanan di ponsel dan photo ID.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000468', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan panggilan telepon ke layanan pelanggan aplikasi streaming ini. Mengapa pelanggan meminta pengembalian dana?', '{"options":[{"id":"opt_1","text":"Karena ia lupa kata sandi akunnya"},{"id":"opt_2","text":"Karena ia sudah membatalkan masa uji coba gratis sebelum tengah malam kemarin, namun kartunya masih terpotong $12 pagi ini"},{"id":"opt_3","text":"Karena ia ingin berlangganan paket sepuluh tahun"},{"id":"opt_4","text":"Karena film favoritnya memenangkan penghargaan"}],"audio_text":"Hi, I canceled my free trial yesterday before midnight, but my credit card was still charged twelve dollars this morning."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan ejaan Amerika ''canceled'' menggunakan satu huruf ''l'' (British memakai ''cancelled'')!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000469', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun pertanyaan mencari kamar pas di toko pakaian: "Permisi, di mana letak kamar pasnya?"', '{"romaji":"/ɪkˈskjuːz miː, wer ɑːr ðə ˈfɪtɪŋ ruːmz/","tokens":["where is","room","rooms?","Excuse me,","the fitting","where are"],"target_translation":"Permisi, di mana letak kamar pasnya?"}'::jsonb, '["Excuse me,","where are","the fitting","rooms?"]'::jsonb, NULL, NULL, 'Di toko AS disebut ''fitting rooms'' atau ''dressing rooms''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000470', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat mengambil pesanan daring: "Saya memesan buku ini secara daring—di mana saya bisa mengambilnya?"', '{"romaji":"/aɪ ˈɔːrdərd ðɪs bʊk ˈɑːnlaɪn—wer kæn aɪ pɪk ɪt ʌp/","tokens":["online—where can","I ordered","I pick","picks","pick up it?","it up?","this book"],"target_translation":"Saya memesan buku ini secara daring—di mana saya bisa mengambilnya?"}'::jsonb, '["I ordered","this book","online—where can","I pick","it up?"]'::jsonb, NULL, NULL, 'Kata ganti ''it'' berada tepat di tengah phrasal verb: ''pick it up''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000471', 'e4100001-0000-4000-8000-000000000057', 'e2000001-0000-4000-8000-000000000014', 'speaking', 'speaking_repeat', 'Ucapkan kalimat klarifikasi tagihan ganda ini dengan sopan: "Permisi, sepertinya kartu saya tertagih dua kali."', '{"romaji":"/ɪkˈskjuːz miː, aɪ θɪŋk maɪ kɑːrd wʌz tʃɑːrdʒd twaɪs/","display_text":"Excuse me, I think my card was charged twice.","phonetic_breakdown":["ɪk-ˈskjuːz","miː","aɪ","θɪŋk","maɪ","kɑːrd","wʌz","tʃɑːrdʒd","twaɪs"]}'::jsonb, '{"expected_transcript":"Excuse me, I think my card was charged twice."}'::jsonb, NULL, NULL, 'Membuka dengan ''I think...'' membuat penyampaian koreksi tagihan terdengar tenang, sopan, dan efektif!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000472', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih phrasal verb khas AS untuk ''mengisi formulir retur'': Please ___ out this short return form with your email address.', '{"options":["fill","put","take","try"],"translation":"Mohon isi formulir pengembalian singkat ini dengan alamat email Anda.","sentence_template":"Please [blank] out this short return form with your email address."}'::jsonb, '{"selected":"fill"}'::jsonb, NULL, NULL, 'Dalam American English, mengisi formulir selalu menggunakan ''fill out a form''!', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000473', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih kalimat yang bebas dari kesalahan kata sambung ganda: ___ the zipper was broken, the store gave me a full refund.', '{"options":["Because","So","Because of","During"],"translation":"Karena resletingnya rusak, pihak toko memberi saya pengembalian dana penuh.","sentence_template":"[blank] the zipper was broken, the store gave me a full refund."}'::jsonb, '{"selected":"Because"}'::jsonb, NULL, NULL, '''Because + Subject + Verb'' membuka klausa alasan sebelum koma tanpa kata ''so'' di klausa kedua.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000474', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'reading', 'fill_blank', 'Pilih posisi objek kata ganti yang benar untuk ''drop off'' (menyerahkan paket): Print the return label and ___ at the post office.', '{"options":["drop the box off","drop off it","dropping it","to drop them"],"translation":"Cetak label returnya dan serahkan kotak tersebut di kantor pos.","sentence_template":"Print the return label and [blank] at the post office."}'::jsonb, '{"selected":"drop the box off"}'::jsonb, NULL, NULL, 'Untuk noun phrase (''the box''), boleh ''drop the box off'' atau ''drop off the box'' (sedangkan ''drop off it'' salah).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000475', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan percakapan pembeli di konter pengembalian barang toko elektronik ini. Mengapa ia memilih tukar barang (exchange) daripada uang kembali (refund)?', '{"options":[{"id":"opt_1","text":"Karena ia tidak menyukai model papan ketik tersebut"},{"id":"opt_2","text":"Ia memilih menukar dengan model yang persis sama karena membutuhkannya untuk bekerja hari ini"},{"id":"opt_3","text":"Karena tokonya tidak punya uang kembalian"},{"id":"opt_4","text":"Karena ia ingin menukarnya dengan televisi"}],"audio_text":"Would you like a refund to your card or a replacement keyboard? — Just an exchange for the exact same model, please—I need it for work today."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''An exchange for the exact same model'' berarti tukar guling unit baru dengan tipe yang sama.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000476', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'listening', 'listening_choice', 'Dengarkan pesan otomatis pelacakan kurir ini. Kapan paket diperkirakan tiba di alamat tujuan?', '{"options":[{"id":"opt_1","text":"Paket masih tertahan di pabrik pembuatnya"},{"id":"opt_2","text":"Paket sedang dibawa kurir pengantar lokal (''out for delivery'') dan diperkirakan tiba paling lambat jam 8 malam ini"},{"id":"opt_3","text":"Paket sudah tiba tiga hari yang lalu"},{"id":"opt_4","text":"Pengiriman ditunda hingga minggu depan"}],"audio_text":"Good news! Your package is out for delivery with our local courier and is expected to arrive by eight p.m. tonight."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Status ''out for delivery'' berarti paket sudah di mobil kurir menuju rumahmu hari itu juga!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000477', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat permintaan pembatalan langganan: "Saya ingin membatalkan keanggotaan bulanan saya, tolong."', '{"romaji":"/aɪd laɪk tə ˈkænsəl maɪ ˈmʌnθli ˈmembərʃɪp, pliːz/","tokens":["please.","to cancel","membership,","memberships,","canceling","my monthly","I''d like"],"target_translation":"Saya ingin membatalkan keanggotaan bulanan saya, tolong."}'::jsonb, '["I''d like","to cancel","my monthly","membership,","please."]'::jsonb, NULL, NULL, 'Kalimat lugas dan sopan saat menghubungi layanan pelanggan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000478', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat keluhan ukuran celana: "Celana panjang ini tidak cukup panjang untuk saya."', '{"romaji":"/ðiːz pænts ˈɑːrənt lɔːŋ ɪˈnʌf fɔːr miː/","tokens":["These pants","long enough","enough long","isn''t","aren''t","for me."],"target_translation":"Celana panjang ini tidak cukup panjang untuk saya."}'::jsonb, '["These pants","aren''t","long enough","for me."]'::jsonb, NULL, NULL, '''These pants'' jamak (''aren''t'') + kata sifat ''long'' sebelum ''enough'' (''long enough'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000479', 'e4100001-0000-4000-8000-000000000058', 'e2000001-0000-4000-8000-000000000014', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan kebijakan pengembalian toko ini sebelum membeli: "Bagaimana kebijakan pengembalian barang untuk barang elektronik di sini?"', '{"romaji":"/wʌt ɪz ðə rɪˈtɜːrn ˈpɑːləsi fɔːr ɪˌlekˈtrɑːnɪks hɪr/","display_text":"What is the return policy for electronics here?","phonetic_breakdown":["wʌt","ɪz","ðə","rɪ-ˈtɜːrn","ˈpɑː-lə-si","fɔːr","ɪ-ˌlek-ˈtrɑː-nɪks","hɪr"]}'::jsonb, '{"expected_transcript":"What is the return policy for electronics here?"}'::jsonb, NULL, NULL, 'Barang elektronik di AS kadang memiliki ''14-day return policy'' (lebih pendek dari pakaian 30 hari), jadi bagus sekali menanyakannya lebih dulu!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000480', 'e4100001-0000-4000-8000-000000000059', NULL, 'reading', 'fill_blank', 'Pilih pola yang benar untuk kata sifat sensasi tubuh ''dizzy'' (kliyengan): I stood up too fast and suddenly ___ a little dizzy.', '{"options":["felt","had","hurted","did"],"translation":"Saya berdiri terlalu cepat dan tiba-tiba merasa agak pusing kliyengan.","sentence_template":"I stood up too fast and suddenly [blank] a little dizzy."}'::jsonb, '{"selected":"felt"}'::jsonb, NULL, NULL, '''Dizzy'' adalah kata sifat, sehingga berpasangan dengan kata kerja ''feel'' (bentuk lampau: ''felt''), bukan ''have''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000481', 'e4100001-0000-4000-8000-000000000059', NULL, 'reading', 'fill_blank', 'Pilih istilah AS untuk obat yang bisa langsung dibeli bebas di rak apotek tanpa resep dokter: For a mild cold, the pharmacist recommended an ___ decongestant.', '{"options":["over-the-counter","under-the-table","out-of-office","up-to-date"],"translation":"Untuk pilek ringan, apoteker menyarankan obat pelega hidung bebas tanpa resep.","sentence_template":"For a mild cold, the pharmacist recommended an [blank] decongestant."}'::jsonb, '{"selected":"over-the-counter"}'::jsonb, NULL, NULL, '''Over-the-counter'' (disingkat OTC) berarti obat bebas yang tidak memerlukan resep dokter (''prescription'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000482', 'e4100001-0000-4000-8000-000000000059', NULL, 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang tepat untuk satu bagian tubuh tunggal (''My right ankle''): I twisted my foot playing basketball, and now my right ankle really ___!', '{"options":["hurts","hurt","is pain","ache"],"translation":"Kaki saya terkilir saat bermain basket, dan sekarang pergelangan kaki kanan saya benar-benar sakit!","sentence_template":"I twisted my foot playing basketball, and now my right ankle really [blank]!"}'::jsonb, '{"selected":"hurts"}'::jsonb, NULL, NULL, 'Subjek tunggal ''my right ankle'' membutuhkan kata kerja Present Simple + -s (''hurts'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000483', 'e4100001-0000-4000-8000-000000000059', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan telepon membuat janji di klinik kesehatan kampus (Student Health Center). Dokumen apa yang harus dibawa mahasiswa?', '{"options":[{"id":"opt_1","text":"Transkrip nilai dan laptop"},{"id":"opt_2","text":"Kartu mahasiswa dan kartu asuransi kesehatan, serta datang 10 menit lebih awal untuk jadwal jam 14.30"},{"id":"opt_3","text":"Paspor dan tiket pesawat"},{"id":"opt_4","text":"Uang tunai lima ratus dolar"}],"audio_text":"We have an opening with Dr. Miller at two-thirty today. Please arrive ten minutes early and bring your student ID and health insurance card."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kata ''an opening'' dalam konteks janji temu di AS berarti ''slot jadwal kosong yang tersedia''!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000484', 'e4100001-0000-4000-8000-000000000059', NULL, 'listening', 'listening_choice', 'Dengarkan konsultasi singkat pelanggan dengan apoteker di CVS ini. Apa efek samping obat alergi yang berada di kotak biru?', '{"options":[{"id":"opt_1","text":"Kotak biru membuat mata terjaga semalaman"},{"id":"opt_2","text":"Kotak hijau tidak menyebabkan kantuk (''non-drowsy'') untuk siang hari, sedangkan kotak biru bisa membuat mengantuk"},{"id":"opt_3","text":"Kedua kotak khusus untuk anak balita"},{"id":"opt_4","text":"Kotak biru hanya boleh diminum sebulan sekali"}],"audio_text":"What''s the difference between these two allergy pills? — The green box is non-drowsy for daytime, while the blue box can make you sleepy."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Label ''Non-Drowsy'' sangat penting diperhatikan pada kemasan obat flu/alergi di AS agar tidak mengantuk saat kuliah atau kerja!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000485', 'e4100001-0000-4000-8000-000000000059', NULL, 'writing', 'sentence_builder', 'Susun kalimat menjelaskan gejala flu ke perawat: "Saya mengalami sakit tenggorokan dan demam ringan."', '{"romaji":"/aɪ hæv ə sɔːr θroʊt ænd ə maɪld ˈfiːvər/","tokens":["throat and","I have","a sore","feel a","fevers.","a mild","fever."],"target_translation":"Saya mengalami sakit tenggorokan dan demam ringan."}'::jsonb, '["I have","a sore","throat and","a mild","fever."]'::jsonb, NULL, NULL, 'Keluhan umum memakai artikel ''a'': ''have a sore throat'', ''have a fever'', ''have a cold''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000486', 'e4100001-0000-4000-8000-000000000059', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan di konter apotek: "Apakah saya memerlukan resep dokter untuk salep ini?"', '{"romaji":"/də aɪ niːd ə prɪˈskrɪpʃən fɔːr ðɪs ˈɔɪntmənt/","tokens":["need a","for this","prescriptions","ointment?","prescription","Are I","Do I"],"target_translation":"Apakah saya memerlukan resep dokter untuk salep ini?"}'::jsonb, '["Do I","need a","prescription","for this","ointment?"]'::jsonb, NULL, NULL, '''Ointment'' (/ˈɔɪntmənt/) berarti salep kulit medis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000487', 'e4100001-0000-4000-8000-000000000059', NULL, 'speaking', 'speaking_repeat', 'Latih pelafalan kata stomachache (/ˈstʌməkeɪk/) dan cough (/kɔːf/) pada kalimat ini: "Saya mengalami batuk parah dan sakit perut."', '{"romaji":"/aɪ hæv ə bæd kɔːf ænd ə ˈstʌməkeɪk/","display_text":"I have a bad cough and a stomachache.","phonetic_breakdown":["aɪ","hæv","ə","bæd","kɔːf","ænd","ə","ˈstʌ-mə-keɪk"]}'::jsonb, '{"expected_transcript":"I have a bad cough and a stomachache."}'::jsonb, NULL, NULL, 'Kedua huruf ''ch'' pada ''stomach-ache'' berbunyi /k/: /ˈstʌməkeɪk/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000488', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih kata kerja kolokasi yang benar untuk ''minum obat tablet'' dalam bahasa Inggris: You should ___ one capsule twice a day with food.', '{"options":["take","eat","drink","chew"],"translation":"Sebaiknya Anda minum satu kapsul dua kali sehari bersama makanan.","sentence_template":"You should [blank] one capsule twice a day with food."}'::jsonb, '{"selected":"take"}'::jsonb, NULL, NULL, 'Dalam bahasa Inggris, mengonsumsi obat pil/kapsul selalu memakai kata kerja ''take'' (bukan ''drink'' atau ''eat''!).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000489', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Perhatikan bentuk kata kerja setelah modal ''shouldn''t'': He has a sprained knee, so he shouldn''t ___ up the stairs today.', '{"options":["walk","walks","to walk","walking"],"translation":"Lututnya terkilir, jadi sebaiknya dia tidak berjalan menaiki tangga hari ini.","sentence_template":"He has a sprained knee, so he shouldn''t [blank] up the stairs today."}'::jsonb, '{"selected":"walk"}'::jsonb, NULL, NULL, 'Setelah modal ''shouldn''t'', gunakan kata kerja dasar V1 murni (''walk'') untuk semua subjek.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000490', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih preposisi untuk ungkapan ''saat perut kosong'': Don''t take this pain reliever ___ an empty stomach.', '{"options":["on","in","at","by"],"translation":"Jangan minum obat pereda nyeri ini saat perut kosong.","sentence_template":"Don''t take this pain reliever [blank] an empty stomach."}'::jsonb, '{"selected":"on"}'::jsonb, NULL, NULL, 'Idiom medis standar bahasa Inggris adalah ''on an empty stomach''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000491', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan nasihat dokter di klinik kampus kepada mahasiswa yang mengalami mata tegang ini. Kebiasaan apa yang disarankan dokter?', '{"options":[{"id":"opt_1","text":"Berhenti kuliah ilmu komputer selamanya"},{"id":"opt_2","text":"Menerapkan aturan 20-20-20: setiap 20 menit, alihkan pandangan sejauh 20 kaki selama 20 detik"},{"id":"opt_3","text":"Memakai kacamata hitam gelap di dalam kamar malam hari"},{"id":"opt_4","text":"Mencuci layar laptop dengan sabun"}],"audio_text":"Your eyes are very dry from coding all day. You should follow the twenty-twenty-twenty rule: every twenty minutes, look twenty feet away for twenty seconds."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Aturan kesehatan mata populer di kantor teknologi AS adalah ''the 20-20-20 rule''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000492', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan percakapan telepon karyawan yang sedang demam kepada manajernya. Apa tanggapan manajernya?', '{"options":[{"id":"opt_1","text":"Manajer memaksa karyawan tetap datang ke kantor"},{"id":"opt_2","text":"Manajer berempati dan menyarankan mengambil cuti sakit (''take a sick day'') tanpa perlu mencemaskan slide hari ini"},{"id":"opt_3","text":"Manajer memotong gaji karyawan selama sebulan"},{"id":"opt_4","text":"Manajer meminta karyawan mempresentasikan materi dari tempat tidur"}],"audio_text":"Hi Rachel, I woke up with a high fever this morning. — Oh no, I''m sorry to hear that! You should definitely take a sick day—don''t worry about today''s slides."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Respons empati standar di AS saat mendengar kabar sakit/buruk adalah ''I''m sorry to hear that!'' diikuti ''Feel better soon!''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000493', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat nasihat kesehatan ini: "Sebaiknya kamu minum banyak air dan tidur lebih awal."', '{"romaji":"/juː ʃʊd drɪŋk ˈplenti ʌv ˈwɔːtər ænd sliːp ˈɜːrli/","tokens":["drinks","You should","drink plenty","early.","and sleep","of water","to drink"],"target_translation":"Sebaiknya kamu minum banyak air dan tidur lebih awal."}'::jsonb, '["You should","drink plenty","of water","and sleep","early."]'::jsonb, NULL, NULL, 'Dua kata kerja sejajar setelah ''should'' sama-sama berbentuk V1 (''drink ... and sleep'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000494', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat saran negatif alami dengan I don''t think: "Menurutku sebaiknya kamu tidak menyetir dalam cuaca bersalju ini."', '{"romaji":"/aɪ doʊnt θɪŋk juː ʃʊd draɪv ɪn ðɪs snoʊ/","tokens":["driving","snow.","I don''t","shouldn''t","in this","think you","should drive"],"target_translation":"Menurutku sebaiknya kamu tidak menyetir dalam cuaca bersalju ini."}'::jsonb, '["I don''t","think you","should drive","in this","snow."]'::jsonb, NULL, NULL, 'Karena negatifnya sudah di ''I don''t think'', klausa kedua memakai positif ''you should drive'' (jangan negatif ganda!).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000495', 'e4100001-0000-4000-8000-000000000060', 'e2000001-0000-4000-8000-000000000015', 'speaking', 'speaking_repeat', 'Ucapkan doa kesembuhan yang hangat kepada teman/rekan kerja yang sakit ini: "Maaf mendengar kabar itu—semoga lekas sembuh ya!"', '{"romaji":"/aɪm ˈsɑːri tə hɪr ðæt—fiːl ˈbetər suːn/","display_text":"I''m sorry to hear that—feel better soon!","phonetic_breakdown":["aɪm","ˈsɑː-ri","tə","hɪr","ðæt","fiːl","ˈbe-tər","suːn"]}'::jsonb, '{"expected_transcript":"I''m sorry to hear that—feel better soon!"}'::jsonb, NULL, NULL, 'Di AS, ''Feel better soon!'' atau ''Get well soon!'' adalah ucapan standar mendoakan teman yang sedang sakit!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000496', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih kata frekuensi yang tepat untuk ''dua kali sehari'' (pagi dan malam): Take this antibiotic ___ a day for seven days until the bottle is finished.', '{"options":["twice","two","second","double"],"translation":"Minum antibiotik ini dua kali sehari selama tujuh hari sampai habis.","sentence_template":"Take this antibiotic [blank] a day for seven days until the bottle is finished."}'::jsonb, '{"selected":"twice"}'::jsonb, NULL, NULL, 'Dalam bahasa Inggris, ''satu kali'' adalah ''once'' dan ''dua kali'' adalah ''twice'' (bukan ''two times'' dalam instruksi medis baku).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000497', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih idiom bahasa Inggris yang berarti ''sedang kurang enak badan / meriang'': Hi team, I''m feeling a little under the ___ today, so I''ll be offline resting.', '{"options":["weather","cloud","rain","wind"],"translation":"Hai tim, saya merasa agak kurang enak badan hari ini, jadi saya akan luring untuk beristirahat.","sentence_template":"Hi team, I''m feeling a little under the [blank] today, so I''ll be offline resting."}'::jsonb, '{"selected":"weather"}'::jsonb, NULL, NULL, '''Feeling under the weather'' adalah idiom halus yang sangat lazim dipakai di kantor maupun kampus AS.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000498', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat saat datang mengambil obat resep di konter apotek Walgreens: Hi, I''m here to ___ up a prescription for Clara Wijaya.', '{"options":["pick","take","get","bring"],"translation":"Halo, saya ke sini untuk mengambil obat resep atas nama Clara Wijaya.","sentence_template":"Hi, I''m here to [blank] up a prescription for Clara Wijaya."}'::jsonb, '{"selected":"pick"}'::jsonb, NULL, NULL, 'Phrasal verb standar menebus/mengambil pesanan obat di apotek adalah ''pick up a prescription''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000499', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan verifikasi petugas apotek di AS berikut. Berapa biaya tebus sendiri (copay) yang harus dibayar mahasiswa setelah dipotong asuransi?', '{"options":[{"id":"opt_1","text":"Seratus dua puluh dolar penuh karena asuransi ditolak"},{"id":"opt_2","text":"Hanya sepuluh dolar ($10 copay) karena sebagian besar biaya sudah ditanggung asuransi mahasiswa"},{"id":"opt_3","text":"Gratis tanpa membayar satu sen pun"},{"id":"opt_4","text":"Lima puluh dolar tunai"}],"audio_text":"Got it—born March twelfth, two thousand three. Your student insurance covers most of the cost, so your copay is just ten dollars."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Istilah penting asuransi AS: ''copay'' (/ˈkoʊpeɪ/) adalah porsi biaya tetap kecil (misal $10–$25) yang dibayar pasien saat berobat/menebus resep!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000500', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan dokter klinik menjelaskan ke mana resep obat dikirimkan. Kapan obatnya siap diambil?', '{"options":[{"id":"opt_1","text":"Pasien harus membawa kertas resep ke rumah sakit pusat besok"},{"id":"opt_2","text":"Resep dikirim elektronik ke apotek CVS di Main Street dan diperkirakan siap diambil sekitar 45 menit lagi"},{"id":"opt_3","text":"Obat akan dikirim lewat pos minggu depan"},{"id":"opt_4","text":"Dokter tidak memberikan obat apa pun"}],"audio_text":"I just sent your prescription electronically to the CVS Pharmacy on Main Street—it should be ready for pickup in about forty-five minutes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Should be ready in about forty-five minutes'' juga menunjukkan penggunaan ''should'' untuk perkiraan wajar!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000501', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat menebus resep di konter apotek: "Saya ke sini untuk mengambil obat resep atas nama Bima."', '{"romaji":"/aɪm hɪr tə pɪk ʌp ə prɪˈskrɪpʃən fɔːr ˈbiːmə/","tokens":["to pick up","a prescription","I''m here","for Bima.","recipe","picks up"],"target_translation":"Saya ke sini untuk mengambil obat resep atas nama Bima."}'::jsonb, '["I''m here","to pick up","a prescription","for Bima."]'::jsonb, NULL, NULL, 'Jangan tertukar: ''prescription'' = resep dokter, ''receipt'' = struk kasir, ''recipe'' = resep masakan!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000502', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun pesan izin sakit pagi hari ke manajer: "Saya kurang enak badan hari ini, jadi saya perlu mengambil izin sakit."', '{"romaji":"/aɪm ˈfiːlɪŋ ˈʌndər ðə ˈweðər, soʊ aɪ niːd ə sɪk deɪ/","tokens":["under the","weather, so","I need","below the","sicks","I''m feeling","a sick day."],"target_translation":"Saya kurang enak badan hari ini, jadi saya perlu mengambil izin sakit."}'::jsonb, '["I''m feeling","under the","weather, so","I need","a sick day."]'::jsonb, NULL, NULL, 'Sopan, profesional, dan langsung dipahami di semua perusahaan AS.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000503', 'e4100001-0000-4000-8000-000000000061', 'e2000001-0000-4000-8000-000000000015', 'speaking', 'speaking_repeat', 'Ucapkan kalimat membuat janji klinik lewat telepon ini: "Halo, saya ingin membuat janji temu dengan dokter hari ini."', '{"romaji":"/haɪ, aɪd laɪk tə meɪk ən əˈpɔɪntmənt tə siː ə ˈdɑːktər təˈdeɪ/","display_text":"Hi, I''d like to make an appointment to see a doctor today.","phonetic_breakdown":["haɪ","aɪd","laɪk","tə","meɪk","ən","ə-ˈpɔɪnt-mənt","tə","siː","ə","ˈdɑːk-tər","tə-ˈdeɪ"]}'::jsonb, '{"expected_transcript":"Hi, I''d like to make an appointment to see a doctor today."}'::jsonb, NULL, NULL, 'Perhatikan dua kolokasi emas sekaligus: ''make an appointment'' dan ''see a doctor'' (berkonsultasi ke dokter)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000504', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih tempat berobat yang paling tepat di AS untuk keluhan keseleo ringan atau radang tenggorokan di akhir pekan saat klinik kampus tutup: Let''s go to the neighborhood ___ Care clinic.', '{"options":["Urgent","Emergency Room","Pharmacy","Dental"],"translation":"Ayo pergi ke klinik Urgent Care di lingkungan sekitar kita.","sentence_template":"Let''s go to the neighborhood [blank] Care clinic."}'::jsonb, '{"selected":"Urgent"}'::jsonb, NULL, NULL, '''Urgent Care'' melayani keluhan medis mendesak non-gawat-jiwa dengan cepat dan biaya jauh lebih terjangkau dibanding UGD rumah sakit (''ER'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000505', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih kalimat yang tata bahasanya tepat untuk keluhan sakit punggung: I sat at my desk for nine hours, and now my lower back ___.', '{"options":["hurts","is hurt of","have pain","aching"],"translation":"Saya duduk di meja kerja selama sembilan jam, dan sekarang punggung bawah saya terasa nyeri.","sentence_template":"I sat at my desk for nine hours, and now my lower back [blank]."}'::jsonb, '{"selected":"hurts"}'::jsonb, NULL, NULL, '''My lower back'' tunggal diikuti kata kerja Present Simple ''hurts'' (atau ''aches'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000506', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'reading', 'fill_blank', 'Pilih kata tanya saran yang benar: My flight was canceled and my medication is in my checked bag—what ___ I do?', '{"options":["should","am","have","would to"],"translation":"Penerbangan saya dibatalkan dan obat rutin saya ada di bagasi tercatat—apa yang sebaiknya saya lakukan? (Tips: selalu simpan obat di carry-on!)","sentence_template":"My flight was canceled and my medication is in my checked bag—what [blank] I do?"}'::jsonb, '{"selected":"should"}'::jsonb, NULL, NULL, '''What should I do?'' meminta saran langkah terbaik dalam situasi sulit.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000507', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan instruksi apoteker mengenai cara penyimpanan dan pemakaian obat tetes mata ini. Kapan obat tersebut harus digunakan?', '{"options":[{"id":"opt_1","text":"Disimpan di dalam freezer pembeku es"},{"id":"opt_2","text":"Dua tetes pada masing-masing mata setiap pagi dan malam, disimpan pada suhu ruang jauh dari sinar matahari langsung"},{"id":"opt_3","text":"Diminum satu sendok makan sebelum tidur"},{"id":"opt_4","text":"Hanya dipakai sekali dalam sebulan"}],"audio_text":"Use two drops in each eye every morning and night, and make sure you keep the bottle at room temperature away from direct sunlight."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Two drops in each eye every morning and night'' dan ''at room temperature'' sangat jelas.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000508', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'listening', 'listening_choice', 'Dengarkan percakapan perawat triase klinik kampus berikut. Sudah berapa lama mahasiswa tersebut mengalami batuk?', '{"options":[{"id":"opt_1","text":"Baru lima menit yang lalu"},{"id":"opt_2","text":"Batuk kering sejak hari Rabu, dan tadi malam mulai menggigil (''chills'')"},{"id":"opt_3","text":"Sudah sembuh total minggu lalu"},{"id":"opt_4","text":"Hanya datang untuk meminta surat sehat olahraga"}],"audio_text":"What brings you into the clinic today? — I''ve had this dry cough since Wednesday, and last night I started getting chills."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pertanyaan pembuka khas dokter/perawat di AS adalah ''What brings you in today?'' (Keluhan apa yang membawa Anda datang hari ini?).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000509', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat nasihat istirahat kepada rekan kerja: "Sebaiknya kamu pulang lebih awal dan beristirahat."', '{"romaji":"/juː ʃʊd ɡoʊ hoʊm ˈɜːrli ænd ɡet sʌm rest/","tokens":["You should","go home","rests.","to home","get some","early and","rest."],"target_translation":"Sebaiknya kamu pulang lebih awal dan beristirahat."}'::jsonb, '["You should","go home","early and","get some","rest."]'::jsonb, NULL, NULL, 'Ingat kembali: ''go home'' tidak memakai preposisi ''to''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000510', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat aturan minum obat: "Minum satu tablet setelah makan malam bersama segelas air."', '{"romaji":"/teɪk wʌn ˈtæblət ˈæftər ˈdɪnər wɪð ə ɡlæs ʌv ˈwɔːtər/","tokens":["dinners","Take one","of water.","a glass","tablet after","Drink one","dinner with"],"target_translation":"Minum satu tablet setelah makan malam bersama segelas air."}'::jsonb, '["Take one","tablet after","dinner with","a glass","of water."]'::jsonb, NULL, NULL, 'Gunakan kata kerja ''Take'' untuk tablet/kapsul.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000511', 'e4100001-0000-4000-8000-000000000062', 'e2000001-0000-4000-8000-000000000015', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembuka kepada perawat klinik ini: "Saya mengalami sakit kepala dan tenggorokan nyeri sejak kemarin."', '{"romaji":"/aɪv hæd ə ˈhedeɪk ænd ə sɔːr θroʊt sɪns ˈjestərdeɪ/","display_text":"I''ve had a headache and a sore throat since yesterday.","phonetic_breakdown":["aɪv","hæd","ə","ˈhed-eɪk","ænd","ə","sɔːr","θroʊt","sɪns","ˈjes-tər-deɪ"]}'::jsonb, '{"expected_transcript":"I''ve had a headache and a sore throat since yesterday."}'::jsonb, NULL, NULL, 'Jembatan sempurna menuju materi Present Perfect di paruh kedua Level A2!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000512', 'e4100001-0000-4000-8000-000000000063', NULL, 'reading', 'fill_blank', 'Pilih bentuk V3 (Past Participle) yang tepat setelah ''have'': Have you ever ___ an online coding course on Coursera?', '{"options":["taken","took","take","taking"],"translation":"Pernahkah kamu mengambil kursus pemrograman daring di Coursera?","sentence_template":"Have you ever [blank] an online coding course on Coursera?"}'::jsonb, '{"selected":"taken"}'::jsonb, NULL, NULL, 'Setelah ''Have + subject + ever'', kata kerja wajib berbentuk V3: ''take'' -> ''took'' (V2) -> ''taken'' (V3).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000513', 'e4100001-0000-4000-8000-000000000063', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk menyatakan seseorang PERNAH ke Tokyo dan sekarang sudah kembali di kantor: Nadia has ___ to Tokyo twice for business conferences.', '{"options":["been","gone","went","be"],"translation":"Nadia sudah pernah ke Tokyo dua kali untuk konferensi bisnis.","sentence_template":"Nadia has [blank] to Tokyo twice for business conferences."}'::jsonb, '{"selected":"been"}'::jsonb, NULL, NULL, '''Has been to'' berarti pernah mengunjungi suatu tempat dan sudah kembali, sedangkan ''has gone to'' berarti masih berada di sana.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000514', 'e4100001-0000-4000-8000-000000000063', NULL, 'reading', 'fill_blank', 'Hindari jebakan negasi ganda saat memakai ''never'': I ___ eaten authentic Texas barbecue before.', '{"options":["have never","haven''t never","did never","am never"],"translation":"Saya belum pernah makan barbeku asli Texas sebelumnya.","sentence_template":"I [blank] eaten authentic Texas barbecue before."}'::jsonb, '{"selected":"have never"}'::jsonb, NULL, NULL, 'Kata ''never'' sudah membawa arti negatif (''tidak pernah''), sehingga dipasangkan dengan kata bantu positif ''have'' (''have never eaten'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000515', 'e4100001-0000-4000-8000-000000000063', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan santai dua mahasiswa baru saat orientasi kampus ini. Pengalaman apa yang belum pernah dirasakan pembicara pria?', '{"options":[{"id":"opt_1","text":"Ia belum pernah naik pesawat terbang ke luar negeri"},{"id":"opt_2","text":"Ia tumbuh di Surabaya sehingga belum pernah merasakan salju musim dingin"},{"id":"opt_3","text":"Ia sudah lima kali bermain ski di Colorado"},{"id":"opt_4","text":"Ia belum pernah tinggal di kota besar sebelumnya"}],"audio_text":"Have you ever lived in a cold climate before? — No, I grew up in Surabaya, so I''ve never experienced winter snow!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''ve never experienced winter snow'' menjelaskan pengalaman baru yang belum pernah ia alami sepanjang hidupnya.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000516', 'e4100001-0000-4000-8000-000000000063', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja di lobi gedung berikut. Di mana posisi Pak Direktur (Mr. Alvarez) sekarang?', '{"options":[{"id":"opt_1","text":"Beliau sedang rapat di ruang lantai tiga gedung ini"},{"id":"opt_2","text":"Beliau baru saja kembali dari cabang pusat kota"},{"id":"opt_3","text":"Beliau sedang pergi ke kantor cabang pusat kota dan baru kembali pukul empat"},{"id":"opt_4","text":"Beliau sedang cuti sakit di rumah hari ini"}],"audio_text":"Is Mr. Alvarez in his office right now? — No, he''s gone to the downtown branch, and he won''t be back until four."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Perhatikan ''he''s gone to the downtown branch'' (= he has gone): beliau sudah berangkat ke sana dan saat ini belum kembali.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000517', 'e4100001-0000-4000-8000-000000000063', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan pengalaman kerja berikut: "Pernahkah Anda memberikan presentasi dalam bahasa Inggris?"', '{"romaji":"/hæv juː ˈevər ˈɡɪvən ə ˌprezənˈteɪʃən ɪn ˈɪŋɡlɪʃ/","tokens":["gave","a presentation","ever given","in English?","Have you","Did you"],"target_translation":"Pernahkah Anda memberikan presentasi dalam bahasa Inggris?"}'::jsonb, '["Have you","ever given","a presentation","in English?"]'::jsonb, NULL, NULL, 'Pola pengalaman hidup: ''Have you ever + V3 (given)...?'' (V3 dari ''give'' adalah ''given'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000518', 'e4100001-0000-4000-8000-000000000063', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengalaman perjalanan ini: "Adik laki-laki saya belum pernah terbang ke luar negeri."', '{"romaji":"/maɪ ˈjʌŋɡər ˈbrʌðər hæz ˈnevər floʊn əˈbrɔːd/","tokens":["never flown","flew","brother has","My younger","have","abroad."],"target_translation":"Adik laki-laki saya belum pernah terbang ke luar negeri."}'::jsonb, '["My younger","brother has","never flown","abroad."]'::jsonb, NULL, NULL, 'Subjek tunggal ''My younger brother'' memakai ''has + never + V3'' (''fly'' -> ''flew'' -> ''flown'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000519', 'e4100001-0000-4000-8000-000000000063', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pengalaman akademik ini dengan lafal US been (/bɪn/): "Saya sudah pernah ke perpustakaan utama dua kali minggu ini."', '{"romaji":"/aɪv bɪn tə ðə meɪn ˈlaɪbreri twaɪs ðɪs wiːk/","display_text":"I''ve been to the main library twice this week.","phonetic_breakdown":["aɪv","bɪn","tə","ðə","meɪn","ˈlaɪ-brer-i","twaɪs","ðɪs","wiːk"]}'::jsonb, '{"expected_transcript":"I''ve been to the main library twice this week."}'::jsonb, NULL, NULL, 'Di American English, ''library'' melafalkan kedua bunyi ''r'' (/ˈlaɪbreri/) dan ''been'' dibaca pendek /bɪn/.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000520', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih penanda yang tepat di akhir kalimat negatif untuk arti ''belum'': Our designer hasn''t finalized the new logo ___.', '{"options":["yet","already","just","ever"],"translation":"Desainer kami belum merampungkan logo barunya.","sentence_template":"Our designer hasn''t finalized the new logo [blank]."}'::jsonb, '{"selected":"yet"}'::jsonb, NULL, NULL, 'Pada kalimat negatif (''hasn''t finalized''), gunakan ''yet'' di akhir kalimat untuk menyatakan ''belum''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000521', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih kata yang tepat untuk menyatakan tugas SUDAH beres lebih awal: Don''t worry about booking the room—I''ve ___ reserved Conference Room B.', '{"options":["already","yet","never","ever"],"translation":"Jangan khawatir soal pemesanan ruangan—saya sudah memesan Ruang Konferensi B.","sentence_template":"Don''t worry about booking the room—I''ve [blank] reserved Conference Room B."}'::jsonb, '{"selected":"already"}'::jsonb, NULL, NULL, '''Already'' disisipkan di antara ''have/has'' dan V3 (''I''ve already reserved'') untuk menegaskan sesuatu sudah beres.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000522', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat kabar yang BARU SAJA terjadi beberapa detik lalu: Look! The professor ___ posted our midterm grades on Canvas.', '{"options":["has just","have just","has yet","just has"],"translation":"Lihat! Profesor baru saja mengunggah nilai ujian tengah semester kita di Canvas.","sentence_template":"Look! The professor [blank] posted our midterm grades on Canvas."}'::jsonb, '{"selected":"has just"}'::jsonb, NULL, NULL, 'Subjek tunggal ''The professor'' memakai ''has'', diikuti ''just'' + V3 (''has just posted'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000523', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan percakapan singkat dua anggota tim produk ini. Apa status peninjauan kontrak vendor saat ini?', '{"options":[{"id":"opt_1","text":"Kevin sudah menandatangani kontraknya kemarin sore"},{"id":"opt_2","text":"Kevin belum meninjau kontraknya karena baru saja selesai menelepon klien, dan akan membacanya seusai makan siang"},{"id":"opt_3","text":"Kontrak vendor tersebut sudah dibatalkan oleh bagian hukum"},{"id":"opt_4","text":"Kevin menolak membaca kontrak tersebut"}],"audio_text":"Hey Kevin, have you reviewed the vendor contract yet? — Not yet, I''ve just finished my client call, so I''ll read it right after lunch."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Jawaban singkat ''Not yet'' (Belum) diikuti ''I''ve just finished...'' menjelaskan urutan progres kerja saat ini.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000524', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan pengumuman petugas gerbang keberangkatan (gate agent) di bandara Denver ini. Apa yang baru saja dimulai?', '{"options":[{"id":"opt_1","text":"Penerbangan 418 ke Seattle ditunda selama tiga jam"},{"id":"opt_2","text":"Penerbangan 418 baru saja memulai proses naik pesawat (boarding) di Gerbang C9"},{"id":"opt_3","text":"Gerbang keberangkatan dipindahkan ke Terminal A"},{"id":"opt_4","text":"Pesawat sudah lepas landas sepuluh menit lalu"}],"audio_text":"Good afternoon, passengers. Flight 418 to Seattle has just begun general boarding at Gate C9. Please have your boarding passes ready."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Has just begun general boarding'' (begun adalah V3 dari begin) menandakan proses boarding baru saja dibuka.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000525', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat laporan progres: "Saya belum menerima email konfirmasi itu."', '{"romaji":"/aɪ ˈhævənt rɪˈsiːvd ðæt ˌkɑːnfərˈmeɪʃən ˈiːmeɪl jet/","tokens":["I haven''t","that confirmation","received","email","receive","yet.","already."],"target_translation":"Saya belum menerima email konfirmasi itu."}'::jsonb, '["I haven''t","received","that confirmation","email","yet."]'::jsonb, NULL, NULL, 'Kerangka ''belum'': ''I haven''t + V3 (received) + objek + yet'' di paling belakang.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000526', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun pertanyaan pengecekan rekan satu tim: "Apakah Anda sudah mengunggah laporan anggarannya?"', '{"romaji":"/hæv juː ʌpˈloʊdɪd ðə ˈbʌdʒɪt rɪˈpɔːrt jet/","tokens":["upload","yet?","the budget","Have you","uploaded","report","Has you"],"target_translation":"Apakah Anda sudah mengunggah laporan anggarannya?"}'::jsonb, '["Have you","uploaded","the budget","report","yet?"]'::jsonb, NULL, NULL, 'Pertanyaan ''apakah sudah'' menggunakan ''Have you + V3 + ... + yet?''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000527', 'e4100001-0000-4000-8000-000000000064', 'e2000001-0000-4000-8000-000000000016', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembaruan cepat di kantor ini: "Kami baru saja mengirimkan proposal terbaru kepada klien."', '{"romaji":"/wiːv dʒʌst sent ði ʌpˈdeɪtɪd prəˈpoʊzəl tə ðə ˈklaɪənt/","display_text":"We''ve just sent the updated proposal to the client.","phonetic_breakdown":["wiːv","dʒʌst","sent","ði","ʌp-ˈdeɪ-tɪd","prə-ˈpoʊ-zəl","tə","ðə","ˈklaɪ-ənt"]}'::jsonb, '{"expected_transcript":"We''ve just sent the updated proposal to the client."}'::jsonb, NULL, NULL, 'Kontraksi ''We''ve'' (/wiːv/) membuat kalimat terdengar sigap dan alami dalam rapat tim.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000528', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih antara ''for'' dan ''since'' untuk titik tahun kalender ''2021'': Our startup has operated in Seattle ___ 2021.', '{"options":["since","for","from","in"],"translation":"Perusahaan rintisan kami telah beroperasi di Seattle sejak tahun 2021.","sentence_template":"Our startup has operated in Seattle [blank] 2021."}'::jsonb, '{"selected":"since"}'::jsonb, NULL, NULL, 'Tahun ''2021'' adalah titik awal waktu spesifik (starting point), sehingga wajib memakai ''since''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000529', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih preposisi durasi untuk rentang ''almost ten years'': Mr. Kim has taught computer science at this college ___ almost ten years.', '{"options":["for","since","during","ago"],"translation":"Pak Kim telah mengajar ilmu komputer di kampus ini selama hampir sepuluh tahun.","sentence_template":"Mr. Kim has taught computer science at this college [blank] almost ten years."}'::jsonb, '{"selected":"for"}'::jsonb, NULL, NULL, '''Almost ten years'' menunjukkan jumlah/panjang durasi waktu, sehingga memakai ''for'' (dan bukan ''ago'' karena beliau masih mengajar!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000530', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Ingat larangan Present Simple untuk kalimat berpenanda ''since'': I ___ my academic advisor since last September.', '{"options":["have known","know","am knowing","knew"],"translation":"Saya sudah mengenal pembimbing akademik saya sejak September lalu.","sentence_template":"I [blank] my academic advisor since last September."}'::jsonb, '{"selected":"have known"}'::jsonb, NULL, NULL, 'Hubungan yang dimulai September lalu dan masih berlangsung hingga kini memakai ''have + V3'' (''have known''; ''know'' adalah stative verb sehingga tidak boleh ''have been knowing'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000531', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan obrolan dua peserta konferensi di San Diego ini. Sudah berapa lama Maya bekerja sebagai peneliti UX?', '{"options":[{"id":"opt_1","text":"Baru dua minggu sejak lulus kuliah"},{"id":"opt_2","text":"Selama empat tahun, yakni sejak beralih dari desain grafis pada tahun 2022"},{"id":"opt_3","text":"Selama dua belas tahun di perusahaan perbankan"},{"id":"opt_4","text":"Ia belum pernah bekerja di bidang UX"}],"audio_text":"How long have you worked as a UX researcher, Maya? — Let''s see, I switched from graphic design four years ago, so I''ve been in UX since 2022."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan kontras jernih di kalimatnya: Past Simple untuk kejadian titik balik (''switched ... four years ago'') dan Present Perfect untuk kondisi yang berlanjut (''I''ve been in UX since 2022'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000532', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan keluhan pelanggan kepada teknisi internet berikut. Sejak kapan Wi-Fi di apartemennya mati?', '{"options":[{"id":"opt_1","text":"Baru mati lima menit sebelum menelepon"},{"id":"opt_2","text":"Mati sejak pukul tujuh pagi ini dan hingga kini belum menyala"},{"id":"opt_3","text":"Sudah mati selama tiga minggu penuh"},{"id":"opt_4","text":"Hanya melambat setiap tengah malam"}],"audio_text":"Hi, our apartment Wi-Fi has been down since seven o''clock this morning, and my roommate and I both work remotely."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Has been down since seven o''clock this morning'' menunjukkan gangguan dimulai jam 7 pagi dan masih mati saat menelepon.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000533', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun pertanyaan durasi tinggal: "Sudah berapa lama kamu tinggal di lingkungan ini?"', '{"romaji":"/haʊ lɔːŋ hæv juː lɪvd ɪn ðɪs ˈneɪbərhʊd/","tokens":["How long","do you","living","this neighborhood?","lived in","have you"],"target_translation":"Sudah berapa lama kamu tinggal di lingkungan ini?"}'::jsonb, '["How long","have you","lived in","this neighborhood?"]'::jsonb, NULL, NULL, 'Jangan gunakan ''How long do you live...''—selalu gunakan ''How long have you lived...?''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000534', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat kepemilikan berdurasi hingga kini: "Saya sudah memiliki sepeda ini selama tiga semester."', '{"romaji":"/aɪ hæv hæd ðɪs ˈbaɪsɪkəl fɔːr θriː sɪˈmestərz/","tokens":["since","has","three semesters.","had this","I have","bicycle for"],"target_translation":"Saya sudah memiliki sepeda ini selama tiga semester."}'::jsonb, '["I have","had this","bicycle for","three semesters."]'::jsonb, NULL, NULL, '''Have had'' = kata bantu Present Perfect ''have'' + V3 ''had'' (memiliki), diikuti ''for'' + rentang tiga semester.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000535', 'e4100001-0000-4000-8000-000000000065', 'e2000001-0000-4000-8000-000000000016', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan profesional ini dengan lancar: "Saya telah bekerja di bidang analitik data selama empat tahun."', '{"romaji":"/aɪv wɜːrkt ɪn ˈdeɪtə ˌænəˈlɪtɪks fɔːr fɔːr jɪrz/","display_text":"I''ve worked in data analytics for four years.","phonetic_breakdown":["aɪv","wɜːrkt","ɪn","ˈdeɪ-tə","ˌæn-ə-ˈlɪt-ɪks","fɔːr","fɔːr","jɪrz"]}'::jsonb, '{"expected_transcript":"I''ve worked in data analytics for four years."}'::jsonb, NULL, NULL, 'Pastikan ''worked'' diucapkan satu suku kata tegas /wɜːrkt/ diikuti ''for four years''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000536', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih kata bantu dan V3 yang tepat untuk subjek tunggal ''Clara'': Clara ___ three scholarship essays so far this month.', '{"options":["has written","have written","has wrote","wrote"],"translation":"Clara sudah menulis tiga esai beasiswa sejauh bulan ini.","sentence_template":"Clara [blank] three scholarship essays so far this month."}'::jsonb, '{"selected":"has written"}'::jsonb, NULL, NULL, 'Penanda ''so far this month'' (sejauh bulan ini—bulannya belum berakhir) membutuhkan Present Perfect tunggal ''has written''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000537', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih antara ''been'' dan ''gone'': Where is Bagas? — He''s ___ to the campus bookstore, but he''ll be back in ten minutes.', '{"options":["gone","been","went","going"],"translation":"Di mana Bagas? — Dia sedang pergi ke toko buku kampus, tapi akan kembali sepuluh menit lagi.","sentence_template":"Where is Bagas? — He''s [blank] to the campus bookstore, but he''ll be back in ten minutes."}'::jsonb, '{"selected":"gone"}'::jsonb, NULL, NULL, 'Karena Bagas saat ini tidak ada di tempat dan masih di perjalanan/toko buku, gunakan ''has gone to'' (''He''s gone to'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000538', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'reading', 'fill_blank', 'Pilih penanda waktu yang cocok untuk titik kejadian lampau sebagai awal durasi: We haven''t had an in-person team retreat ___ 2023.', '{"options":["since","for","yet","already"],"translation":"Kami belum pernah mengadakan retret tim tatap muka lagi sejak tahun 2023.","sentence_template":"We haven''t had an in-person team retreat [blank] 2023."}'::jsonb, '{"selected":"since"}'::jsonb, NULL, NULL, 'Tahun spesifik ''2023'' sebagai titik awal dipasangkan dengan ''since''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000539', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan percakapan dua mahasiswa di depan ruang laboratorium ini. Mengapa mereka belum masuk ke dalam lab?', '{"options":[{"id":"opt_1","text":"Karena kelas kimia hari ini dipindahkan ke perpustakaan"},{"id":"opt_2","text":"Karena asisten dosen (TA) belum datang sehingga pintu lab belum dibuka"},{"id":"opt_3","text":"Karena mereka lupa membawa jas laboratorium"},{"id":"opt_4","text":"Karena laboratorium sedang dicat ulang"}],"audio_text":"Have they unlocked the chemistry lab yet? — No, the teaching assistant hasn''t arrived yet, so everyone is waiting in the hallway."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di universitas AS, ''teaching assistant'' (TA) sering memegang kunci lab/kelas praktikum; ''hasn''t arrived yet'' berarti belum tiba.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000540', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'listening', 'listening_choice', 'Dengarkan wawancara singkat pelamar magang berikut. Pengalaman internasional apa yang sudah pernah ia jalani?', '{"options":[{"id":"opt_1","text":"Ia belum pernah bekerja sama dengan tim luar negeri"},{"id":"opt_2","text":"Ia pernah berkolaborasi dengan pengembang di Singapura dan Austin pada dua proyek sumber terbuka (open-source)"},{"id":"opt_3","text":"Ia tinggal di Singapura selama sepuluh tahun"},{"id":"opt_4","text":"Ia baru akan memulai proyek pertamanya bulan depan"}],"audio_text":"Have you ever collaborated with an overseas team? — Yes, I''ve worked with developers in Singapore and Austin on two open-source projects."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''ve worked with developers in Singapore and Austin...'' merangkum pengalaman relevan kandidat tanpa perlu menyebut tanggal.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000541', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat konfirmasi pembayaran: "Saya sudah membayar uang sewa bulan ini."', '{"romaji":"/aɪv ɔːlˈredi peɪd ðɪs mʌnθs rent/","tokens":["I''ve already","yet.","payed","this month''s","paid","rent."],"target_translation":"Saya sudah membayar uang sewa bulan ini."}'::jsonb, '["I''ve already","paid","this month''s","rent."]'::jsonb, NULL, NULL, 'Hati-hati ejaan V3 dari ''pay'' adalah ''paid'' (bukan ''payed''!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000542', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'writing', 'sentence_builder', 'Susun pertanyaan pengecekan dokumen: "Apakah kamu sudah memeriksa komentar dosen di esaimu?"', '{"romaji":"/hæv juː tʃekt ðə prəˈfesərz ˈkɑːments ɑːn jʊr ˈeseɪ jet/","tokens":["professor''s comments","on your essay","already?","checked the","Have you","yet?","check"],"target_translation":"Apakah kamu sudah memeriksa komentar dosen di esaimu?"}'::jsonb, '["Have you","checked the","professor''s comments","on your essay","yet?"]'::jsonb, NULL, NULL, 'Gunakan ''Have you + V3 (checked) ... + yet?'' untuk menanyakan progres penyelesaian.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000543', 'e4100001-0000-4000-8000-000000000066', 'e2000001-0000-4000-8000-000000000016', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pengalaman dan durasi ini dengan jelas: "Kami sudah saling mengenal sejak tahun pertama kuliah."', '{"romaji":"/wiːv noʊn iːtʃ ˈʌðər sɪns ˈaʊər ˈfreʃmən jɪr/","display_text":"We''ve known each other since our freshman year.","phonetic_breakdown":["wiːv","noʊn","iːtʃ","ˈʌð-ər","sɪns","ˈaʊ-ər","ˈfreʃ-mən","jɪr"]}'::jsonb, '{"expected_transcript":"We''ve known each other since our freshman year."}'::jsonb, NULL, NULL, 'Huruf ''k'' di awal ''known'' tidak diucapkan (silent k: /noʊn/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000544', 'e4100001-0000-4000-8000-000000000067', NULL, 'reading', 'fill_blank', 'Pilih bentuk kewajiban yang tepat untuk subjek tunggal ''Every intern'': Every intern ___ complete the cybersecurity training this week.', '{"options":["has to","have to","must to","having to"],"translation":"Setiap peserta magang wajib menyelesaikan pelatihan keamanan siber minggu ini.","sentence_template":"Every intern [blank] complete the cybersecurity training this week."}'::jsonb, '{"selected":"has to"}'::jsonb, NULL, NULL, 'Kata ''Every + kata benda tunggal'' selalu dihitung TUNGGAL, sehingga memakai ''has to + V1'' (dan ''must'' tidak boleh diikuti ''to'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000545', 'e4100001-0000-4000-8000-000000000067', NULL, 'reading', 'fill_blank', 'Pilih bentuk kewajiban LAMPAU untuk kalimat dengan penanda ''last night'': Our server crashed last night, so the DevOps engineer ___ fix it at midnight.', '{"options":["had to","must","has to","have to"],"translation":"Server kami tumbang tadi malam, sehingga insinyur DevOps harus memperbaikinya tengah malam.","sentence_template":"Our server crashed last night, so the DevOps engineer [blank] fix it at midnight."}'::jsonb, '{"selected":"had to"}'::jsonb, NULL, NULL, 'Kewajiban yang terjadi di masa lampau (''last night'') wajib menggunakan bentuk lampau ''had to + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000546', 'e4100001-0000-4000-8000-000000000067', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan tentang aturan berpakaian kantor: ___ employees have to scan their ID badges at the elevator?', '{"options":["Do","Are","Must","Have"],"translation":"Apakah karyawan wajib memindai kartu identitas mereka di lift?","sentence_template":"[blank] employees have to scan their ID badges at the elevator?"}'::jsonb, '{"selected":"Do"}'::jsonb, NULL, NULL, 'Pertanyaan dengan ''have to'' dibentuk menggunakan kata bantu ''Do/Does + Subject + have to + V1?''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000547', 'e4100001-0000-4000-8000-000000000067', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan staf kantor mahasiswa internasional (ISSO) ini. Apa yang wajib dilaporkan mahasiswa pemegang visa F-1 dalam sepuluh hari?', '{"options":[{"id":"opt_1","text":"Mengganti paspor di kedutaan setiap semester"},{"id":"opt_2","text":"Memperbarui alamat tinggal lokal AS di portal mahasiswa dalam waktu sepuluh hari setelah pindah apartemen"},{"id":"opt_3","text":"Membeli mobil pribadi sebelum semester dimulai"},{"id":"opt_4","text":"Membayar uang sewa satu tahun penuh di muka"}],"audio_text":"Remember, if you move to a new apartment, you have to update your local US address in the student portal within ten days."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Aturan nyata imigrasi kampus AS: pemegang visa pelajar F-1 wajib memperbarui alamat (''have to update your local US address'') maksimal 10 hari setelah pindah.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000548', 'e4100001-0000-4000-8000-000000000067', NULL, 'listening', 'listening_choice', 'Dengarkan alasan rekan kerja yang baru bergabung ke rapat daring berikut. Mengapa ia terlambat lima menit?', '{"options":[{"id":"opt_1","text":"Ia ketiduran setelah makan siang"},{"id":"opt_2","text":"Laptopnya memuat ulang otomatis sehingga tadi ia harus memasang pembaruan sistem terlebih dahulu"},{"id":"opt_3","text":"Ia salah masuk ke gedung kantor cabang"},{"id":"opt_4","text":"Tautan rapatnya belum dikirim oleh manajer"}],"audio_text":"Sorry for joining five minutes late, everyone—my laptop restarted automatically, and I had to install a system update."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I had to install a system update'' menjelaskan keharusan tak terduga yang baru saja terjadi beberapa menit lalu.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000549', 'e4100001-0000-4000-8000-000000000067', NULL, 'writing', 'sentence_builder', 'Susun kalimat peraturan tertulis laboratorium: "Semua pengunjung wajib mengenakan kacamata pelindung di dalam lab."', '{"romaji":"/ɔːl ˈvɪzɪtərz mʌst wer ˈseɪfti ˈɡlæsɪz ɪnˈsaɪd ðə læb/","tokens":["safety glasses","wears","must to","All visitors","must wear","the lab.","inside"],"target_translation":"Semua pengunjung wajib mengenakan kacamata pelindung di dalam lab."}'::jsonb, '["All visitors","must wear","safety glasses","inside","the lab."]'::jsonb, NULL, NULL, 'Aturan keselamatan resmi memakai ''must + V1 murni'' (''must wear'', tanpa ''to'' dan tanpa ''-s'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000550', 'e4100001-0000-4000-8000-000000000067', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan kewajiban administrasi: "Apakah dia harus menyerahkan salinan cetak hari ini?"', '{"romaji":"/dʌz ʃiː ˈhæf tə səbˈmɪt ə hɑːrd ˈkɑːpi təˈdeɪ/","tokens":["today?","has to","Must she to","hard copy","submit a","have to","Does she"],"target_translation":"Apakah dia harus menyerahkan salinan cetak hari ini?"}'::jsonb, '["Does she","have to","submit a","hard copy","today?"]'::jsonb, NULL, NULL, 'Setelah kata bantu ''Does'', bentuk ''has to'' kembali ke dasar ''have to'' (''Does she have to submit...?'', ''hard copy'' = dokumen cetak fisik).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000551', 'e4100001-0000-4000-8000-000000000067', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat kewajiban harian ini dengan asimilasi alami /ˈhæf tə/: "Saya harus berangkat pukul tujuh untuk mengejar kereta pertama."', '{"romaji":"/aɪ ˈhæf tə liːv æt ˈsevən tə kætʃ ðə fɜːrst treɪn/","display_text":"I have to leave at seven to catch the first train.","phonetic_breakdown":["aɪ","ˈhæf","tə","liːv","æt","ˈsev-ən","tə","kætʃ","ðə","fɜːrst","treɪn"]}'::jsonb, '{"expected_transcript":"I have to leave at seven to catch the first train."}'::jsonb, NULL, NULL, 'Lafalkan ''have to'' menyatu ringan sebagai /ˈhæf tə/ seperti penutur asli Amerika!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000552', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kegiatan OPSIONAL (gratis/tidak perlu bayar): Admission to the museum is free for students, so you ___ buy a ticket.', '{"options":["don''t have to","must not","hasn''t to","cannot to"],"translation":"Tiket masuk museum gratis bagi mahasiswa, jadi kamu tidak perlu membeli tiket.","sentence_template":"Admission to the museum is free for students, so you [blank] buy a ticket."}'::jsonb, '{"selected":"don''t have to"}'::jsonb, NULL, NULL, 'Karena gratis (tidak perlu membayar, bukan larangan hukum), gunakan ''don''t have to''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000553', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih bentuk untuk LARANGAN KERAS demi keamanan: Passengers ___ leave their luggage unattended at the airport at any time.', '{"options":["must not","don''t have to","doesn''t have to","not have to"],"translation":"Penumpang dilarang keras meninggalkan bagasi tanpa pengawasan di bandara kapan pun.","sentence_template":"Passengers [blank] leave their luggage unattended at the airport at any time."}'::jsonb, '{"selected":"must not"}'::jsonb, NULL, NULL, 'Meninggalkan koper tanpa pengawasan adalah pelanggaran keamanan serius di bandara AS, sehingga wajib memakai ''must not''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000554', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih bentuk ketidakwajiban untuk subjek tunggal ''Rina'': Since tomorrow''s town hall is recorded, Rina ___ attend live at midnight Jakarta time.', '{"options":["doesn''t have to","don''t have to","must not","isn''t have to"],"translation":"Karena rapat akbar besok direkam, Rina tidak harus hadir secara langsung tengah malam waktu Jakarta.","sentence_template":"Since tomorrow''s town hall is recorded, Rina [blank] attend live at midnight Jakarta time."}'::jsonb, '{"selected":"doesn''t have to"}'::jsonb, NULL, NULL, 'Subjek tunggal ''Rina'' memakai ''doesn''t have to + V1'' untuk menyatakan sesuatu bersifat tidak wajib (opsional).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000555', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan penjelasan HRD saat orientasi karyawan baru di perusahaan hibrida ini. Apa aturan kehadiran pada hari Jumat?', '{"options":[{"id":"opt_1","text":"Gedung kantor dikunci rapat dan karyawan dilarang masuk pada hari Jumat"},{"id":"opt_2","text":"Senin–Rabu wajib ke kantor, sedangkan Kamis–Jumat tidak wajib datang ke kantor karena boleh bekerja dari rumah"},{"id":"opt_3","text":"Semua karyawan wajib masuk kantor tujuh hari seminggu"},{"id":"opt_4","text":"Hari Jumat adalah hari libur nasional tanpa jam kerja"}],"audio_text":"From Monday through Wednesday, working from the office is mandatory, but on Thursdays and Fridays you don''t have to come in—you can work from home."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Mandatory'' (wajib) dikontraskan dengan ''you don''t have to come in'' (tidak wajib ke kantor, bebas memilih WFH).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000556', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan peringatan pengawas ujian TOEFL di ruang tes berikut. Apa yang dilarang dilakukan peserta selama waktu istirahat?', '{"options":[{"id":"opt_1","text":"Peserta tidak perlu minum air putih saat istirahat"},{"id":"opt_2","text":"Peserta dilarang menyalakan ponsel atau membuka catatan belajar selama istirahat sepuluh menit"},{"id":"opt_3","text":"Peserta wajib keluar dari gedung ujian selama satu jam"},{"id":"opt_4","text":"Peserta boleh menelepon keluarga dari ruang tunggu"}],"audio_text":"During the ten-minute break, you may drink water in the lobby, but you must not turn on your cell phone or open your study notes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''You must not turn on your cell phone or open your study notes'' adalah larangan tegas yang bisa membatalkan skor ujian.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000557', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat penjelasan fleksibilitas berpakaian: "Kita tidak perlu memakai jas untuk rapat tim internal."', '{"romaji":"/wiː doʊnt ˈhæf tə wer ə suːt fɔːr ɪnˈtɜːrnəl tiːm ˈmiːtɪŋz/","tokens":["must not","have to","has to","wear a suit","team meetings.","for internal","We don''t"],"target_translation":"Kita tidak perlu memakai jas untuk rapat tim internal."}'::jsonb, '["We don''t","have to","wear a suit","for internal","team meetings."]'::jsonb, NULL, NULL, '''Don''t have to wear a suit'' = tidak diwajibkan memakai setelan jas.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000558', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat larangan kerahasiaan proyek: "Anda dilarang membagikan berkas klien ini ke luar perusahaan."', '{"romaji":"/juː mʌst nɑːt ʃer ðɪs ˈklaɪənt faɪl ˌaʊtˈsaɪd ðə ˈkʌmpəni/","tokens":["don''t have","the company.","this client file","You must","not share","outside","to share"],"target_translation":"Anda dilarang membagikan berkas klien ini ke luar perusahaan."}'::jsonb, '["You must","not share","this client file","outside","the company."]'::jsonb, NULL, NULL, 'Larangan keamanan data memakai ''must not + V1'' (''must not share'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000559', 'e4100001-0000-4000-8000-000000000068', 'e2000001-0000-4000-8000-000000000017', 'speaking', 'speaking_repeat', 'Ucapkan kalimat melegakan rekan kerja ini dengan ramah: "Kamu tidak perlu membalas email di akhir pekan."', '{"romaji":"/juː doʊnt ˈhæf tə rɪˈplaɪ tə ˈiːmeɪlz ˈoʊvər ðə ˈwiːkend/","display_text":"You don''t have to reply to emails over the weekend.","phonetic_breakdown":["juː","doʊnt","ˈhæf","tə","rɪ-ˈplaɪ","tə","ˈiː-meɪlz","ˈoʊ-vər","ðə","ˈwiːk-end"]}'::jsonb, '{"expected_transcript":"You don''t have to reply to emails over the weekend."}'::jsonb, NULL, NULL, 'Perhatikan kolokasi ''reply TO emails'' (memakai ''to'') dan frasa khas AS ''over the weekend''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000560', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih saran yang tepat setelah modal ''should'': Before moving to Chicago for winter quarter, Raka ___ invest in a waterproof winter coat.', '{"options":["should","should to","shoulds","have"],"translation":"Sebelum pindah ke Chicago untuk kuartal musim dingin, Raka sebaiknya membeli mantel musim dingin tahan air.","sentence_template":"Before moving to Chicago for winter quarter, Raka [blank] invest in a waterproof winter coat."}'::jsonb, '{"selected":"should"}'::jsonb, NULL, NULL, 'Modal ''should'' berlaku sama untuk semua subjek dan langsung diikuti V1 (''should invest'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000561', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih pola saran negatif diplomatis khas penutur asli AS: ___ you should take five heavy lab courses in your very first semester.', '{"options":["I don''t think","I not think","Don''t I think","I doesn''t think"],"translation":"Menurut saya sebaiknya kamu tidak mengambil lima mata kuliah praktikum berat sekaligus di semester pertamamu.","sentence_template":"[blank] you should take five heavy lab courses in your very first semester."}'::jsonb, '{"selected":"I don''t think"}'::jsonb, NULL, NULL, '''I don''t think you should + V1'' adalah cara paling alami dan santun untuk menyarankan agar seseorang tidak melakukan sesuatu.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000562', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Lengkapi pertanyaan meminta saran jadwal keberangkatan: What time ___ we head to the airport for an international flight?', '{"options":["should","have","must to","are"],"translation":"Jam berapa sebaiknya kita berangkat ke bandara untuk penerbangan internasional?","sentence_template":"What time [blank] we head to the airport for an international flight?"}'::jsonb, '{"selected":"should"}'::jsonb, NULL, NULL, '''What time should we + V1?'' menanyakan waktu terbaik/rekomendasi.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000563', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan saran penasihat karier kampus (career advisor) kepada mahasiswa yang akan wawancara kerja ini. Apa yang sebaiknya dilakukan mahasiswa malam ini?', '{"options":[{"id":"opt_1","text":"Menghafal jawaban sampai pukul tiga dini hari tanpa tidur"},{"id":"opt_2","text":"Menyiapkan dua pertanyaan berbobot untuk pewawancara dan sebaiknya tidak begadang terlalu larut"},{"id":"opt_3","text":"Membatalkan wawancara dan meminta jadwal bulan depan"},{"id":"opt_4","text":"Tidak perlu menanyakan apa pun di akhir wawancara"}],"audio_text":"For tomorrow''s panel interview, you should prepare two thoughtful questions to ask the hiring manager at the end, and you shouldn''t stay up too late rehearsing."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di wawancara kerja AS, kandidat sangat disarankan mengajukan pertanyaan cerdas di sesi akhir (''prepare two thoughtful questions'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000564', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan diskusi dua insinyur perangkat lunak tentang pembaruan basis data berikut. Mengapa pembicara wanita menyarankan menunggu sampai Senin pagi?', '{"options":[{"id":"opt_1","text":"Karena server sedang dimatikan total hari ini"},{"id":"opt_2","text":"Karena tidak bijak menjalankan migrasi pukul 16.30 Jumat sore; lebih aman Senin pagi saat tim lengkap"},{"id":"opt_3","text":"Karena manajer melarang semua pembaruan selamanya"},{"id":"opt_4","text":"Karena hari Senin adalah hari libur nasional"}],"audio_text":"Should we run the database migration right now? — Honestly, I don''t think we should do it at 4:30 p.m. on a Friday; let''s wait until Monday morning when the full team is online."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I don''t think we should do it at 4:30 p.m. on a Friday'' memberikan alasan mitigasi risiko teknis yang sangat lazim di industri teknologi.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000565', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat meminta masukan mentor: "Menurut Anda kursus pilihan mana yang sebaiknya saya ambil?"', '{"romaji":"/wɪtʃ ɪˈlektɪv kɔːrs duː juː θɪŋk aɪ ʃʊd teɪk/","tokens":["I should","you think","should I","course do","taking?","take?","Which elective"],"target_translation":"Menurut Anda kursus pilihan mana yang sebaiknya saya ambil?"}'::jsonb, '["Which elective","course do","you think","I should","take?"]'::jsonb, NULL, NULL, 'Perhatikan susunan setelah ''do you think'': subjek dulu baru ''should'' (''...do you think I should take?'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000566', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat saran keamanan akun: "Sebaiknya kamu tidak memakai kata sandi yang sama di setiap situs."', '{"romaji":"/juː ˈʃʊdənt juːz ðə seɪm ˈpæswɜːrd ɑːn ˈevri ˈwebsaɪt/","tokens":["same password","You shouldn''t","passwords","to use","website.","on every","use the"],"target_translation":"Sebaiknya kamu tidak memakai kata sandi yang sama di setiap situs."}'::jsonb, '["You shouldn''t","use the","same password","on every","website."]'::jsonb, NULL, NULL, '''Shouldn''t + V1 (use)'' menyampaikan saran pencegahan secara jelas.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000567', 'e4100001-0000-4000-8000-000000000069', 'e2000001-0000-4000-8000-000000000017', 'speaking', 'speaking_repeat', 'Ucapkan kalimat saran akademik ini tanpa membunyikan huruf l pada should (/ʃʊd/): "Menurut saya sebaiknya kamu mengunjungi jam konsultasi dosen minggu ini."', '{"romaji":"/aɪ θɪŋk juː ʃʊd stɑːp baɪ ðə prəˈfesərz ˈɔːfɪs ˈaʊərz ðɪs wiːk/","display_text":"I think you should stop by the professor''s office hours this week.","phonetic_breakdown":["aɪ","θɪŋk","juː","ʃʊd","stɑːp","baɪ","ðə","prə-ˈfe-sərz","ˈɔː-fɪs","ˈaʊ-ərz","ðɪs","wiːk"]}'::jsonb, '{"expected_transcript":"I think you should stop by the professor''s office hours this week."}'::jsonb, NULL, NULL, '''Stop by'' berarti mampir sebentar, dan ''office hours'' adalah waktu resmi dosen menerima konsultasi mahasiswa.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000568', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Bedakan ketidakwajiban vs larangan: Because I already passed the placement exam, I ___ take the introductory course.', '{"options":["don''t have to","must not","doesn''t have to","shouldn''t to"],"translation":"Karena saya sudah lulus ujian penempatan, saya tidak perlu mengambil mata kuliah pengantar tersebut.","sentence_template":"Because I already passed the placement exam, I [blank] take the introductory course."}'::jsonb, '{"selected":"don''t have to"}'::jsonb, NULL, NULL, 'Dibebaskan dari syarat mata kuliah dasar berarti tidak wajib (''don''t have to''), bukan larangan.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000569', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih modal untuk larangan keras di laboratorium rumah sakit: Unauthorized staff ___ enter the MRI room when the magnet is active.', '{"options":["must not","don''t have to","haven''t to","not should"],"translation":"Staf yang tidak berwenang dilarang keras memasuki ruang MRI saat magnet aktif.","sentence_template":"Unauthorized staff [blank] enter the MRI room when the magnet is active."}'::jsonb, '{"selected":"must not"}'::jsonb, NULL, NULL, 'Larangan keselamatan medis wajib memakai ''must not + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000570', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'reading', 'fill_blank', 'Pilih bentuk kewajiban masa lampau: My flight from Seattle was delayed, so I ___ rebook my connecting train.', '{"options":["had to","must","have to","has to"],"translation":"Penerbangan saya dari Seattle tertunda, sehingga saya harus memesan ulang kereta lanjutan saya.","sentence_template":"My flight from Seattle was delayed, so I [blank] rebook my connecting train."}'::jsonb, '{"selected":"had to"}'::jsonb, NULL, NULL, 'Konteks masa lampau (''was delayed'') mewajibkan bentuk lampau ''had to + V1''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000571', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan penjelasan pustakawan kampus kepada mahasiswa baru ini. Kapan mahasiswa harus membayar denda keterlambatan buku?', '{"options":[{"id":"opt_1","text":"Setiap peminjam buku wajib membayar biaya sewa harian sejak hari pertama"},{"id":"opt_2","text":"Mahasiswa tidak perlu membayar denda keterlambatan selama memperpanjang masa pinjam secara daring sebelum tanggal jatuh tempo"},{"id":"opt_3","text":"Buku teks perpustakaan dilarang dibawa pulang ke asrama"},{"id":"opt_4","text":"Masa pinjam buku hanya berlaku dua puluh empat jam"}],"audio_text":"You can keep borrowed textbooks for three weeks, and you don''t have to pay any late fees as long as you renew them online before the due date."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''You don''t have to pay any late fees as long as...'' menjelaskan syarat bebas denda.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000572', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'listening', 'listening_choice', 'Dengarkan percakapan rekan sekamar tentang gejala flu ini. Apa saran pembicara pria?', '{"options":[{"id":"opt_1","text":"Tetap berolahraga berat di pusat kebugaran malam ini"},{"id":"opt_2","text":"Sebaiknya tidak pergi ke gym yang ramai malam ini, melainkan beristirahat dan minum teh hangat"},{"id":"opt_3","text":"Minum es kopi tiga gelas sebelum tidur"},{"id":"opt_4","text":"Pergi berlari maraton besok pagi"}],"audio_text":"My throat feels really scratchy and I have a mild fever. — Oh no, you shouldn''t go to the crowded gym tonight; you should rest and drink warm tea."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kombinasi ''you shouldn''t go...'' dan ''you should rest...'' memberikan nasihat peduli kepada teman.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000573', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun pertanyaan klarifikasi aturan magang: "Apakah peserta magang harus menyerahkan laporan mingguan setiap Jumat?"', '{"romaji":"/duː ˈɪntɜːrnz ˈhæf tə səbˈmɪt ə ˈwiːkli rɪˈpɔːrt ˈevri ˈfraɪdeɪ/","tokens":["Does interns","has to","have to","every Friday?","submit a","weekly report","Do interns"],"target_translation":"Apakah peserta magang harus menyerahkan laporan mingguan setiap Jumat?"}'::jsonb, '["Do interns","have to","submit a","weekly report","every Friday?"]'::jsonb, NULL, NULL, 'Subjek jamak ''interns'' memakai ''Do ... have to + V1?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000574', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat saran persiapan visa: "Sebaiknya Anda menjadwalkan wawancara visa Anda jauh-jauh hari."', '{"romaji":"/juː ʃʊd ˈskedʒuːl jʊr ˈviːzə ˈɪntərvjuː wel ɪn ədˈvæns/","tokens":["You should","schedules","advance.","well in","schedule your","should to","visa interview"],"target_translation":"Sebaiknya Anda menjadwalkan wawancara visa Anda jauh-jauh hari."}'::jsonb, '["You should","schedule your","visa interview","well in","advance."]'::jsonb, NULL, NULL, 'Idiom ''well in advance'' berarti jauh-jauh hari sebelum tenggat waktu.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000575', 'e4100001-0000-4000-8000-000000000070', 'e2000001-0000-4000-8000-000000000017', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penjelasan aturan dan fleksibilitas ini dengan jelas: "Kamu wajib mendaftar terlebih dahulu, tetapi acaranya gratis."', '{"romaji":"/juː ˈhæf tə ˈredʒɪstər ɪn ədˈvæns, bʌt ði ɪˈvent ɪz friː/","display_text":"You have to register in advance, but the event is free.","phonetic_breakdown":["juː","ˈhæf","tə","ˈredʒ-ɪ-stər","ɪn","əd-ˈvæns","bʌt","ði","ɪ-ˈvent","ɪz","friː"]}'::jsonb, '{"expected_transcript":"You have to register in advance, but the event is free."}'::jsonb, NULL, NULL, 'Perhatikan lafal ''in advance'' (/ɪn ədˈvæns/) = terlebih dahulu.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000576', 'e4100001-0000-4000-8000-000000000071', NULL, 'reading', 'fill_blank', 'Pilih modal permintaan sopan untuk email kepada manajer lintas divisi: Hi Elena, ___ you grant me view access to the Q4 roadmap when you get a chance?', '{"options":["could","may","should","must"],"translation":"Hai Elena, bisakah Anda memberi saya akses lihat ke peta jalan Kuartal 4 saat Anda ada waktu luang?","sentence_template":"Hi Elena, [blank] you grant me view access to the Q4 roadmap when you get a chance?"}'::jsonb, '{"selected":"could"}'::jsonb, NULL, NULL, '''Could you + V1...?'' dipakai untuk meminta orang lain melakukan sesuatu (''May'' tidak pernah dipasangkan dengan ''you'' dalam permintaan: bukan ''May you''!).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000577', 'e4100001-0000-4000-8000-000000000071', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat saat meminta izin untuk DIRI SENDIRI di sela presentasi: Excuse me, ___ ask a quick clarifying question about slide three?', '{"options":["may I","could you","would you","may you"],"translation":"Permisi, bolehkah saya mengajukan satu pertanyaan klarifikasi singkat tentang salindia tiga?","sentence_template":"Excuse me, [blank] ask a quick clarifying question about slide three?"}'::jsonb, '{"selected":"may I"}'::jsonb, NULL, NULL, 'Meminta izin melakukan sesuatu sendiri memakai ''May I + V1?'' atau ''Could I + V1?''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000578', 'e4100001-0000-4000-8000-000000000071', NULL, 'reading', 'fill_blank', 'Pilih respons mengiyakan yang paling alami di kantor AS ketika rekan bertanya ''Could you send me the PDF?'': ___! I''ll Slack it to you right now.', '{"options":["Sure thing","Yes, I could","No, I couldn''t","You may"],"translation":"Tentu saja! Saya kirim lewat Slack sekarang juga.","sentence_template":"[blank]! I''ll Slack it to you right now."}'::jsonb, '{"selected":"Sure thing"}'::jsonb, NULL, NULL, 'Di AS, respons positif alami untuk ''Could you...?'' adalah ''Sure!'', ''Sure thing!'', atau ''Of course!'' (bukan ''Yes, I could'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000579', 'e4100001-0000-4000-8000-000000000071', NULL, 'listening', 'listening_choice', 'Dengarkan pesan suara rekan satu tim di Slack berikut. Bantuan apa yang ia minta?', '{"options":[{"id":"opt_1","text":"Menghapus seluruh tabel anggaran tahunan sekarang juga"},{"id":"opt_2","text":"Mengecek ulang rumus konversi mata uang di tab dua sebelum besok pagi saat senggang"},{"id":"opt_3","text":"Menukarkan uang tunai dolar di bandara sore ini"},{"id":"opt_4","text":"Mempresentasikan laporan keuangan kepada dewan direksi"}],"audio_text":"Hey Dimas, could you double-check the currency conversion formulas on tab two when you get a chance? No rush—anytime before tomorrow morning works!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan betapa santunnya kolaborasi ala AS: ''could you double-check...'' diperhalus dengan ''when you get a chance'' dan ''No rush''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000580', 'e4100001-0000-4000-8000-000000000071', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan mahasiswa dengan staf administrasi jurusan ini. Izin apa yang diminta mahasiswa?', '{"options":[{"id":"opt_1","text":"Meminjam kunci mobil pribadi Profesor Miller"},{"id":"opt_2","text":"Menitipkan formulir yang sudah ditandatangani ke kotak surat Profesor Miller karena beliau sedang seminar"},{"id":"opt_3","text":"Membatalkan mata kuliah Profesor Miller semester ini"},{"id":"opt_4","text":"Menggunakan ruang kerja Profesor Miller untuk rapat"}],"audio_text":"Good morning! Could I leave this signed form in Professor Miller''s mailbox since he''s in a seminar right now?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Could I leave this signed form in Professor Miller''s mailbox...?'' meminta izin secara sopan kepada staf departemen.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000581', 'e4100001-0000-4000-8000-000000000071', NULL, 'writing', 'sentence_builder', 'Susun kalimat permintaan halus di rapat daring: "Bisakah Anda memperbesar tampilan tabelnya sedikit?"', '{"romaji":"/ˈkʊdʒuː zuːm ɪn ɑːn ðə ˈteɪbəl ə ˈlɪtəl bɪt/","tokens":["on the table","a little","May you","zooming","zoom in","Could you","bit?"],"target_translation":"Bisakah Anda memperbesar tampilan tabelnya sedikit?"}'::jsonb, '["Could you","zoom in","on the table","a little","bit?"]'::jsonb, NULL, NULL, '''Zoom in on [something]'' = memperbesar tampilan layar, diperhalus dengan ''a little bit''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000582', 'e4100001-0000-4000-8000-000000000071', NULL, 'writing', 'sentence_builder', 'Susun kalimat meminta izin pulang lebih awal karena janji dokter: "Bolehkah saya pulang tiga puluh menit lebih awal hari ini?"', '{"romaji":"/kʊd aɪ hed aʊt ˈθɜːrti ˈmɪnɪts ˈɜːrli təˈdeɪ/","tokens":["head out","thirty minutes","Could I","heads","Could you","early","today?"],"target_translation":"Bolehkah saya pulang tiga puluh menit lebih awal hari ini?"}'::jsonb, '["Could I","head out","thirty minutes","early","today?"]'::jsonb, NULL, NULL, 'Phrasal verb ''head out'' sangat lazim dipakai di kantor AS untuk pamit berangkat/pulang secara santun.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000583', 'e4100001-0000-4000-8000-000000000071', NULL, 'speaking', 'speaking_repeat', 'Ucapkan permintaan email lisan ini dengan tautan alami /ˈkʊdʒuː/: "Bisakah Anda meninjau draf saya saat Anda punya waktu luang?"', '{"romaji":"/ˈkʊdʒuː lʊk ˈoʊvər maɪ dræft wen juː ɡet ə tʃæns/","display_text":"Could you look over my draft when you get a chance?","phonetic_breakdown":["ˈkʊdʒ-uː","lʊk","ˈoʊ-vər","maɪ","dræft","wen","juː","ɡet","ə","tʃæns"]}'::jsonb, '{"expected_transcript":"Could you look over my draft when you get a chance?"}'::jsonb, NULL, NULL, '''Look over'' berarti memeriksa/membaca sekilas untuk memberi masukan.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000584', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Ingat bentuk kata kerja wajib tepat setelah ''Would you mind'': Would you mind ___ the AC temperature up a little? It''s freezing in here.', '{"options":["turning","to turn","turn","turned"],"translation":"Apakah Anda keberatan menaikkan suhu AC sedikit? Di sini dingin sekali.","sentence_template":"Would you mind [blank] the AC temperature up a little? It''s freezing in here."}'::jsonb, '{"selected":"turning"}'::jsonb, NULL, NULL, 'Setelah frasa ''Would you mind'', kata kerja wajib berbentuk Gerund (-ing): ''turning''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000585', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih respons yang tepat jika Anda MENGIZINKAN rekan duduk di kursi kosong sebelah Anda saat ditanya ''Would you mind if I sat here?'': ___! Please, have a seat.', '{"options":["Not at all","Yes, I mind","Yes, I would","Never"],"translation":"Tidak keberatan sama sekali! Silakan duduk.","sentence_template":"[blank]! Please, have a seat."}'::jsonb, '{"selected":"Not at all"}'::jsonb, NULL, NULL, 'Karena ''mind'' berarti ''keberatan'', untuk memberi izin kita menjawab ''Not at all!'' (= saya tidak keberatan sama sekali).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000586', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih bentuk kata kerja halus setelah ''Would you mind if I...'': Would you mind if I ___ a photo of the whiteboard notes?', '{"options":["took","taking","to take","taken"],"translation":"Apakah Anda keberatan jika saya memotret catatan di papan tulis ini?","sentence_template":"Would you mind if I [blank] a photo of the whiteboard notes?"}'::jsonb, '{"selected":"took"}'::jsonb, NULL, NULL, 'Dalam tata bahasa standar dan TOEFL, ''Would you mind if I...'' diikuti Past Simple (''took'') agar selaras dengan ''Would''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000587', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan percakapan dua penumpang di kereta Amtrak dari New York ke Boston ini. Apakah penumpang wanita bersedia bertukar kursi?', '{"options":[{"id":"opt_1","text":"Ia menolak keras karena ingin duduk dekat jendela"},{"id":"opt_2","text":"Ia bersedia dengan senang hati bertukar kursi karena justru lebih menyukai kursi lorong (aisle seat)"},{"id":"opt_3","text":"Ia meminta petugas kereta memindahkan penumpang pria ke gerbong lain"},{"id":"opt_4","text":"Kursi tersebut sudah dipesan oleh penumpang ketiga"}],"audio_text":"Excuse me, would you mind switching seats so I can sit next to my daughter? — Oh, not at all! I actually prefer the aisle seat anyway."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Respons ''Oh, not at all!'' membuktikan ia sama sekali tidak keberatan dan langsung menyetujui permintaan tersebut.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000588', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan obrolan penjadwalan ulang di kantor berikut. Jam berapa rapat mereka akhirnya dimulai?', '{"options":[{"id":"opt_1","text":"Dimajukan menjadi pukul 12.30 siang"},{"id":"opt_2","text":"Tetap dimulai tepat pukul 13.00 siang"},{"id":"opt_3","text":"Dimundurkan setengah jam menjadi pukul 13.30 siang"},{"id":"opt_4","text":"Ditunda sampai minggu depan"}],"audio_text":"Hey Marcus, would you mind pushing our one o''clock sync back by half an hour? My noon client call is running long. — No problem, let''s make it 1:30!"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Pushing our one o''clock sync back by half an hour'' = memundurkan rapat jam 1.00 selama 30 menit ke jam 1:30.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000589', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun permintaan sopan di ruang kerja terbuka (open office): "Apakah Anda keberatan memakai headphone selama panggilan itu?"', '{"romaji":"/ˈwʊdʒuː maɪnd ˈwerɪŋ ˈhedfoʊnz ˈdʊrɪŋ ðæt kɔːl/","tokens":["mind wearing","that call?","to wear","headphones","wear","Would you","during"],"target_translation":"Apakah Anda keberatan memakai headphone selama panggilan itu?"}'::jsonb, '["Would you","mind wearing","headphones","during","that call?"]'::jsonb, NULL, NULL, '''Would you mind + V-ing (wearing)...?'' menyampaikan teguran ruang kerja tanpa menyinggung perasaan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000590', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun permintaan bantuan memeriksa tata bahasa: "Apakah kamu keberatan membaca sekilas paragraf pembuka saya?"', '{"romaji":"/ˈwʊdʒuː maɪnd ˈriːdɪŋ θruː maɪ ˈoʊpənɪŋ ˈpærəɡræf/","tokens":["Would you","through my","to read","opening","reads","paragraph?","mind reading"],"target_translation":"Apakah kamu keberatan membaca sekilas paragraf pembuka saya?"}'::jsonb, '["Would you","mind reading","through my","opening","paragraph?"]'::jsonb, NULL, NULL, '''Mind + reading through'' = keberatan membaca keseluruhan isi draf.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000591', 'e4100001-0000-4000-8000-000000000072', 'e2000001-0000-4000-8000-000000000018', 'speaking', 'speaking_repeat', 'Ucapkan kalimat permintaan jadwal ulang yang sangat profesional ini: "Apakah Anda keberatan memundurkan panggilan kita ke besok pagi?"', '{"romaji":"/ˈwʊdʒuː maɪnd ˈmuːvɪŋ ˈaʊər kɔːl tə təˈmɑːroʊ ˈmɔːrnɪŋ/","display_text":"Would you mind moving our call to tomorrow morning?","phonetic_breakdown":["ˈwʊdʒ-uː","maɪnd","ˈmuː-vɪŋ","ˈaʊ-ər","kɔːl","tə","tə-ˈmɑːr-oʊ","ˈmɔːr-nɪŋ"]}'::jsonb, '{"expected_transcript":"Would you mind moving our call to tomorrow morning?"}'::jsonb, NULL, NULL, 'Gunakan intonasi sedikit naik di akhir agar terdengar tulus dan terbuka.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000592', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk menawarkan bantuan profesional kepada klien: ___ me to send a calendar invite with the dial-in details?', '{"options":["Would you like","Would you mind","Could you","Should you"],"translation":"Apakah Anda ingin saya mengirimkan undangan kalender beserta detail panggilannya?","sentence_template":"[blank] me to send a calendar invite with the dial-in details?"}'::jsonb, '{"selected":"Would you like"}'::jsonb, NULL, NULL, 'Pola ''Would you like me to + V1...?'' menawarkan tindakan yang akan kita kerjakan untuk lawan bicara.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000593', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih ungkapan sopan khas AS untuk menolak tawaran tambahan dari pelayan atau rekan karena semuanya sudah cukup: Do you need anything else before we start? — No, I''m ___, thank you!', '{"options":["all set","all mind","very hand","set up"],"translation":"Apakah Anda membutuhkan hal lain sebelum kita mulai? — Tidak, sudah beres/cukup semua, terima kasih!","sentence_template":"Do you need anything else before we start? — No, I''m [blank], thank you!"}'::jsonb, '{"selected":"all set"}'::jsonb, NULL, NULL, '''I''m all set, thank you!'' adalah ungkapan idiomatis Amerika paling ramah untuk menyatakan sudah siap/cukup.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000594', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih kata benda idiomatis yang berarti ''bantuan'': Those monitor stands look heavy—can I give you a ___?', '{"options":["hand","foot","shoulder","finger"],"translation":"Penyangga monitor itu kelihatannya berat—boleh saya bantu?","sentence_template":"Those monitor stands look heavy—can I give you a [blank]?"}'::jsonb, '{"selected":"hand"}'::jsonb, NULL, NULL, 'Idiom ''give (someone) a hand'' berarti membantu seseorang melakukan pekerjaan.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000595', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan percakapan persiapan presentasi kelompok di perpustakaan ini. Tugas apa yang ditawarkan oleh Maya?', '{"options":[{"id":"opt_1","text":"Maya meminta Leo mengerjakan daftar pustaka sendirian"},{"id":"opt_2","text":"Maya menawarkan diri merapikan daftar pustaka dan memeriksa sitasi gaya APA"},{"id":"opt_3","text":"Maya membatalkan presentasi kelompok mereka"},{"id":"opt_4","text":"Maya meminjam laptop Leo untuk menonton film"}],"audio_text":"You''ve been writing the research summary all afternoon, Leo. Would you like me to format the bibliography and check the APA citations?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di universitas AS, format kutipan ''APA citations'' sangat sering dipakai; Maya proaktif menawarkan bantuan dengan ''Would you like me to format...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000596', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan respons manajer saat anggota tim menawarkan bantuan berikut. Apa keputusan manajer?', '{"options":[{"id":"opt_1","text":"Manajer menolak karena catatan rilis sudah selesai ditulis kemarin"},{"id":"opt_2","text":"Manajer sangat terbantu dan menerima tawaran tersebut, lalu meminta tautannya dikirim di Slack saat siap"},{"id":"opt_3","text":"Manajer menunda peluncuran versi 2.4 hingga tahun depan"},{"id":"opt_4","text":"Manajer meminta tim menghapus aplikasi Slack"}],"audio_text":"Hi Sarah, do you want me to draft the release notes for version two point four? — Oh, that''d be a huge help, thanks! Just drop the link in Slack when it''s ready."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''That''d be a huge help, thanks!'' adalah apresiasi antusias saat menerima tawaran bantuan di kantor AS.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000597', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat tawaran bantuan profesional: "Apakah Anda ingin saya membagikan layar saya sekarang?"', '{"romaji":"/ˈwʊdʒuː laɪk miː tə ʃer maɪ skriːn naʊ/","tokens":["my screen","like me","sharing","now?","Would you","to share","like I"],"target_translation":"Apakah Anda ingin saya membagikan layar saya sekarang?"}'::jsonb, '["Would you","like me","to share","my screen","now?"]'::jsonb, NULL, NULL, 'Perhatikan kata ganti objek ''me'' + ''to + V1'': ''Would you like me to share...?'' (bukan ''like I'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000598', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun penutup pesan yang suportif untuk rekan baru: "Kabari saya jika kamu butuh bantuan dengan pengaturannya."', '{"romaji":"/let miː noʊ ɪf juː niːd ə hænd wɪð ðə ˈsetʌp/","tokens":["with","Let me know","needs","if you","need a hand","the setup.","hands"],"target_translation":"Kabari saya jika kamu butuh bantuan dengan pengaturannya."}'::jsonb, '["Let me know","if you","need a hand","with","the setup."]'::jsonb, NULL, NULL, '''Let me know if you need a hand with...'' adalah kalimat penutup onboarding paling hangat di tim global.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000599', 'e4100001-0000-4000-8000-000000000073', 'e2000001-0000-4000-8000-000000000018', 'speaking', 'speaking_repeat', 'Ucapkan tawaran bantuan kepada rekan kerja ini dengan intonasi bersahabat: "Mau aku belikan es kopi selagi aku di bawah?"', '{"romaji":"/də juː wɑːnt miː tə ɡræb juː ən aɪst ˈkɔːfi waɪl aɪm ˌdaʊnˈsterz/","display_text":"Do you want me to grab you an iced coffee while I''m downstairs?","phonetic_breakdown":["də","juː","wɑːnt","miː","tə","ɡræb","juː","ən","aɪst","ˈkɔː-fi","waɪl","aɪm","ˌdaʊn-ˈsterz"]}'::jsonb, '{"expected_transcript":"Do you want me to grab you an iced coffee while I''m downstairs?"}'::jsonb, NULL, NULL, 'Kata kerja ''grab'' sangat populer di AS untuk arti kasual ''membelikan/mengambilkan sebentar''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000600', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''Would you mind'': Would you mind ___ me on the email thread with the logistics vendor?', '{"options":["copying","to copy","copy","copied"],"translation":"Apakah Anda keberatan menyertakan tembusan (cc) ke saya pada rangkaian email dengan vendor logistik?","sentence_template":"Would you mind [blank] me on the email thread with the logistics vendor?"}'::jsonb, '{"selected":"copying"}'::jsonb, NULL, NULL, '''Would you mind'' wajib diikuti bentuk -ing (''copying me on the email thread'' = memasukkan ke kolom CC).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000601', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih permintaan sopan yang benar untuk meminta orang lain mengulangi ucapannya: Sorry, the connection broke up—___ you repeat the last sentence, please?', '{"options":["could","may","mind","shall"],"translation":"Maaf, suaranya tadi terputus-putus—bisakah Anda mengulangi kalimat terakhir?","sentence_template":"Sorry, the connection broke up—[blank] you repeat the last sentence, please?"}'::jsonb, '{"selected":"could"}'::jsonb, NULL, NULL, '''Could you + V1...?'' adalah standar permintaan sopan saat panggilan audio terputus (''broke up'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000602', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'reading', 'fill_blank', 'Pilih jawaban yang benar saat Anda SETUJU meminjamkan pena ketika ditanya ''Would you mind if I used your pen for a second?'': ___! Here you go.', '{"options":["No, not at all","Yes, I do mind","Yes, please","I''m afraid yes"],"translation":"Tidak keberatan sama sekali! Ini silakan.","sentence_template":"[blank]! Here you go."}'::jsonb, '{"selected":"No, not at all"}'::jsonb, NULL, NULL, 'Menyetujui ''Would you mind...?'' menggunakan ''No, not at all!'' diikuti ''Here you go'' saat menyerahkan barang.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000603', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan kerja menjelang tenggat sore ini. Mengapa David belum bisa langsung memeriksa dokumen Tari sekarang?', '{"options":[{"id":"opt_1","text":"David menolak membantu karena itu bukan tugas divisinya"},{"id":"opt_2","text":"David sedang terikat rapat tinjauan anggaran sampai jam tiga, tapi dengan senang hati akan memeriksanya tepat setelah itu"},{"id":"opt_3","text":"Siaran pers tersebut panjangnya lima puluh halaman"},{"id":"opt_4","text":"David sudah pulang ke rumah karena sakit"}],"audio_text":"Hi David, could you proofread this one-page press release? — Actually, I''m tied up in budget reviews until three, but I''d be happy to look at it right after that!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Cara menolak/menunda paling elegan di AS: jelaskan kendala singkat (''I''m tied up until three'') lalu tawarkan alternatif waktu (''right after that'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000604', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'listening', 'listening_choice', 'Dengarkan pertanyaan tamu hotel kepada resepsionis di Boston ini. Fasilitas apa yang diminta tamu tersebut?', '{"options":[{"id":"opt_1","text":"Meminta perpanjangan kamar gratis sampai jam tujuh malam"},{"id":"opt_2","text":"Meminta tolong menitipkan kopernya di meja resepsionis setelah check-out pukul 12.00 siang"},{"id":"opt_3","text":"Memesan taksi menuju bandara sekarang juga"},{"id":"opt_4","text":"Menukar kamar ke lantai paling atas"}],"audio_text":"Good morning! My flight isn''t until seven tonight—would you mind holding my suitcase at the front desk after I check out at noon?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Would you mind holding my suitcase...'' adalah kalimat praktis yang hampir selalu terpakai saat bepergian di AS!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000605', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat meminta izin merekam sesi pelatihan: "Bolehkah saya merekam sesi pelatihan ini untuk tim kami?"', '{"romaji":"/kʊd aɪ rɪˈkɔːrd ðɪs ˈtreɪnɪŋ ˈseʃən fɔːr ˈaʊər tiːm/","tokens":["Could you","Could I","training session","for our","record this","team?","recording"],"target_translation":"Bolehkah saya merekam sesi pelatihan ini untuk tim kami?"}'::jsonb, '["Could I","record this","training session","for our","team?"]'::jsonb, NULL, NULL, 'Meminta izin untuk diri sendiri: ''Could I + V1 (record)...?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000606', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat menawarkan tindak lanjut rapat: "Apakah Anda ingin saya merangkum poin-poin tindak lanjutnya?"', '{"romaji":"/ˈwʊdʒuː laɪk miː tə ˈsʌməraɪz ði ˈækʃən ˈaɪtəmz/","tokens":["Would you","items?","mind me","like me","summarizing","the action","to summarize"],"target_translation":"Apakah Anda ingin saya merangkum poin-poin tindak lanjutnya?"}'::jsonb, '["Would you","like me","to summarize","the action","items?"]'::jsonb, NULL, NULL, 'Perhatikan ejaan Amerika ''summarize'' (memakai huruf ''z'', bukan ''summarise''!) dan istilah bisnis ''action items''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000607', 'e4100001-0000-4000-8000-000000000074', 'e2000001-0000-4000-8000-000000000018', 'speaking', 'speaking_repeat', 'Ucapkan kalimat permintaan halus di email/telepon ini dengan lancar: "Apakah Anda keberatan mengirimkan berkas PDF-nya sebelum hari Jumat?"', '{"romaji":"/ˈwʊdʒuː maɪnd ˈsendɪŋ ˈoʊvər ðə ˌpiːdiːˈef faɪl bɪˈfɔːr ˈfraɪdeɪ/","display_text":"Would you mind sending over the PDF file before Friday?","phonetic_breakdown":["ˈwʊdʒ-uː","maɪnd","ˈsen-dɪŋ","ˈoʊ-vər","ðə","ˌpiː-diː-ˈef","faɪl","bɪ-ˈfɔːr","ˈfraɪ-deɪ"]}'::jsonb, '{"expected_transcript":"Would you mind sending over the PDF file before Friday?"}'::jsonb, NULL, NULL, '''Sending over'' terdengar ramah dan kolaboratif dibanding sekadar ''sending''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000608', 'e4100001-0000-4000-8000-000000000075', NULL, 'reading', 'fill_blank', 'Pilih bentuk kata kerja kedua yang tepat setelah ''finish'': As soon as I finish ___ this lab report, let''s grab dinner at the dining hall.', '{"options":["writing","to write","write","written"],"translation":"Begitu saya selesai menulis laporan praktikum ini, ayo makan malam di kantin kampus.","sentence_template":"As soon as I finish [blank] this lab report, let''s grab dinner at the dining hall."}'::jsonb, '{"selected":"writing"}'::jsonb, NULL, NULL, 'Kata kerja ''finish'' wajib diikuti Gerund (-ing): ''finish writing'' (bukan ''finish to write'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000609', 'e4100001-0000-4000-8000-000000000075', NULL, 'reading', 'fill_blank', 'Ingat aturan ketat kata kerja ''suggest'' dalam bahasa Inggris standar & TOEFL: My advisor suggested ___ for the research grant before November.', '{"options":["applying","to apply","apply","applied"],"translation":"Pembimbing saya menyarankan mendaftar hibah riset tersebut sebelum bulan November.","sentence_template":"My advisor suggested [blank] for the research grant before November."}'::jsonb, '{"selected":"applying"}'::jsonb, NULL, NULL, '''Suggest'' dan ''recommend'' langsung diikuti Gerund (''suggested applying''), tidak pernah ''suggested to apply''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000610', 'e4100001-0000-4000-8000-000000000075', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''avoid'': To stay focused during deep work, Tari avoids ___ social media notifications.', '{"options":["checking","to check","check","checked"],"translation":"Agar tetap fokus saat kerja mendalam, Tari menghindari mengecek notifikasi media sosial.","sentence_template":"To stay focused during deep work, Tari avoids [blank] social media notifications."}'::jsonb, '{"selected":"checking"}'::jsonb, NULL, NULL, 'Kata kerja ''avoid'' selalu diikuti bentuk -ing (''avoids checking'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000611', 'e4100001-0000-4000-8000-000000000075', NULL, 'listening', 'listening_choice', 'Dengarkan cerita insinyur perangkat lunak tentang rutinitas belajarnya ini. Bagaimana cara ia melatih kemampuan bicaranya setiap pagi?', '{"options":[{"id":"opt_1","text":"Ia berhenti berlatih bahasa Inggris karena terlalu sibuk bekerja"},{"id":"opt_2","text":"Ia terus berlatih pelafalan bahasa Inggris selama lima belas menit setiap pagi sambil membuat kopi"},{"id":"opt_3","text":"Ia hanya belajar bahasa Inggris setahun sekali sebelum ujian"},{"id":"opt_4","text":"Ia menyewa guru privat selama empat jam setiap pagi"}],"audio_text":"Even with a busy schedule, I keep practicing my English pronunciation for fifteen minutes every morning while making coffee."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Keep + V-ing'' (''keep practicing'') berarti terus rutin melakukan sesuatu tanpa berhenti.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000612', 'e4100001-0000-4000-8000-000000000075', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dua komuter di Chicago berikut. Mengapa pembicara pria memilih naik kereta api komuter (Metra) daripada menyetir mobil?', '{"options":[{"id":"opt_1","text":"Karena ia belum memiliki surat izin mengemudi"},{"id":"opt_2","text":"Karena ia benci terjebak macet jam sibuk dan di kereta ia menikmati membaca buletin industri"},{"id":"opt_3","text":"Karena mobilnya baru saja dijual kemarin"},{"id":"opt_4","text":"Karena parkir di pusat kota Chicago gratis"}],"audio_text":"Why don''t you drive to downtown Chicago? — Honestly, I hate sitting in rush-hour traffic, and on the train I enjoy reading industry newsletters."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Enjoy reading'' menunjukkan aktivitas yang disukai selama perjalanan naik kereta.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000613', 'e4100001-0000-4000-8000-000000000075', NULL, 'writing', 'sentence_builder', 'Susun kalimat tentang waktu pemecahan masalah: "Kami menghabiskan waktu dua jam untuk memperbaiki bug itu."', '{"romaji":"/wiː spent tuː ˈaʊərz ˈfɪksɪŋ ðæt bʌɡ/","tokens":["bug.","We spent","fixing","to fix","hours for","two hours","that"],"target_translation":"Kami menghabiskan waktu dua jam untuk memperbaiki bug itu."}'::jsonb, '["We spent","two hours","fixing","that","bug."]'::jsonb, NULL, NULL, 'Pola ''spend + [waktu] + V-ing'' (''spent two hours fixing'', tanpa kata ''for'' atau ''to'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000614', 'e4100001-0000-4000-8000-000000000075', NULL, 'writing', 'sentence_builder', 'Susun kalimat semangat belajar: "Teruslah mencoba pendekatan berbeda sampai kodenya berhasil."', '{"romaji":"/kiːp ˈtraɪɪŋ ˈdɪfərənt əˈproʊtʃɪz ənˈtɪl ðə koʊd wɜːrks/","tokens":["approach","Keep trying","approaches","different","until the","Keep to try","code works."],"target_translation":"Teruslah mencoba pendekatan berbeda sampai kodenya berhasil."}'::jsonb, '["Keep trying","different","approaches","until the","code works."]'::jsonb, NULL, NULL, '''Keep + V-ing'' (''Keep trying'') menyatakan dorongan untuk terus berusaha.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000615', 'e4100001-0000-4000-8000-000000000075', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat wawancara kerja ini dengan lafal US suggest (/səɡˈdʒest/): "Saya menikmati memecahkan masalah data yang rumit bersama tim saya."', '{"romaji":"/aɪ ɪnˈdʒɔɪ ˈsɑːlvɪŋ ˈkɑːmpleks ˈdeɪtə ˈprɑːbləmz wɪð maɪ tiːm/","display_text":"I enjoy solving complex data problems with my team.","phonetic_breakdown":["aɪ","ɪn-ˈdʒɔɪ","ˈsɑːl-vɪŋ","ˈkɑːm-pleks","ˈdeɪ-tə","ˈprɑː-bləmz","wɪð","maɪ","tiːm"]}'::jsonb, '{"expected_transcript":"I enjoy solving complex data problems with my team."}'::jsonb, NULL, NULL, 'Di aksen AS, kata sifat ''complex'' ditekan pada suku kata kedua atau pertama (/kəmˈpleks/ atau /ˈkɑːmpleks/), dan ''solving'' memakai vokal /ɑː/.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000616', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Hati-hati dengan penutup email bisnis paling populer ini: Thank you for your time today. I look forward to ___ with your team next week!', '{"options":["working","work","worked","works"],"translation":"Terima kasih atas waktu Anda hari ini. Saya menantikan bekerja sama dengan tim Anda minggu depan!","sentence_template":"Thank you for your time today. I look forward to [blank] with your team next week!"}'::jsonb, '{"selected":"working"}'::jsonb, NULL, NULL, 'Dalam ''look forward to'', kata ''to'' berfungsi sebagai preposisi sehingga wajib diikuti bentuk -ing (''look forward to working'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000617', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah kata kerja keputusan ''decide'': After comparing three offers, Laras decided ___ the cloud security startup in Denver.', '{"options":["to join","joining","join","for joining"],"translation":"Setelah membandingkan tiga tawaran kerja, Laras memutuskan bergabung dengan startup keamanan cloud di Denver.","sentence_template":"After comparing three offers, Laras decided [blank] the cloud security startup in Denver."}'::jsonb, '{"selected":"to join"}'::jsonb, NULL, NULL, 'Kata kerja ''decide'' selalu diikuti to-infinitive (''decided to join'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000618', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Ingat hukum kata kerja setelah preposisi ''without'': Never sign a housing lease in the US without ___ every clause carefully.', '{"options":["reading","to read","read","reads"],"translation":"Jangan pernah menandatangani kontrak sewa tempat tinggal di AS tanpa membaca setiap pasalnya dengan cermat.","sentence_template":"Never sign a housing lease in the US without [blank] every clause carefully."}'::jsonb, '{"selected":"reading"}'::jsonb, NULL, NULL, '''Without'' adalah preposisi, sehingga kata kerja tepat di belakangnya wajib berbentuk Gerund (''without reading'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000619', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan kisah mahasiswa perantau tentang tantangan anggaran bulanan di kota besar ini. Mengapa mereka memilih memasak bersama di apartemen?', '{"options":[{"id":"opt_1","text":"Karena semua restoran di Manhattan tutup pukul lima sore"},{"id":"opt_2","text":"Karena sebagai mahasiswa pascasarjana mereka tidak sanggup membiayai makan di luar setiap malam sehingga bergantian memasak"},{"id":"opt_3","text":"Karena mereka sedang mengikuti kompetisi koki televisi"},{"id":"opt_4","text":"Karena apartemen mereka tidak memiliki kulkas"}],"audio_text":"Eating out every night in Manhattan is way too expensive—as grad students, we can''t afford to buy twenty-dollar salads every day, so we take turns cooking dinner."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Can''t afford to buy...'' menunjukkan keterbatasan finansial untuk membeli sesuatu yang mahal secara terus-menerus.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000620', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan percakapan penutupan rapat dengan klien baru berikut. Apa yang ditawarkan oleh Bima?', '{"options":[{"id":"opt_1","text":"Membatalkan kontrak kerja sama secara sepihak"},{"id":"opt_2","text":"Ia telah berjanji membagikan materi salindia kepada tim hukum klien paling lambat besok pukul 12.00 siang"},{"id":"opt_3","text":"Meminta tim hukum klien membuat presentasi sendiri"},{"id":"opt_4","text":"Menunda pengiriman dokumen sampai bulan depan"}],"audio_text":"Before we wrap up, I''d be happy to send everyone a one-page summary—actually, I promised to share the slide deck with your legal team by noon tomorrow."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Promised to share...'' menggunakan pola ''promise + to V1'' untuk menegaskan komitmen tindak lanjut.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000621', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat ucapan terima kasih profesional: "Terima kasih telah membantu saya mempersiapkan wawancara itu."', '{"romaji":"/θæŋk juː fɔːr ˈhelpɪŋ miː prɪˈper fɔːr ðæt ˈɪntərvjuː/","tokens":["helping I","for help","for helping","interview.","Thank you","me prepare","for that"],"target_translation":"Terima kasih telah membantu saya mempersiapkan wawancara itu."}'::jsonb, '["Thank you","for helping","me prepare","for that","interview."]'::jsonb, NULL, NULL, 'Setelah preposisi ''for'', gunakan Gerund: ''Thank you for helping me...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000622', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat pencapaian kerja: "Kami berhasil menyelesaikan migrasi server tepat waktu."', '{"romaji":"/wiː ˈmænɪdʒd tə kəmˈpliːt ðə ˈsɜːrvər maɪˈɡreɪʃən ɑːn taɪm/","tokens":["migration","the server","completing","in time.","to complete","We managed","on time."],"target_translation":"Kami berhasil menyelesaikan migrasi server tepat waktu."}'::jsonb, '["We managed","to complete","the server","migration","on time."]'::jsonb, NULL, NULL, '''Managed to + V1'' berarti berhasil menuntaskan pekerjaan yang tidak mudah.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000623', 'e4100001-0000-4000-8000-000000000076', 'e2000001-0000-4000-8000-000000000019', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup email wawancara paling ikonik ini dengan lancar: "Saya sangat menantikan kabar dari Anda segera."', '{"romaji":"/aɪ lʊk ˈfɔːrwərd tə ˈhɪrɪŋ frʌm juː suːn/","display_text":"I look forward to hearing from you soon.","phonetic_breakdown":["aɪ","lʊk","ˈfɔːr-wərd","tə","ˈhɪr-ɪŋ","frʌm","juː","suːn"]}'::jsonb, '{"expected_transcript":"I look forward to hearing from you soon."}'::jsonb, NULL, NULL, 'Kunci emas email profesional AS: ''look forward to HEARING'' (bukan ''to hear'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000624', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Waspadai jebakan kata benda jamak di tengah frasa subjek Gerund: Managing multiple time zones ___ clear written communication.', '{"options":["requires","require","requiring","are requiring"],"translation":"Mengelola banyak zona waktu membutuhkan komunikasi tertulis yang jelas.","sentence_template":"Managing multiple time zones [blank] clear written communication."}'::jsonb, '{"selected":"requires"}'::jsonb, NULL, NULL, 'Subjek kalimat adalah aktivitas tunggal ''Managing'' (bukan ''time zones''), sehingga kata kerja wajib tunggal berakhiran -s: ''requires''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000625', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang benar untuk menjadi subjek di awal kalimat: ___ a part-time campus job is a great way to practice everyday English.', '{"options":["Getting","Get","Gets","Got"],"translation":"Mendapatkan pekerjaan paruh waktu di kampus adalah cara bagus untuk melatih bahasa Inggris sehari-hari.","sentence_template":"[blank] a part-time campus job is a great way to practice everyday English."}'::jsonb, '{"selected":"Getting"}'::jsonb, NULL, NULL, 'Untuk memosisikan kata kerja sebagai subjek kalimat pernyataan, gunakan bentuk Gerund ''Getting''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000626', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''instead of'': Let''s cook pasta at home tonight instead of ___ delivery again.', '{"options":["ordering","to order","order","ordered"],"translation":"Mari memasak pasta di rumah malam ini alih-alih memesan antar lagi.","sentence_template":"Let''s cook pasta at home tonight instead of [blank] delivery again."}'::jsonb, '{"selected":"ordering"}'::jsonb, NULL, NULL, 'Frasa preposisi ''instead of'' wajib diikuti Gerund (''instead of ordering'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000627', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan tips pembimbing penulisan akademik (Writing Tutor) tentang cara memperkaya kosakata ini. Metode apa yang ia sarankan?', '{"options":[{"id":"opt_1","text":"Menghafal kamus tebal dari halaman pertama sampai terakhir tanpa konteks"},{"id":"opt_2","text":"Membaca artikel berita pendek dan memperhatikan pasangan kata (kolokasi) alih-alih menghafal daftar kata lepas"},{"id":"opt_3","text":"Berhenti membaca teks bahasa Inggris sama sekali"},{"id":"opt_4","text":"Hanya menonton film tanpa teks terjemahan"}],"audio_text":"Instead of memorizing isolated word lists, you''ll remember vocabulary much faster by reading short news articles and noticing how words pair together."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan dua struktur Gerund beruntun: ''Instead of memorizing...'' dan ''by reading... and noticing...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000628', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan pembukaan presentasi mahasiswa kesehatan masyarakat berikut. Apa manfaat jalan kaki pagi yang ia tekankan?', '{"options":[{"id":"opt_1","text":"Berlari maraton setiap malam membuat mahasiswa mengantuk di kelas"},{"id":"opt_2","text":"Berjalan cepat selama tiga puluh menit setiap pagi menurunkan tingkat stres dan meningkatkan konsentrasi kuliah pagi"},{"id":"opt_3","text":"Mahasiswa dilarang berjalan kaki di sekitar area kampus"},{"id":"opt_4","text":"Olahraga hanya bermanfaat jika dilakukan tiga jam sehari"}],"audio_text":"Walking briskly for thirty minutes every morning lowers stress levels and boosts concentration during morning lectures."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Subjek Gerund ''Walking briskly...'' diikuti dua kata kerja tunggal sejajar: ''lowers... and boosts...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000629', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat opini pembuka esai: "Belajar di luar negeri membangun kemandirian dan kemampuan beradaptasi."', '{"romaji":"/ˈstʌdiɪŋ əˈbrɔːd bɪldz ˌɪndɪˈpendəns ænd əˌdæptəˈbɪləti/","tokens":["builds","independence","build","Studying abroad","and","adaptability.","Study abroad"],"target_translation":"Belajar di luar negeri membangun kemandirian dan kemampuan beradaptasi."}'::jsonb, '["Studying abroad","builds","independence","and","adaptability."]'::jsonb, NULL, NULL, 'Subjek tunggal Gerund ''Studying abroad'' diikuti kata kerja tunggal ''builds''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000630', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat penjelasan metode penghematan: "Dia menghemat uang dengan menyewa buku teks bekas."', '{"romaji":"/ʃiː seɪvd ˈmʌni baɪ ˈrentɪŋ juːzd ˈtekstbʊks/","tokens":["used","for rent","renting","textbooks.","She saved","by rent","money by"],"target_translation":"Dia menghemat uang dengan menyewa buku teks bekas."}'::jsonb, '["She saved","money by","renting","used","textbooks."]'::jsonb, NULL, NULL, 'Di kampus AS, mahasiswa sering menyewa buku teks bekas (''renting used textbooks''); metode memakai ''by + V-ing''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000631', 'e4100001-0000-4000-8000-000000000077', 'e2000001-0000-4000-8000-000000000019', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kiat produktivitas ini dengan jelas: "Menuliskan tiga prioritas harian membuat pagi saya tetap terarah."', '{"romaji":"/ˈraɪtɪŋ daʊn θriː ˈdeɪli praɪˈɔːrətiz kiːps maɪ ˈmɔːrnɪŋz ˈfoʊkəst/","display_text":"Writing down three daily priorities keeps my mornings focused.","phonetic_breakdown":["ˈraɪ-tɪŋ","daʊn","θriː","ˈdeɪ-li","praɪ-ˈɔːr-ə-tiz","kiːps","maɪ","ˈmɔːr-nɪŋz","ˈfoʊ-kəst"]}'::jsonb, '{"expected_transcript":"Writing down three daily priorities keeps my mornings focused."}'::jsonb, NULL, NULL, 'Perhatikan keselarasan subjek tunggal ''Writing down...'' dengan kata kerja tunggal ''keeps''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000632', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Uji ketelitian ''look forward to'': All of us on the committee look forward to ___ your research presentation on Friday.', '{"options":["attending","attend","attended","attends"],"translation":"Kami semua di komite sangat menantikan menghadiri presentasi riset Anda pada hari Jumat.","sentence_template":"All of us on the committee look forward to [blank] your research presentation on Friday."}'::jsonb, '{"selected":"attending"}'::jsonb, NULL, NULL, '''Look forward to'' diakhiri preposisi ''to'', sehingga wajib disambung Gerund ''attending''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000633', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang benar setelah kata kerja ''offer'': When my car wouldn''t start, my neighbor kindly offered ___ me a ride to the train station.', '{"options":["to give","giving","give","for giving"],"translation":"Saat mobil saya mogok tidak mau menyala, tetangga saya dengan baik hati menawarkan tumpangan ke stasiun kereta.","sentence_template":"When my car wouldn''t start, my neighbor kindly offered [blank] me a ride to the train station."}'::jsonb, '{"selected":"to give"}'::jsonb, NULL, NULL, 'Kata kerja ''offer'' selalu diikuti to-infinitive (''offered to give me a ride'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000634', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'reading', 'fill_blank', 'Perhatikan kesesuaian kata kerja untuk subjek Gerund: Comparing flight prices across different dates ___ travelers save hundreds of dollars.', '{"options":["helps","help","helping","are helping"],"translation":"Membandingkan harga tiket pesawat di berbagai tanggal membantu pelancong menghemat ratusan dolar.","sentence_template":"Comparing flight prices across different dates [blank] travelers save hundreds of dollars."}'::jsonb, '{"selected":"helps"}'::jsonb, NULL, NULL, 'Inti subjeknya adalah Gerund tunggal ''Comparing'' (bukan ''prices'' atau ''dates''), sehingga memakai kata kerja tunggal ''helps''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000635', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan percakapan rekan satu tim setelah rapat retrospektif berikut. Perubahan apa yang disarankan manajer proyek?', '{"options":[{"id":"opt_1","text":"Menghapus rapat harian selamanya"},{"id":"opt_2","text":"Ia menyarankan menjaga rapat standup harian di bawah sepuluh menit dan berjanji membagikan catatan agenda tertulis sebelumnya"},{"id":"opt_3","text":"Memperpanjang rapat harian menjadi dua jam setiap pagi"},{"id":"opt_4","text":"Meminta semua anggota bekerja pada hari Minggu"}],"audio_text":"What did Evan say during the retro? — He suggested keeping our daily standup under ten minutes and promised to share written agenda notes beforehand."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kalimat ini menggabungkan keduanya secara kontras: ''suggested keeping'' (+ V-ing) dan ''promised to share'' (+ to V1)!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000636', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'listening', 'listening_choice', 'Dengarkan jawaban kandidat saat ditanya bidang minatnya dalam wawancara magang ini. Bidang apa yang membuatnya tertarik?', '{"options":[{"id":"opt_1","text":"Merancang permainan video balap mobil"},{"id":"opt_2","text":"Tertarik membangun antarmuka seluler yang ramah aksesibilitas bagi lansia"},{"id":"opt_3","text":"Bekerja di bagian akuntansi pajak perusahaan"},{"id":"opt_4","text":"Mengelola gudang pengiriman barang"}],"audio_text":"I''m really interested in building accessible mobile interfaces for older adults, which is why I applied to your healthcare design team."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Interested in + V-ing'' (''interested in building...'') menyampaikan minat karier dengan struktur yang bersih.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000637', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat nasihat kesehatan kerja: "Hindari menatap layar terang tepat sebelum tidur."', '{"romaji":"/əˈvɔɪd ˈsterɪŋ æt braɪt skriːnz raɪt bɪˈfɔːr bed/","tokens":["at bright","bed.","to stare","screen","before","screens right","Avoid staring"],"target_translation":"Hindari menatap layar terang tepat sebelum tidur."}'::jsonb, '["Avoid staring","at bright","screens right","before","bed."]'::jsonb, NULL, NULL, '''Avoid + V-ing'' (''Avoid staring at...'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000638', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat keputusan studi lanjut: "Dia memutuskan untuk melamar program magister di Seattle."', '{"romaji":"/ʃiː dɪˈsaɪdɪd tə əˈplaɪ fɔːr ə ˈmæstərz ˈproʊɡræm ɪn siˈætəl/","tokens":["to apply","She decided","in Seattle.","decide","applying","for a","master''s program"],"target_translation":"Dia memutuskan untuk melamar program magister di Seattle."}'::jsonb, '["She decided","to apply","for a","master''s program","in Seattle."]'::jsonb, NULL, NULL, '''Decided + to V1'' (''decided to apply'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000639', 'e4100001-0000-4000-8000-000000000078', 'e2000001-0000-4000-8000-000000000019', 'speaking', 'speaking_repeat', 'Ucapkan kalimat apresiasi profesional ini dengan jelas: "Terima kasih telah meninjau draf saya begitu cepat."', '{"romaji":"/θæŋk juː fɔːr rɪˈvjuːɪŋ maɪ dræft soʊ ˈkwɪkli/","display_text":"Thank you for reviewing my draft so quickly.","phonetic_breakdown":["θæŋk","juː","fɔːr","rɪ-ˈvjuː-ɪŋ","maɪ","dræft","soʊ","ˈkwɪk-li"]}'::jsonb, '{"expected_transcript":"Thank you for reviewing my draft so quickly."}'::jsonb, NULL, NULL, 'Preposisi ''for'' langsung diikuti Gerund ''reviewing''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000640', 'e4100001-0000-4000-8000-000000000079', NULL, 'reading', 'fill_blank', 'Pilih konjungsi waktu yang menyatakan ''segera setelah tanpa menunda'': Please message our group chat ___ your plane lands at JFK!', '{"options":["as soon as","until","during","while"],"translation":"Tolong kirim pesan ke grup obrolan kita begitu pesawatmu mendarat di bandara JFK!","sentence_template":"Please message our group chat [blank] your plane lands at JFK!"}'::jsonb, '{"selected":"as soon as"}'::jsonb, NULL, NULL, '''As soon as'' menunjukkan aksi kedua dilakukan tepat sesaat setelah aksi pertama terjadi.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000641', 'e4100001-0000-4000-8000-000000000079', NULL, 'reading', 'fill_blank', 'Bedakan ''until'' (durasi berlangsung sampai) vs ''by'': Our campus library stays open ___ midnight during final exam week.', '{"options":["until","as soon as","once","after"],"translation":"Perpustakaan kampus kami tetap buka sampai tengah malam selama pekan ujian akhir.","sentence_template":"Our campus library stays open [blank] midnight during final exam week."}'::jsonb, '{"selected":"until"}'::jsonb, NULL, NULL, 'Keadaan yang terus berlangsung (''stays open'') hingga batas waktu tertentu memakai ''until'' (satu huruf ''l''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000642', 'e4100001-0000-4000-8000-000000000079', NULL, 'reading', 'fill_blank', 'Pilih urutan prosedur yang logis: Always back up your important files ___ you install a major operating system update.', '{"options":["before","after","until","once"],"translation":"Selalu cadangkan berkas-berkas penting Anda sebelum memasang pembaruan besar sistem operasi.","sentence_template":"Always back up your important files [blank] you install a major operating system update."}'::jsonb, '{"selected":"before"}'::jsonb, NULL, NULL, 'Pencadangan data (''back up'') wajib dilakukan terlebih dahulu (''before'') sebelum memperbarui OS.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000643', 'e4100001-0000-4000-8000-000000000079', NULL, 'listening', 'listening_choice', 'Dengarkan instruksi staf laboratorium komputer ini. Kapan mahasiswa boleh mencetak poster riset mereka?', '{"options":[{"id":"opt_1","text":"Sebelum membuat desain poster sama sekali"},{"id":"opt_2","text":"Begitu Dr. Kim menyetujui tata letak poster di portal, mahasiswa dapat mencetaknya gratis di lab media lantai dua"},{"id":"opt_3","text":"Mahasiswa harus membayar lima puluh dolar sebelum Dr. Kim memeriksa"},{"id":"opt_4","text":"Lab media lantai dua sudah ditutup permanen"}],"audio_text":"Once Dr. Kim approves your poster layout in the portal, you can print it for free at the media lab on the second floor."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Once Dr. Kim approves...'' berfungsi sebagai penanda syarat waktu (''begitu/setelah disetujui'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000644', 'e4100001-0000-4000-8000-000000000079', NULL, 'listening', 'listening_choice', 'Dengarkan pesan otomatis layanan pelanggan bank di AS berikut. Sampai kapan nasabah diminta tetap berada di sambungan telepon?', '{"options":[{"id":"opt_1","text":"Diminta langsung menutup telepon sekarang juga"},{"id":"opt_2","text":"Diminta tetap menunggu di sambungan telepon sampai petugas berikutnya yang tersedia menjawab"},{"id":"opt_3","text":"Diminta datang langsung ke kantor pusat di New York"},{"id":"opt_4","text":"Layanan telepon hanya buka pada hari Minggu"}],"audio_text":"All of our representatives are currently assisting other callers. Please stay on the line until the next available agent answers your call."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Ungkapan standar telepon AS ''stay on the line until...'' berarti jangan menutup telepon sampai tersambung ke petugas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000645', 'e4100001-0000-4000-8000-000000000079', NULL, 'writing', 'sentence_builder', 'Susun kalimat prosedur keamanan laboratorium: "Cuci tangan Anda sebelum meninggalkan laboratorium biologi."', '{"romaji":"/wɑːʃ jʊr hændz bɪˈfɔːr ˈliːvɪŋ ðə baɪˈɑːlədʒi læb/","tokens":["hands before","lab.","to leave","the biology","Wash your","until","leaving"],"target_translation":"Cuci tangan Anda sebelum meninggalkan laboratorium biologi."}'::jsonb, '["Wash your","hands before","leaving","the biology","lab."]'::jsonb, NULL, NULL, '''Before + V-ing'' (''before leaving'') meringkas prosedur instruksi dengan sangat lugas.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000646', 'e4100001-0000-4000-8000-000000000079', NULL, 'writing', 'sentence_builder', 'Susun kalimat urutan rilis perangkat lunak: "Begitu pengujian selesai, kami akan meluncurkan pembaruannya."', '{"romaji":"/wʌns ðə tests pæs, wiːl lɔːntʃ ði ˈʌpdeɪt/","tokens":["Once the","we''ll launch","tests pass,","will pass,","launches","update.","the"],"target_translation":"Begitu pengujian selesai, kami akan meluncurkan pembaruannya."}'::jsonb, '["Once the","tests pass,","we''ll launch","the","update."]'::jsonb, NULL, NULL, 'Perhatikan di dalam klausa ''Once...'', kata kerjanya memakai Present Simple (''pass''), bukan ''will pass''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000647', 'e4100001-0000-4000-8000-000000000079', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat koordinasi perjalanan ini dengan jelas: "Saya akan menelepon Anda begitu saya tiba di hotel."', '{"romaji":"/aɪl ɡɪv juː ə kɔːl æz suːn æz aɪ ɡet tə ðə hoʊˈtel/","display_text":"I''ll give you a call as soon as I get to the hotel.","phonetic_breakdown":["aɪl","ɡɪv","juː","ə","kɔːl","æz","suːn","æz","aɪ","ɡet","tə","ðə","hoʊ-ˈtel"]}'::jsonb, '{"expected_transcript":"I''ll give you a call as soon as I get to the hotel."}'::jsonb, NULL, NULL, '''Give someone a call'' adalah frasa alami AS untuk ''menelepon seseorang''.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000648', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Terapkan hukum besi Future Time Clause (perhatikan juga subjek tunggal ''the client''): We''ll start building the prototype as soon as the client ___ the agreement.', '{"options":["signs","will sign","sign","signed"],"translation":"Kami akan mulai membangun prototipe begitu klien menandatangani perjanjiannya.","sentence_template":"We''ll start building the prototype as soon as the client [blank] the agreement."}'::jsonb, '{"selected":"signs"}'::jsonb, NULL, NULL, 'Di dalam klausa ''as soon as...'', dilarang memakai ''will''; karena ''the client'' tunggal, Present Simple memakai -s (''signs'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000649', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih bentuk kata kerja yang benar setelah ''After'' untuk rencana tahun depan: After Nadia ___ next spring, she''s going to pursue a master''s degree in Boston.', '{"options":["graduates","will graduate","graduated","graduating"],"translation":"Setelah Nadia lulus musim semi depan, dia berencana melanjutkan gelar magister di Boston.","sentence_template":"After Nadia [blank] next spring, she''s going to pursue a master''s degree in Boston."}'::jsonb, '{"selected":"graduates"}'::jsonb, NULL, NULL, 'Meskipun waktunya ''next spring'', klausa waktu setelah ''After'' wajib menggunakan Present Simple tunggal ''graduates''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000650', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Lengkapi klausa waktu setelah ''until'': Please don''t open your test booklet until the proctor ___ you to begin.', '{"options":["tells","will tell","tell","telling"],"translation":"Harap jangan membuka buku soal ujian Anda sampai pengawas meminta Anda memulai.","sentence_template":"Please don''t open your test booklet until the proctor [blank] you to begin."}'::jsonb, '{"selected":"tells"}'::jsonb, NULL, NULL, 'Subjek tunggal ''the proctor'' (pengawas ujian) di dalam klausa ''until'' wajib memakai Present Simple ''tells''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000651', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan mengenai jadwal pengiriman paket peralatan kerja jarak jauh ini. Kapan nomor resi pelacakan akan dikirim?', '{"options":[{"id":"opt_1","text":"Nomor resi sudah dikirim tiga hari yang lalu"},{"id":"opt_2","text":"Tautan pelacakan otomatis akan dikirim begitu kurir FedEx menjemput paketnya sore ini"},{"id":"opt_3","text":"Karyawan harus mengambil sendiri monitornya di gudang pusat"},{"id":"opt_4","text":"Pengiriman monitor ditunda sampai bulan depan"}],"audio_text":"When will I get my company monitor? — IT is packing it today, and you''ll receive an automated tracking link as soon as FedEx picks it up this afternoon."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan struktur bersihnya: ''you''ll receive... as soon as FedEx picks it up'' (bukan ''will pick it up'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000652', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan rencana mahasiswa internasional menjelang libur musim panas berikut. Apa yang akan ia lakukan sebelum terbang pulang ke Jakarta?', '{"options":[{"id":"opt_1","text":"Menjual semua jaket musim dinginnya di bandara"},{"id":"opt_2","text":"Menyimpan pakaian musim dingin dan buku teksnya di gudang penyimpanan bersama dekat kampus sebelum terbang ke Jakarta"},{"id":"opt_3","text":"Membawa lima koper penuh buku teks ke Jakarta"},{"id":"opt_4","text":"Membatalkan tiket pulang ke Jakarta"}],"audio_text":"Before I fly back to Jakarta in June, I''m going to store my winter clothes and textbooks in a shared storage unit near campus."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di kampus AS, menyewa ''storage unit'' bersama teman selama libur musim panas sangat lazim saat pindah asrama.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000653', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat janji kabar kepada orang tua: "Saya akan memberi tahu Ibu ketika nilai ujiannya keluar."', '{"romaji":"/aɪl let juː noʊ wen ði ɪɡˈzæm skɔːrz kʌm aʊt/","tokens":["exam scores","comes","will come","when the","you know","I''ll let","come out."],"target_translation":"Saya akan memberi tahu Ibu ketika nilai ujiannya keluar."}'::jsonb, '["I''ll let","you know","when the","exam scores","come out."]'::jsonb, NULL, NULL, 'Subjek jamak ''the exam scores'' di dalam klausa ''when'' memakai Present Simple jamak ''come out'' (tanpa ''will'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000654', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat prosedur rilis yang aman: "Kami tidak akan meluncurkan fitur itu sampai semua pengujian lulus."', '{"romaji":"/wiː woʊnt rɪˈliːs ðæt ˈfiːtʃər ənˈtɪl ɔːl tests pæs/","tokens":["passes.","feature until","release that","We won''t","pass.","will pass.","all tests"],"target_translation":"Kami tidak akan meluncurkan fitur itu sampai semua pengujian lulus."}'::jsonb, '["We won''t","release that","feature until","all tests","pass."]'::jsonb, NULL, NULL, '''We won''t release... until all tests pass'' memadukan klausa utama negatif masa depan dengan klausa ''until'' Present Simple.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000655', 'e4100001-0000-4000-8000-000000000080', 'e2000001-0000-4000-8000-000000000020', 'speaking', 'speaking_repeat', 'Ucapkan kalimat koordinasi rapat ini dengan mulus: "Ketika semua orang sudah bergabung, kita akan memulai presentasinya."', '{"romaji":"/wen ˈevriwʌn dʒɔɪnz ðə kɔːl, wiːl stɑːrt ðə ˌprezənˈteɪʃən/","display_text":"When everyone joins the call, we''ll start the presentation.","phonetic_breakdown":["wen","ˈev-ri-wʌn","dʒɔɪnz","ðə","kɔːl","wiːl","stɑːrt","ðə","ˌprez-ən-ˈteɪ-ʃən"]}'::jsonb, '{"expected_transcript":"When everyone joins the call, we''ll start the presentation."}'::jsonb, NULL, NULL, 'Ingat: kata ganti ''everyone'' selalu dihitung TUNGGAL dalam Bahasa Inggris -> ''everyone joins''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000656', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih antara ''during'', ''while'', dan ''for'' sebelum frasa kata benda ''the orientation week'': All new international students receive their campus ID cards ___ the orientation week.', '{"options":["during","while","as soon as","for"],"translation":"Semua mahasiswa internasional baru menerima kartu identitas kampus mereka selama pekan orientasi.","sentence_template":"All new international students receive their campus ID cards [blank] the orientation week."}'::jsonb, '{"selected":"during"}'::jsonb, NULL, NULL, '''The orientation week'' adalah frasa kata benda murni (tanpa subjek + kata kerja) yang menjawab ''kapan'', sehingga memakai ''during''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000657', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih konjungsi untuk aksi latar berdurasi yang sedang berlangsung (was + V-ing): ___ Bagas was sharing his screen on Zoom, a calendar notification popped up.', '{"options":["While","During","Until","For"],"translation":"Selagi Bagas sedang membagikan layarnya di Zoom, notifikasi kalender muncul tiba-tiba.","sentence_template":"[blank] Bagas was sharing his screen on Zoom, a calendar notification popped up."}'::jsonb, '{"selected":"While"}'::jsonb, NULL, NULL, 'Diikuti klausa lengkap Past Continuous (''Bagas was sharing''), sehingga wajib memakai ''While'' (bukan preposisi ''During'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000658', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih kata hubung antarkalimat untuk menjelaskan pekerjaan paralel divisi lain: I''m drafting the user survey today; ___, Leo is setting up the analytics dashboard.', '{"options":["meanwhile","during","until","before"],"translation":"Saya sedang menyusun survei pengguna hari ini; sementara itu, Leo sedang menyiapkan dasbor analitik.","sentence_template":"I''m drafting the user survey today; [blank], Leo is setting up the analytics dashboard."}'::jsonb, '{"selected":"meanwhile"}'::jsonb, NULL, NULL, '''Meanwhile,'' berdiri sebagai kata transisi pembuka klausa kedua untuk dua aktivitas yang berjalan paralel.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000659', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan cerita perjalanan bisnis seorang konsultan di bandara Dallas ini. Kapan ia berhasil menyelesaikan bacaan laporannya?', '{"options":[{"id":"opt_1","text":"Saat sedang menyetir mobil menuju bandara"},{"id":"opt_2","text":"Selagi sedang menunggu selama dua jam di gerbang keberangkatan bandara Dallas"},{"id":"opt_3","text":"Tiga hari setelah pulang ke rumah"},{"id":"opt_4","text":"Ia belum sempat membaca laporannya sama sekali"}],"audio_text":"My connecting flight in Dallas was delayed for two hours, so I finished reading the entire market report while I was waiting at the gate."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''While I was waiting at the gate'' menggambarkan aktivitas membaca yang dilakukan di tengah durasi menunggu pesawat.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000660', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan aturan keselamatan dari pramugari pesawat maskapai AS berikut. Kapan penumpang wajib tetap duduk dengan sabuk pengaman terpasang?', '{"options":[{"id":"opt_1","text":"Hanya saat pramugari membagikan minuman ringan"},{"id":"opt_2","text":"Selagi lampu tanda sabuk pengaman menyala serta selama proses lepas landas dan mendarat"},{"id":"opt_3","text":"Penumpang bebas berdiri saat pesawat mendarat"},{"id":"opt_4","text":"Sabuk pengaman tidak perlu dipakai di kursi dekat jendela"}],"audio_text":"For your safety, please remain seated with your seatbelt fastened while the seatbelt sign is illuminated and during takeoff and landing."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pengumuman pesawat ini memperlihatkan kontras nyata keduanya dalam satu kalimat: ''WHILE the seatbelt sign is illuminated'' (klausa) dan ''DURING takeoff and landing'' (kata benda)!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000661', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat pengalaman magang: "Saya belajar banyak tentang riset produk selama magang musim panas saya."', '{"romaji":"/aɪ lɜːrnd ə lɑːt əˈbaʊt ˈprɑːdʌkt ˈriːsɜːrtʃ ˈdʊrɪŋ maɪ ˈsʌmər ˈɪntɜːrnʃɪp/","tokens":["product research","a lot about","I learned","while my","during my","for my","summer internship."],"target_translation":"Saya belajar banyak tentang riset produk selama magang musim panas saya."}'::jsonb, '["I learned","a lot about","product research","during my","summer internship."]'::jsonb, NULL, NULL, '''My summer internship'' adalah frasa kata benda -> gunakan ''during''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000662', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat dua kejadian masa lampau: "Listrik padam ketika kami sedang memasak makan malam."', '{"romaji":"/ðə ˈpaʊər went aʊt waɪl wiː wɜːr ˈkʊkɪŋ ˈdɪnər/","tokens":["dinner.","while we","The power","were cooking","was cooking","during we","went out"],"target_translation":"Listrik padam ketika kami sedang memasak makan malam."}'::jsonb, '["The power","went out","while we","were cooking","dinner."]'::jsonb, NULL, NULL, 'Idiom AS untuk mati lampu adalah ''The power went out'', dipadukan dengan ''while we were cooking dinner''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000663', 'e4100001-0000-4000-8000-000000000081', 'e2000001-0000-4000-8000-000000000020', 'speaking', 'speaking_repeat', 'Ucapkan kalimat etika kuliah ini dengan lafal US during (/ˈdʊrɪŋ/): "Harap simpan ponsel Anda selama presentasi berlangsung."', '{"romaji":"/pliːz pʊt jʊr foʊnz əˈweɪ ˈdʊrɪŋ ðə ˌprezənˈteɪʃənz/","display_text":"Please put your phones away during the presentations.","phonetic_breakdown":["pliːz","pʊt","jʊr","foʊnz","ə-ˈweɪ","ˈdʊr-ɪŋ","ðə","ˌprez-ən-ˈteɪ-ʃənz"]}'::jsonb, '{"expected_transcript":"Please put your phones away during the presentations."}'::jsonb, NULL, NULL, '''Put (something) away'' berarti menyimpan ke dalam tas/saku agar tidak mengganggu.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000664', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Uji aturan Future Time Clause setelah ''when'': When our new intern ___ on Monday morning, I''ll show him around the office.', '{"options":["arrives","will arrive","arrive","arrived"],"translation":"Ketika peserta magang baru kita tiba pada Senin pagi, saya akan mengajaknya berkeliling kantor.","sentence_template":"When our new intern [blank] on Monday morning, I''ll show him around the office."}'::jsonb, '{"selected":"arrives"}'::jsonb, NULL, NULL, 'Klausa waktu masa depan (''When...'') wajib memakai Present Simple tunggal ''arrives'', bukan ''will arrive''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000665', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih antara ''during'', ''while'', dan ''until'': Nobody spoke a word ___ the CEO''s keynote address.', '{"options":["during","while","as soon as","once"],"translation":"Tak seorang pun berbicara selama pidato utama CEO berlangsung.","sentence_template":"Nobody spoke a word [blank] the CEO''s keynote address."}'::jsonb, '{"selected":"during"}'::jsonb, NULL, NULL, '''The CEO''s keynote address'' adalah frasa kata benda (tanpa kata kerja), sehingga wajib memakai preposisi ''during''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000666', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'reading', 'fill_blank', 'Pilih konjungsi batas akhir berlakunya kupon: You can use this campus bookstore discount code ___ September 30th.', '{"options":["until","while","once","during"],"translation":"Anda dapat menggunakan kode diskon toko buku kampus ini sampai tanggal 30 September.","sentence_template":"You can use this campus bookstore discount code [blank] September 30th."}'::jsonb, '{"selected":"until"}'::jsonb, NULL, NULL, 'Keberlakuan terus-menerus sampai tanggal berakhir memakai ''until''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000667', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan penjelasan alur wawancara kerja tiga tahap di perusahaan teknologi AS ini. Kapan kandidat akan diundang ke wawancara panel akhir?', '{"options":[{"id":"opt_1","text":"Sebelum berbicara dengan perekrut sama sekali"},{"id":"opt_2","text":"Begitu kandidat lulus tantangan pemrograman bawa pulang (take-home coding challenge)"},{"id":"opt_3","text":"Semua kandidat langsung diterima tanpa tes teknis"},{"id":"opt_4","text":"Setahun setelah melamar melalui situs web"}],"audio_text":"First, you''ll have a twenty-minute recruiter chat. Once you pass the take-home coding challenge, we''ll schedule your final panel interview with the engineering team."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Once you pass..., we''ll schedule...'' menjelaskan urutan tahapan seleksi rekrutmen secara kronologis.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000668', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'listening', 'listening_choice', 'Dengarkan cerita insiden kecil saat rapat klien daring berikut. Apa yang terjadi ketika Maya sedang menjawab pertanyaan klien?', '{"options":[{"id":"opt_1","text":"Laptop Maya kehabisan baterai sebelum rapat dimulai"},{"id":"opt_2","text":"Alarm kebakaran gedung apartemennya tiba-tiba berbunyi untuk latihan bulanan selagi ia sedang menjawab pertanyaan klien"},{"id":"opt_3","text":"Klien membatalkan rapat sehari sebelumnya"},{"id":"opt_4","text":"Suara mikrofon klien tidak terdengar sama sekali"}],"audio_text":"While Maya was answering the client''s budget question, the fire alarm in her apartment building suddenly went off for a monthly drill!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Phrasal verb ''went off'' untuk alarm berarti ''berbunyi nyaring'', menyela aksi ''While Maya was answering...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000669', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat konfirmasi pengiriman berkas: "Saya akan mengirimkan salindianya kepada Anda sebelum rapat dimulai."', '{"romaji":"/aɪl send juː ðə slaɪdz bɪˈfɔːr ðə ˈmiːtɪŋ stɑːrts/","tokens":["starting.","I''ll send","you the","slides before","starts.","will start.","the meeting"],"target_translation":"Saya akan mengirimkan salindianya kepada Anda sebelum rapat dimulai."}'::jsonb, '["I''ll send","you the","slides before","the meeting","starts."]'::jsonb, NULL, NULL, 'Di dalam klausa ''before...'', subjek tunggal ''the meeting'' memakai Present Simple ''starts''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000670', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat belajar sambil naik komuter: "Dia mendengarkan siniar bisnis selagi naik kereta ke tempat kerja."', '{"romaji":"/hiː ˈlɪsənz tə ˈbɪznəs ˈpɑːdkæsts waɪl kəˈmjuːtɪŋ tə wɜːrk/","tokens":["during commuting","to business","podcasts while","commuting","He listens","to work.","commutes"],"target_translation":"Dia mendengarkan siniar bisnis selagi naik kereta ke tempat kerja."}'::jsonb, '["He listens","to business","podcasts while","commuting","to work."]'::jsonb, NULL, NULL, '''While + V-ing'' (''while commuting'') sangat ringkas saat subjek kedua klausa sama (''He'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000671', 'e4100001-0000-4000-8000-000000000082', 'e2000001-0000-4000-8000-000000000020', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kesiapan melangkah ke tingkat menengah B1 ini dengan percaya diri: "Begitu saya menyelesaikan tingkat ini, saya akan memulai persiapan B1!"', '{"romaji":"/æz suːn æz aɪ ˈfɪnɪʃ ðɪs ˈlevəl, aɪl stɑːrt prɪˈperɪŋ fɔːr biː wʌn/","display_text":"As soon as I finish this level, I''ll start preparing for B1!","phonetic_breakdown":["æz","suːn","æz","aɪ","ˈfɪn-ɪʃ","ðɪs","ˈlev-əl","aɪl","stɑːrt","prɪ-ˈper-ɪŋ","fɔːr","biː","wʌn"]}'::jsonb, '{"expected_transcript":"As soon as I finish this level, I''ll start preparing for B1!"}'::jsonb, NULL, NULL, 'Selamat! Kamu sudah menguasai fondasi penuh CEFR A2 American English!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000672', 'e4100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih bentuk lampau yang tepat: Two days ago, Nadia ___ her academic transcript to the university registrar.', '{"options":["sent","send","sends","has sent"],"translation":"Dua hari yang lalu, Nadia mengirimkan transkrip akademiknya ke bagian registrasi universitas.","sentence_template":"Two days ago, Nadia [blank] her academic transcript to the university registrar."}'::jsonb, '{"selected":"sent"}'::jsonb, NULL, NULL, 'Keterangan waktu lampau tertentu (''Two days ago'') wajib memakai Past Simple tak beraturan: ''send'' -> ''sent''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000673', 'e4100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih bentuk masa depan untuk rencana matang yang sudah diputuskan: I ___ start my data analytics bootcamp next month.', '{"options":["am going to","will be","going to","went to"],"translation":"Saya berencana memulai bootcamp analitik data saya bulan depan.","sentence_template":"I [blank] start my data analytics bootcamp next month."}'::jsonb, '{"selected":"am going to"}'::jsonb, NULL, NULL, 'Rencana yang sudah diniatkan/dipersiapkan sebelumnya menggunakan ''am/is/are + going to + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000674', 'e4100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat Present Perfect berikut: ___ you ever attended an international tech conference before?', '{"options":["Have","Did","Are","Were"],"translation":"Pernahkah Anda menghadiri konferensi teknologi internasional sebelumnya?","sentence_template":"[blank] you ever attended an international tech conference before?"}'::jsonb, '{"selected":"Have"}'::jsonb, NULL, NULL, 'Pertanyaan pengalaman hidup (''ever ... before?'') menggunakan ''Have/Has + Subject + V3 (attended)''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000675', 'e4100001-0000-4000-8000-000000000083', NULL, 'reading', 'fill_blank', 'Pilih modal kewajiban yang tepat sesuai aturan kantor: All visitors ___ wear a guest badge inside the lab.', '{"options":["have to","has to","could","would"],"translation":"Semua pengunjung wajib mengenakan tanda pengenal tamu di dalam laboratorium.","sentence_template":"All visitors [blank] wear a guest badge inside the lab."}'::jsonb, '{"selected":"have to"}'::jsonb, NULL, NULL, 'Aturan wajib bagi subjek jamak (''All visitors'') menggunakan ''have to + V1''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000676', 'e4100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dengan pengelola apartemen (landlord) di Denver berikut. Biaya utilitas apa yang SUDAH termasuk dalam uang sewa?', '{"options":[{"id":"opt_1","text":"Listrik, internet Wi-Fi, dan pemanas ruangan"},{"id":"opt_2","text":"Air bersih dan pengangkutan sampah, sedangkan listrik dan Wi-Fi dibayar terpisah"},{"id":"opt_3","text":"Semua tagihan sudah termasuk tanpa biaya tambahan apa pun"},{"id":"opt_4","text":"Hanya biaya parkir mobil di garasi bawah tanah"}],"audio_text":"The monthly rent is fourteen hundred dollars, which includes water and trash pickup, but tenants pay for electricity and Wi-Fi separately."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Includes water and trash pickup, but tenants pay for electricity and Wi-Fi separately'' membedakan fasilitas termasuk vs terpisah.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000677', 'e4100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan dialog pengembalian barang di layanan pelanggan toko AS ini. Apa syarat agar pembeli mendapat pengembalian dana penuh (full refund)?', '{"options":[{"id":"opt_1","text":"Membayar biaya administrasi sebesar sepuluh dolar tunai"},{"id":"opt_2","text":"Menukarnya dengan dua barang lain yang lebih mahal"},{"id":"opt_3","text":"Menunjukkan struk pembelian asli dan barang belum pernah dipakai"},{"id":"opt_4","text":"Menunggu persetujuan manajer cabang selama dua minggu"}],"audio_text":"Sure, we can issue a full refund to your credit card as long as you have the original receipt and the item is unworn."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Original receipt'' (struk asli) dan ''unworn'' (belum dipakai) adalah syarat standar retur di ritel AS.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000678', 'e4100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan resepsionis hotel di Chicago saat tamu melakukan check-in. Jam berapa sarapan pagi disajikan?', '{"options":[{"id":"opt_1","text":"Pukul 05.30 sampai 08.00 pagi di lobi utama"},{"id":"opt_2","text":"Pukul 06.30 sampai 09.30 pagi di lantai dua"},{"id":"opt_3","text":"Pukul 07.00 sampai 11.00 siang di restoran atap"},{"id":"opt_4","text":"Diantar langsung ke kamar 608 pukul 08.00 pagi"}],"audio_text":"Here is your key card for Room 608. Complimentary breakfast is served on the second floor from 6:30 to 9:30 a.m."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Complimentary breakfast'' berarti sarapan gratis bagi tamu hotel, disajikan di lantai 2 pukul 6:30–9:30 pagi.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000679', 'e4100001-0000-4000-8000-000000000083', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dua mahasiswa yang membandingkan laptop. Mengapa pembicara memilih model ProBook?', '{"options":[{"id":"opt_1","text":"Karena layar ProBook jauh lebih besar untuk bermain gim"},{"id":"opt_2","text":"Karena harga ProBook paling murah di toko kampus"},{"id":"opt_3","text":"Karena daya tahan baterai ProBook empat jam lebih awet saat kuliah beruntun"},{"id":"opt_4","text":"Karena mendapatkan bonus tas ransel gratis"}],"audio_text":"Even though the AirLite is slightly cheaper, I bought the ProBook because its battery lasts four hours longer during back-to-back lectures."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '''Its battery lasts four hours longer during back-to-back lectures'' menjadi alasan utama pilihan pembicara.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000680', 'e4100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun permintaan sopan di kantor: "Bisakah Anda mengirimkan jadwal rapat terbaru kepada saya?"', '{"romaji":"/kʊd juː send miː ðə ʌpˈdeɪtɪd ˈmiːtɪŋ ˈskedʒuːl, pliːz/","tokens":["sending","please?","schedules","the updated","send me","meeting schedule,","Could you"],"target_translation":"Bisakah Anda mengirimkan jadwal rapat terbaru kepada saya?"}'::jsonb, '["Could you","send me","the updated","meeting schedule,","please?"]'::jsonb, NULL, NULL, '''Could you + V1 ...?'' lebih halus dan profesional untuk komunikasi kantor dibandingkan ''Can you''.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000681', 'e4100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun kalimat nasihat kesehatan: "Sebaiknya Anda membuat janji temu dengan dokter kampus hari ini."', '{"romaji":"/juː ʃʊd meɪk ən əˈpɔɪntmənt wɪð ðə ˈkæmpəs ˈdɑːktər/","tokens":["with the","You should","make an","appointments","campus doctor.","appointment","making"],"target_translation":"Sebaiknya Anda membuat janji temu dengan dokter kampus hari ini."}'::jsonb, '["You should","make an","appointment","with the","campus doctor."]'::jsonb, NULL, NULL, 'Kolokasi alami Bahasa Inggris untuk membuat janji dokter adalah ''make an appointment'' (bukan ''do an appointment'').', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000682', 'e4100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun kalimat perbandingan superlatif: "September adalah bulan paling sibuk bagi tim admisi kami."', '{"romaji":"/sepˈtembər ɪz ðə ˈbɪziɪst mʌnθ fɔːr ˈaʊər ədˈmɪʃənz tiːm/","tokens":["more busy","month for","our admissions","team.","the busiest","September is","busier"],"target_translation":"September adalah bulan paling sibuk bagi tim admisi kami."}'::jsonb, '["September is","the busiest","month for","our admissions","team."]'::jsonb, NULL, NULL, 'Kata sifat berakhiran -y (''busy'') berubah menjadi ''the busiest'' pada bentuk superlatif (''paling sibuk'').', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000683', 'e4100001-0000-4000-8000-000000000083', NULL, 'writing', 'sentence_builder', 'Susun kalimat pengalaman kerja: "Dia telah bekerja di perusahaan rintisan ini selama dua tahun."', '{"romaji":"/ʃiː hæz wɜːrkt æt ðɪs ˈstɑːrtʌp fɔːr tuː jɪrz/","tokens":["worked at","for two","this startup","She has","years.","working","since"],"target_translation":"Dia telah bekerja di perusahaan rintisan ini selama dua tahun."}'::jsonb, '["She has","worked at","this startup","for two","years."]'::jsonb, NULL, NULL, 'Gunakan ''for'' untuk durasi waktu (''for two years''), sedangkan ''since'' dipakai untuk titik awal waktu (''since 2024'').', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000684', 'e4100001-0000-4000-8000-000000000083', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat cerita masa lalu ini dengan pelafalan akhiran -ed yang tepat: "Saya lulus dari universitas tahun lalu dan pindah ke Boston."', '{"romaji":"/aɪ ˈɡrædʒueɪtɪd frʌm ˈkɑːlɪdʒ læst jɪr ænd muːvd tə ˈbɑːstən/","display_text":"I graduated from college last year and moved to Boston.","phonetic_breakdown":["aɪ","ˈɡrædʒ-u-eɪ-tɪd","frʌm","ˈkɑː-lɪdʒ","læst","jɪr","ænd","muːvd","tə","ˈbɑː-stən"]}'::jsonb, '{"expected_transcript":"I graduated from college last year and moved to Boston."}'::jsonb, NULL, NULL, 'Di AS, ''college'' lazim dipakai untuk merujuk jenjang kuliah S1 secara umum; perhatikan ''moved'' dibaca /muːvd/ tanpa vokal ''e''.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000685', 'e4100001-0000-4000-8000-000000000083', NULL, 'speaking', 'speaking_repeat', 'Tirukan kalimat layanan pelanggan berikut: "Saya ingin mengembalikan jaket ini karena ukurannya terlalu kecil."', '{"romaji":"/aɪd laɪk tə rɪˈtɜːrn ðɪs ˈdʒækɪt bɪˈkɔːz ɪts tuː smɔːl/","display_text":"I''d like to return this jacket because it''s too small.","phonetic_breakdown":["aɪd","laɪk","tə","rɪ-ˈtɜːrn","ðɪs","ˈdʒæ-kɪt","bɪ-ˈkɔːz","ɪts","tuː","smɔːl"]}'::jsonb, '{"expected_transcript":"I''d like to return this jacket because it''s too small."}'::jsonb, NULL, NULL, 'Gunakan kata kerja ''return'' untuk mengembalikan barang ke toko, dan ''exchange'' jika ingin menukar ukuran.', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000686', 'e4100001-0000-4000-8000-000000000083', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat permintaan sopan di kantor ini: "Apakah Anda keberatan memundurkan rapat kita ke hari Kamis?"', '{"romaji":"/wʊd juː maɪnd ˈmuːvɪŋ ˈaʊər ˈmiːtɪŋ tə ˈθɜːrzdeɪ/","display_text":"Would you mind moving our meeting to Thursday?","phonetic_breakdown":["wʊd","juː","maɪnd","ˈmuː-vɪŋ","ˈaʊ-ər","ˈmiː-tɪŋ","tə","ˈθɜːrz-deɪ"]}'::jsonb, '{"expected_transcript":"Would you mind moving our meeting to Thursday?"}'::jsonb, NULL, NULL, 'Ingat: setelah ''Would you mind'', kata kerja selalu berbentuk -ing (''moving'').', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000687', 'e4100001-0000-4000-8000-000000000083', NULL, 'speaking', 'speaking_repeat', 'Tirukan kalimat saat check-in hotel bisnis berikut: "Saya punya reservasi atas nama Pratama untuk tiga malam."', '{"romaji":"/aɪ hæv ə ˌrezərˈveɪʃən ˈʌndər prɑːˈtɑːmə fɔːr θriː naɪts/","display_text":"I have a reservation under Pratama for three nights.","phonetic_breakdown":["aɪ","hæv","ə","ˌre-zər-ˈveɪ-ʃən","ˈʌn-dər","prɑː-ˈtɑː-mə","fɔːr","θriː","naɪts"]}'::jsonb, '{"expected_transcript":"I have a reservation under Pratama for three nights."}'::jsonb, NULL, NULL, 'Ungkapan standar hotel di AS untuk menyebut nama pemesan kamar adalah ''a reservation under [Last Name]''.', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000688', 'e4100001-0000-4000-8000-000000000084', NULL, 'reading', 'fill_blank', 'Perhatikan penanda jendela waktu terbuka ''over the past decade'': Renewable energy adoption ___ dramatically across the Midwest over the past decade.', '{"options":["has increased","increased","have increased","is increase"],"translation":"Adopsi energi terbarukan telah meningkat pesat di wilayah Midwest selama satu dekade terakhir.","sentence_template":"Renewable energy adoption [blank] dramatically across the Midwest over the past decade."}'::jsonb, '{"selected":"has increased"}'::jsonb, NULL, NULL, 'Frasa ''over the past decade'' mencakup sepuluh tahun terakhir hingga hari ini, sehingga subjek tunggal ''adoption'' memakai ''has increased''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000689', 'e4100001-0000-4000-8000-000000000084', NULL, 'reading', 'fill_blank', 'Perhatikan penanda waktu lampau tertutup ''in 2020'': Our engineering division ___ to a cloud-native architecture in 2020.', '{"options":["migrated","has migrated","have migrated","migrates"],"translation":"Divisi teknik kami bermigrasi ke arsitektur berbasis cloud pada tahun 2020.","sentence_template":"Our engineering division [blank] to a cloud-native architecture in 2020."}'::jsonb, '{"selected":"migrated"}'::jsonb, NULL, NULL, 'Tahun spesifik yang sudah berlalu (''in 2020'') mengunci kalimat ke Past Simple (''migrated'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000690', 'e4100001-0000-4000-8000-000000000084', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk capaian kuartal yang masih berjalan (''so far this quarter''): Our sales team ___ four enterprise deals so far this quarter.', '{"options":["has closed","closed","was closing","close"],"translation":"Tim penjualan kami telah menutup empat kesepakatan korporat sejauh kuartal ini.","sentence_template":"Our sales team [blank] four enterprise deals so far this quarter."}'::jsonb, '{"selected":"has closed"}'::jsonb, NULL, NULL, '''So far this quarter'' menandakan kuartal belum berakhir, dan kata kolektif tunggal ''Our sales team'' di US English memakai ''has closed''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000691', 'e4100001-0000-4000-8000-000000000084', NULL, 'listening', 'listening_choice', 'Dengarkan rangkuman pembuka rapat produk ini. Berapa banyak responden yang sudah diwawancarai minggu ini vs minggu lalu?', '{"options":[{"id":"opt_1","text":"Enam belas responden minggu lalu dan belum ada minggu ini"},{"id":"opt_2","text":"Enam penguji beta minggu lalu (selesai), dan sejauh minggu ini sudah sembilan pemilik toko lagi di Chicago"},{"id":"opt_3","text":"Total sembilan responden sepanjang tahun lalu"},{"id":"opt_4","text":"Wawancara baru akan dimulai minggu depan"}],"audio_text":"Last week we interviewed six beta testers, and so far this week we''ve spoken with nine more store owners in Chicago."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan pergantian tense yang presisi: ''Last week we interviewed'' (V2) beralih ke ''so far this week we''ve spoken'' (Present Perfect).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000692', 'e4100001-0000-4000-8000-000000000084', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan pengantar kuliah sejarah teknologi setara TOEFL berikut. Mengapa profesor memakai Past Simple untuk ARPANET tetapi Present Perfect untuk internet modern?', '{"options":[{"id":"opt_1","text":"Karena ARPANET masih beroperasi di semua kampus saat ini"},{"id":"opt_2","text":"Karena pembangunan dan penutupan ARPANET sudah tuntas di masa lampau, sedangkan protokol internet modern terus mengubah industri sejak saat itu hingga kini"},{"id":"opt_3","text":"Karena internet modern baru ditemukan kemarin sore"},{"id":"opt_4","text":"Karena profesor sedang membahas prediksi abad depan"}],"audio_text":"Engineers built ARPANET in the late 1960s, and while that original network shut down in 1990, modern internet protocols have transformed every industry since then."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Built... in the late 1960s'' & ''shut down in 1990'' adalah sejarah tuntas (V2), sedangkan ''have transformed... since then'' berlanjut hingga kini.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000693', 'e4100001-0000-4000-8000-000000000084', NULL, 'writing', 'sentence_builder', 'Susun kalimat laporan riset: "Kami telah menguji lima prototipe berbeda sejauh bulan ini."', '{"romaji":"/wiː hæv ˈtestɪd faɪv ˈdɪfərənt ˈproʊtətaɪps soʊ fɑːr ðɪs mʌnθ/","tokens":["tested in","this month.","has tested","We have","different prototypes","tested five","so far"],"target_translation":"Kami telah menguji lima prototipe berbeda sejauh bulan ini."}'::jsonb, '["We have","tested five","different prototypes","so far","this month."]'::jsonb, NULL, NULL, '''So far this month'' memicu Present Perfect ''We have tested...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000694', 'e4100001-0000-4000-8000-000000000084', NULL, 'writing', 'sentence_builder', 'Susun kalimat latar belakang pendirian perusahaan: "Kedua pendiri itu memulai perusahaan mereka di garasi pada tahun 2018."', '{"romaji":"/ðə tuː ˈfaʊndərz ˈstɑːrtɪd ðer ˈkʌmpəni ɪn ə ɡəˈrɑːʒ ɪn ˌtwenti eɪˈtiːn/","tokens":["The two founders","in 2018.","a garage","have started","since 2018.","started their","company in"],"target_translation":"Kedua pendiri itu memulai perusahaan mereka di garasi pada tahun 2018."}'::jsonb, '["The two founders","started their","company in","a garage","in 2018."]'::jsonb, NULL, NULL, 'Perhatikan pelafalan US untuk ''garage'' ditekan di suku kata kedua (/ɡəˈrɑːʒ/), dan ''in 2018'' mewajibkan Past Simple ''started''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000695', 'e4100001-0000-4000-8000-000000000084', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kontras pencapaian masa lalu dan kini ini dengan jelas: "Saya bergabung dengan tim ini pada tahun 2023, dan sejak itu saya telah memimpin tiga proyek."', '{"romaji":"/aɪ dʒɔɪnd ðɪs tiːm ɪn ˌtwenti twenti ˈθriː, ænd aɪv led θriː ˈprɑːdʒekts sɪns ðen/","display_text":"I joined this team in 2023, and I''ve led three projects since then.","phonetic_breakdown":["aɪ","dʒɔɪnd","ðɪs","tiːm","ɪn","ˌtwen-ti","twen-ti","ˈθriː","ænd","aɪv","led","θriː","ˈprɑː-dʒekts","sɪns","ðen"]}'::jsonb, '{"expected_transcript":"I joined this team in 2023, and I''ve led three projects since then."}'::jsonb, NULL, NULL, 'V2 dan V3 dari ''lead'' (/liːd/) sama-sama dieja ''led'' dan dibaca pendek /led/ (jangan salah eja menjadi ''lead'' untuk masa lampau!).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000696', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Ingat aturan mutlak kata tanya ''When'': I heard you''ve moved into a new apartment! When ___ you sign the lease?', '{"options":["did","have","has","were"],"translation":"Saya dengar kamu sudah pindah ke apartemen baru! Kapan kamu menandatangani kontrak sewanya?","sentence_template":"I heard you''ve moved into a new apartment! When [blank] you sign the lease?"}'::jsonb, '{"selected":"did"}'::jsonb, NULL, NULL, 'Pertanyaan ''When'' menanyakan titik waktu spesifik di masa lampau, sehingga wajib memakai ''When did + S + V1?''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000697', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Perhatikan perpindahan dari pembuka Present Perfect ke kalimat detail kedua: Have you ever met our VP of Engineering? — Yes, we ___ briefly at the Seattle offsite in May.', '{"options":["spoke","have spoken","has spoken","speaking"],"translation":"Pernahkah kamu bertemu VP Engineering kita? — Ya, kami sempat berbincang singkat saat acara rapat luar kantor di Seattle bulan Mei lalu.","sentence_template":"Have you ever met our VP of Engineering? — Yes, we [blank] briefly at the Seattle offsite in May."}'::jsonb, '{"selected":"spoke"}'::jsonb, NULL, NULL, 'Begitu lokasi dan bulan lampau disebut (''at the Seattle offsite in May''), kalimat berpindah ke Past Simple ''spoke''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000698', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Pilih pembuka berita utama yang berdampak langsung pada situasi saat ini (tanpa menyebut jam lampau): Good news, everyone—the client ___ our revised budget proposal!', '{"options":["has approved","approved yesterday","did approve yet","have approved"],"translation":"Kabar gembira, semuanya—klien telah menyetujui proposal anggaran revisi kita!","sentence_template":"Good news, everyone—the client [blank] our revised budget proposal!"}'::jsonb, '{"selected":"has approved"}'::jsonb, NULL, NULL, 'Mengumumkan kabar baru yang hasilnya dirasakan sekarang tanpa keterangan waktu lampau memakai ''has approved''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000699', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan peneliti di lorong fakultas ini. Kapan tepatnya dana hibah tersebut disetujui?', '{"options":[{"id":"opt_1","text":"Sebulan yang lalu melalui surat pos"},{"id":"opt_2","text":"Kemarin sore saat yayasan mengirimkan surat resmi lewat email kepada Dr. Chen"},{"id":"opt_3","text":"Masih menunggu pengumuman minggu depan"},{"id":"opt_4","text":"Tahun lalu pada konferensi musim dingin"}],"audio_text":"Congratulations! I heard your lab has won the national clean-water grant! — Thanks! The foundation emailed Dr. Chen the official letter yesterday afternoon."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pembicara pertama membuka kabar dengan Present Perfect (''has won''), lalu pembicara kedua memberi detail waktu lampau dengan Past Simple (''emailed ... yesterday afternoon'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000700', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan cuplikan wawancara kerja kandidat analis produk berikut. Bagaimana kandidat menyusun jawabannya?', '{"options":[{"id":"opt_1","text":"Ia belum pernah menjalankan eksperimen A/B sama sekali"},{"id":"opt_2","text":"Ia merangkum total pengalamannya (>30 eksperimen) lalu memberi contoh spesifik musim gugur lalu yang menaikkan konversi 8%"},{"id":"opt_3","text":"Ia hanya membaca buku teori tentang eksperimen A/B"},{"id":"opt_4","text":"Eksperimennya menurunkan penjualan sebesar delapan persen"}],"audio_text":"I''ve run over thirty A/B experiments across mobile apps. For example, last autumn I redesigned a checkout button that lifted conversion by eight percent."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Transisi emas wawancara AS: ''I''ve run...'' (portofolio akumulatif) -> ''For example, last autumn I redesigned...'' (bukti konkret Past Simple).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000701', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun pertanyaan lanjutan untuk menggali waktu kejadian: "Kapan Anda pertama kali menyadari adanya bug keamanan itu?"', '{"romaji":"/wen dɪd juː fɜːrst ˈnoʊtɪs ðæt sɪˈkjʊrəti bʌɡ/","tokens":["that security","When have","bug?","you first","noticed","When did","notice"],"target_translation":"Kapan Anda pertama kali menyadari adanya bug keamanan itu?"}'::jsonb, '["When did","you first","notice","that security","bug?"]'::jsonb, NULL, NULL, '''When did you + V1 (notice)...?'' selalu dipakai untuk menanyakan kapan suatu insiden terjadi.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000702', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat pengumuman hasil kini: "Tim desain kami telah merampungkan prototipe aplikasi selulernya."', '{"romaji":"/ˈaʊər dɪˈzaɪn tiːm hæz ˈfaɪnəlaɪzd ðə ˈmoʊbəl æp ˈproʊtətaɪp/","tokens":["yesterday.","prototype.","mobile app","have finalized","finalized the","team has","Our design"],"target_translation":"Tim desain kami telah merampungkan prototipe aplikasi selulernya."}'::jsonb, '["Our design","team has","finalized the","mobile app","prototype."]'::jsonb, NULL, NULL, 'Ejaan Amerika memakai ''-ize'' (''finalized''), dan subjek kolektif tunggal ''Our design team'' memakai ''has''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000703', 'e4100001-0000-4000-8000-000000000085', 'e2000001-0000-4000-8000-000000000021', 'speaking', 'speaking_repeat', 'Ucapkan alur 2 kalimat (pengalaman umum -> detail waktu) ini dengan mulus: "Saya sudah pernah membaca makalah itu. Saya membacanya untuk seminar saya semester lalu."', '{"romaji":"/aɪv red ðæt ˈpeɪpər bɪˈfɔːr. aɪ red ɪt fɔːr maɪ ˈsemɪnɑːr læst sɪˈmestər/","display_text":"I''ve read that paper before. I read it for my seminar last semester.","phonetic_breakdown":["aɪv","red","ðæt","ˈpeɪ-pər","bɪ-ˈfɔːr","aɪ","red","ɪt","fɔːr","maɪ","ˈsem-ɪ-nɑːr","læst","sɪ-ˈmes-tər"]}'::jsonb, '{"expected_transcript":"I''ve read that paper before. I read it for my seminar last semester."}'::jsonb, NULL, NULL, 'Hati-hati: ejaan V2 dan V3 ''read'' tetap ''read'', tetapi KEDUANYA diucapkan /red/ seperti warna merah!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000704', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Perhatikan konteks bahwa Pak Rahman sudah pensiun tahun lalu: Before retiring last June, Mr. Rahman ___ as a civil engineer for thirty-two years.', '{"options":["worked","has worked","have worked","is working"],"translation":"Sebelum pensiun Juni lalu, Pak Rahman bekerja sebagai insinyur sipil selama tiga puluh dua tahun.","sentence_template":"Before retiring last June, Mr. Rahman [blank] as a civil engineer for thirty-two years."}'::jsonb, '{"selected":"worked"}'::jsonb, NULL, NULL, 'Karena masa kerjanya sudah berakhir saat pensiun Juni lalu, durasi ''for thirty-two years'' wajib memakai Past Simple ''worked''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000705', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Perhatikan konteks bahwa Clara masih menjadi mahasiswa aktif di sana: Clara loves living in Ann Arbor—she ___ at the University of Michigan for three semesters now.', '{"options":["has studied","studied","was studying","study"],"translation":"Clara senang tinggal di Ann Arbor—dia sudah kuliah di University of Michigan selama tiga semester hingga kini.","sentence_template":"Clara loves living in Ann Arbor—she [blank] at the University of Michigan for three semesters now."}'::jsonb, '{"selected":"has studied"}'::jsonb, NULL, NULL, 'Kalimat pertama (''loves living'') dan kata ''now'' menegaskan ia masih kuliah di sana, sehingga memakai ''has studied''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000706', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Situasi sekarang pukul 15.30 sore (jam kuliah pagi sudah lama berakhir): ___ Professor Gomez''s morning lecture today? It was super insightful!', '{"options":["Did you attend","Have you attended","Do you attend","Are you attending"],"translation":"Apakah tadi kamu menghadiri kuliah pagi Profesor Gomez hari ini? Kuliahnya tadi sangat membuka wawasan!","sentence_template":"[blank] Professor Gomez''s morning lecture today? It was super insightful!"}'::jsonb, '{"selected":"Did you attend"}'::jsonb, NULL, NULL, 'Karena sekarang sudah sore dan kalimat kedua memakai ''It was'', sesi pagi sudah selesai sehingga memakai ''Did you attend''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000707', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan perkenalan singkat pembicara tamu pada webinar karier ini. Di kota mana pembicara tersebut tinggal SEKARANG?', '{"options":[{"id":"opt_1","text":"Ia masih tinggal di Los Angeles sampai hari ini"},{"id":"opt_2","text":"Ia sekarang berbasis di Seattle (sudah dua tahun terakhir), setelah sebelumnya tinggal enam tahun di Los Angeles"},{"id":"opt_3","text":"Ia baru akan pindah ke Seattle tahun depan"},{"id":"opt_4","text":"Ia belum pernah tinggal di pantai barat AS"}],"audio_text":"I lived in Los Angeles for six years after college, and I''ve been based in Seattle for the past two years working on cloud infrastructure."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kontras ''I lived in LA for six years'' (sudah pindah) vs ''I''ve been based in Seattle for the past two years'' (lokasi saat ini) menjawab soal inferensi dengan akurat.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000708', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja tentang novel karya seorang penulis terkenal yang sudah wafat abad ke-20 berikut. Mengapa pembicara memakai ''wrote''?', '{"options":[{"id":"opt_1","text":"Karena Hemingway masih menulis novel baru tahun ini"},{"id":"opt_2","text":"Karena masa hidup Hemingway sudah berakhir (''wrote''), sedangkan pengalaman membaca pembicara masih bisa bertambah (''I''ve read'')"},{"id":"opt_3","text":"Karena kedua pembicara belum pernah membaca bukunya"},{"id":"opt_4","text":"Karena buku tersebut belum diterbitkan"}],"audio_text":"Did Ernest Hemingway write many novels? — Yes, he wrote seven published novels during his lifetime, and I''ve read three of them so far."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Karya tokoh sejarah yang telah tiada selalu memakai Past Simple (''he wrote''), sedangkan pengalaman hidup pembicara yang masih hidup memakai Present Perfect (''I''ve read'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000709', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat riwayat karier sebelumnya yang sudah berakhir: "Dia mengelola cabang Jakarta selama empat tahun sebelum pindah ke Boston."', '{"romaji":"/ʃiː ˈmænɪdʒd ðə dʒəˈkɑːrtə bræntʃ fɔːr fɔːr jɪrz bɪˈfɔːr ˈmuːvɪŋ tə ˈbɑːstən/","tokens":["before moving to Boston.","since four","She managed","has managed","four years","the Jakarta","branch for"],"target_translation":"Dia mengelola cabang Jakarta selama empat tahun sebelum pindah ke Boston."}'::jsonb, '["She managed","the Jakarta","branch for","four years","before moving to Boston."]'::jsonb, NULL, NULL, 'Karena ia sudah pindah ke Boston, masa jabatan di Jakarta sudah tuntas -> ''She managed... for four years''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000710', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat status kepemimpinan yang masih aktif: "Beliau telah menjabat sebagai dekan kami sejak musim gugur lalu."', '{"romaji":"/hiː hæz sɜːrvd æz ˈaʊər diːn sɪns læst fɔːl/","tokens":["our dean","last fall.","served","He has","since","for last","served as"],"target_translation":"Beliau telah menjabat sebagai dekan kami sejak musim gugur lalu."}'::jsonb, '["He has","served as","our dean","since","last fall."]'::jsonb, NULL, NULL, 'Di AS, musim gugur sehari-hari dan akademik disebut ''fall'' (lebih umum daripada ''autumn''); ''has served... since last fall'' menunjukkan masih menjabat.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000711', 'e4100001-0000-4000-8000-000000000086', 'e2000001-0000-4000-8000-000000000021', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kontras riwayat hidup ini dengan artikulasi jernih: "Dulu saya bekerja di perbankan selama dua tahun, tetapi sekarang saya telah berkarier di teknologi sejak 2022."', '{"romaji":"/aɪ wɜːrkt ɪn ˈbæŋkɪŋ fɔːr tuː jɪrz, ænd aɪv bɪn ɪn tek sɪns ˌtwenti twenti ˈtuː/","display_text":"I worked in banking for two years, and I''ve been in tech since 2022.","phonetic_breakdown":["aɪ","wɜːrkt","ɪn","ˈbæŋ-kɪŋ","fɔːr","tuː","jɪrz","ænd","aɪv","bɪn","ɪn","tek","sɪns","ˌtwen-ti","twen-ti","ˈtuː"]}'::jsonb, '{"expected_transcript":"I worked in banking for two years, and I''ve been in tech since 2022."}'::jsonb, NULL, NULL, 'Satu kalimat ringkas yang merangkum transisi karier secara sangat profesional!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000712', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Pilih tense yang tepat dengan penanda ''when I was an undergrad'': I ___ two macroeconomics courses when I was an undergrad in Bandung.', '{"options":["took","have taken","has taken","take"],"translation":"Saya mengambil dua mata kuliah ekonomi makro ketika saya masih mahasiswa S1 di Bandung.","sentence_template":"I [blank] two macroeconomics courses when I was an undergrad in Bandung."}'::jsonb, '{"selected":"took"}'::jsonb, NULL, NULL, 'Klausa ''when I was an undergrad'' mengunci peristiwa ke masa kuliah S1 yang sudah selesai -> Past Simple ''took''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000713', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Pilih tense yang tepat untuk tren riset berkelanjutan ''in recent decades'': Urban planners ___ increasingly prioritized bike lanes and green spaces in recent decades.', '{"options":["have","did","has","were"],"translation":"Para perencana kota semakin memprioritaskan jalur sepeda dan ruang terbuka hijau dalam beberapa dekade terakhir.","sentence_template":"Urban planners [blank] increasingly prioritized bike lanes and green spaces in recent decades."}'::jsonb, '{"selected":"have"}'::jsonb, NULL, NULL, 'Subjek jamak ''Urban planners'' + V3 ''prioritized'' + ''in recent decades'' membutuhkan ''have''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000714', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'reading', 'fill_blank', 'Pilih pertanyaan yang tepat untuk menanyakan titik waktu spesifik: You''ve already finished the data cleaning? Impressive—when ___ you start?', '{"options":["did","have","were","do"],"translation":"Kamu sudah menyelesaikan pembersihan datanya? Mengesankan—kapan kamu memulainya?","sentence_template":"You''ve already finished the data cleaning? Impressive—when [blank] you start?"}'::jsonb, '{"selected":"did"}'::jsonb, NULL, NULL, 'Kata tanya ''when'' tidak boleh diikuti Present Perfect; gunakan ''when did you start?''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000715', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan pembaruan manajer logistik dalam rapat operasional ini. Apa perbedaan pengiriman bulan Oktober vs bulan November (bulan berjalan)?', '{"options":[{"id":"opt_1","text":"Pengiriman bulan November mengalami lebih banyak keterlambatan daripada Oktober"},{"id":"opt_2","text":"Bulan Oktober (sudah lewat) terjadi tiga keterlambatan pelabuhan, tetapi sejauh bulan November ini setiap kontainer tiba tepat jadwal"},{"id":"opt_3","text":"Semua pengiriman dihentikan selama bulan November"},{"id":"opt_4","text":"Pelabuhan ditutup sejak awal Oktober"}],"audio_text":"In October we experienced three port delays, but so far in November every single container has arrived right on schedule."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Bulan Oktober sudah berlalu (''experienced''), sedangkan November masih berjalan (''so far in November ... has arrived'').', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000716', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti pascadoktoral di kantin kampus berikut. Apa yang kita ketahui tentang masa tinggal Dr. Lin di Toronto?', '{"options":[{"id":"opt_1","text":"Dr. Lin saat ini masih tinggal di Kanada"},{"id":"opt_2","text":"Dr. Lin dulu tinggal di Kanada selama lima tahun saat S3, dan sekarang sudah pindah ke lab di Boston"},{"id":"opt_3","text":"Dr. Lin belum pernah mengunjungi Kanada"},{"id":"opt_4","text":"Dr. Lin baru akan memulai S3-nya di Montreal bulan depan"}],"audio_text":"Did you know Dr. Lin speaks fluent French? — Yes! She did her PhD in Montreal and lived in Canada for five years before joining our Boston lab."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Penggunaan Past Simple ''did her PhD ... and lived in Canada for five years'' menegaskan masa tinggal di Kanada sudah berakhir.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000717', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat laporan metrik produk: "Aplikasi seluler kita telah mencapai seratus ribu unduhan minggu ini."', '{"romaji":"/ˈaʊər ˈmoʊbəl æp hæz riːtʃt wʌn ˈhʌndrəd ˈθaʊzənd ˈdaʊnloʊdz ðɪs wiːk/","tokens":["reached one","app has","downloads this week.","have reached","Our mobile","hundred thousand","reached in"],"target_translation":"Aplikasi seluler kita telah mencapai seratus ribu unduhan minggu ini."}'::jsonb, '["Our mobile","app has","reached one","hundred thousand","downloads this week."]'::jsonb, NULL, NULL, '''This week'' (jendela waktu terbuka) + subjek tunggal ''Our mobile app'' -> ''has reached''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000718', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat tindak lanjut rapat kemarin: "Saya mengirimkan notulen rapat kepada seluruh peserta kemarin sore."', '{"romaji":"/aɪ sent ðə ˈmiːtɪŋ ˈmɪnɪts tə ɔːl əˌtenˈdiːz ˈjestərdeɪ ˌæftərˈnuːn/","tokens":["I sent","the meeting","yesterday afternoon.","minutes to","all attendees","sends","have sent"],"target_translation":"Saya mengirimkan notulen rapat kepada seluruh peserta kemarin sore."}'::jsonb, '["I sent","the meeting","minutes to","all attendees","yesterday afternoon."]'::jsonb, NULL, NULL, '''Meeting minutes'' berarti notulen rapat resmi, dan ''yesterday afternoon'' mewajibkan Past Simple ''sent''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000719', 'e4100001-0000-4000-8000-000000000087', 'e2000001-0000-4000-8000-000000000021', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pembuka wawancara kerja ini dengan intonasi meyakinkan: "Selama tiga tahun terakhir, saya telah membangun sistem pembayaran untuk bisnis kecil."', '{"romaji":"/ˈoʊvər ðə pæst θriː jɪrz, aɪv bɪlt ˈpeɪmənt ˈsɪstəmz fɔːr smɔːl ˈbɪznəsɪz/","display_text":"Over the past three years, I''ve built payment systems for small businesses.","phonetic_breakdown":["ˈoʊ-vər","ðə","pæst","θriː","jɪrz","aɪv","bɪlt","ˈpeɪ-mənt","ˈsɪs-təmz","fɔːr","smɔːl","ˈbɪz-nə-sɪz"]}'::jsonb, '{"expected_transcript":"Over the past three years, I''ve built payment systems for small businesses."}'::jsonb, NULL, NULL, 'V3 dari ''build'' adalah ''built'' (/bɪlt/—huruf ''u'' tidak dibaca).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000720', 'e4100001-0000-4000-8000-000000000088', NULL, 'reading', 'fill_blank', 'Hindari jebakan memakai ''am/is/are'' bersama durasi ''for forty minutes'': Excuse me, we ___ for our table for forty minutes—could you check the waitlist?', '{"options":["have been waiting","are waiting","waited ago","has been waiting"],"translation":"Permisi, kami sudah menunggu meja kami selama empat puluh menit—bisakah Anda mengecek daftar tunggunya?","sentence_template":"Excuse me, we [blank] for our table for forty minutes—could you check the waitlist?"}'::jsonb, '{"selected":"have been waiting"}'::jsonb, NULL, NULL, 'Aksi menunggu yang dimulai 40 menit lalu dan masih berlangsung detik ini wajib memakai ''have been waiting'' (bukan ''are waiting'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000721', 'e4100001-0000-4000-8000-000000000088', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk subjek tunggal ''Dr. Morales'': Dr. Morales ___ clinical trials on mRNA vaccines since 2019.', '{"options":["has been conducting","have been conducting","is conducting since","conducted since"],"translation":"Dr. Morales telah terus menjalankan uji klinis vaksin mRNA sejak tahun 2019.","sentence_template":"Dr. Morales [blank] clinical trials on mRNA vaccines since 2019."}'::jsonb, '{"selected":"has been conducting"}'::jsonb, NULL, NULL, 'Subjek tunggal ''Dr. Morales'' + aktivitas riset berkelanjutan sejak 2019 memakai ''has been conducting''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000722', 'e4100001-0000-4000-8000-000000000088', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat cuaca yang masih berlangsung di luar jendela: Grab an umbrella—it ___ steadily since six this morning.', '{"options":["has been raining","rains","is raining since","rained since"],"translation":"Bawa payung—hujan terus turun sejak pukul enam pagi tadi.","sentence_template":"Grab an umbrella—it [blank] steadily since six this morning."}'::jsonb, '{"selected":"has been raining"}'::jsonb, NULL, NULL, 'Perintah ''Grab an umbrella'' menunjukkan hujan masih turun sekarang sejak jam 6 pagi -> ''has been raining''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000723', 'e4100001-0000-4000-8000-000000000088', NULL, 'listening', 'listening_choice', 'Dengarkan laporan anggota tim pada rapat Daily Standup ini. Apa yang terus dikerjakan pembicara sejak kemarin sore?', '{"options":[{"id":"opt_1","text":"Mendesain ulang halaman login dari awal"},{"id":"opt_2","text":"Terus mengoptimalkan kecepatan kueri pencarian sejak kemarin sore hingga waktu respons turun 30%"},{"id":"opt_3","text":"Baru akan mulai memeriksa kueri pencarian besok"},{"id":"opt_4","text":"Menghapus seluruh basis data pelanggan"}],"audio_text":"Since yesterday afternoon, I''ve been optimizing our search query speed, and response times are already down by thirty percent."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''ve been optimizing...'' menonjolkan fokus pengerjaan teknis yang intensif sejak kemarin sore hingga rapat berlangsung.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000724', 'e4100001-0000-4000-8000-000000000088', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan dua mahasiswa di ruang baca perpustakaan berikut. Berapa lama Bima sudah belajar untuk ujian statistiknya?', '{"options":[{"id":"opt_1","text":"Baru lima belas menit sejak makan siang"},{"id":"opt_2","text":"Sejak pukul sembilan pagi seharian meninjau model regresi statistik"},{"id":"opt_3","text":"Ia baru saja tiba di perpustakaan"},{"id":"opt_4","text":"Ia sedang menonton pertandingan basket di laptop"}],"audio_text":"Hey Bima, you look exhausted! How long have you been sitting in this cubicle? — Since nine a.m.! I''ve been reviewing regression models all day."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''How long have you been sitting...?'' dijawab dengan ''Since nine a.m.! I''ve been reviewing... all day.''', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000725', 'e4100001-0000-4000-8000-000000000088', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan durasi pencarian kerja: "Sudah berapa lama dia melamar posisi analis data?"', '{"romaji":"/haʊ lɔːŋ hæz ʃiː bɪn əˈplaɪɪŋ fɔːr ˈdeɪtə ˈænəlɪst roʊlz/","tokens":["How long","analyst roles?","for data","been applying","have she","is she","has she"],"target_translation":"Sudah berapa lama dia melamar posisi analis data?"}'::jsonb, '["How long","has she","been applying","for data","analyst roles?"]'::jsonb, NULL, NULL, 'Pola tanya orang ketiga tunggal: ''How long + has + she + been + V-ing?''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000726', 'e4100001-0000-4000-8000-000000000088', NULL, 'writing', 'sentence_builder', 'Susun kalimat diskusi kebijakan kampus: "Dewan mahasiswa telah mendiskusikan usulan parkir itu sepanjang minggu."', '{"romaji":"/ðə ˈstuːdənt ˈkaʊnsəl hæz bɪn dɪˈskʌsɪŋ ðæt ˈpɑːrkɪŋ prəˈpoʊzəl ɔːl wiːk/","tokens":["been discussing","that parking","discusses","The student","have been","proposal all week.","council has"],"target_translation":"Dewan mahasiswa telah mendiskusikan usulan parkir itu sepanjang minggu."}'::jsonb, '["The student","council has","been discussing","that parking","proposal all week."]'::jsonb, NULL, NULL, '''Discuss'' langsung diikuti objek tanpa ''about'' (''discussing that parking proposal'', bukan ''discussing about'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000727', 'e4100001-0000-4000-8000-000000000088', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pembaruan proyek ini dengan ritme mengalir (/aɪv bɪn/): "Saya terus mengerjakan dek presentasi investor sepanjang pagi."', '{"romaji":"/aɪv bɪn ˈwɜːrkɪŋ ɑːn ði ɪnˈvestər pɪtʃ dek ɔːl ˈmɔːrnɪŋ/","display_text":"I''ve been working on the investor pitch deck all morning.","phonetic_breakdown":["aɪv","bɪn","ˈwɜːr-kɪŋ","ɑːn","ði","ɪn-ˈves-tər","pɪtʃ","dek","ɔːl","ˈmɔːr-nɪŋ"]}'::jsonb, '{"expected_transcript":"I''ve been working on the investor pitch deck all morning."}'::jsonb, NULL, NULL, '''Pitch deck'' adalah istilah standar startup AS untuk materi salindia presentasi bisnis kepada investor.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000728', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Perhatikan adanya hitungan kuantitas selesai (''six journal articles''): For my literature review, I ___ six peer-reviewed journal articles since Monday.', '{"options":["have read","have been reading","am reading","readed"],"translation":"Untuk tinjauan pustaka saya, saya telah selesai membaca enam artikel jurnal ilmiah sejak hari Senin.","sentence_template":"For my literature review, I [blank] six peer-reviewed journal articles since Monday."}'::jsonb, '{"selected":"have read"}'::jsonb, NULL, NULL, 'Ketika jumlah benda yang diselesaikan disebut secara spesifik (''six journal articles''), gunakan Present Perfect Simple (''have read'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000729', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Waspadai aturan Stative Verb untuk kata kerja ''belong'' (milik): That brick laboratory near the river ___ to the chemistry department since 1968.', '{"options":["has belonged","has been belonging","is belonging","belongs since"],"translation":"Laboratorium bata di dekat sungai itu telah menjadi milik jurusan kimia sejak tahun 1968.","sentence_template":"That brick laboratory near the river [blank] to the chemistry department since 1968."}'::jsonb, '{"selected":"has belonged"}'::jsonb, NULL, NULL, '''Belong'' adalah stative verb (kepemilikan, bukan aksi fisik), sehingga tidak pernah berbentuk ''-ing''; gunakan ''has belonged''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000730', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang menonjolkan aktivitas tanpa henti sepanjang sore (tanpa angka kuantitas): Our support engineers ___ customer tickets nonstop all afternoon.', '{"options":["have been answering","has been answering","are answering since","answered so far"],"translation":"Para insinyur dukungan kami terus menjawab tiket bantuan pelanggan tanpa henti sepanjang sore.","sentence_template":"Our support engineers [blank] customer tickets nonstop all afternoon."}'::jsonb, '{"selected":"have been answering"}'::jsonb, NULL, NULL, 'Penekanan pada durasi proses intensif (''nonstop all afternoon'') untuk subjek jamak memakai ''have been answering''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000731', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan percakapan editor dan penulis konten berikut. Berapa bab panduan pengguna yang sudah rampung ditulis?', '{"options":[{"id":"opt_1","text":"Belum ada satu bab pun yang selesai ditulis"},{"id":"opt_2","text":"Ia telah menyusunnya sepanjang minggu (proses) dan sudah menuntaskan empat dari lima bab sejauh ini (kuantitas)"},{"id":"opt_3","text":"Seluruh sepuluh bab sudah dicetak bulan lalu"},{"id":"opt_4","text":"Proyek panduan pengguna dibatalkan hari ini"}],"audio_text":"How''s the user guide coming along? — Great! I''ve been drafting it all week, and I''ve completed four out of five chapters so far."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Contoh kontras sempurna dalam satu kalimat kerja nyata: ''I''ve been drafting it all week'' (proses) + ''I''ve completed four out of five chapters'' (kuantitas selesai).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000732', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan obrolan tetangga apartemen di Seattle ini. Sudah berapa lama keluarga Pak Ramirez memiliki kedai roti tersebut?', '{"options":[{"id":"opt_1","text":"Baru buka dua minggu yang lalu"},{"id":"opt_2","text":"Orang tuanya telah memiliki kedai roti itu selama dua puluh dua tahun"},{"id":"opt_3","text":"Kedai roti tersebut sudah dijual kepada perusahaan lain"},{"id":"opt_4","text":"Mereka hanya menyewa stan akhir pekan selama sebulan"}],"audio_text":"This sourdough bread is incredible! How long has your family had this bakery? — Thank you! My parents have owned it for twenty-two years."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Baik ''had'' (kepemilikan) maupun ''owned'' adalah stative verbs, sehingga keduanya memakai Present Perfect Simple (''has had'', ''have owned'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000733', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat kuantitas percobaan menghubungi: "Saya sudah menelepon kantor pajak tiga kali pagi ini."', '{"romaji":"/aɪ hæv kɔːld ðə tæks ˈɔːfɪs θriː taɪmz ðɪs ˈmɔːrnɪŋ/","tokens":["I have","three times","been calling","called the","this morning.","tax office","has called"],"target_translation":"Saya sudah menelepon kantor pajak tiga kali pagi ini."}'::jsonb, '["I have","called the","tax office","three times","this morning."]'::jsonb, NULL, NULL, 'Keterangan frekuensi angka (''three times'') wajib memakai Present Perfect Simple ''I have called''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000734', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat negosiasi yang masih berlangsung: "Kedua perusahaan telah menegosiasikan kemitraan itu sejak bulan Januari."', '{"romaji":"/boʊθ ˈkʌmpəniz hæv bɪn nɪˈɡoʊʃieɪtɪŋ ðæt ˈpɑːrtnərʃɪp sɪns ˈdʒænjueri/","tokens":["negotiate","negotiating that","since January.","Both companies","partnership","has been","have been"],"target_translation":"Kedua perusahaan telah menegosiasikan kemitraan itu sejak bulan Januari."}'::jsonb, '["Both companies","have been","negotiating that","partnership","since January."]'::jsonb, NULL, NULL, 'Proses perundingan yang masih berjalan sejak Januari memakai ''have been negotiating''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000735', 'e4100001-0000-4000-8000-000000000089', 'e2000001-0000-4000-8000-000000000022', 'speaking', 'speaking_repeat', 'Ucapkan kalimat gabungan proses dan hasil ini dengan lafal US process (/ˈprɑːses/): "Kami terus menyempurnakan proses orientasi, dan kami telah memangkas waktu pelatihan hingga setengahnya."', '{"romaji":"/wiːv bɪn rɪˈfaɪnɪŋ ði ˈɑːnbɔːrdɪŋ ˈprɑːses, ænd wiːv kʌt ˈtreɪnɪŋ taɪm ɪn hæf/","display_text":"We''ve been refining the onboarding process, and we''ve cut training time in half.","phonetic_breakdown":["wiːv","bɪn","rɪ-ˈfaɪ-nɪŋ","ði","ˈɑːn-bɔːr-dɪŋ","ˈprɑː-ses","ænd","wiːv","kʌt","ˈtreɪ-nɪŋ","taɪm","ɪn","hæf"]}'::jsonb, '{"expected_transcript":"We''ve been refining the onboarding process, and we''ve cut training time in half."}'::jsonb, NULL, NULL, 'V1, V2, dan V3 dari ''cut'' semuanya sama (''cut''), dan ''cut [something] in half'' adalah idiom bisnis AS untuk memangkas 50%.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000736', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk menjelaskan alasan mengapa suara pembicara serak sekarang: Excuse my hoarse voice—I ___ at our career fair booth for six hours straight!', '{"options":["have been talking","talk","am talking for","has been talking"],"translation":"Maafkan suara serak saya—saya habis berbicara di stan bursa karier kami selama enam jam berturut-turut!","sentence_template":"Excuse my hoarse voice—I [blank] at our career fair booth for six hours straight!"}'::jsonb, '{"selected":"have been talking"}'::jsonb, NULL, NULL, 'Efek fisik saat ini (''hoarse voice'' = suara serak) akibat aktivitas panjang yang baru usai memakai ''have been talking''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000737', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Lengkapi tebakan berdasarkan bukti jalanan yang tertutup salju tebal pagi ini: Look at all that snow on the cars! It ___ all night.', '{"options":["has been snowing","snows","is snowing all night","have been snowing"],"translation":"Lihat tebalnya salju di atas mobil-mobil itu! Pasti semalaman terus turun salju.","sentence_template":"Look at all that snow on the cars! It [blank] all night."}'::jsonb, '{"selected":"has been snowing"}'::jsonb, NULL, NULL, 'Bukti fisik yang terlihat sekarang akibat proses semalaman dijelaskan dengan ''It has been snowing''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000738', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Pilih kalimat pembuka permintaan maaf profesional saat baru sempat membalas pesan rekan: Sorry I missed your Slack message—I ___ a production outage with DevOps.', '{"options":["have been troubleshooting","troubleshoot","has been troubleshooting","am troubleshoot"],"translation":"Maaf saya melewatkan pesan Slack-mu—barusan saya terus menangani gangguan server produksi bersama tim DevOps.","sentence_template":"Sorry I missed your Slack message—I [blank] a production outage with DevOps."}'::jsonb, '{"selected":"have been troubleshooting"}'::jsonb, NULL, NULL, '''Have been troubleshooting'' menjelaskan kesibukan intensif yang baru saja menyita perhatian pembicara.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000739', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan obrolan teman sekamar saat melihat banyak buku berserakan di meja ruang tamu ini. Apa yang baru saja dikerjakan Tari?', '{"options":[{"id":"opt_1","text":"Ia sedang mengemas barang untuk pindah apartemen"},{"id":"opt_2","text":"Ia habis menyusun sumber referensi untuk makalah hukum tata negaranya sehingga meja penuh catatan tempel"},{"id":"opt_3","text":"Ia baru saja membeli meja belajar bekas"},{"id":"opt_4","text":"Teman sekamarnya yang membuat meja berantakan"}],"audio_text":"Whoa, there are sticky notes and highlighters everywhere! — Haha, sorry about the mess! I''ve been organizing my sources for my constitutional law paper."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Meja yang penuh sticky notes dijelaskan penyebabnya dengan ''I''ve been organizing my sources...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000740', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan analisis manajer pemasaran dalam rapat tinjauan mingguan berikut. Tren baru apa yang terus mereka amati akhir-akhir ini?', '{"options":[{"id":"opt_1","text":"Pendaftaran dari mahasiswa universitas turun drastis bulan ini"},{"id":"opt_2","text":"Akhir-akhir ini mereka terus melihat lonjakan pendaftaran dari mahasiswa Indonesia setelah penambahan panduan belajar dwibahasa"},{"id":"opt_3","text":"Panduan belajar dwibahasa dihapus dari aplikasi"},{"id":"opt_4","text":"Tim pemasaran berhenti memantau data pendaftaran"}],"audio_text":"Lately, we''ve been seeing a noticeable jump in sign-ups from Indonesian university students, especially after we added bilingual study guides."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Lately, we''ve been seeing...'' digunakan secara luas di bisnis AS untuk mendeskripsikan tren data yang sedang berkembang.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000741', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat penjelasan mata lelah: "Mata saya terasa kering karena saya terus mengedit hamparan angka."', '{"romaji":"/maɪ aɪz fiːl draɪ bɪˈkɔːz aɪv bɪn ˈedɪtɪŋ ˈspredʃiːts/","tokens":["feel dry","My eyes","spreadsheets.","been editing","edit","has been","because I''ve"],"target_translation":"Mata saya terasa kering karena saya terus mengedit hamparan angka."}'::jsonb, '["My eyes","feel dry","because I''ve","been editing","spreadsheets."]'::jsonb, NULL, NULL, 'Efek sekarang (''My eyes feel dry'') + penyebab berdurasi (''because I''ve been editing spreadsheets'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000742', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun pertanyaan berdasarkan pengamatan positif: "Bahasa Inggrismu terdengar sangat lancar—apakah kamu terus berlatih setiap hari?"', '{"romaji":"/jʊr ˈɪŋɡlɪʃ saʊndz ɡreɪt—hæv juː bɪn ˈpræktɪsɪŋ ˈevri deɪ/","tokens":["has you","practice","you been","every day?","sounds great—have","practicing","Your English"],"target_translation":"Bahasa Inggrismu terdengar sangat lancar—apakah kamu terus berlatih setiap hari?"}'::jsonb, '["Your English","sounds great—have","you been","practicing","every day?"]'::jsonb, NULL, NULL, 'Pujian atas hasil yang terdengar sekarang dihubungkan ke kebiasaan latihan baru-baru ini (''have you been practicing...?'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000743', 'e4100001-0000-4000-8000-000000000090', 'e2000001-0000-4000-8000-000000000022', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kolaborasi kerja ini dengan intonasi hangat: "Maaf atas keterlambatannya—tadi saya terus menghadiri rapat beruntun."', '{"romaji":"/ˈsɑːri fɔːr ðə dɪˈleɪ—aɪv bɪn ɪn ˈmiːtɪŋz bæk tə bæk/","display_text":"Sorry for the delay—I''ve been in meetings back to back.","phonetic_breakdown":["ˈsɑːr-i","fɔːr","ðə","dɪ-ˈleɪ","aɪv","bɪn","ɪn","ˈmiː-tɪŋz","bæk","tə","bæk"]}'::jsonb, '{"expected_transcript":"Sorry for the delay—I''ve been in meetings back to back."}'::jsonb, NULL, NULL, 'Idiom kantor AS ''back to back'' berarti beruntun sambung-menyambung tanpa jeda istirahat!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000744', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Pilih antara Present Perfect Simple vs Continuous saat ada angka kuantitas (''three mock exams''): Raka ___ three full-length TOEFL mock exams so far this month.', '{"options":["has taken","has been taking","is taking","have taken"],"translation":"Raka telah menyelesaikan tiga ujian simulasi penuh TOEFL sejauh bulan ini.","sentence_template":"Raka [blank] three full-length TOEFL mock exams so far this month."}'::jsonb, '{"selected":"has taken"}'::jsonb, NULL, NULL, 'Angka hasil tuntas (''three full-length TOEFL mock exams'') mewajibkan Present Perfect Simple tunggal ''has taken''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000745', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Ingat aturan Stative Verb untuk ''know'': Even though we work in different time zones, I ___ Elena for more than five years.', '{"options":["have known","have been knowing","am knowing","knew since"],"translation":"Meskipun kami bekerja di zona waktu berbeda, saya sudah mengenal Elena selama lebih dari lima tahun.","sentence_template":"Even though we work in different time zones, I [blank] Elena for more than five years."}'::jsonb, '{"selected":"have known"}'::jsonb, NULL, NULL, 'Kata kerja mental/relasi ''know'' dilarang memakai bentuk ''-ing'', sehingga wajib ''have known''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000746', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang menonjolkan proses menunggu yang masih berlangsung sekarang: The passengers ___ at Gate B4 for two hours because of thick fog in San Francisco.', '{"options":["have been waiting","has been waiting","are waiting for","waited since"],"translation":"Para penumpang sudah menunggu di Gerbang B4 selama dua jam karena kabut tebal di San Francisco.","sentence_template":"The passengers [blank] at Gate B4 for two hours because of thick fog in San Francisco."}'::jsonb, '{"selected":"have been waiting"}'::jsonb, NULL, NULL, 'Subjek jamak ''The passengers'' + durasi hingga kini ''for two hours'' memakai ''have been waiting''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000747', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan penjelasan peneliti biologi laut pada kuliah tamu ini. Apa fokus pengamatan timnya selama tiga musim panas terakhir?', '{"options":[{"id":"opt_1","text":"Menangkap ikan salmon untuk restoran di Alaska"},{"id":"opt_2","text":"Terus melacak rute migrasi paus bungkuk di sepanjang pesisir Alaska menggunakan penanda satelit selama tiga musim panas terakhir"},{"id":"opt_3","text":"Penelitian paus bungkuk sudah dihentikan sepuluh tahun lalu"},{"id":"opt_4","text":"Membangun akuarium wisata di pusat kota"}],"audio_text":"For the past three summers, our marine team has been tracking humpback whale migration routes along the Alaska coast using satellite tags."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Has been tracking... for the past three summers'' khas gaya pemaparan riset lapangan berkelanjutan pada TOEFL Listening.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000748', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan di dapur kantor berikut. Mengapa tangan Kevin berbau biji kopi segar?', '{"options":[{"id":"opt_1","text":"Kevin baru saja menumpahkan kopi ke laptopnya"},{"id":"opt_2","text":"Kevin habis mengalibrasi mesin espresso baru di ruang istirahat (proses) dan sudah membuat dua latte uji coba (kuantitas)"},{"id":"opt_3","text":"Mesin espresso di ruang istirahat rusak total"},{"id":"opt_4","text":"Kevin membeli kopi kalengan dari minimarket"}],"audio_text":"Something smells amazing! — Haha, yeah, I''ve been calibrating the new espresso machine in the break room, and I''ve already made two test lattes."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kembali memadukan ''I''ve been calibrating...'' (penyebab aroma kopi sekarang) dan ''I''ve already made two test lattes'' (jumlah hasil).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000749', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat laporan durasi negosiasi sewa: "Kami terus merundingkan pembaruan kontrak sewa kantor sejak bulan April."', '{"romaji":"/wiːv bɪn dɪˈskʌsɪŋ ði ˈɔːfɪs liːs rɪˈnuːəl sɪns ˈeɪprəl/","tokens":["office lease","discussing the","discussing about","has been","since April.","renewal","We''ve been"],"target_translation":"Kami terus merundingkan pembaruan kontrak sewa kantor sejak bulan April."}'::jsonb, '["We''ve been","discussing the","office lease","renewal","since April."]'::jsonb, NULL, NULL, '''We''ve been discussing...'' (tanpa ''about''!) + ''since April''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000750', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'writing', 'sentence_builder', 'Susun pertanyaan tentang kegiatan belajar teman: "Sudah berapa lama kamu mempersiapkan ujian sertifikasi cloud itu?"', '{"romaji":"/haʊ lɔːŋ hæv juː bɪn prɪˈperɪŋ fɔːr ðæt klaʊd ˌsɜːrtɪfɪˈkeɪʃən/","tokens":["How long","cloud certification?","do you","prepared","been preparing","for that","have you"],"target_translation":"Sudah berapa lama kamu mempersiapkan ujian sertifikasi cloud itu?"}'::jsonb, '["How long","have you","been preparing","for that","cloud certification?"]'::jsonb, NULL, NULL, '''How long have you been preparing for...?'' menanyakan durasi persiapan yang masih berjalan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000751', 'e4100001-0000-4000-8000-000000000091', 'e2000001-0000-4000-8000-000000000022', 'speaking', 'speaking_repeat', 'Ucapkan kalimat laporan fokus kerja ini dengan jelas: "Tim kami terus menguji fitur aksesibilitas baru sepanjang minggu ini."', '{"romaji":"/ˈaʊər tiːm hæz bɪn ˈtestɪŋ ðə nuː ækˌsesəˈbɪləti ˈfiːtʃərz ɔːl wiːk/","display_text":"Our team has been testing the new accessibility features all week.","phonetic_breakdown":["ˈaʊ-ər","tiːm","hæz","bɪn","ˈtes-tɪŋ","ðə","nuː","æk-ˌse-sə-ˈbɪ-lə-ti","ˈfiː-tʃərz","ɔːl","wiːk"]}'::jsonb, '{"expected_transcript":"Our team has been testing the new accessibility features all week."}'::jsonb, NULL, NULL, 'Latih ketukan suku kata ''accessibility'' (/ækˌsesəˈbɪləti/)—kosakata penting di dunia produk modern!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000752', 'e4100001-0000-4000-8000-000000000092', NULL, 'reading', 'fill_blank', 'Terapkan aturan First Conditional (ingat subjek tunggal ''our grant proposal''): If our grant proposal ___ approved next month, we''ll hire two research assistants.', '{"options":["gets","will get","got","would get"],"translation":"Jika proposal hibah kita disetujui bulan depan, kita akan merekrut dua asisten peneliti.","sentence_template":"If our grant proposal [blank] approved next month, we''ll hire two research assistants."}'::jsonb, '{"selected":"gets"}'::jsonb, NULL, NULL, 'Kemungkinan nyata bulan depan memakai Present Simple tunggal ''gets'' di dalam klausa ''If'' (bukan ''will get'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000753', 'e4100001-0000-4000-8000-000000000092', NULL, 'reading', 'fill_blank', 'Pilih penghubung syarat yang berarti ''kecuali jika'' (diikuti kata kerja positif): You won''t get a full tuition refund ___ you drop the course before Friday''s deadline.', '{"options":["unless","in case","although","despite"],"translation":"Anda tidak akan mendapat pengembalian penuh uang kuliah kecuali jika Anda membatalkan mata kuliah itu sebelum tenggat hari Jumat.","sentence_template":"You won''t get a full tuition refund [blank] you drop the course before Friday''s deadline."}'::jsonb, '{"selected":"unless"}'::jsonb, NULL, NULL, '''Unless you drop...'' setara dengan ''if you do not drop...''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000754', 'e4100001-0000-4000-8000-000000000092', NULL, 'reading', 'fill_blank', 'Bedakan tindakan antisipasi ''berjaga-jaga kalau nanti'' dengan ''if'': Let''s download the offline slides onto a USB drive ___ the conference Wi-Fi fails.', '{"options":["in case","unless","as long as","so that"],"translation":"Mari mengunduh salindia luring ke diska lepas USB untuk berjaga-jaga kalau Wi-Fi konferensi mati.","sentence_template":"Let''s download the offline slides onto a USB drive [blank] the conference Wi-Fi fails."}'::jsonb, '{"selected":"in case"}'::jsonb, NULL, NULL, 'Kita mengunduhnya SEKARANG sebagai antisipasi sebelum Wi-Fi benar-benar gagal -> gunakan ''in case''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000755', 'e4100001-0000-4000-8000-000000000092', NULL, 'listening', 'listening_choice', 'Dengarkan kebijakan manajer teknik tentang kerja jarak jauh dari luar negeri ini. Apa syarat utamanya?', '{"options":[{"id":"opt_1","text":"Karyawan dilarang bekerja dari luar Amerika Serikat dalam kondisi apa pun"},{"id":"opt_2","text":"Diperbolehkan hingga empat minggu setahun asalkan disetujui ketua tim dan ada irisan jam kerja tiga jam dengan Waktu Pasifik"},{"id":"opt_3","text":"Boleh bekerja dari luar negeri selama satu tahun penuh tanpa izin"},{"id":"opt_4","text":"Harus mengambil cuti tanpa gaji selama empat minggu"}],"audio_text":"You can work from Indonesia for up to four weeks a year, as long as your team lead approves the dates and there''s a three-hour overlap with Pacific Time."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''As long as...'' menetapkan dua syarat spesifik yang harus dipenuhi agar izin berlaku.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000756', 'e4100001-0000-4000-8000-000000000092', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan persiapan pameran dagang di Las Vegas berikut. Mengapa pembicara wanita mencetak brosur cadangan ekstra?', '{"options":[{"id":"opt_1","text":"Karena mereka tidak punya situs web perusahaan"},{"id":"opt_2","text":"Untuk berjaga-jaga seandainya jumlah pengunjung stan pameran (''foot traffic'') lebih ramai dari perkiraan"},{"id":"opt_3","text":"Karena semua brosur sebelumnya basah kehujanan"},{"id":"opt_4","text":"Karena panitia mewajibkan seribu brosur per meja"}],"audio_text":"Should we print fifty extra brochures? — Definitely! Let''s pack an extra box in case foot traffic at our booth is heavier than expected."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Istilah bisnis ''foot traffic'' berarti arus pengunjung fisik, dan ''in case...'' menjelaskan alasan tindakan berjaga-jaga.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000757', 'e4100001-0000-4000-8000-000000000092', NULL, 'writing', 'sentence_builder', 'Susun kalimat peringatan tenggat pendaftaran: "Pendaftaran Anda akan dibatalkan kecuali jika Anda membayar sebelum tengah malam."', '{"romaji":"/jʊr ˌredʒɪˈstreɪʃən wɪl biː ˈkænsəld ənˈles juː peɪ bɪˈfɔːr ˈmɪdnaɪt/","tokens":["don''t pay","unless you","will be canceled","pay before","will pay","midnight.","Your registration"],"target_translation":"Pendaftaran Anda akan dibatalkan kecuali jika Anda membayar sebelum tengah malam."}'::jsonb, '["Your registration","will be canceled","unless you","pay before","midnight."]'::jsonb, NULL, NULL, 'Perhatikan ejaan standar Amerika ''canceled'' (satu huruf ''l''!), dan setelah ''unless'' gunakan positif ''you pay''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000758', 'e4100001-0000-4000-8000-000000000092', NULL, 'writing', 'sentence_builder', 'Susun kalimat tindak lanjut teknis: "Jika Anda menemui kendala apa pun, kirimkan pesan kepada saya di Slack."', '{"romaji":"/ɪf juː rʌn ˈɪntə ˈeni ˈɪʃuːz, ˈmesɪdʒ miː ɑːn slæk/","tokens":["issues","will run","on Slack.","If you","run into","message me","any issues,"],"target_translation":"Jika Anda menemui kendala apa pun, kirimkan pesan kepada saya di Slack."}'::jsonb, '["If you","run into","any issues,","message me","on Slack."]'::jsonb, NULL, NULL, 'Phrasal verb ''run into issues'' = mengalami kendala tak terduga; klausa utama menggunakan kalimat perintah sopan.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000759', 'e4100001-0000-4000-8000-000000000092', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat negosiasi jadwal ini dengan jelas: "Jika kita merampungkan desainnya hari ini, kita bisa mulai pengujian pada hari Rabu."', '{"romaji":"/ɪf wiː ˈfaɪnəlaɪz ðə dɪˈzaɪn təˈdeɪ, wiː kən stɑːrt ˈtestɪŋ ɑːn ˈwenzdeɪ/","display_text":"If we finalize the design today, we can start testing on Wednesday.","phonetic_breakdown":["ɪf","wiː","ˈfaɪ-nə-laɪz","ðə","dɪ-ˈzaɪn","tə-ˈdeɪ","wiː","kən","stɑːrt","ˈtes-tɪŋ","ɑːn","ˈwenz-deɪ"]}'::jsonb, '{"expected_transcript":"If we finalize the design today, we can start testing on Wednesday."}'::jsonb, NULL, NULL, 'Ingat pelafalan ''Wednesday'' hanya 2 suku kata (/ˈwenzdeɪ/ — huruf ''d'' pertama dan ''e'' tengah bisu)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000760', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Pilih bentuk Second Conditional yang tepat (fakta saat ini: harga sewa di Manhattan sangat mahal): If rent in Manhattan ___ more affordable, more artists would live near Midtown.', '{"options":["were","will be","is","would be"],"translation":"Seandainya harga sewa di Manhattan lebih terjangkau, lebih banyak seniman akan tinggal di dekat Midtown.","sentence_template":"If rent in Manhattan [blank] more affordable, more artists would live near Midtown."}'::jsonb, '{"selected":"were"}'::jsonb, NULL, NULL, 'Pengandaian yang berlawanan dengan fakta saat ini + klausa hasil ''would live'' mewajibkan subjunctive ''were'' (dan dilarang ''would be'' di dalam klausa ''If'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000761', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Lengkapi klausa hasil Second Conditional berikut: If our campus shuttle ran every ten minutes instead of every hour, fewer students ___ to class.', '{"options":["would drive","will drive","drove","drive"],"translation":"Seandainya bus kampus kita beroperasi tiap sepuluh menit alih-alih tiap jam, lebih sedikit mahasiswa yang akan menyetir mobil ke kelas.","sentence_template":"If our campus shuttle ran every ten minutes instead of every hour, fewer students [blank] to class."}'::jsonb, '{"selected":"would drive"}'::jsonb, NULL, NULL, 'Klausa ''If + Past Simple (ran)'' berpasangan dengan klausa utama ''would + V1 (would drive)''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000762', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Pilih bentuk Past Simple di dalam pertanyaan hipotesis wawancara kerja: How would you prioritize tasks if two managers ___ you urgent requests at the same time?', '{"options":["gave","give","will give","would give"],"translation":"Bagaimana Anda akan memprioritaskan tugas seandainya dua manajer memberi Anda permintaan mendesak secara bersamaan?","sentence_template":"How would you prioritize tasks if two managers [blank] you urgent requests at the same time?"}'::jsonb, '{"selected":"gave"}'::jsonb, NULL, NULL, 'Pertanyaan hipotesis ''How would you... if...'' menggunakan Past Simple ''gave'' setelah ''if''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000763', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan diskusi evaluasi produk antara dua desainer ini. Apa realitas masalah pada formulir pendaftaran mereka SAAT INI?', '{"options":[{"id":"opt_1","text":"Formulir pendaftaran mereka saat ini hanya memiliki dua kolom singkat"},{"id":"opt_2","text":"Formulir pendaftaran mereka saat ini meminta sepuluh kolom terpisah di layar pertama sehingga banyak pengguna seluler batal di tengah jalan"},{"id":"opt_3","text":"Pengguna seluler tidak diizinkan mendaftar di aplikasi mereka"},{"id":"opt_4","text":"Mereka sudah menghapus formulir pendaftaran bulan lalu"}],"audio_text":"If our sign-up form didn''t ask for ten separate fields on the first screen, way fewer mobile users would abandon it halfway through."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kemampuan inferensi TOEFL B1: kalimat imajiner ''If our sign-up form didn''t ask for ten fields...'' membuktikan fakta kini bahwa formulir tersebut MEMANG meminta sepuluh kolom!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000764', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan nasihat mentor karier kepada rekannya yang ragu melamar promosi jabatan berikut. Apa saran mentornya?', '{"options":[{"id":"opt_1","text":"Menunggu lima tahun lagi sampai memenuhi 100% syarat"},{"id":"opt_2","text":"Mencoba melamar posisi analis senior karena sudah memenuhi 80% kualifikasi"},{"id":"opt_3","text":"Membeli sepatu kerja baru sebelum wawancara"},{"id":"opt_4","text":"Pindah ke divisi pemasaran"}],"audio_text":"Honestly, if I were in your shoes, I''d go for the senior analyst role—you already meet eighty percent of the requirements!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Idiom ''if I were in your shoes'' (= seandainya saya berada di posisimu) + ''go for [it]'' (= berani mencoba melamar).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000765', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat pengandaian efisiensi tim: "Seandainya kita mengotomatiskan laporan ini, kita bisa menghemat empat jam setiap minggu."', '{"romaji":"/ɪf wiː ˈɔːtəmeɪtɪd ðɪs rɪˈpɔːrt, wiː kʊd seɪv fɔːr ˈaʊərz ˈevri wiːk/","tokens":["automate","will save","If we","automated this","could save","report, we","four hours every week."],"target_translation":"Seandainya kita mengotomatiskan laporan ini, kita bisa menghemat empat jam setiap minggu."}'::jsonb, '["If we","automated this","report, we","could save","four hours every week."]'::jsonb, NULL, NULL, '''If we automated (V2)..., we could save (modal hipotesis + V1)...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000766', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun pertanyaan wawancara perilaku: "Apa yang akan Anda ubah seandainya Anda memimpin proyek ini?"', '{"romaji":"/wʌt wʊd juː tʃeɪndʒ ɪf juː led ðɪs ˈprɑːdʒekt/","tokens":["if you","you change","What would","will lead","led this","would lead","project?"],"target_translation":"Apa yang akan Anda ubah seandainya Anda memimpin proyek ini?"}'::jsonb, '["What would","you change","if you","led this","project?"]'::jsonb, NULL, NULL, '''What would you change if you led (V2 dari lead)...?''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000767', 'e4100001-0000-4000-8000-000000000093', 'e2000001-0000-4000-8000-000000000023', 'speaking', 'speaking_repeat', 'Ucapkan kalimat saran diplomatis ini dengan kontraksi alami I''d (/aɪd/): "Seandainya saya menjadi Anda, saya akan bernegosiasi untuk tanggal mulai yang fleksibel."', '{"romaji":"/ɪf aɪ wɜːr juː, aɪd nɪˈɡoʊʃieɪt fɔːr ə ˈfleksəbəl stɑːrt deɪt/","display_text":"If I were you, I''d negotiate for a flexible start date.","phonetic_breakdown":["ɪf","aɪ","wɜːr","juː","aɪd","nɪ-ˈɡoʊ-ʃi-eɪt","fɔːr","ə","ˈflek-sə-bəl","stɑːrt","deɪt"]}'::jsonb, '{"expected_transcript":"If I were you, I''d negotiate for a flexible start date."}'::jsonb, NULL, NULL, 'Kontraksi ''I''d'' untuk ''I would'' membuat kalimat Second Conditional terdengar luwes dan tidak kaku.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000768', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Konteks: kandidat SUDAH masuk babak final dan pengumuman keluar besok (peluang sangat nyata!): If they ___ me the fellowship tomorrow, I''ll celebrate with my family!', '{"options":["offer","offered","will offer","would offer"],"translation":"Jika mereka menawari saya beasiswa fellowship itu besok, saya akan merayakannya bersama keluarga saya!","sentence_template":"If they [blank] me the fellowship tomorrow, I''ll celebrate with my family!"}'::jsonb, '{"selected":"offer"}'::jsonb, NULL, NULL, 'Pasangan klausa utama ''I''ll celebrate'' dan peluang nyata besok mengunci klausa ''If'' ke First Conditional (''offer'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000769', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Konteks: manusia jelas tidak bisa hidup tanpa tidur (100% khayalan imajiner): If humans ___ need sleep, people would have eight extra hours every single day!', '{"options":["didn''t","don''t","won''t","wouldn''t"],"translation":"Seandainya manusia tidak membutuhkan tidur, orang-orang akan punya delapan jam ekstra setiap harinya!","sentence_template":"If humans [blank] need sleep, people would have eight extra hours every single day!"}'::jsonb, '{"selected":"didn''t"}'::jsonb, NULL, NULL, 'Fakta biologis mustahil + klausa utama ''would have'' mewajibkan Second Conditional (''didn''t need'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000770', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Pilih kata transisi yang berarti ''kalau tidak demikian'': Make sure you reserve Amtrak tickets early during Thanksgiving week; ___, every train will be sold out.', '{"options":["otherwise","unless","in case","although"],"translation":"Pastikan Anda memesan tiket kereta Amtrak lebih awal saat pekan Thanksgiving; kalau tidak, setiap kereta akan habis terjual.","sentence_template":"Make sure you reserve Amtrak tickets early during Thanksgiving week; [blank], every train will be sold out."}'::jsonb, '{"selected":"otherwise"}'::jsonb, NULL, NULL, 'Setelah titik koma (;) dan diikuti koma, ''otherwise,'' berarti ''jika tidak melakukan hal sebelumnya''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000771', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan sesi curah pendapat (brainstorming) tim produk berikut. Mengapa pembicara memakai ''What if we added...''?', '{"options":[{"id":"opt_1","text":"Fitur mode gelap sudah diluncurkan tahun lalu"},{"id":"opt_2","text":"Ia melontarkan usulan eksploratif secara tentatif untuk mendiskusikan kelayakan usaha dua hari kerja vs manfaat bagi pengguna malam"},{"id":"opt_3","text":"Ia melarang tim teknik membuat fitur mode gelap"},{"id":"opt_4","text":"Fitur mode gelap membutuhkan waktu pengerjaan enam bulan"}],"audio_text":"What if we added a dark-mode toggle in the next sprint? If it only took two days of engineering work, our night-owl readers would love it!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Penggunaan ''What if we added... If it only took..., readers would love it!'' adalah gaya brainstorming tentatif khas tim produk AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000772', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah astronomi dasar ala TOEFL ini. Apa yang akan terjadi pada suhu Bumi seandainya Bumi tidak memiliki atmosfer?', '{"options":[{"id":"opt_1","text":"Suhu permukaan Bumi akan meningkat hingga mendidih"},{"id":"opt_2","text":"Suhu rata-rata permukaan akan anjlok di bawah titik beku di seluruh penjuru planet"},{"id":"opt_3","text":"Bumi saat ini memang tidak memiliki atmosfer"},{"id":"opt_4","text":"Atmosfer Bumi baru akan terbentuk seribu tahun lagi"}],"audio_text":"If Earth didn''t have an atmosphere to trap heat, average surface temperatures would plunge below freezing across the entire planet."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dosen sains di kampus AS rutin menggunakan Second Conditional (''If Earth didn''t have..., temperatures would plunge...'') untuk menjelaskan fungsi fenomena alam lewat skenario kontrafaktual.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000773', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat permintaan izin yang ekstra halus: "Apakah tidak apa-apa seandainya saya bergabung ke panggilan itu dari ponsel saya?"', '{"romaji":"/wʊd ɪt biː oʊˈkeɪ ɪf aɪ dʒɔɪnd ðə kɔːl frʌm maɪ foʊn/","tokens":["if I","join","from my phone?","will join","be okay","Would it","joined the call"],"target_translation":"Apakah tidak apa-apa seandainya saya bergabung ke panggilan itu dari ponsel saya?"}'::jsonb, '["Would it","be okay","if I","joined the call","from my phone?"]'::jsonb, NULL, NULL, '''Would it be okay if I + Past Simple (joined)...?'' terdengar sangat sopan saat sedang dalam perjalanan.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000774', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat usulan rapat kolaboratif: "Bagaimana seandainya kita menguji ide ini pada kelompok kecil terlebih dahulu?"', '{"romaji":"/wʌt ɪf wiː ˈtestɪd ðɪs aɪˈdiːə wɪð ə smɔːl ɡruːp fɜːrst/","tokens":["with a small","group first?","What if","this idea","would test","testing","we tested"],"target_translation":"Bagaimana seandainya kita menguji ide ini pada kelompok kecil terlebih dahulu?"}'::jsonb, '["What if","we tested","this idea","with a small","group first?"]'::jsonb, NULL, NULL, '''What if we + Past Simple (tested)...?'' mengajak rekan menimbang ide secara terbuka.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000775', 'e4100001-0000-4000-8000-000000000094', 'e2000001-0000-4000-8000-000000000023', 'speaking', 'speaking_repeat', 'Ucapkan kalimat nasihat antisipatif ini dengan jelas: "Catat nomor konfirmasinya untuk berjaga-jaga kalau aplikasinya keluar sendiri."', '{"romaji":"/raɪt daʊn ðə ˌkɑːnfərˈmeɪʃən ˈnʌmbər ɪn keɪs ði æp lɔːɡz aʊt/","display_text":"Write down the confirmation number in case the app logs out.","phonetic_breakdown":["raɪt","daʊn","ðə","ˌkɑːn-fər-ˈmeɪ-ʃən","ˈnʌm-bər","ɪn","keɪs","ði","æp","lɔːɡz","aʊt"]}'::jsonb, '{"expected_transcript":"Write down the confirmation number in case the app logs out."}'::jsonb, NULL, NULL, 'Huruf ''w'' di awal ''write'' bisu (/raɪt/), dan ''in case the app logs out'' menjelaskan antisipasi cerdas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000776', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Pilih bentuk yang benar untuk Second Conditional subjunctive: If our office ___ closer to the subway line, commuting in winter would be much easier.', '{"options":["were","is","will be","would be"],"translation":"Seandainya kantor kita lebih dekat ke jalur kereta bawah tanah, perjalanan kerja di musim dingin akan jauh lebih mudah.","sentence_template":"If our office [blank] closer to the subway line, commuting in winter would be much easier."}'::jsonb, '{"selected":"were"}'::jsonb, NULL, NULL, 'Pengandaian berlawanan fakta kini + klausa utama ''would be'' membutuhkan ''were'' untuk standar formal/TOEFL.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000777', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Pilih penghubung yang tepat: The automated deployment pipeline won''t run ___ all unit tests pass with zero errors.', '{"options":["unless","in case","otherwise","despite"],"translation":"Alur perilisan otomatis tidak akan berjalan kecuali jika seluruh pengujian unit lulus tanpa galat.","sentence_template":"The automated deployment pipeline won''t run [blank] all unit tests pass with zero errors."}'::jsonb, '{"selected":"unless"}'::jsonb, NULL, NULL, '''Won''t run unless all unit tests pass'' = hanya akan berjalan jika semua tes lulus.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000778', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'reading', 'fill_blank', 'Cocokkan pasangan klausa First Conditional: If the keynote speaker finishes ten minutes early, we ___ more time for audience Q&A.', '{"options":["will have","would had","had","having"],"translation":"Jika pembicara utama selesai sepuluh menit lebih awal, kita akan punya lebih banyak waktu untuk tanya jawab audiens.","sentence_template":"If the keynote speaker finishes ten minutes early, we [blank] more time for audience Q&A."}'::jsonb, '{"selected":"will have"}'::jsonb, NULL, NULL, '''If + Present Simple (finishes)'' berpasangan dengan kemungkinan nyata masa depan ''will have''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000779', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan jawaban mahasiswa pascasarjana ketika ditanya topik riset impiannya berikut. Mengapa ia memakai ''would study''?', '{"options":[{"id":"opt_1","text":"Lab mereka sudah memetakan ventilasi hidrotermal bulan lalu"},{"id":"opt_2","text":"Saat ini anggaran hibah mereka belum mencukupi untuk membeli drone laut dalam sehingga proyek tersebut masih berupa pengandaian"},{"id":"opt_3","text":"Mereka tidak tertarik meneliti perairan Indonesia timur"},{"id":"opt_4","text":"Drone laut dalam sudah tiba di laboratorium kemarin"}],"audio_text":"If our lab had access to deep-sea autonomous drones, we would map hydrothermal vents in eastern Indonesia—right now the equipment is still beyond our grant budget."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kalimat penjelas ''right now the equipment is still beyond our grant budget'' mengonfirmasi mengapa pembicara memakai Second Conditional.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000780', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'listening', 'listening_choice', 'Dengarkan instruksi koordinator acara orientasi kampus ini. Ke mana acara barbeku akan dipindahkan jika sore nanti turun hujan?', '{"options":[{"id":"opt_1","text":"Acara akan langsung dibatalkan tanpa pengganti"},{"id":"opt_2","text":"Dipindahkan ke aula besar gedung kegiatan mahasiswa (student union ballroom) jika badai petir datang sore ini"},{"id":"opt_3","text":"Semua mahasiswa diminta pulang ke asrama masing-masing"},{"id":"opt_4","text":"Tetap diadakan di lapangan terbuka di tengah hujan"}],"audio_text":"Right now the sky looks clear, so we''re setting up on the main quad. However, if a thunderstorm rolls in this afternoon, we''ll move everything into the student union ballroom."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Rencana kontingensi nyata sore ini (''if a thunderstorm rolls in..., we''ll move...'') memakai First Conditional.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000781', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat nasihat karier klasik: "Seandainya saya menjadi Anda, saya akan meminta masukan tertulis dari penguji."', '{"romaji":"/ɪf aɪ wɜːr juː, aɪ wʊd æsk fɔːr ˈrɪtən ˈfiːdbæk/","tokens":["If I","were you,","feedbacks.","written feedback.","I would","was you,","ask for"],"target_translation":"Seandainya saya menjadi Anda, saya akan meminta masukan tertulis dari penguji."}'::jsonb, '["If I","were you,","I would","ask for","written feedback."]'::jsonb, NULL, NULL, 'Ingat dua aturan sekaligus: ''If I were you'' + uncountable ''feedback'' (tanpa -s!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000782', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat syarat fleksibilitas jadwal: "Anda boleh bertukar giliran jaga asalkan manajer Anda menyetujuinya."', '{"romaji":"/juː kən swɑːp ʃɪfts æz lɔːŋ æz jʊr ˈmænɪdʒər əˈpruːvz ɪt/","tokens":["approves it.","your manager","unless","swap shifts","as long as","will approve","You can"],"target_translation":"Anda boleh bertukar giliran jaga asalkan manajer Anda menyetujuinya."}'::jsonb, '["You can","swap shifts","as long as","your manager","approves it."]'::jsonb, NULL, NULL, '''Swap shifts'' = bertukar jadwal giliran kerja; setelah ''as long as'', gunakan Present Simple tunggal ''approves''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000783', 'e4100001-0000-4000-8000-000000000095', 'e2000001-0000-4000-8000-000000000023', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pengandaian negosiasi ini dengan lancar: "Seandainya kita memperpanjang tenggat dua hari, kualitasnya akan jauh lebih baik."', '{"romaji":"/ɪf wiː ɪkˈstendɪd ðə ˈdedlaɪn baɪ tuː deɪz, ðə ˈkwɑːləti wʊd biː mʌtʃ ˈbetər/","display_text":"If we extended the deadline by two days, the quality would be much better.","phonetic_breakdown":["ɪf","wiː","ɪk-ˈsten-dɪd","ðə","ˈded-laɪn","baɪ","tuː","deɪz","ðə","ˈkwɑː-lə-ti","wʊd","biː","mʌtʃ","ˈbe-tər"]}'::jsonb, '{"expected_transcript":"If we extended the deadline by two days, the quality would be much better."}'::jsonb, NULL, NULL, 'Cara sangat diplomatis di kantor AS untuk mengusulkan perpanjangan tenggat demi kualitas kerja!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000784', 'e4100001-0000-4000-8000-000000000096', NULL, 'reading', 'fill_blank', 'Jangan lupakan kata bantu ''Be'' untuk kalimat pasif masa lampau: The first transcontinental railroad in the United States ___ completed in 1869.', '{"options":["was","were","has","did"],"translation":"Jalur kereta lintas benua pertama di Amerika Serikat diselesaikan pada tahun 1869.","sentence_template":"The first transcontinental railroad in the United States [blank] completed in 1869."}'::jsonb, '{"selected":"was"}'::jsonb, NULL, NULL, 'Subjek tunggal ''The first transcontinental railroad'' + tahun lampau ''in 1869'' + V3 ''completed'' membutuhkan ''was''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000785', 'e4100001-0000-4000-8000-000000000096', NULL, 'reading', 'fill_blank', 'Waspadai kata kerja intransitif yang DILARANG dipasifkan di TOEFL: A brief power fluctuation ___ at the data center at 3:14 a.m.', '{"options":["occurred","was occurred","is occurred","were occurred"],"translation":"Fluktuasi daya singkat terjadi di pusat data pada pukul 03.14 dini hari.","sentence_template":"A brief power fluctuation [blank] at the data center at 3:14 a.m."}'::jsonb, '{"selected":"occurred"}'::jsonb, NULL, NULL, '''Occur'' dan ''happen'' adalah kata kerja intransitif (tanpa objek) yang tidak pernah boleh berbentuk pasif (''was occurred'' selalu salah!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000786', 'e4100001-0000-4000-8000-000000000096', NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif untuk kegiatan perbaikan yang SEDANG berlangsung sekarang: Please take the stairs—the north elevator ___ inspected right now.', '{"options":["is being","is been","has being","are being"],"translation":"Silakan gunakan tangga—lift utara sedang diperiksa sekarang.","sentence_template":"Please take the stairs—the north elevator [blank] inspected right now."}'::jsonb, '{"selected":"is being"}'::jsonb, NULL, NULL, 'Present Continuous Passive untuk subjek tunggal memakai ''is + being + V3'' (''is being inspected'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000787', 'e4100001-0000-4000-8000-000000000096', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah geologi pengantar ala TOEFL berikut. Bagaimana batu apung (pumice) terbentuk?', '{"options":[{"id":"opt_1","text":"Terbentuk perlahan di dasar samudra dingin selama jutaan tahun"},{"id":"opt_2","text":"Terbentuk ketika lava panas kaya gas dilontarkan kuat dari gunung berapi lalu mendingin sangat cepat hingga gelembung gas terperangkap"},{"id":"opt_3","text":"Dibuat di pabrik bahan bangunan menggunakan pasir pantai"},{"id":"opt_4","text":"Hanya ditemukan di meteorit luar angkasa"}],"audio_text":"Pumice is formed when superheated, gas-rich lava is ejected violently from a volcano and cools so rapidly that gas bubbles remain trapped inside."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pemaparan proses ilmiah TOEFL mengandalkan Present Passive: ''is formed'' dan ''is ejected''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000788', 'e4100001-0000-4000-8000-000000000096', NULL, 'listening', 'listening_choice', 'Dengarkan laporan singkat pasca-insiden (post-mortem) di rapat teknik ini. Mengapa pembayaran kartu sempat gagal tadi malam?', '{"options":[{"id":"opt_1","text":"Bank sentral menutup jaringan pembayaran nasional"},{"id":"opt_2","text":"Sekitar empat puluh permintaan checkout ditolak karena kunci API yang kedaluwarsa tidak sengaja dirilis"},{"id":"opt_3","text":"Pelanggan salah memasukkan kode pos mereka"},{"id":"opt_4","text":"Tidak ada transaksi sama sekali tadi malam"}],"audio_text":"Between ten and ten-twenty last night, roughly forty checkout requests were rejected because an expired API key was accidentally deployed."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Gaya laporan insiden objektif (blameless post-mortem) di AS memakai Past Passive (''were rejected'', ''was accidentally deployed'') agar fokus pada sistem, bukan menyalahkan individu!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000789', 'e4100001-0000-4000-8000-000000000096', NULL, 'writing', 'sentence_builder', 'Susun kalimat penjelasan sistem keamanan: "Seluruh berkas pelanggan dienkripsi sebelum disimpan."', '{"romaji":"/ɔːl ˈkʌstəmər faɪlz ɑːr ɪnˈkrɪptɪd bɪˈfɔːr ˈstɔːrɪdʒ/","tokens":["encrypted","encrypt","files are","before","is encrypted","storage.","All customer"],"target_translation":"Seluruh berkas pelanggan dienkripsi sebelum disimpan."}'::jsonb, '["All customer","files are","encrypted","before","storage."]'::jsonb, NULL, NULL, 'Subjek jamak ''All customer files'' memakai Present Passive ''are encrypted''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000790', 'e4100001-0000-4000-8000-000000000096', NULL, 'writing', 'sentence_builder', 'Susun kalimat sejarah arsitektur kampus: "Gedung perpustakaan ini dirancang oleh seorang arsitek Chicago."', '{"romaji":"/ðɪs ˈlaɪbreri ˈbɪldɪŋ wʌz dɪˈzaɪnd baɪ ə ʃɪˈkɑːɡoʊ ˈɑːrkɪtekt/","tokens":["architect.","were designed","This library","designed by","designing","a Chicago","building was"],"target_translation":"Gedung perpustakaan ini dirancang oleh seorang arsitek Chicago."}'::jsonb, '["This library","building was","designed by","a Chicago","architect."]'::jsonb, NULL, NULL, 'Pelaku spesifik yang penting disebutkan menggunakan ''by a Chicago architect''; perhatikan ''architect'' dibaca /ˈɑːrkɪtekt/ (''ch'' berbunyi /k/!).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000791', 'e4100001-0000-4000-8000-000000000096', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pemberitahuan layanan ini dengan jelas: "Pesanan Anda dikirim pagi ini dan sedang dalam perjalanan."', '{"romaji":"/jʊr ˈɔːrdər wʌz ʃɪpt ðɪs ˈmɔːrnɪŋ ænd ɪz ɑːn ɪts weɪ/","display_text":"Your order was shipped this morning and is on its way.","phonetic_breakdown":["jʊr","ˈɔːr-dər","wʌz","ʃɪpt","ðɪs","ˈmɔːr-nɪŋ","ænd","ɪz","ɑːn","ɪts","weɪ"]}'::jsonb, '{"expected_transcript":"Your order was shipped this morning and is on its way."}'::jsonb, NULL, NULL, 'Akhiran ''-ed'' pada ''shipped'' berbunyi tajam /t/ (/ʃɪpt/), dan ''its'' kepemilikan ditulis tanpa apostrof!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000792', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Bedakan Aktif (-ing) vs Pasif (V3) setelah ''has been'': Good news—the login issue ___ fixed, so users can sign in normally again.', '{"options":["has been","have been","is being since","has"],"translation":"Kabar baik—masalah login tersebut telah diperbaiki, sehingga pengguna dapat masuk kembali secara normal.","sentence_template":"Good news—the login issue [blank] fixed, so users can sign in normally again."}'::jsonb, '{"selected":"has been"}'::jsonb, NULL, NULL, 'Subjek benda tunggal ''the login issue'' dikenai tindakan dan hasilnya berlaku sekarang -> ''has been + V3 (fixed)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000793', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Jangan lupakan ''be'' setelah modal verb dalam kalimat pasif: Reimbursement receipts must ___ uploaded within thirty days of your business trip.', '{"options":["be","been","being","are"],"translation":"Bukti kuitansi penggantian biaya wajib diunggah dalam waktu tiga puluh hari sejak perjalanan dinas Anda.","sentence_template":"Reimbursement receipts must [blank] uploaded within thirty days of your business trip."}'::jsonb, '{"selected":"be"}'::jsonb, NULL, NULL, 'Setelah modal murni (''must'', ''should'', ''can'', ''will''), kata kerja bantu pasif selalu berbentuk dasar ''be'' + V3.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000794', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk Present Perfect Passive negatif untuk subjek jamak ''The final exam rooms'': The final exam rooms ___ assigned yet; check the portal next week.', '{"options":["haven''t been","hasn''t been","aren''t been","didn''t"],"translation":"Ruang-ruang ujian akhir belum ditetapkan; periksa portalnya minggu depan.","sentence_template":"The final exam rooms [blank] assigned yet; check the portal next week."}'::jsonb, '{"selected":"haven''t been"}'::jsonb, NULL, NULL, 'Subjek jamak ''The final exam rooms'' + penanda ''yet'' membutuhkan ''haven''t been + V3 (assigned)''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000795', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan pengumuman ketua panitia konferensi akademik berikut. Perubahan jadwal apa yang telah diputuskan?', '{"options":[{"id":"opt_1","text":"Sesi poster hari Jumat dibatalkan seluruhnya"},{"id":"opt_2","text":"Sesi poster hari Jumat telah dipindahkan dari Tenda Halaman A ke Ballroom Tiga karena angin kencang"},{"id":"opt_3","text":"Para penyaji diminta membawa tenda sendiri"},{"id":"opt_4","text":"Sesi poster diundur ke hari Senin minggu depan"}],"audio_text":"Attention presenters: Friday''s poster session has been moved from Courtyard Tent A to Ballroom Three due to high winds."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Has been moved from... to...'' menyampaikan pemindahan lokasi resmi yang berdampak langsung saat ini.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000796', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan instruksi dosen tentang aturan pengumpulan makalah akhir ini. Dalam format apa makalah harus dikumpulkan?', '{"options":[{"id":"opt_1","text":"Dikirim lewat lampiran email dalam format dokumen Word"},{"id":"opt_2","text":"Dicetak rangkap tiga dan ditaruh di meja dosen"},{"id":"opt_3","text":"Sebaiknya dikumpulkan sebagai satu berkas PDF tunggal di Canvas karena lampiran email tidak akan dinilai"},{"id":"opt_4","text":"Dikumpulkan dalam bentuk rekaman video lima menit"}],"audio_text":"Your final policy paper should be submitted as a single PDF file on Canvas—email attachments won''t be graded."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Dua Modal Passive tegas dalam silabus kampus AS: ''should be submitted'' dan ''won''t be graded''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000797', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat informasi layanan tiket: "Tiket parkir dapat dibeli di kios pintu masuk."', '{"romaji":"/ˈpɑːrkɪŋ ˈpæsɪz kən biː ˈpɜːrtʃəst æt ði ˈentrəns ˈkiːɑːsk/","tokens":["can purchased","can be","kiosk.","Parking passes","purchased at","the entrance","purchasing"],"target_translation":"Tiket parkir dapat dibeli di kios pintu masuk."}'::jsonb, '["Parking passes","can be","purchased at","the entrance","kiosk."]'::jsonb, NULL, NULL, 'Modal Passive ''can be purchased'' terdengar jauh lebih formal dan informatif dibanding ''you can buy''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000798', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat konfirmasi undangan wawancara: "Semua kandidat terpilih telah dihubungi melalui email."', '{"romaji":"/ɔːl ˈʃɔːrtlɪstɪd ˈkændɪdeɪts hæv bɪn ˈkɑːntæktɪd baɪ ˈiːmeɪl/","tokens":["been contacted","email.","All shortlisted","has been","by","candidates have","contacting"],"target_translation":"Semua kandidat terpilih telah dihubungi melalui email."}'::jsonb, '["All shortlisted","candidates have","been contacted","by","email."]'::jsonb, NULL, NULL, 'Perhatikan ''by email'' (tanpa artikel ''a/the'' untuk sarana komunikasi!) + ''have been contacted''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000799', 'e4100001-0000-4000-8000-000000000097', 'e2000001-0000-4000-8000-000000000024', 'speaking', 'speaking_repeat', 'Ucapkan kalimat status proyek ini dengan ejaan/lafal US canceled: "Rapat luar ruangan telah dibatalkan karena peringatan badai."', '{"romaji":"/ði ˈaʊtdɔːr ˈmiːtɪŋ hæz bɪn ˈkænsəld duː tə ðə stɔːrm ˈwɔːrnɪŋ/","display_text":"The outdoor meeting has been canceled due to the storm warning.","phonetic_breakdown":["ði","ˈaʊt-dɔːr","ˈmiː-tɪŋ","hæz","bɪn","ˈkæn-səld","duː","tə","ðə","stɔːrm","ˈwɔːr-nɪŋ"]}'::jsonb, '{"expected_transcript":"The outdoor meeting has been canceled due to the storm warning."}'::jsonb, NULL, NULL, 'Di American English, ''due to'' dibaca /duː tə/ (bukan /djuː tə/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000800', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Perhatikan kata benda tak terhitung ''data'' dalam bahasa Inggris bisnis/teknis modern AS saat menjelaskan proses: First, anonymized sensor data ___ gathered from smart meters across the grid.', '{"options":["is","are being to","were yesterday","have"],"translation":"Pertama, data sensor yang telah dianonimkan dikumpulkan dari meteran pintar di seluruh jaringan listrik.","sentence_template":"First, anonymized sensor data [blank] gathered from smart meters across the grid."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Dalam bahasa Inggris teknis AS modern, ''data'' lazim diperlakukan sebagai uncountable tunggal -> ''is gathered'' untuk proses rutin.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000801', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Pilih kata kerja pasif yang tepat setelah ''Once'': Once the manuscript ___ peer-reviewed by two specialists, the journal editor makes a final decision.', '{"options":["has been","have been","will be","was yesterday"],"translation":"Begitu naskah ilmiah tersebut selesai ditinjau sejawat oleh dua pakar, editor jurnal mengambil keputusan akhir.","sentence_template":"Once the manuscript [blank] peer-reviewed by two specialists, the journal editor makes a final decision."}'::jsonb, '{"selected":"has been"}'::jsonb, NULL, NULL, 'Di dalam klausa ''Once...'', Present Perfect Passive tunggal ''has been peer-reviewed'' menekankan tahap review harus tuntas lebih dulu (dan dilarang memakai ''will be'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000802', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Pilih preposisi yang tepat untuk menyebutkan ALAT/BAHAN (bukan pelaku bernyawa!) pada kalimat pasif: During winter storms, icy highways in Minnesota are treated ___ salt and sand.', '{"options":["with","by","from","at"],"translation":"Selama badai musim dingin, jalan raya berlapis es di Minnesota ditaburi dengan garam dan pasir.","sentence_template":"During winter storms, icy highways in Minnesota are treated [blank] salt and sand."}'::jsonb, '{"selected":"with"}'::jsonb, NULL, NULL, 'Tips penting TOEFL: gunakan ''BY'' untuk pelaku yang mengerjakan aksi, tetapi gunakan ''WITH'' untuk bahan/alat yang dipakai (''treated with salt'', ''written with a pen'')!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000803', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan penjelasan proses daur ulang aluminium dalam kuliah ilmu lingkungan ini. Berapa persen energi yang dihemat dibanding memproduksi aluminium baru dari bijih tambang?', '{"options":[{"id":"opt_1","text":"Menggunakan energi dua kali lipat lebih besar daripada bijih tambang mentah"},{"id":"opt_2","text":"Kaleng dihancurkan, dilebur menjadi batangan, lalu digilas menjadi lembaran tipis—menghemat 95% energi"},{"id":"opt_3","text":"Kaleng aluminium hanya dicuci dengan air lalu langsung diisi minuman lagi"},{"id":"opt_4","text":"Hanya menghemat lima persen energi listrik"}],"audio_text":"After used aluminum cans are shredded and melted down into ingots, they are rolled into thin sheets—a process that uses ninety-five percent less energy than refining raw ore."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan ejaan dan lafal Amerika: ''aluminum'' (/əˈluːmɪnəm/ — 4 suku kata, bukan ''aluminium''!) serta rangkaian pasif ''are shredded... melted... are rolled''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000804', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan penjelasan alur autentikasi dua faktor (2FA) oleh insinyur keamanan berikut. Kapan pengguna diizinkan masuk ke dasbor?', '{"options":[{"id":"opt_1","text":"Langsung masuk tanpa kode apa pun dari peramban baru"},{"id":"opt_2","text":"Setelah kode verifikasi enam digit yang dikirim ke ponsel pengguna berhasil dimasukkan"},{"id":"opt_3","text":"Setelah pengguna menelepon kantor pusat secara manual"},{"id":"opt_4","text":"Peramban baru diblokir selamanya oleh sistem"}],"audio_text":"When a login attempt is detected from a new browser, a six-digit verification code is sent to the user''s phone, and dashboard access isn''t granted until that code is entered."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Seluruh alur sistem dijelaskan dengan empat Passive Voice beruntun: ''is detected -> is sent -> isn''t granted -> is entered''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000805', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat tahapan pengolahan sampel: "Selanjutnya, sampel darah tersebut dianalisis di laboratorium klinis."', '{"romaji":"/nekst, ðə blʌd ˈsæmpəlz ɑːr ˈænəlaɪzd ɪn ðə ˈklɪnɪkəl læb/","tokens":["are analyzed","in the","is analyzed","Next, the","analyzing","blood samples","clinical lab."],"target_translation":"Selanjutnya, sampel darah tersebut dianalisis di laboratorium klinis."}'::jsonb, '["Next, the","blood samples","are analyzed","in the","clinical lab."]'::jsonb, NULL, NULL, 'Ejaan Amerika: ''analyzed'' (dengan ''y'' dan ''z'', bukan ''analysed''!) + subjek jamak ''samples are analyzed''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000806', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat penutup alur distribusi: "Terakhir, buku-buku cetakan itu dikirimkan ke toko buku kampus."', '{"romaji":"/ˈfaɪnəli, ðə ˈprɪntɪd bʊks ɑːr ʃɪpt tə ˈkæmpəs ˈbʊkstɔːrz/","tokens":["bookstores.","printed books","to campus","is shipped","Finally, the","are shipped","ship"],"target_translation":"Terakhir, buku-buku cetakan itu dikirimkan ke toko buku kampus."}'::jsonb, '["Finally, the","printed books","are shipped","to campus","bookstores."]'::jsonb, NULL, NULL, '''The printed books'' (jamak) + ''are shipped''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000807', 'e4100001-0000-4000-8000-000000000098', 'e2000001-0000-4000-8000-000000000024', 'speaking', 'speaking_repeat', 'Ucapkan rangkuman alur otomatis ini dengan jelas: "Begitu pembayarannya diverifikasi, tanda terima digital dikirimkan secara otomatis."', '{"romaji":"/wʌns ðə ˈpeɪmənt ɪz ˈverɪfaɪd, ə ˈdɪdʒɪtəl rɪˈsiːt ɪz sent ˌɔːtəˈmætɪkli/","display_text":"Once the payment is verified, a digital receipt is sent automatically.","phonetic_breakdown":["wʌns","ðə","ˈpeɪ-mənt","ɪz","ˈver-ɪ-faɪd","ə","ˈdɪdʒ-ɪ-təl","rɪ-ˈsiːt","ɪz","sent","ˌɔː-tə-ˈmæt-ɪk-li"]}'::jsonb, '{"expected_transcript":"Once the payment is verified, a digital receipt is sent automatically."}'::jsonb, NULL, NULL, 'Ingat kembali huruf ''p'' bisu pada ''receipt'' (/rɪˈsiːt/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000808', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk Modal Passive yang benar untuk kebijakan ujian: Graphing calculators may ___ used only on the second section of the exam.', '{"options":["be","been","being","are"],"translation":"Kalkulator grafik hanya boleh digunakan pada bagian kedua ujian.","sentence_template":"Graphing calculators may [blank] used only on the second section of the exam."}'::jsonb, '{"selected":"be"}'::jsonb, NULL, NULL, 'Modal ''may'' diikuti bentuk dasar ''be'' + V3 (''may be used'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000809', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Waspadai kata kerja intransitif ''collapse'' / ''disappear'' / ''happen'': Fortunately, nobody was injured when the sudden snowstorm ___ yesterday.', '{"options":["happened","was happened","were happened","has happened"],"translation":"Untungnya, tidak seorang pun terluka ketika badai salju mendadak itu terjadi kemarin.","sentence_template":"Fortunately, nobody was injured when the sudden snowstorm [blank] yesterday."}'::jsonb, '{"selected":"happened"}'::jsonb, NULL, NULL, 'Perhatikan kontras di satu kalimat: ''was injured'' (pasif benar karena ''injure'' transitif), sedangkan ''happen'' intransitif sehingga wajib aktif ''happened''!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000810', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk Present Perfect Passive untuk laporan kemajuan gedung baru: Over eighty percent of the solar panels ___ installed on the campus roof so far.', '{"options":["have been","has been","were yesterday","are being since"],"translation":"Lebih dari delapan puluh persen panel surya telah dipasang di atap kampus sejauh ini.","sentence_template":"Over eighty percent of the solar panels [blank] installed on the campus roof so far."}'::jsonb, '{"selected":"have been"}'::jsonb, NULL, NULL, 'Persentase dari benda jamak (''eighty percent of the solar panels'') dihitung jamak + ''so far'' -> ''have been installed''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000811', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan pengumuman pustakawan mengenai buku referensi yang dipesan mahasiswa berikut. Apa status bukunya sekarang?', '{"options":[{"id":"opt_1","text":"Permintaan pinjaman bukunya ditolak oleh perpustakaan mitra"},{"id":"opt_2","text":"Buku ekonometrika tersebut baru saja diantar ke meja sirkulasi dan akan disimpan untuk Clara sampai hari Jumat"},{"id":"opt_3","text":"Clara harus mengambil bukunya sendiri ke kampus lain"},{"id":"opt_4","text":"Buku tersebut sedang dipinjam dosen sampai bulan depan"}],"audio_text":"Hi Clara, the econometrics textbook you requested from interlibrary loan has just been delivered to the circulation desk, and it''ll be held for you until Friday."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Has just been delivered'' (Present Perfect Passive) + ''it''ll be held for you until Friday'' (Future Passive).', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000812', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah sejarah seni arsitektur AS ini. Mengapa Patung Liberty awalnya berwarna cokelat kemerahan berkilau?', '{"options":[{"id":"opt_1","text":"Karena awalnya dicat merah oleh pemerintah kota New York"},{"id":"opt_2","text":"Karena lapisan luarnya terbuat dari tembaga berkilau yang perlahan berubah hijau akibat oksidasi selama puluhan tahun"},{"id":"opt_3","text":"Karena dibuat dari batu bata merah asal Prancis"},{"id":"opt_4","text":"Karena baru saja dibersihkan minggu lalu"}],"audio_text":"When the Statue of Liberty was gifted to the United States in 1886, its outer shell was made of shiny copper, which gradually turned green over decades due to oxidation."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Was gifted... in 1886'' dan ''was made of shiny copper'' menjelaskan sejarah material dengan Past Passive.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000813', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat pengumuman pemeliharaan sistem: "Portal mahasiswa sedang diperbarui malam ini mulai pukul sebelas."', '{"romaji":"/ðə ˈstuːdənt ˈpɔːrtəl ɪz ˈbiːɪŋ ʌpˈdeɪtɪd təˈnaɪt ˈstɑːrtɪŋ æt ɪˈlevən/","tokens":["is been","being updated","The student","at eleven.","portal is","updating","tonight starting"],"target_translation":"Portal mahasiswa sedang diperbarui malam ini mulai pukul sebelas."}'::jsonb, '["The student","portal is","being updated","tonight starting","at eleven."]'::jsonb, NULL, NULL, '''Is being updated'' untuk jadwal pemeliharaan dekat/berlangsung.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000814', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat peraturan keamanan gedung: "Kartu identitas wajib dikenakan setiap saat di dalam gedung ini."', '{"romaji":"/ˌaɪˈdiː ˈbædʒɪz mʌst biː wɔːrn æt ɔːl taɪmz ɪnˈsaɪd ðɪs ˈbɪldɪŋ/","tokens":["ID badges","must worn","all times","weared","worn at","must be","inside this building."],"target_translation":"Kartu identitas wajib dikenakan setiap saat di dalam gedung ini."}'::jsonb, '["ID badges","must be","worn at","all times","inside this building."]'::jsonb, NULL, NULL, 'V3 tak beraturan dari ''wear'' adalah ''worn'' (''wear - wore - worn'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000815', 'e4100001-0000-4000-8000-000000000099', 'e2000001-0000-4000-8000-000000000024', 'speaking', 'speaking_repeat', 'Ucapkan kalimat laporan penyelesaian audit ini dengan tegas: "Seluruh laporan keuangan telah diaudit oleh kantor akuntan independen."', '{"romaji":"/ɔːl faɪˈnænʃəl ˈsteɪtmənts hæv bɪn ˈɔːdɪtɪd baɪ ən ˌɪndɪˈpendənt fɜːrm/","display_text":"All financial statements have been audited by an independent firm.","phonetic_breakdown":["ɔːl","faɪ-ˈnæn-ʃəl","ˈsteɪt-mənts","hæv","bɪn","ˈɔː-dɪ-tɪd","baɪ","ən","ˌɪn-dɪ-ˈpen-dənt","fɜːrm"]}'::jsonb, '{"expected_transcript":"All financial statements have been audited by an independent firm."}'::jsonb, NULL, NULL, 'Di AS, ''firm'' sering merujuk pada firma jasa profesional (akuntansi, hukum, konsultan).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000816', 'e4100001-0000-4000-8000-000000000100', NULL, 'reading', 'fill_blank', 'Pilih relative pronoun yang tepat untuk menjelaskan orang (''applicants''): Scholarships are awarded to applicants ___ demonstrate strong community leadership.', '{"options":["who","which","whose","where"],"translation":"Beasiswa diberikan kepada para pelamar yang menunjukkan kepemimpinan masyarakat yang kuat.","sentence_template":"Scholarships are awarded to applicants [blank] demonstrate strong community leadership."}'::jsonb, '{"selected":"who"}'::jsonb, NULL, NULL, '''Applicants'' merujuk kepada orang (manusia) yang bertindak sebagai subjek kata kerja ''demonstrate'', sehingga memakai ''who''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000817', 'e4100001-0000-4000-8000-000000000100', NULL, 'reading', 'fill_blank', 'Perhatikan kesesuaian jumlah kata kerja setelah ''that'' dengan kata benda di depannya (''a battery''): Researchers developed a solid-state battery that ___ in just ten minutes.', '{"options":["charges","charge","charging","are charging"],"translation":"Para peneliti mengembangkan baterai solid-state yang mengisi daya hanya dalam sepuluh menit.","sentence_template":"Researchers developed a solid-state battery that [blank] in just ten minutes."}'::jsonb, '{"selected":"charges"}'::jsonb, NULL, NULL, 'Kata benda yang dijelaskan oleh ''that'' adalah tunggal (''a solid-state battery''), sehingga kata kerjanya wajib memakai -s (''charges'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000818', 'e4100001-0000-4000-8000-000000000100', NULL, 'reading', 'fill_blank', 'Hindari jebakan pengulangan kata ganti (double pronoun): That''s the keynote speaker who ___ the bestselling book on behavioral economics.', '{"options":["wrote","she wrote","writing","was wrote"],"translation":"Itulah pembicara utama yang menulis buku terlaris tentang ekonomi perilaku.","sentence_template":"That''s the keynote speaker who [blank] the bestselling book on behavioral economics."}'::jsonb, '{"selected":"wrote"}'::jsonb, NULL, NULL, 'Kata ''who'' sudah menggantikan subjek ''she'', jadi dilarang mengulang ''she wrote''—langsung ikuti dengan kata kerja ''wrote''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000819', 'e4100001-0000-4000-8000-000000000100', NULL, 'listening', 'listening_choice', 'Dengarkan deskripsi lowongan kerja dari perekrut teknologi ini. Kriteria insinyur seperti apa yang sedang dicari tim mereka?', '{"options":[{"id":"opt_1","text":"Desainer grafis yang mahir membuat poster cetak"},{"id":"opt_2","text":"Insinyur backend yang berpengalaman dengan kepatuhan data medis HIPAA serta senang membimbing pengembang junior"},{"id":"opt_3","text":"Manajer penjualan yang sering bepergian ke Eropa"},{"id":"opt_4","text":"Mahasiswa tahun pertama tanpa pengalaman pemrograman"}],"audio_text":"Our healthcare team is hiring a backend engineer who has experience with HIPAA compliance and enjoys mentoring junior developers."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di AS, ''HIPAA compliance'' adalah standar hukum perlindungan privasi data pasien; klausa ''who has experience... and enjoys...'' memerinci dua kualifikasi utama.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000820', 'e4100001-0000-4000-8000-000000000100', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan dosen ekologi tentang tanaman asli daerah kering (xerophytes) berikut. Apa ciri khusus tanaman tersebut?', '{"options":[{"id":"opt_1","text":"Tanaman air tawar yang hidup mengapung di permukaan danau"},{"id":"opt_2","text":"Tanaman gurun yang menyimpan air di batang tebal berdaging dan meminimalkan penguapan lewat daun berlapis lilin"},{"id":"opt_3","text":"Pohon hutan hujan yang membutuhkan curah hujan harian tinggi"},{"id":"opt_4","text":"Tanaman pertanian yang hanya tumbuh di daerah bersalju"}],"audio_text":"Xerophytes are desert plants that store water in thick fleshy stems and minimize moisture loss through waxy leaves."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Definisi istilah ilmiah di kuliah AS hampir selalu memakai pola ''[Term] is/are [Category] that/which + [Characteristics]''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000821', 'e4100001-0000-4000-8000-000000000100', NULL, 'writing', 'sentence_builder', 'Susun kalimat deskripsi perangkat lunak: "Kami membutuhkan alat yang menyinkronkan catatan di seluruh perangkat."', '{"romaji":"/wiː niːd ə tuːl ðæt sɪŋks noʊts əˈkrɔːs ɔːl dɪˈvaɪsɪz/","tokens":["that syncs","sync","all devices.","a tool","who syncs","We need","notes across"],"target_translation":"Kami membutuhkan alat yang menyinkronkan catatan di seluruh perangkat."}'::jsonb, '["We need","a tool","that syncs","notes across","all devices."]'::jsonb, NULL, NULL, 'Tunggal ''a tool'' (benda) + ''that syncs'' (dengan akhiran -s!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000822', 'e4100001-0000-4000-8000-000000000100', NULL, 'writing', 'sentence_builder', 'Susun kalimat penghargaan tim: "Mahasiswa yang mengumpulkan draf lebih awal menerima masukan terperinci."', '{"romaji":"/ˈstuːdənts huː səbˈmɪt dræfts ˈɜːrli rɪˈsiːv dɪˈteɪld ˈfiːdbæk/","tokens":["feedback.","receives","Students who","detailed","which submit","submit drafts","early receive"],"target_translation":"Mahasiswa yang mengumpulkan draf lebih awal menerima masukan terperinci."}'::jsonb, '["Students who","submit drafts","early receive","detailed","feedback."]'::jsonb, NULL, NULL, 'Subjek utama ''Students'' (jamak) dijelaskan oleh ''who submit drafts early'', lalu bertemu predikat utama jamak ''receive''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000823', 'e4100001-0000-4000-8000-000000000100', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat perkenalan produk startup ini dengan mantap: "Kami membangun platform yang menghubungkan pekerja jarak jauh dengan perusahaan global."', '{"romaji":"/wiː bɪld ə ˈplætfɔːrm ðæt kəˈnekts rɪˈmoʊt ˈtælənt wɪð ˈɡloʊbəl ˈkʌmpəniz/","display_text":"We build a platform that connects remote talent with global companies.","phonetic_breakdown":["wiː","bɪld","ə","ˈplæt-fɔːrm","ðæt","kə-ˈnekts","rɪ-ˈmoʊt","ˈtæ-lənt","wɪð","ˈɡloʊ-bəl","ˈkʌm-pə-niz"]}'::jsonb, '{"expected_transcript":"We build a platform that connects remote talent with global companies."}'::jsonb, NULL, NULL, 'Formula elevator pitch startup AS paling klasik: ''We build a [product] that [solves X for Y]!''', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000824', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Pilih kata hubung kepemilikan (''yang laptopnya...'') tepat di depan kata benda ''laptop'': Please assist the presenter ___ laptop won''t connect to the projector.', '{"options":["whose","who''s","who","which"],"translation":"Tolong bantu penyaji yang laptopnya tidak bisa tersambung ke proyektor.","sentence_template":"Please assist the presenter [blank] laptop won''t connect to the projector."}'::jsonb, '{"selected":"whose"}'::jsonb, NULL, NULL, 'Di depan kata benda milik (''laptop''), gunakan relative pronoun kepemilikan ''whose'' (''who''s'' berarti ''who is/has'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000825', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Hindari pengulangan objek ''it'' yang mubazir di dalam klausa penjelas: The feedback that our mentor ___ yesterday helped us restructure the pitch.', '{"options":["gave us","gave it to us","giving us","was given it"],"translation":"Masukan yang diberikan mentor kami kemarin membantu kami menata ulang presentasi bisnis tersebut.","sentence_template":"The feedback that our mentor [blank] yesterday helped us restructure the pitch."}'::jsonb, '{"selected":"gave us"}'::jsonb, NULL, NULL, 'Kata ''that'' sudah mewakili objek ''the feedback'', sehingga dilarang mengulang ''it'' lagi (''gave us'', bukan ''gave it to us'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000826', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Pilih relative pronoun kepemilikan untuk entitas perusahaan: Investors prefer backing startups ___ core products solve urgent real-world pain points.', '{"options":["whose","which","that","who''s"],"translation":"Para investor lebih suka mendukung startup yang produk intinya memecahkan masalah nyata yang mendesak.","sentence_template":"Investors prefer backing startups [blank] core products solve urgent real-world pain points."}'::jsonb, '{"selected":"whose"}'::jsonb, NULL, NULL, '''Whose'' + kata benda (''whose core products'') sah dan sangat rapi dipakai untuk organisasi/benda maupun manusia.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000827', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan percakapan rekan sekantor yang mencari dokumen bersama ini. Dokumen mana yang dimaksud oleh pembicara pria?', '{"options":[{"id":"opt_1","text":"Tabel anggaran tahun lalu yang dibuat oleh tim keuangan"},{"id":"opt_2","text":"Pelacak rekrutmen Kuartal 4 yang dibagikan Sarah di kanal pimpinan pagi ini"},{"id":"opt_3","text":"Daftar inventaris kursi kantor di lantai empat"},{"id":"opt_4","text":"Jadwal libur musim panas seluruh karyawan"}],"audio_text":"Which spreadsheet are you looking for? — The Q4 hiring tracker Sarah shared in the leadership channel this morning."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan penghilangan alami ''that'': ''The Q4 hiring tracker [that] Sarah shared...'' sangat khas percakapan asli AS—penting dikenali di TOEFL Listening!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000828', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan pengumuman bagian beasiswa universitas berikut. Mahasiswa mana yang berhak mendaftar dana darurat ini?', '{"options":[{"id":"opt_1","text":"Semua mahasiswa lokal yang ingin berlibur musim semi"},{"id":"opt_2","text":"Mahasiswa internasional yang penerbangan pulangnya dibatalkan akibat penutupan maskapai tak terduga"},{"id":"opt_3","text":"Dosen yang akan menghadiri seminar di kota tetangga"},{"id":"opt_4","text":"Alumni yang sudah lulus lebih dari lima tahun"}],"audio_text":"Emergency travel grants are available for international students whose return flights were canceled due to unforeseen airline closures."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Students whose return flights were canceled...'' menggabungkan kepemilikan ''whose'' dengan Past Passive secara mulus.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000829', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat ringkas tanpa kata that (Object Relative Clause): "Kedai kopi yang kita kunjungi kemarin menyajikan matcha yang enak."', '{"romaji":"/ðə ˈkɔːfi ʃɑːp wiː ˈvɪzɪtɪd ˈjestərdeɪ sɜːrvz ɡreɪt ˈmɑːtʃə/","tokens":["The coffee shop","great","we visited","serve","matcha.","yesterday serves","visited it"],"target_translation":"Kedai kopi yang kita kunjungi kemarin menyajikan matcha yang enak."}'::jsonb, '["The coffee shop","we visited","yesterday serves","great","matcha."]'::jsonb, NULL, NULL, 'Subjek tunggal ''The coffee shop'' + klausa penjelas ''(that) we visited yesterday'' + kata kerja utama tunggal ''serves''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000830', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat dengan whose: "Saya bekerja dengan seorang peneliti yang makalahnya memenangkan penghargaan tahun lalu."', '{"romaji":"/aɪ wɜːrk wɪð ə ˈriːsɜːrtʃər huːz ˈpeɪpər wʌn ən əˈwɔːrd læst jɪr/","tokens":["which paper","last year.","who''s paper","with a researcher","whose paper","won an award","I work"],"target_translation":"Saya bekerja dengan seorang peneliti yang makalahnya memenangkan penghargaan tahun lalu."}'::jsonb, '["I work","with a researcher","whose paper","won an award","last year."]'::jsonb, NULL, NULL, '''A researcher whose paper won...'' menghubungkan peneliti dengan makalah miliknya.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000831', 'e4100001-0000-4000-8000-000000000101', 'e2000001-0000-4000-8000-000000000025', 'speaking', 'speaking_repeat', 'Ucapkan kalimat rekomendasi buku ini dengan irama alami tanpa jeda kaku: "Buku tentang negosiasi yang kamu pinjamkan kepadaku sangat praktis."', '{"romaji":"/ðə nɪˌɡoʊʃiˈeɪʃən bʊk juː lent miː wʌz ˈsuːpər ˈpræktɪkəl/","display_text":"The negotiation book you lent me was super practical.","phonetic_breakdown":["ðə","nɪ-ˌɡoʊ-ʃi-ˈeɪ-ʃən","bʊk","juː","lent","miː","wʌz","ˈsuː-pər","ˈpræk-tɪ-kəl"]}'::jsonb, '{"expected_transcript":"The negotiation book you lent me was super practical."}'::jsonb, NULL, NULL, 'V2 dari ''lend'' (meminjamkan) adalah ''lent'', dan penghilangan ''that'' setelah ''book'' terdengar 100% native!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000832', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Uji jebakan nomor satu tempat + kata kerja langsung: The Willis Tower is a famous Chicago skyscraper ___ has an observation deck on the 103rd floor.', '{"options":["that","where","whose","who"],"translation":"Willis Tower adalah gedung pencakar langit terkenal di Chicago yang memiliki dek observasi di lantai 103.","sentence_template":"The Willis Tower is a famous Chicago skyscraper [blank] has an observation deck on the 103rd floor."}'::jsonb, '{"selected":"that"}'::jsonb, NULL, NULL, 'Karena titik-titik langsung diikuti kata kerja ''has'' (butuh subjek ''yang'', bukan keterangan ''di mana''), wajib memakai ''that'' atau ''which''—BUKAN ''where''!', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000833', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Sekarang perhatikan tempat sebagai lokasi berlangsungnya aksi (''we tested our robot IN that warehouse''): That''s the campus maker space ___ our team built our first autonomous drone.', '{"options":["where","which","who","whose"],"translation":"Itulah ruang bengkel kreatif kampus tempat (di mana) tim kami merakit drone otonom pertama kami.","sentence_template":"That''s the campus maker space [blank] our team built our first autonomous drone."}'::jsonb, '{"selected":"where"}'::jsonb, NULL, NULL, 'Tim kami merakit drone DI ruang tersebut (''in the maker space''), dan diikuti klausa lengkap ''our team built...'', sehingga tepat memakai ''where''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000834', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Hindari jebakan redundansi setelah ''the main reason'' dalam penulisan standar: Career growth was the main reason ___ Raka accepted the offer in Seattle.', '{"options":["why","because","where","whose"],"translation":"Perkembangan karier adalah alasan utama mengapa Raka menerima tawaran kerja di Seattle.","sentence_template":"Career growth was the main reason [blank] Raka accepted the offer in Seattle."}'::jsonb, '{"selected":"why"}'::jsonb, NULL, NULL, 'Setelah kata benda ''the reason'', gunakan ''why'' atau ''that'' (jangan gunakan ''because'' karena ''reason + because'' mubazir!).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000835', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan penjelasan pemandu tur kampus kepada calon mahasiswa baru ini. Apa keistimewaan Gedung Sains Terpadu (Integrated Science Complex)?', '{"options":[{"id":"opt_1","text":"Gedung khusus tempat mahasiswa tingkat doktoral tidur"},{"id":"opt_2","text":"Gedung di mana mahasiswa S1 sudah bisa bergabung ke lab riset dosen sejak semester pertama mereka"},{"id":"opt_3","text":"Gedung olahraga yang sedang ditutup untuk renovasi"},{"id":"opt_4","text":"Gedung administrasi pembayaran uang kuliah"}],"audio_text":"On your left is the Integrated Science Complex, where undergraduate students can join faculty research labs starting in their very first semester."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Klausa ''where undergraduate students can join...'' menjelaskan aktivitas akademik yang berlangsung di dalam gedung tersebut.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000836', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan obrolan dua pendiri startup tentang ruang kerja bersama (coworking space) baru mereka berikut. Mengapa mereka memilih gedung di Market Street?', '{"options":[{"id":"opt_1","text":"Karena letaknya paling jauh dari stasiun kereta"},{"id":"opt_2","text":"Karena ruang kerja tersebut sudah mencakup bilik telepon kedap suara dan akses kartu kunci 24 jam sehari, 7 hari seminggu"},{"id":"opt_3","text":"Karena tidak memiliki ruang rapat sama sekali"},{"id":"opt_4","text":"Karena hanya buka dari jam sembilan pagi sampai jam dua siang"}],"audio_text":"We picked a coworking space on Market Street that includes soundproof phone booths and twenty-four-seven keycard access."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Istilah AS ''twenty-four-seven'' (24/7) berarti buka terus sepanjang waktu; perhatikan ''a coworking space... THAT includes...'' karena diikuti langsung oleh kata kerja ''includes''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000837', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat kenangan lokasi kuliah: "Ini adalah kedai kopi tempat saya dulu menulis tesis magister saya."', '{"romaji":"/ðɪs ɪz ðə kæˈfeɪ wer aɪ roʊt maɪ ˈmæstərz ˈθiːsɪs/","tokens":["master''s thesis.","where I wrote in","This is","the café","where I","wrote my","which I wrote"],"target_translation":"Ini adalah kedai kopi tempat saya dulu menulis tesis magister saya."}'::jsonb, '["This is","the café","where I","wrote my","master''s thesis."]'::jsonb, NULL, NULL, 'Di American English, kata ''café'' ditekan pada suku kata KEDUA (/kæˈfeɪ/), berbeda dari Inggris (/ˈkæfeɪ/)! Gunakan ''where I wrote...'' tanpa ''in''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000838', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat kriteria apartemen (tempat sebagai subjek): "Kami menyewa apartemen yang menghadap ke sungai."', '{"romaji":"/wiː ˈrentɪd ən əˈpɑːrtmənt ðæt ˌoʊvərˈlʊks ðə ˈrɪvər/","tokens":["river.","where overlooks","an apartment","overlook","We rented","that overlooks","the"],"target_translation":"Kami menyewa apartemen yang menghadap ke sungai."}'::jsonb, '["We rented","an apartment","that overlooks","the","river."]'::jsonb, NULL, NULL, 'Diikuti kata kerja tunggal ''overlooks'' -> wajib memakai ''that'' (bukan ''where'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000839', 'e4100001-0000-4000-8000-000000000102', 'e2000001-0000-4000-8000-000000000025', 'speaking', 'speaking_repeat', 'Ucapkan kalimat refleksi karier ini dengan jelas: "Saya ingin bekerja di lingkungan tempat orang-orang bebas berbagi ide secara terbuka."', '{"romaji":"/aɪ wɑːnt tə wɜːrk ɪn ən ɪnˈvaɪrənmənt wer ˈpiːpəl ʃer aɪˈdiːəz ˈoʊpənli/","display_text":"I want to work in an environment where people share ideas openly.","phonetic_breakdown":["aɪ","wɑːnt","tə","wɜːrk","ɪn","ən","ɪn-ˈvaɪ-rən-mənt","wer","ˈpiː-pəl","ʃer","aɪ-ˈdiː-əz","ˈoʊ-pən-li"]}'::jsonb, '{"expected_transcript":"I want to work in an environment where people share ideas openly."}'::jsonb, NULL, NULL, 'Perhatikan ejaan dan bunyi ''n'' kedua pada ''environment'' (/ɪnˈvaɪrənmənt/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000840', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Pilih antara ''where'', ''that'', dan ''whose'' saat diikuti langsung oleh kata kerja ''offers'': Nadia applied to a Boston hospital ___ offers a specialized residency in pediatrics.', '{"options":["that","where","whose","who"],"translation":"Nadia melamar ke rumah sakit di Boston yang menawarkan program residensi khusus ilmu kesehatan anak.","sentence_template":"Nadia applied to a Boston hospital [blank] offers a specialized residency in pediatrics."}'::jsonb, '{"selected":"that"}'::jsonb, NULL, NULL, 'Meskipun ''hospital'' adalah tempat, setelah titik-titik langsung terdapat kata kerja ''offers'', sehingga wajib memakai subjek ''that'' (bukan ''where'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000841', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Pilih kata hubung kepemilikan yang tepat: The user ___ account was locked contacted technical support this morning.', '{"options":["whose","who''s","which","whom"],"translation":"Pengguna yang akunnya terkunci menghubungi dukungan teknis pagi ini.","sentence_template":"The user [blank] account was locked contacted technical support this morning."}'::jsonb, '{"selected":"whose"}'::jsonb, NULL, NULL, '''Whose + noun'' (''whose account'') menyatakan kepemilikan akun oleh pengguna tersebut.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000842', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'reading', 'fill_blank', 'Perhatikan kesesuaian jumlah kata kerja setelah ''who'': Mentors who ___ honest, constructive advice help interns grow rapidly.', '{"options":["give","gives","giving","is giving"],"translation":"Para mentor yang memberikan nasihat jujur dan membangun membantu peserta magang berkembang pesat.","sentence_template":"Mentors who [blank] honest, constructive advice help interns grow rapidly."}'::jsonb, '{"selected":"give"}'::jsonb, NULL, NULL, 'Kata benda di depan ''who'' berbentuk jamak (''Mentors''), sehingga kata kerja di dalam klausa penjelas juga jamak tanpa -s (''give'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000843', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti tentang jurnal referensi berikut. Artikel mana yang direkomendasikan oleh pembicara wanita?', '{"options":[{"id":"opt_1","text":"Buku cetak yang ada di meja perpustakaan lantai empat"},{"id":"opt_2","text":"Makalah riset Stanford yang disematkan pembicara wanita di kanal Slack mereka"},{"id":"opt_3","text":"Artikel koran yang baru akan terbit minggu depan"},{"id":"opt_4","text":"Laporan keuangan kuartalan kompetitor"}],"audio_text":"Have you found a good benchmark study yet? — Yes! Check out the Stanford paper I pinned in our Slack channel—it compares six transformer architectures."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Object relative clause ringkas ''the Stanford paper [that] I pinned in our Slack channel'' langsung menunjuk dokumen spesifik.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000844', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah ekonomi perkotaan ala TOEFL ini. Apa yang dimaksud profesor dengan ''transit-oriented neighborhoods''?', '{"options":[{"id":"opt_1","text":"Kawasan pinggiran kota di mana setiap warga wajib memiliki dua mobil pribadi"},{"id":"opt_2","text":"Kawasan perkotaan ramah pejalan kaki di mana warga dapat menjangkau toko bahan makanan, kantor, dan stasiun kereta dalam sepuluh menit berjalan kaki"},{"id":"opt_3","text":"Kawasan industri pabrik berat di luar kota"},{"id":"opt_4","text":"Jalan tol khusus truk logistik antarnegara bagian"}],"audio_text":"Transit-oriented neighborhoods are walkable urban districts where residents can access grocery stores, offices, and rail stations within ten minutes on foot."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Urban districts where residents can access...'' mendefinisikan ruang kota berdasarkan aktivitas warganya.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000845', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat deskripsi kandidat ideal: "Kami merekrut analis yang dapat menjelaskan data secara jernih."', '{"romaji":"/wiː ˈhaɪər ˈænəlɪsts huː kən ɪkˈspleɪn ˈdeɪtə ˈklɪrli/","tokens":["data","can explain","analysts who","datas","We hire","clearly.","which can"],"target_translation":"Kami merekrut analis yang dapat menjelaskan data secara jernih."}'::jsonb, '["We hire","analysts who","can explain","data","clearly."]'::jsonb, NULL, NULL, '''Analysts'' (manusia) memakai ''who'', dan kata ''data'' tidak pernah memakai akhiran ''-s'' (''datas'' tidak ada!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000846', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat tentang laboratorium tempat eksperimen berlangsung: "Itulah laboratorium tempat vaksin tersebut pertama kali diuji."', '{"romaji":"/ðæt ɪz ðə ˈlæbrətɔːri wer ðə vækˈsiːn wʌz fɜːrst ˈtestɪd/","tokens":["That is","tested it.","where the","which the","vaccine was","first tested.","the laboratory"],"target_translation":"Itulah laboratorium tempat vaksin tersebut pertama kali diuji."}'::jsonb, '["That is","the laboratory","where the","vaccine was","first tested."]'::jsonb, NULL, NULL, 'Perhatikan lafal US ''laboratory'' (/ˈlæbrətɔːri/ — tekanan di suku kata pertama!) dan ''vaccine'' (/vækˈsiːn/).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000847', 'e4100001-0000-4000-8000-000000000103', 'e2000001-0000-4000-8000-000000000025', 'speaking', 'speaking_repeat', 'Ucapkan kalimat ringkas profesional ini dengan lancar: "Solusi yang diusulkan Elena menghemat waktu berjam-jam bagi tim kami."', '{"romaji":"/ðə səˈluːʃən ˈelənə prəˈpoʊzd seɪvd ˈaʊər tiːm ˈaʊərz ʌv wɜːrk/","display_text":"The solution Elena proposed saved our team hours of work.","phonetic_breakdown":["ðə","sə-ˈluː-ʃən","ˈe-lə-nə","prə-ˈpoʊzd","seɪvd","ˈaʊ-ər","tiːm","ˈaʊ-ərz","ʌv","wɜːrk"]}'::jsonb, '{"expected_transcript":"The solution Elena proposed saved our team hours of work."}'::jsonb, NULL, NULL, 'Penghilangan ''that'' pada ''The solution [that] Elena proposed'' membuat kalimat terdengar tajam dan fasih!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000848', 'e4100001-0000-4000-8000-000000000104', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kebiasaan masa lalu yang sekarang sudah berubah: Before switching to product management, Nadia ___ work as a QA analyst.', '{"options":["used to","use to","is used to","usually"],"translation":"Sebelum beralih ke manajemen produk, Nadia dulunya bekerja sebagai analis QA.","sentence_template":"Before switching to product management, Nadia [blank] work as a QA analyst."}'::jsonb, '{"selected":"used to"}'::jsonb, NULL, NULL, 'Keadaan karier masa lalu yang kini sudah berubah dinyatakan dengan ''used to + V1 (work)''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000849', 'e4100001-0000-4000-8000-000000000104', NULL, 'reading', 'fill_blank', 'Perhatikan ejaan standar setelah kata bantu ''Did'': ___ this building use to be an old textile factory back in the 1920s?', '{"options":["Did","Was","Has","Does"],"translation":"Apakah gedung ini dulunya merupakan pabrik tekstil tua pada era 1920-an?","sentence_template":"[blank] this building use to be an old textile factory back in the 1920s?"}'::jsonb, '{"selected":"Did"}'::jsonb, NULL, NULL, 'Kalimat tanya untuk ''used to'' memakai kata bantu ''Did + Subject + use to + V1?''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000850', 'e4100001-0000-4000-8000-000000000104', NULL, 'reading', 'fill_blank', 'Jangan tertukar kebiasaan SEKARANG vs DULU: Nowadays, our remote team ___ holds a virtual coffee chat every Thursday morning.', '{"options":["usually","used to","use to","was used to"],"translation":"Saat ini, tim jarak jauh kami biasanya mengadakan obrolan kopi virtual setiap Kamis pagi.","sentence_template":"Nowadays, our remote team [blank] holds a virtual coffee chat every Thursday morning."}'::jsonb, '{"selected":"usually"}'::jsonb, NULL, NULL, 'Penanda masa kini ''Nowadays'' + kata kerja Present Simple ''holds'' wajib memakai adverbia frekuensi ''usually'' (bukan ''used to'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000851', 'e4100001-0000-4000-8000-000000000104', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan dua alumni saat reuni kampus di Boston ini. Apa yang dulunya berdiri di lokasi gedung laboratorium baru tersebut?', '{"options":[{"id":"opt_1","text":"Dulunya adalah stasiun kereta bawah tanah"},{"id":"opt_2","text":"Dulunya terdapat lapangan tenis luar ruangan tepat di lokasi lab bioteknologi kaca yang berdiri sekarang"},{"id":"opt_3","text":"Lapangan tenisnya baru dibangun bulan lalu"},{"id":"opt_4","text":"Lokasi tersebut masih berupa lapangan kosong"}],"audio_text":"Wow, campus has changed so much! Didn''t there use to be an outdoor tennis court right where that glass bioengineering lab stands now?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Didn''t there use to be an outdoor tennis court...?'' menanyakan keberadaan fasilitas lama yang kini telah digantikan gedung baru.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000852', 'e4100001-0000-4000-8000-000000000104', NULL, 'listening', 'listening_choice', 'Dengarkan cerita seorang desainer tentang rasa gugup berbicara di depan umum berikut. Bagaimana perubahannya sekarang?', '{"options":[{"id":"opt_1","text":"Tangannya masih selalu gemetar setiap rapat"},{"id":"opt_2","text":"Saat tahun pertama kuliah tangannya dulu sering gemetar tiap bicara di depan kelas, tetapi kini demam panggungnya sudah hilang berkat memimpin sesi kritik desain mingguan"},{"id":"opt_3","text":"Ia tidak pernah mau berbicara di depan kelas"},{"id":"opt_4","text":"Ia berhenti bekerja sebagai desainer"}],"audio_text":"In my freshman year, my hands used to shake whenever I spoke in front of class, but leading weekly design critiques cured my stage fright."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''My hands used to shake..., but... cured my stage fright'' menunjukkan kontras masa lalu vs masa kini yang sangat jelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000853', 'e4100001-0000-4000-8000-000000000104', NULL, 'writing', 'sentence_builder', 'Susun kalimat perubahan pola kerja: "Dulu saya tidak suka bekerja dari rumah, tetapi sekarang saya menyukainya."', '{"romaji":"/aɪ ˈdɪdənt ˈjuːs tə laɪk ˈwɜːrkɪŋ frʌm hoʊm, bʌt naʊ aɪ lʌv ɪt/","tokens":["I didn''t","from home,","use to","used to","like working","but now I love it.","to work"],"target_translation":"Dulu saya tidak suka bekerja dari rumah, tetapi sekarang saya menyukainya."}'::jsonb, '["I didn''t","use to","like working","from home,","but now I love it."]'::jsonb, NULL, NULL, 'Setelah ''didn''t'', gunakan ejaan ''use to'' tanpa huruf ''d''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000854', 'e4100001-0000-4000-8000-000000000104', NULL, 'writing', 'sentence_builder', 'Susun kalimat sejarah lokasi kota: "Dulu pernah ada bioskop kecil di seberang jalan."', '{"romaji":"/ðer ˈjuːst tə biː ə smɔːl ˈmuːvi ˈθiːətər əˈkrɔːs ðə striːt/","tokens":["a small","to be","across the street.","There used","use to","movie theater","was used"],"target_translation":"Dulu pernah ada bioskop kecil di seberang jalan."}'::jsonb, '["There used","to be","a small","movie theater","across the street."]'::jsonb, NULL, NULL, 'Di AS, bioskop disebut ''movie theater'' (ejaan ''-er'', bukan ''cinema/theatre''!) + pola ''There used to be...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000855', 'e4100001-0000-4000-8000-000000000104', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat perbandingan teknologi ini dengan asimilasi alami /ˈjuːst tə/: "Dulu kami melacak pengeluaran di atas kertas, tetapi sekarang kami menggunakan aplikasi."', '{"romaji":"/wiː ˈjuːst tə træk ɪkˈspensɪz ɑːn ˈpeɪpər, bʌt naʊ wiː juːz ən æp/","display_text":"We used to track expenses on paper, but now we use an app.","phonetic_breakdown":["wiː","ˈjuːst","tə","træk","ɪk-ˈspen-sɪz","ɑːn","ˈpeɪ-pər","bʌt","naʊ","wiː","juːz","ən","æp"]}'::jsonb, '{"expected_transcript":"We used to track expenses on paper, but now we use an app."}'::jsonb, NULL, NULL, 'Dengarkan bedanya: ''used to'' dibaca /ˈjuːst tə/ (bunyi /s/ tajam), sedangkan kata kerja ''use'' sekarang dibaca /juːz/ (bunyi /z/ bergetar)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000856', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Perhatikan keberadaan ''am'' di depan ''used to'' (subjek manusia yang sudah terbiasa): Don''t worry about the spicy sambal—I''m from Manado, so I''m used to ___ super spicy dishes!', '{"options":["eating","eat","ate","eaten"],"translation":"Jangan khawatir soal sambal pedas itu—saya dari Manado, jadi saya sudah terbiasa makan hidangan super pedas!","sentence_template":"Don''t worry about the spicy sambal—I''m from Manado, so I''m used to [blank] super spicy dishes!"}'::jsonb, '{"selected":"eating"}'::jsonb, NULL, NULL, 'Struktur ''be (am) + used to'' bagi manusia yang terbiasa wajib diikuti bentuk Gerund ''-ing'' (''eating'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000857', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''get used to'' untuk proses adaptasi di jalan raya AS: Coming from Indonesia, it took Dimas two weeks to get used to ___ on the right side of the road.', '{"options":["driving","drive","drove","driven"],"translation":"Berasal dari Indonesia, butuh dua minggu bagi Dimas untuk membiasakan diri menyetir di lajur kanan jalan.","sentence_template":"Coming from Indonesia, it took Dimas two weeks to get used to [blank] on the right side of the road."}'::jsonb, '{"selected":"driving"}'::jsonb, NULL, NULL, 'Di AS pengemudi berkendara di lajur kanan (kebalikan dari Indonesia); setelah ''get used to'', wajib gunakan Gerund ''driving''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000858', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Uji ketajaman membedakan Passive Voice benda mati (''dipakai untuk'') vs adaptasi manusia: Liquid nitrogen is used ___ biological samples at ultra-low temperatures.', '{"options":["to preserve","preserving","for preserve","preserved"],"translation":"Nitrogen cair digunakan untuk mengawetkan sampel biologis pada suhu sangat rendah.","sentence_template":"Liquid nitrogen is used [blank] biological samples at ultra-low temperatures."}'::jsonb, '{"selected":"to preserve"}'::jsonb, NULL, NULL, 'Jebakan tingkat tinggi TOEFL: subjeknya adalah zat benda mati (''Liquid nitrogen'') dalam kalimat pasif (''digunakan UNTUK mengawetkan''), sehingga memakai Infinitive of Purpose ''to preserve''!', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000859', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan curhat mahasiswa Indonesia semester pertama di Michigan ini. Hal apa yang sedang berusaha ia biasakan?', '{"options":[{"id":"opt_1","text":"Ia sudah terbiasa sejak kecil dengan matahari terbenam jam empat sore"},{"id":"opt_2","text":"Ia masih dalam proses membiasakan diri dengan betapa cepatnya hari menjadi gelap di bulan November karena matahari terbenam sebelum jam 5 sore"},{"id":"opt_3","text":"Ia kesulitan memahami materi kuliah di kelas"},{"id":"opt_4","text":"Matahari di Michigan bersinar sampai pukul sembilan malam di bulan November"}],"audio_text":"Classes are going well, though I''m still getting used to how early it gets dark in November—the sun sets before five p.m. here!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''m still getting used to...'' menunjukkan proses adaptasi budaya/iklim yang sedang berlangsung saat ini.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000860', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja baru dengan seniornya berikut. Mengapa karyawan baru tersebut tampak santai menghadapi tenggat ketat?', '{"options":[{"id":"opt_1","text":"Ia belum pernah bekerja di bawah tenggat waktu sebelumnya"},{"id":"opt_2","text":"Dulu ia pernah bekerja di ruang redaksi berita harian (''used to work''), sehingga kini ia sangat terbiasa dengan penyelesaian kerja serbacepat (''used to fast turnarounds'')"},{"id":"opt_3","text":"Ia saat ini masih bekerja rangkap sebagai wartawan"},{"id":"opt_4","text":"Tenggat proyeknya baru bulan depan"}],"audio_text":"You seem super calm under tight deadlines! — Haha, I used to work at a daily newsroom, so I''m totally used to fast turnarounds."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kalimat ini menyandingkan keduanya dengan jernih: ''I used to work'' (+ V1, masa lalu) dan ''I''m totally used to fast turnarounds'' (+ Noun, kondisi terbiasa kini).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000861', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat proses adaptasi kuliah di AS: "Dia mulai terbiasa memanggil profesornya secara langsung di diskusi kelas."', '{"romaji":"/ʃiː ɪz ˈɡetɪŋ ˈjuːst tə ˈspiːkɪŋ ʌp ˈdʊrɪŋ klæs dɪˈskʌʃənz/","tokens":["use to","to speaking","getting used","She is","to speak","up during","class discussions."],"target_translation":"Dia mulai terbiasa angkat bicara selama diskusi kelas."}'::jsonb, '["She is","getting used","to speaking","up during","class discussions."]'::jsonb, NULL, NULL, '''Speak up'' = berani menyampaikan pendapat di kelas; setelah ''getting used to'' wajib V-ing (''speaking up'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000862', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat belum terbiasa dengan cuaca dingin: "Saya belum terbiasa berjalan kaki di suhu di bawah titik beku."', '{"romaji":"/aɪm nɑːt ˈjuːst tə ˈwɔːkɪŋ ɪn ˈfriːzɪŋ ˈtemprətʃərz jet/","tokens":["freezing","didn''t use","to walk","used to","walking in","I''m not","temperatures yet."],"target_translation":"Saya belum terbiasa berjalan kaki di suhu di bawah titik beku."}'::jsonb, '["I''m not","used to","walking in","freezing","temperatures yet."]'::jsonb, NULL, NULL, 'Perhatikan lafal US ''temperatures'' hanya 3 suku kata (/ˈtemprətʃərz/ — vokal ''e'' kedua luluh)!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000863', 'e4100001-0000-4000-8000-000000000105', 'e2000001-0000-4000-8000-000000000026', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penyemangat bagi mahasiswa baru ini dengan lancar: "Awalnya terasa canggung, tetapi kamu akan segera terbiasa!"', '{"romaji":"/ɪt fiːlz ˈɔːkwərd æt fɜːrst, bʌt juːl ɡet ˈjuːst tə ɪt suːn/","display_text":"It feels awkward at first, but you''ll get used to it soon!","phonetic_breakdown":["ɪt","fiːlz","ˈɔːk-wərd","æt","fɜːrst","bʌt","juːl","ɡet","ˈjuːst","tə","ɪt","suːn"]}'::jsonb, '{"expected_transcript":"It feels awkward at first, but you''ll get used to it soon!"}'::jsonb, NULL, NULL, 'Kalimat motivasi paling populer antar sesama perantau internasional di AS!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000864', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Ingat perbedaan ''used to'' vs nostalgia ''would'' untuk kata kerja KEADAAN (''be / have / know''): Before the highway was built, this suburb ___ a quiet farming town.', '{"options":["used to be","would be","is used to being","got used to"],"translation":"Sebelum jalan raya itu dibangun, kawasan pinggiran ini dulunya adalah kota pertanian yang tenang.","sentence_template":"Before the highway was built, this suburb [blank] a quiet farming town."}'::jsonb, '{"selected":"used to be"}'::jsonb, NULL, NULL, 'Untuk kata kerja keadaan statis (''be''), hanya ''used to be'' yang benar (nostalgia ''would'' hanya boleh untuk kata kerja aksi berulang, bukan keadaan).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000865', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Lengkapi idiom penyesuaian budaya AS berikut: Seeing prices without tax on store shelves ___ some getting used to when I first arrived.', '{"options":["took","made","did","gave"],"translation":"Melihat harga belum termasuk pajak di rak toko membutuhkan waktu penyesuaian saat saya pertama kali tiba.","sentence_template":"Seeing prices without tax on store shelves [blank] some getting used to when I first arrived."}'::jsonb, '{"selected":"took"}'::jsonb, NULL, NULL, 'Idiom baku untuk hal yang butuh waktu adaptasi adalah ''take (lampau: took) some getting used to''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000866', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah ''are used to'': Most professors in the US are used to students ___ questions directly during lectures.', '{"options":["asking","ask","to ask","asked"],"translation":"Sebagian besar profesor di AS sudah terbiasa dengan mahasiswa yang mengajukan pertanyaan langsung di tengah perkuliahan.","sentence_template":"Most professors in the US are used to students [blank] questions directly during lectures."}'::jsonb, '{"selected":"asking"}'::jsonb, NULL, NULL, 'Setelah preposisi ''to'' pada ''are used to (someone)...'', kata kerjanya tetap berbentuk Gerund (''asking'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000867', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan obrolan dua mahasiswa internasional tentang satuan ukuran di AS berikut. Mengapa pembicara pria sempat terkejut saat melihat prakiraan cuaca ''75 degrees''?', '{"options":[{"id":"opt_1","text":"Suhu udara di California mencapai 75 derajat Celsius"},{"id":"opt_2","text":"Ia sempat mengira 75 derajat itu Celsius, padahal aplikasi cuaca AS memakai Fahrenheit yang setara 24°C yang sejuk nyaman"},{"id":"opt_3","text":"Aplikasi cuacanya rusak dan menampilkan angka acak"},{"id":"opt_4","text":"Sedang terjadi badai salju lebat di California"}],"audio_text":"The first week I landed in California, my weather app said seventy-five degrees and I panicked—until my roommate reminded me that''s Fahrenheit, which is a pleasant twenty-four Celsius!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pengalaman klasik setiap orang Indonesia yang baru mendarat di AS: 75°F = ~24°C!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000868', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan cerita insinyur Indonesia yang bekerja di Seattle tentang budaya komunikasi rapat di AS ini. Adaptasi apa yang ia pelajari?', '{"options":[{"id":"opt_1","text":"Ia berhenti berbicara sama sekali di dalam rapat"},{"id":"opt_2","text":"Dulu ia biasa menunggu sampai akhir rapat, namun kini ia sudah terbiasa ikut masuk ke diskusi secara santun saat rapat berlangsung"},{"id":"opt_3","text":"Manajernya melarang anggota tim berbicara selama rapat"},{"id":"opt_4","text":"Rapat di Seattle selalu dilakukan lewat surat tertulis"}],"audio_text":"Back home, I used to wait until the end of a meeting to share feedback politely, but here I''ve gotten used to jumping into the conversation respectfully."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di American English, V3 dari ''get'' adalah ''gotten'' (''I''ve gotten used to jumping in...'' — ciri khas otentik US vs UK ''have got'')!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000869', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat adaptasi satuan jarak: "Saya sudah terbiasa mengukur jarak dalam mil sekarang."', '{"romaji":"/aɪm ˈjuːst tə ˈmeʒərɪŋ ˈdɪstənsɪz ɪn maɪlz naʊ/","tokens":["use to","I''m used","to measure","distances","now.","in miles","to measuring"],"target_translation":"Saya sudah terbiasa mengukur jarak dalam mil sekarang."}'::jsonb, '["I''m used","to measuring","distances","in miles","now."]'::jsonb, NULL, NULL, '''I''m used to + V-ing (measuring)...''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000870', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat kenangan rutinitas masa kuliah: "Setiap Jumat sore, kelompok belajar kami biasa berkumpul di halaman kampus."', '{"romaji":"/ˈevri ˈfraɪdeɪ ˌæftərˈnuːn, ˈaʊər ˈstʌdi ɡruːp wʊd miːt ɑːn ðə kwɑːd/","tokens":["Every Friday","would meet","study group","on the quad.","is used to","used to met","afternoon, our"],"target_translation":"Setiap Jumat sore, kelompok belajar kami biasa berkumpul di halaman kampus."}'::jsonb, '["Every Friday","afternoon, our","study group","would meet","on the quad."]'::jsonb, NULL, NULL, '''Quad'' (quadrangle) adalah halaman rumput utama di tengah kampus AS; aksi berulang masa lalu memakai ''would + V1 (meet)''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000871', 'e4100001-0000-4000-8000-000000000106', 'e2000001-0000-4000-8000-000000000026', 'speaking', 'speaking_repeat', 'Ucapkan kalimat keberhasilan adaptasi khas US English (gotten) ini: "Saya sudah terbiasa memberi tip dua puluh persen di restoran."', '{"romaji":"/aɪv ˈɡɑːtən ˈjuːst tə ˈtɪpɪŋ ˈtwenti pərˈsent æt ˈrestrɑːnts/","display_text":"I''ve gotten used to tipping twenty percent at restaurants.","phonetic_breakdown":["aɪv","ˈɡɑː-tən","ˈjuːst","tə","ˈtɪ-pɪŋ","ˈtwen-ti","pər-ˈsent","æt","ˈres-trɑːnts"]}'::jsonb, '{"expected_transcript":"I''ve gotten used to tipping twenty percent at restaurants."}'::jsonb, NULL, NULL, 'Bentuk ''have gotten used to + V-ing'' adalah penanda fasih American English sejati!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000872', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang benar untuk adaptasi saat ini: Even after six months in New York, Leo still isn''t used to ___ so fast on the sidewalk.', '{"options":["walking","walk","walked","walks"],"translation":"Bahkan setelah enam bulan di New York, Leo masih belum terbiasa berjalan begitu cepat di trotoar.","sentence_template":"Even after six months in New York, Leo still isn''t used to [blank] so fast on the sidewalk."}'::jsonb, '{"selected":"walking"}'::jsonb, NULL, NULL, '''Isn''t used to'' wajib diikuti Gerund ''walking''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000873', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk negatif yang benar untuk keadaan masa lalu yang kini sudah berubah: There ___ be a direct flight on this route, so travelers had to transfer in Tokyo.', '{"options":["didn''t use to","wasn''t used to","don''t use to","haven''t used to"],"translation":"Dulunya tidak ada penerbangan langsung di rute ini, sehingga pelancong harus transit di Tokyo.","sentence_template":"There [blank] be a direct flight on this route, so travelers had to transfer in Tokyo."}'::jsonb, '{"selected":"didn''t use to"}'::jsonb, NULL, NULL, 'Keberadaan di masa lalu (''There used to be'') dalam bentuk negatif menjadi ''There didn''t use to be''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000874', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'reading', 'fill_blank', 'Bedakan Passive Voice benda mati vs manusia terbiasa: High-precision lasers are used ___ silicon wafers in semiconductor fabs.', '{"options":["to cut","cutting","for cut","cuts"],"translation":"Laser berpresisi tinggi digunakan untuk memotong keping silikon di pabrik semikonduktor.","sentence_template":"High-precision lasers are used [blank] silicon wafers in semiconductor fabs."}'::jsonb, '{"selected":"to cut"}'::jsonb, NULL, NULL, 'Subjek benda mati ''lasers'' + pasif ''are used'' (= dipakai untuk) diikuti tujuan ''to cut''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000875', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja yang baru pindah ke model jadwal asinkron (async) berikut. Bagaimana perasaan Tari sekarang?', '{"options":[{"id":"opt_1","text":"Tari sangat membenci kerja asinkron dan ingin mengundurkan diri"},{"id":"opt_2","text":"Awalnya ia merindukan balasan instan, namun kini ia sudah terbiasa mendokumentasikan keputusan secara jelas di Notion"},{"id":"opt_3","text":"Tim mereka tidak pernah memakai dokumen tertulis"},{"id":"opt_4","text":"Tari dulu sudah memakai Notion sejak sekolah dasar"}],"audio_text":"How''s async work treating you, Tari? — At first I missed instant replies, but now I''ve gotten used to documenting decisions clearly in Notion."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Now I''ve gotten used to documenting...'' menunjukkan proses adaptasi kerja yang telah berhasil.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000876', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah antropologi budaya ala TOEFL ini. Bagaimana masyarakat pesisir tersebut dulunya mengawetkan ikan sebelum adanya mesin pendingin?', '{"options":[{"id":"opt_1","text":"Mereka langsung mengekspor ikan menggunakan pesawat kargo berpendingin"},{"id":"opt_2","text":"Dulu keluarga nelayan mengawetkan hasil tangkapan dengan garam laut dan mengasapinya di atas api kayu apung"},{"id":"opt_3","text":"Mereka tidak pernah menangkap ikan sebelum tahun 1950-an"},{"id":"opt_4","text":"Metode pengasapan baru ditemukan sepuluh tahun yang lalu"}],"audio_text":"Before electric refrigeration arrived on the island in the 1950s, fishing families used to cure their catch in sea salt and smoke it over driftwood fires."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Used to cure... and smoke...'' memaparkan praktik tradisional masa lampau sebelum perubahan teknologi.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000877', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun pertanyaan tentang latar belakang sekolah teman: "Apakah dulu kamu memakai seragam ketika bersekolah?"', '{"romaji":"/dɪd juː ˈjuːs tə wer ə ˈjuːnɪfɔːrm wen juː wɜːr ɪn skuːl/","tokens":["used to","wear a uniform","Did you","were in school?","when you","use to","wearing"],"target_translation":"Apakah dulu kamu memakai seragam ketika bersekolah?"}'::jsonb, '["Did you","use to","wear a uniform","when you","were in school?"]'::jsonb, NULL, NULL, '''Did you use to wear...?'' (tanpa huruf ''d'' pada ''use'', dan bunyi awal ''uniform'' /juː/ memakai artikel ''a''!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000878', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat adaptasi sistem metrik ke Amerika: "Jangan khawatir, Anda akan segera terbiasa dengan suhu Fahrenheit."', '{"romaji":"/doʊnt ˈwɜːri, juːl ɡet ˈjuːst tə ˈfærənhaɪt ˈtemprətʃərz suːn/","tokens":["Don''t worry,","soon.","use to","used to","Fahrenheit temperatures","get use","you''ll get"],"target_translation":"Jangan khawatir, Anda akan segera terbiasa dengan suhu Fahrenheit."}'::jsonb, '["Don''t worry,","you''ll get","used to","Fahrenheit temperatures","soon."]'::jsonb, NULL, NULL, '''Get used to + Noun Phrase'' (''get used to Fahrenheit temperatures'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000879', 'e4100001-0000-4000-8000-000000000107', 'e2000001-0000-4000-8000-000000000026', 'speaking', 'speaking_repeat', 'Ucapkan kalimat ringkasan adaptasi karier ini dengan jelas: "Dulu saya bekerja sendirian, tetapi sekarang saya sudah terbiasa memimpin rapat lintas divisi."', '{"romaji":"/aɪ ˈjuːst tə wɜːrk ˈsoʊloʊ, ænd naʊ aɪm ˈjuːst tə ˈliːdɪŋ ˈkrɔːs ˈfʌŋkʃənəl ˈmiːtɪŋz/","display_text":"I used to work solo, and now I''m used to leading cross-functional meetings.","phonetic_breakdown":["aɪ","ˈjuːst","tə","wɜːrk","ˈsoʊ-loʊ","ænd","naʊ","aɪm","ˈjuːst","tə","ˈliː-dɪŋ","ˈkrɔːs","ˈfʌŋk-ʃən-əl","ˈmiː-tɪŋz"]}'::jsonb, '{"expected_transcript":"I used to work solo, and now I''m used to leading cross-functional meetings."}'::jsonb, NULL, NULL, 'Kalimat mahakarya Unit 6: ''used to work'' (V1) bersanding langsung dengan ''I''m used to leading'' (V-ing)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000880', 'e4100001-0000-4000-8000-000000000108', NULL, 'reading', 'fill_blank', 'Pilih modal deduksi untuk menunjukkan empati atas kabar bahagia seseorang: You got a full scholarship to Stanford? Congratulations—your parents ___ so proud!', '{"options":["must be","can''t be","have to","must being"],"translation":"Kamu mendapat beasiswa penuh ke Stanford? Selamat—orang tuamu pasti sangat bangga!","sentence_template":"You got a full scholarship to Stanford? Congratulations—your parents [blank] so proud!"}'::jsonb, '{"selected":"must be"}'::jsonb, NULL, NULL, 'Kesimpulan logis yang hampir pasti benar berdasarkan kabar baik memakai ''must be''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000881', 'e4100001-0000-4000-8000-000000000108', NULL, 'reading', 'fill_blank', 'Pilih modal yang tepat untuk menyatakan sesuatu MUSTAHIL berdasarkan bukti nyata: This server metric ___ accurate—it says we have nine billion active users right now!', '{"options":["can''t be","must be","should be","may"],"translation":"Metrik server ini tidak mungkin akurat—tertulis kita punya sembilan miliar pengguna aktif sekarang!","sentence_template":"This server metric [blank] accurate—it says we have nine billion active users right now!"}'::jsonb, '{"selected":"can''t be"}'::jsonb, NULL, NULL, 'Karena melebihi populasi Bumi, angkanya jelas mustahil -> gunakan deduksi negatif ''can''t be'' (atau ''couldn''t be'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000882', 'e4100001-0000-4000-8000-000000000108', NULL, 'reading', 'fill_blank', 'Lengkapi deduksi untuk aksi yang pasti SEDANG terjadi sekarang: Maya''s green status dot is on and she''s typing—she ___ our message right now.', '{"options":["must be reading","must read","can''t reading","must to read"],"translation":"Titik status hijau Maya menyala dan dia sedang mengetik—dia pasti sedang membaca pesan kita sekarang.","sentence_template":"Maya''s green status dot is on and she''s typing—she [blank] our message right now."}'::jsonb, '{"selected":"must be reading"}'::jsonb, NULL, NULL, 'Deduksi atas aktivitas yang sedang berlangsung detik ini menggunakan ''must be + V-ing''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000883', 'e4100001-0000-4000-8000-000000000108', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan pelanggan dan kasir restoran di Boston ini. Mengapa pelanggan yakin tagihannya keliru?', '{"options":[{"id":"opt_1","text":"Pelanggan lupa membawa dompetnya"},{"id":"opt_2","text":"Tagihan (''check'') itu tidak mungkin milik meja mereka karena mencantumkan tiga roti lobster, padahal mereka berdua hanya memesan sup tomat dan es teh"},{"id":"opt_3","text":"Pelanggan ingin memesan tiga roti lobster tambahan untuk dibawa pulang"},{"id":"opt_4","text":"Harga sup tomat sedang diskon lima puluh persen"}],"audio_text":"Excuse me, this check can''t be ours—it lists three lobster rolls, and the two of us only had tomato soup and iced tea!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di restoran AS, bon tagihan disebut ''the check'' (bukan ''the bill''), dan ''this check can''t be ours'' menyampaikan koreksi berdasarkan bukti.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000884', 'e4100001-0000-4000-8000-000000000108', NULL, 'listening', 'listening_choice', 'Dengarkan obrolan dua mahasiswa di depan pintu ruang seminar yang terkunci berikut. Apa kesimpulan mereka?', '{"options":[{"id":"opt_1","text":"Dosen membatalkan kuliah selama satu semester"},{"id":"opt_2","text":"Berdasarkan ruangan yang gelap dan sepi serta pengumuman Canvas, mereka menyimpulkan mereka pasti salah gedung"},{"id":"opt_3","text":"Mereka datang tiga jam lebih cepat"},{"id":"opt_4","text":"Ruang 204 sedang dipakai ujian kelas lain"}],"audio_text":"Strange, all the lights inside Room 204 are off and nobody''s here. — Wait, check Canvas... oh! We must be in the wrong building—the seminar moved to Hall B!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''We must be in the wrong building'' menyimpulkan penyebab situasi janggal yang baru saja mereka amati.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000885', 'e4100001-0000-4000-8000-000000000108', NULL, 'writing', 'sentence_builder', 'Susun kalimat empati perjalanan jauh: "Kamu baru saja menempuh penerbangan sembilan belas jam—kamu pasti sangat kelelahan!"', '{"romaji":"/juː dʒʌst fluː ˌnaɪnˈtiːn ˈaʊərz—juː mʌst biː ɪɡˈzɔːstɪd/","tokens":["You just","can''t be","hours—you","must exhausted!","must be","flew nineteen","exhausted!"],"target_translation":"Kamu baru saja menempuh penerbangan sembilan belas jam—kamu pasti sangat kelelahan!"}'::jsonb, '["You just","flew nineteen","hours—you","must be","exhausted!"]'::jsonb, NULL, NULL, 'Jangan lupakan kata kerja ''be'' di depan kata sifat ''exhausted'' (''you must be exhausted'')!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000886', 'e4100001-0000-4000-8000-000000000108', NULL, 'writing', 'sentence_builder', 'Susun kalimat deduksi kemustahilan: "Itu tidak mungkin edisi terakhirnya—sampulnya berbeda."', '{"romaji":"/ðæt kænt biː ðə ˈleɪtɪst ɪˈdɪʃən—ðə ˈkʌvər ɪz ˈdɪfərənt/","tokens":["be the","That can''t","latest edition—the","different.","cover is","can''t is","mustn''t to"],"target_translation":"Itu tidak mungkin edisi terakhirnya—sampulnya berbeda."}'::jsonb, '["That can''t","be the","latest edition—the","cover is","different."]'::jsonb, NULL, NULL, '''That can''t be...'' menyatakan ketidakmungkinan logis.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000887', 'e4100001-0000-4000-8000-000000000108', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat koreksi data yang santun ini: "Pasti ada salah ketik pada rumus di kolom empat."', '{"romaji":"/ðer mʌst biː ə ˈtaɪpoʊ ɪn ðə ˈfɔːrmjələ ɑːn ˈkɑːləm fɔːr/","display_text":"There must be a typo in the formula on column four.","phonetic_breakdown":["ðer","mʌst","biː","ə","ˈtaɪ-poʊ","ɪn","ðə","ˈfɔːr-mjə-lə","ɑːn","ˈkɑː-ləm","fɔːr"]}'::jsonb, '{"expected_transcript":"There must be a typo in the formula on column four."}'::jsonb, NULL, NULL, 'Huruf ''n'' di akhir ''column'' 100% BISU (/ˈkɑːləm/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000888', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Bedakan penulisan ''may be'' (2 kata: modal + verb) vs ''maybe'' (1 kata: adverbia) saat tidak ada kata kerja lain di kalimat: Take a light sweater to the lecture hall—the air conditioning ___ freezing.', '{"options":["may be","maybe","can","might"],"translation":"Bawalah sweter tipis ke ruang kuliah—pendingin ruangannya mungkin sangat dingin.","sentence_template":"Take a light sweater to the lecture hall—the air conditioning [blank] freezing."}'::jsonb, '{"selected":"may be"}'::jsonb, NULL, NULL, 'Kalimat setelah subjek ''the air conditioning'' belum memiliki kata kerja utama, sehingga wajib memakai modal + kata kerja ''may be'' (dua kata terpisah; ''maybe'' satu kata tidak punya kata kerja, dan ''might'' saja kurang ''be'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000889', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk arti ''mungkin tidak sempat'' (keraguan 50%, BUKAN kemustahilan mutlak!): Traffic on Interstate 90 is pretty heavy, so we ___ make it to the theater before the previews.', '{"options":["might not","can''t be","must","maybe not"],"translation":"Lalu lintas di jalan tol Interstate 90 cukup padat, jadi kita mungkin tidak sempat tiba di bioskop sebelum cuplikan film.","sentence_template":"Traffic on Interstate 90 is pretty heavy, so we [blank] make it to the theater before the previews."}'::jsonb, '{"selected":"might not"}'::jsonb, NULL, NULL, 'Untuk kemungkinan negatif 50% (''mungkin tidak''), gunakan ''might not + V1'' atau ''may not + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000890', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Pilih kata keterangan 1 kata (''Barangkali'') di awal kalimat yang SUDAH memiliki kata kerja ''is'': ___ the Wi-Fi router just needs a quick reboot.', '{"options":["Maybe","May be","Might","Must"],"translation":"Barangkali perute Wi-Fi-nya hanya butuh dimuat ulang sebentar.","sentence_template":"[blank] the Wi-Fi router just needs a quick reboot."}'::jsonb, '{"selected":"Maybe"}'::jsonb, NULL, NULL, 'Karena klausa ''the Wi-Fi router just needs...'' sudah memiliki subjek dan kata kerja lengkap (''needs''), pembuka di depan memakai adverbia satu kata ''Maybe''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000891', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan diskusi dua insinyur yang sedang mendiagnosis lonjakan penggunaan memori server ini. Apa hipotesis mereka?', '{"options":[{"id":"opt_1","text":"Mereka sudah yakin 100% bahwa hard disk server terbakar"},{"id":"opt_2","text":"Mereka menduga koneksi WebSocket mungkin tidak tertutup sempurna saat pengguna menutup tab peramban"},{"id":"opt_3","text":"Penggunaan memori server justru sedang turun drastis"},{"id":"opt_4","text":"Tidak ada pengguna yang membuka peramban hari ini"}],"audio_text":"Why is RAM usage climbing every hour? — I''m not completely sure yet, but an open WebSocket connection might not be closing properly when users close their browser tabs."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I''m not completely sure yet, but ... might not be closing properly'' menunjukkan hipotesis teknis yang hati-hati.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000892', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah arkeologi ala TOEFL berikut. Mengapa profesor memakai kata ''could indicate''?', '{"options":[{"id":"opt_1","text":"Profesor membantah adanya perdagangan kuno"},{"id":"opt_2","text":"Ornamen kerang laut 300 mil di pedalaman itu berpotensi mengindikasikan adanya jaringan dagang jarak jauh antara suku gurun dan pesisir"},{"id":"opt_3","text":"Kerang laut tersebut baru ditaruh oleh wisatawan tahun lalu"},{"id":"opt_4","text":"Lokasi penggalian berada tepat di tepi pantai"}],"audio_text":"These seashell ornaments found three hundred miles inland could indicate that ancient desert tribes maintained long-distance trade networks with coastal communities."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Bahasa kehati-hatian ilmiah (academic hedging) di TOEFL selalu menggunakan ''could/may/might indicate'' saat menafsirkan bukti arkeologis.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000893', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat kemungkinan aktivitas rekan saat ini: "Jangan menelepon dulu—dia mungkin masih sedang mewawancarai kandidat itu."', '{"romaji":"/doʊnt kɔːl jet—ʃiː maɪt stɪl biː ˈɪntərvjuːɪŋ ðæt ˈkændɪdeɪt/","tokens":["yet—she","be interviewing","Don''t call","might still","maybe still","that candidate.","interview"],"target_translation":"Jangan menelepon dulu—dia mungkin masih sedang mewawancarai kandidat itu."}'::jsonb, '["Don''t call","yet—she","might still","be interviewing","that candidate."]'::jsonb, NULL, NULL, 'Kemungkinan aksi sedang berlangsung memakai ''might (still) be + V-ing''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000894', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat saran penyebab masalah teknis: "Masalah audio itu mungkin disebabkan oleh izin peramban."', '{"romaji":"/ði ˈɔːdioʊ ˈɪʃuː kʊd biː kɔːzd baɪ ˈbraʊzər pərˈmɪʃənz/","tokens":["permissions.","be caused","The audio","maybe caused","by browser","issue could","could caused"],"target_translation":"Masalah audio itu mungkin disebabkan oleh izin peramban."}'::jsonb, '["The audio","issue could","be caused","by browser","permissions."]'::jsonb, NULL, NULL, 'Gabungan cantik Modal Deduksi + Passive Voice: ''could be caused by...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000895', 'e4100001-0000-4000-8000-000000000109', 'e2000001-0000-4000-8000-000000000027', 'speaking', 'speaking_repeat', 'Ucapkan kalimat antisipasi sopan ini dengan lafal US router (/ˈraʊtər/): "Barangkali perutenya hanya butuh dimulai ulang."', '{"romaji":"/ˈmeɪbiː ðə ˈraʊtər dʒʌst niːdz tə biː ˌriːˈstɑːrtɪd/","display_text":"Maybe the router just needs to be restarted.","phonetic_breakdown":["ˈmeɪ-biː","ðə","ˈraʊ-tər","dʒʌst","niːdz","tə","biː","ˌriː-ˈstɑːr-tɪd"]}'::jsonb, '{"expected_transcript":"Maybe the router just needs to be restarted."}'::jsonb, NULL, NULL, 'Perbedaan ikonik US vs UK di dunia IT: di Amerika ''router'' selalu dibaca /ˈraʊtər/ (seperti ''out''), BUKAN /ˈruːtər/!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000896', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Gunakan proses eliminasi berdasarkan bukti kontradiktif: The delay ___ due to snow—it''s seventy-eight degrees and sunny in Miami!', '{"options":["couldn''t be","must be","should be","might"],"translation":"Penundaan itu tidak mungkin disebabkan oleh salju—suhu di Miami 78°F (25°C) dan cerah!","sentence_template":"The delay [blank] due to snow—it''s seventy-eight degrees and sunny in Miami!"}'::jsonb, '{"selected":"couldn''t be"}'::jsonb, NULL, NULL, 'Bukti cuaca hangat dan cerah di Miami mengeliminasi kemungkinan salju secara mutlak (''couldn''t be'' / ''can''t be'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000897', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Pilih modal ekspektasi wajar (''seharusnya sudah masuk sekarang'') setelah mengirim email: I just hit send ten seconds ago, so the verification link ___ in your inbox any moment now.', '{"options":["should be","can''t be","maybe","mustn''t be"],"translation":"Saya baru saja menekan kirim sepuluh detik lalu, jadi tautan verifikasinya seharusnya sudah masuk ke kotak masuk Anda sebentar lagi.","sentence_template":"I just hit send ten seconds ago, so the verification link [blank] in your inbox any moment now."}'::jsonb, '{"selected":"should be"}'::jsonb, NULL, NULL, '''Should be'' menyatakan ekspektasi wajar ketika prosedur normal telah dijalankan.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000898', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Tarik kesimpulan akhir setelah mengeliminasi dua opsi lainnya: There are only three keys, and it''s not in my pocket or on the desk—so it ___ in my backpack!', '{"options":["must be","can''t be","might not be","shouldn''t"],"translation":"Hanya ada tiga tempat menyimpan kunci, dan tidak ada di saku atau meja—jadi pasti ada di ransel saya!","sentence_template":"There are only three keys, and it''s not in my pocket or on the desk—so it [blank] in my backpack!"}'::jsonb, '{"selected":"must be"}'::jsonb, NULL, NULL, 'Ketika opsi lain sudah gugur, satu-satunya tempat yang tersisa disimpulkan dengan ''must be''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000899', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti laboratorium yang sedang mencari sampel enzim berikut. Mengapa pembicara wanita yakin sampelnya TIDAK ada di lemari pendingin biasa?', '{"options":[{"id":"opt_1","text":"Lemari pendingin biasa sedang terkunci dari luar"},{"id":"opt_2","text":"Tidak mungkin di kulkas biasa karena enzim rusak di atas suhu -20°, sehingga pasti disimpan di freezer suhu ultra-rendah Ruang C"},{"id":"opt_3","text":"Sampel enzim sudah habis dipakai minggu lalu"},{"id":"opt_4","text":"Mereka belum memesan enzim dari pemasok"}],"audio_text":"Where are the enzyme vials? — Well, they can''t be in the regular fridge because they degrade above minus twenty; they must be in the ultra-low freezer in Room C."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Penalaran deduktif dua langkah yang klasik: ''they can''t be in X because..., [so] they must be in Y''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000900', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan asisten dosen menjawab pertanyaan mahasiswa mengenai jadwal pengumuman nilai ini. Kapan nilai kuis diperkirakan keluar?', '{"options":[{"id":"opt_1","text":"Semua nilai mustahil keluar minggu ini"},{"id":"opt_2","text":"Nilai seharusnya sudah tampil di Canvas paling lambat pukul 5 sore ini, meski beberapa ujian susulan mungkin baru selesai besok"},{"id":"opt_3","text":"Nilai sudah ditempel di papan pengumuman kemarin"},{"id":"opt_4","text":"Kuis tersebut tidak jadi dimasukkan ke nilai akhir"}],"audio_text":"Professor Patel finished grading most of the quizzes this morning, so your scores should be visible on Canvas by five p.m., though a few makeup exams might take until tomorrow."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di kampus AS, ''makeup exam'' berarti ujian susulan! Perhatikan kombinasi ''should be visible'' (ekspektasi jam 5) dan ''might take until tomorrow'' (kemungkinan pengecualian).', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000901', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat eliminasi masalah teknis: "Itu tidak mungkin kata sandi yang salah—saya baru saja menyetel ulang kata sandinya."', '{"romaji":"/ɪt kænt biː ðə rɔːŋ ˈpæswɜːrd—aɪ dʒʌst ˌriːˈset ɪt/","tokens":["It can''t","be the","wrong password—I","mustn''t be","resets","just reset","it."],"target_translation":"Itu tidak mungkin kata sandi yang salah—saya baru saja menyetel ulang kata sandinya."}'::jsonb, '["It can''t","be the","wrong password—I","just reset","it."]'::jsonb, NULL, NULL, 'V1, V2, dan V3 dari ''reset'' tetap ''reset'' (bukan ''resetted''!), dan huruf ''w'' pada ''wrong'' bisu (/rɔːŋ/).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000902', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat ekspektasi perjalanan: "Lalu lintas lancar, jadi kita seharusnya tiba di kampus pukul sembilan."', '{"romaji":"/ˈtræfɪk ɪz laɪt, soʊ wiː ʃʊd riːtʃ ˈkæmpəs baɪ naɪn/","tokens":["can''t reach","reach campus","light, so","by nine.","Traffic is","we should","reaches"],"target_translation":"Lalu lintas lancar, jadi kita seharusnya tiba di kampus pukul sembilan."}'::jsonb, '["Traffic is","light, so","we should","reach campus","by nine."]'::jsonb, NULL, NULL, 'Lawan kata ''heavy traffic'' (macet padat) adalah ''light traffic'' (lancar lengang)!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000903', 'e4100001-0000-4000-8000-000000000110', 'e2000001-0000-4000-8000-000000000027', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konfirmasi cepat di rapat daring ini: "Saya baru saja menyegarkan halamannya, jadi seharusnya grafik barunya sudah tampil sekarang."', '{"romaji":"/aɪ dʒʌst rɪˈfreʃt ðə peɪdʒ, soʊ ðə nuː tʃɑːrt ʃʊd ʃoʊ ʌp naʊ/","display_text":"I just refreshed the page, so the new chart should show up now.","phonetic_breakdown":["aɪ","dʒʌst","rɪ-ˈfreʃt","ðə","peɪdʒ","soʊ","ðə","nuː","tʃɑːrt","ʃʊd","ʃoʊ","ʌp","naʊ"]}'::jsonb, '{"expected_transcript":"I just refreshed the page, so the new chart should show up now."}'::jsonb, NULL, NULL, '''Show up'' = muncul tampil di layar / hadir datang.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000904', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Pilih modal deduksi yang menyatakan ketidakmungkinan berdasarkan bukti: That ___ Professor Lin''s car—she sold her sedan last month and bikes to campus every day now.', '{"options":["can''t be","must be","should be","may"],"translation":"Itu tidak mungkin mobil Profesor Lin—beliau sudah menjual sedannya bulan lalu dan sekarang bersepeda ke kampus setiap hari.","sentence_template":"That [blank] Professor Lin''s car—she sold her sedan last month and bikes to campus every day now."}'::jsonb, '{"selected":"can''t be"}'::jsonb, NULL, NULL, 'Bukti bahwa mobilnya sudah dijual membuat klaim tersebut mustahil -> ''can''t be''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000905', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Perhatikan perbedaan ''may be'' vs ''maybe'': Our keynote guest hasn''t checked in yet; her connecting flight from Denver ___ delayed.', '{"options":["may be","maybe","can","mustn''t"],"translation":"Tamu pembicara utama kita belum melapor masuk; penerbangan lanjutannya dari Denver mungkin tertunda.","sentence_template":"Our keynote guest hasn''t checked in yet; her connecting flight from Denver [blank] delayed."}'::jsonb, '{"selected":"may be"}'::jsonb, NULL, NULL, 'Diperlukan kata kerja bantu pasif/predikat setelah subjek ''her connecting flight'' -> ''may be'' (dua kata).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000906', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'reading', 'fill_blank', 'Pilih deduksi kuat positif berdasarkan bukti prestasi: Nadia speaks English, Mandarin, and Spanish effortlessly—she ___ have a real gift for languages!', '{"options":["must","can''t","might not","maybe"],"translation":"Nadia berbicara bahasa Inggris, Mandarin, dan Spanyol dengan begitu lancar—dia pasti punya bakat alami di bidang bahasa!","sentence_template":"Nadia speaks English, Mandarin, and Spanish effortlessly—she [blank] have a real gift for languages!"}'::jsonb, '{"selected":"must"}'::jsonb, NULL, NULL, '''Must + V1 (have)'' menyatakan kesimpulan kuat positif dari bukti nyata.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000907', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan percakapan dua penghuni apartemen ketika mendengar suara bor dari lantai atas berikut. Apa kesimpulan mereka?', '{"options":[{"id":"opt_1","text":"Tetangga lantai empat sedang mengadakan konser musik"},{"id":"opt_2","text":"Berdasarkan pengumuman kemarin, tim teknisi gedung pasti sedang memasang detektor asap baru di lantai empat"},{"id":"opt_3","text":"Suara tersebut berasal dari konstruksi jalan kereta bawah tanah"},{"id":"opt_4","text":"Tidak ada suara apa pun di gedung apartemen"}],"audio_text":"What''s all that drilling noise upstairs? — Management posted a notice yesterday—the maintenance crew must be installing new smoke detectors on the fourth floor."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Bukti pengumuman pengelola gedung kemarin mendukung deduksi ''must be installing...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000908', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'listening', 'listening_choice', 'Dengarkan diskusi dua rekan tim penjualan mengenai klien yang belum menandatangani kontrak ini. Mengapa klien mungkin belum membalas?', '{"options":[{"id":"opt_1","text":"Apex Corp sudah bangkrut minggu lalu"},{"id":"opt_2","text":"Karena Kamis dan Jumat adalah libur Thanksgiving di AS, direktur keuangan mereka mungkin sudah mulai cuti di luar kantor"},{"id":"opt_3","text":"Kontrak pembaruannya belum dikirim oleh tim penjualan"},{"id":"opt_4","text":"Direktur keuangannya menolak menandatangani selamanya"}],"audio_text":"Why hasn''t Apex Corp signed the renewal yet? — Remember Thursday and Friday are Thanksgiving holidays in the US, so their finance director might already be out of office."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Out of office'' (OOO) adalah istilah standar kerja AS saat sedang cuti/libur; ''might already be out of office'' menyampaikan dugaan masuk akal.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000909', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat kemungkinan negatif 50%: "Dia mungkin belum mengetahui tentang perubahan ruangan tersebut."', '{"romaji":"/hiː maɪt nɑːt noʊ əˈbaʊt ðə ruːm tʃeɪndʒ jet/","tokens":["can''t know","not know","He might","room change","maybe not","yet.","about the"],"target_translation":"Dia mungkin belum mengetahui tentang perubahan ruangan tersebut."}'::jsonb, '["He might","not know","about the","room change","yet."]'::jsonb, NULL, NULL, '''Might not know'' = barangkali ia belum tahu (50%).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000910', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat kesimpulan kuat dari bukti jaket basah: "Jaketmu basah kuyup—di luar pasti sedang hujan deras!"', '{"romaji":"/jʊr ˈdʒækɪt ɪz soʊkt—ɪt mʌst biː ˈpɔːrɪŋ ˌaʊtˈsaɪd/","tokens":["can''t be","Your jacket","pouring","must be","outside!","is soaked—it","maybe pouring"],"target_translation":"Jaketmu basah kuyup—di luar pasti sedang hujan deras!"}'::jsonb, '["Your jacket","is soaked—it","must be","pouring","outside!"]'::jsonb, NULL, NULL, 'Kosakata cuaca alami AS: ''soaked'' (basah kuyup) dan ''It''s pouring!'' (hujan turun sangat deras!).', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000911', 'e4100001-0000-4000-8000-000000000111', 'e2000001-0000-4000-8000-000000000027', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pemecahan masalah ini dengan meyakinkan: "Servernya merespons normal, jadi masalahnya pasti ada pada tembolok peramban."', '{"romaji":"/ðə ˈsɜːrvər ɪz rɪˈspɑːndɪŋ faɪn, soʊ ði ˈɪʃuː mʌst biː ðə ˈbraʊzər kæʃ/","display_text":"The server is responding fine, so the issue must be the browser cache.","phonetic_breakdown":["ðə","ˈsɜːr-vər","ɪz","rɪ-ˈspɑːn-dɪŋ","faɪn","soʊ","ði","ˈɪ-ʃuː","mʌst","biː","ðə","ˈbraʊ-zər","kæʃ"]}'::jsonb, '{"expected_transcript":"The server is responding fine, so the issue must be the browser cache."}'::jsonb, NULL, NULL, 'Hati-hati lafal kata IT ''cache'': dibaca persis seperti uang tunai ''cash'' (/kæʃ/), BUKAN ''kache''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000912', 'e4100001-0000-4000-8000-000000000112', NULL, 'reading', 'fill_blank', 'Pilih antara ''said'' dan ''told'' saat diikuti langsung oleh objek orang ''our team'': After the board meeting, the VP ___ our team that the expansion budget was approved.', '{"options":["told","said","spoke","talked"],"translation":"Seusai rapat dewan, VP memberi tahu tim kami bahwa anggaran ekspansi telah disetujui.","sentence_template":"After the board meeting, the VP [blank] our team that the expansion budget was approved."}'::jsonb, '{"selected":"told"}'::jsonb, NULL, NULL, 'Karena diikuti objek penerima pesan (''our team'') tanpa preposisi ''to'', wajib menggunakan ''told'' (''said'' tidak boleh langsung diikuti objek orang).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000913', 'e4100001-0000-4000-8000-000000000112', NULL, 'reading', 'fill_blank', 'Terapkan aturan Backshift untuk ucapan asli ''I will email the contract tonight'' yang dilaporkan keesokan harinya: Yesterday, the vendor said he ___ email the contract that night.', '{"options":["would","will","can","is going"],"translation":"Kemarin, pihak vendor berkata bahwa ia akan mengirimkan kontraknya lewat email malam itu.","sentence_template":"Yesterday, the vendor said he [blank] email the contract that night."}'::jsonb, '{"selected":"would"}'::jsonb, NULL, NULL, 'Kata kerja pelapor lampau (''Yesterday, the vendor said'') menggeser ''will'' menjadi ''would'' (dan ''tonight'' menjadi ''that night'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000914', 'e4100001-0000-4000-8000-000000000112', NULL, 'reading', 'fill_blank', 'Pilih kata kerja pelapor yang tepat saat TIDAK ada objek orang sebelum klausa: During standup, Bagas ___ he was fixing a layout bug on Safari.', '{"options":["said","told","replied us","asked"],"translation":"Saat rapat standup, Bagas berkata bahwa ia sedang memperbaiki bug tata letak di peramban Safari.","sentence_template":"During standup, Bagas [blank] he was fixing a layout bug on Safari."}'::jsonb, '{"selected":"said"}'::jsonb, NULL, NULL, 'Tanpa objek pendengar (''me/us''), gunakan ''said (that)...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000915', 'e4100001-0000-4000-8000-000000000112', NULL, 'listening', 'listening_choice', 'Dengarkan pesan yang diteruskan asisten administrasi kepada dosen berikut. Mengapa Rina tidak bisa hadir di seminar sore kemarin?', '{"options":[{"id":"opt_1","text":"Rina lupa bahwa ada jadwal seminar"},{"id":"opt_2","text":"Rina memberi kabar bahwa ia tidak bisa datang karena kereta komuternya mogok di luar Boston"},{"id":"opt_3","text":"Rina sedang mengikuti konferensi di luar negeri"},{"id":"opt_4","text":"Seminar sore kemarin dibatalkan oleh kampus"}],"audio_text":"Professor, Rina called earlier and said she couldn''t make it to the seminar because her commuter train had broken down outside Boston."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan dua backshift rapi: ''can''t make it'' -> ''couldn''t make it'', dan kejadian mogok sebelumnya -> Past Perfect ''had broken down''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000916', 'e4100001-0000-4000-8000-000000000112', NULL, 'listening', 'listening_choice', 'Dengarkan pembaruan manajer akun setelah berbicara dengan klien utama ini. Apa kabar baik yang disampaikan klien?', '{"options":[{"id":"opt_1","text":"Klien kecewa dengan hasil uji coba dan ingin berhenti berlangganan"},{"id":"opt_2","text":"CTO mereka menyampaikan bahwa mereka sangat puas dengan hasil uji coba (pilot) dan ingin menambah 200 lisensi pengguna lagi"},{"id":"opt_3","text":"Klien meminta rapat ditunda sampai tahun depan"},{"id":"opt_4","text":"Panggilan telepon dengan klien terputus di tengah jalan"}],"audio_text":"I just got off the phone with Horizon Health—their CTO told me they were thrilled with the pilot results and wanted to add two hundred more seats."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dalam bisnis SaaS AS, ''seats'' berarti jumlah kursi lisensi akun pengguna; ''told me they were thrilled... and wanted...'' merangkum pembicaraan telepon tadi.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000917', 'e4100001-0000-4000-8000-000000000112', NULL, 'writing', 'sentence_builder', 'Susun kalimat laporan progres rekan: "Maya berkata bahwa dia sudah menyerahkan laporan akhirnya."', '{"romaji":"/ˈmɑːjə sed ðæt ʃiː hæd ɔːlˈredi səbˈmɪtɪd hɜːr ˈfaɪnəl rɪˈpɔːrt/","tokens":["submitted her","final report.","Maya said","Maya told","has already","that she","had already"],"target_translation":"Maya berkata bahwa dia sudah menyerahkan laporan akhirnya."}'::jsonb, '["Maya said","that she","had already","submitted her","final report."]'::jsonb, NULL, NULL, 'Tanpa objek orang -> ''Maya said that...'', diikuti backshift Present Perfect menjadi Past Perfect (''had already submitted'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000918', 'e4100001-0000-4000-8000-000000000112', NULL, 'writing', 'sentence_builder', 'Susun kalimat penyampaian pesan perekrut: "Perekrut memberi tahu saya bahwa wawancara berikutnya akan berlangsung daring."', '{"romaji":"/ðə rɪˈkruːtər toʊld miː ðə nekst ˈɪntərvjuː wʊd biː ˈɑːnlaɪn/","tokens":["be online.","told me","the next","will","interview would","said me","The recruiter"],"target_translation":"Perekrut memberi tahu saya bahwa wawancara berikutnya akan berlangsung daring."}'::jsonb, '["The recruiter","told me","the next","interview would","be online."]'::jsonb, NULL, NULL, '''Told me (that) ... would be online''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000919', 'e4100001-0000-4000-8000-000000000112', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pelaporan ini dengan lafal tepat said (/sed/): "Dia berkata bahwa dia bisa membagikan draf terbarunya sebelum tengah hari."', '{"romaji":"/hiː sed hiː kʊd ʃer ði ʌpˈdeɪtɪd dræft bɪˈfɔːr nuːn/","display_text":"He said he could share the updated draft before noon.","phonetic_breakdown":["hiː","sed","hiː","kʊd","ʃer","ði","ʌp-ˈdeɪ-tɪd","dræft","bɪ-ˈfɔːr","nuːn"]}'::jsonb, '{"expected_transcript":"He said he could share the updated draft before noon."}'::jsonb, NULL, NULL, 'Pastikan ''said'' diucapkan pendek bersih /sed/ (bukan /seɪd/)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000920', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Kembalikan susunan kata menjadi Subjek + Kata Kerja (tanpa inversi!) untuk melaporkan ''Where is Gate C12?'': A fellow passenger asked me where ___.', '{"options":["Gate C12 was","was Gate C12","is Gate C12","did Gate C12"],"translation":"Seorang sesama penumpang bertanya kepada saya di mana letak Gerbang C12.","sentence_template":"A fellow passenger asked me where [blank]."}'::jsonb, '{"selected":"Gate C12 was"}'::jsonb, NULL, NULL, 'Reported question wajib memakai urutan pernyataan lurus Subjek + Kata Kerja lampau: ''where Gate C12 was'' (bukan ''where was Gate C12'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000921', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Pilih kata hubung yang tepat untuk melaporkan Yes/No Question (''Do you need visa sponsorship?''): On the application form, they asked ___ I required visa sponsorship.', '{"options":["whether","that","what","which"],"translation":"Pada formulir lamaran kerja itu, mereka menanyakan apakah saya memerlukan sponsor visa kerja.","sentence_template":"On the application form, they asked [blank] I required visa sponsorship."}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, 'Melaporkan pertanyaan Ya/Tidak menggunakan ''if'' atau ''whether'' (tidak pernah memakai ''that''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000922', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Hapus kata bantu tanya ''did'' dan leburkan ke kata kerja lampau saat melaporkan ''Why did you choose Boston?'': My academic advisor asked why ___ Boston for grad school.', '{"options":["I had chosen","did I choose","had I chosen","do I choose"],"translation":"Pembimbing akademik saya bertanya mengapa saya memilih Boston untuk kuliah pascasarjana.","sentence_template":"My academic advisor asked why [blank] Boston for grad school."}'::jsonb, '{"selected":"I had chosen"}'::jsonb, NULL, NULL, 'Kata bantu tanya ''did'' dihilangkan dan susunan kembali lurus ke Subjek + Past/Past Perfect (''why I had chosen'' / ''why I chose'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000923', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan cerita kandidat seusai menjalani wawancara kerja dengan panel teknik ini. Pertanyaan teknis apa yang ditanyakan kepadanya?', '{"options":[{"id":"opt_1","text":"Mereka menanyakan hobi olahraga kandidat di akhir pekan"},{"id":"opt_2","text":"Arsitek utama menanyakan bagaimana tim kandidat mencegah pembayaran ganda saat permintaan jaringan kehabisan waktu (timed out)"},{"id":"opt_3","text":"Mereka sama sekali tidak mengajukan pertanyaan teknis"},{"id":"opt_4","text":"Mereka bertanya kapan kandidat ingin mengambil cuti tahunan"}],"audio_text":"How did the technical round go? — Pretty well! The lead architect asked me how our team prevented duplicate payments when network requests timed out."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Pelaporan ''asked me how our team prevented...'' merangkum inti pertanyaan studi kasus sistem dengan sangat rapi.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000924', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan percakapan dengan petugas imigrasi (CBP officer) yang diceritakan ulang oleh mahasiswa baru ini. Dua hal apa yang ditanyakan petugas di bandara?', '{"options":[{"id":"opt_1","text":"Menanyakan resep masakan Indonesia dan harga koper"},{"id":"opt_2","text":"Menanyakan apa jurusan kuliahnya dan apakah ia membawa formulir I-20 yang sudah ditandatangani"},{"id":"opt_3","text":"Meminta mahasiswa membeli tiket kereta di bandara"},{"id":"opt_4","text":"Menanyakan nilai rapor sekolah dasar"}],"audio_text":"At passport control in San Francisco, the officer asked what my major was and whether I was carrying my signed I-20 form."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dokumen ''I-20 form'' adalah dokumen resmi wajib mahasiswa visa F-1 saat mendarat di bandara AS! Perhatikan struktur ''what my major was'' dan ''whether I was carrying...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000925', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan pertanyaan klien: "Klien bertanya kapan versi selulernya akan siap."', '{"romaji":"/ðə ˈklaɪənt æskt wen ðə ˈmoʊbəl ˈvɜːrʒən wʊd biː ˈredi/","tokens":["ready?","be ready.","version would","the mobile","would the","The client","asked when"],"target_translation":"Klien bertanya kapan versi selulernya akan siap."}'::jsonb, '["The client","asked when","the mobile","version would","be ready."]'::jsonb, NULL, NULL, 'Urutan lurus pernyataan ''when [the mobile version] [would be] ready.'' diakhiri tanda titik (bukan tanda tanya!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000926', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan pertanyaan Yes/No: "Dia bertanya kepada saya apakah saya sudah pernah memakai Python sebelumnya."', '{"romaji":"/ʃiː æskt miː ɪf aɪ hæd juːzd ˈpaɪθɑːn bɪˈfɔːr/","tokens":["had I","used Python","before.","I had","that I","She asked","me if"],"target_translation":"Dia bertanya kepada saya apakah saya sudah pernah memakai Python sebelumnya."}'::jsonb, '["She asked","me if","I had","used Python","before."]'::jsonb, NULL, NULL, 'Di American English, bahasa pemrograman ''Python'' melafalkan suku kata kedua dengan vokal terbuka penuh (/ˈpaɪθɑːn/)!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000927', 'e4100001-0000-4000-8000-000000000113', 'e2000001-0000-4000-8000-000000000028', 'speaking', 'speaking_repeat', 'Ucapkan kalimat rangkuman diskusi tim ini dengan lancar: "Tim keuangan ingin mengetahui apakah kuitansinya sudah disetujui."', '{"romaji":"/ˈfaɪnæns ˈwɑːntɪd tə noʊ ˈweðər ðə rɪˈsiːt hæd bɪn əˈpruːvd/","display_text":"Finance wanted to know whether the receipt had been approved.","phonetic_breakdown":["ˈfaɪ-næns","ˈwɑːn-tɪd","tə","noʊ","ˈweð-ər","ðə","rɪ-ˈsiːt","hæd","bɪn","ə-ˈpruːvd"]}'::jsonb, '{"expected_transcript":"Finance wanted to know whether the receipt had been approved."}'::jsonb, NULL, NULL, 'Menggabungkan Reported Question (''wanted to know whether'') + Past Perfect Passive (''had been approved'')!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000928', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Perhatikan posisi kata ''not'' saat melaporkan larangan (''Don''t reboot the server yet!''): The lead engineer told us ___ the server until the backup finished.', '{"options":["not to reboot","to don''t reboot","don''t to reboot","not rebooting"],"translation":"Insinyur utama meminta kami agar jangan memuat ulang server tersebut sampai pencadangan selesai.","sentence_template":"The lead engineer told us [blank] the server until the backup finished."}'::jsonb, '{"selected":"not to reboot"}'::jsonb, NULL, NULL, 'Melaporkan kalimat larangan (''Don''t + V1'') menggunakan pola ''told/asked + objek + not to + V1'' (''not to reboot'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000929', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Pilih pola yang benar setelah ''reminded + objek'': My roommate reminded me ___ my umbrella before walking to the subway.', '{"options":["to grab","grabbing","that grab","for grab"],"translation":"Teman sekamar saya mengingatkan saya untuk membawa payung sebelum berjalan ke stasiun kereta bawah tanah.","sentence_template":"My roommate reminded me [blank] my umbrella before walking to the subway."}'::jsonb, '{"selected":"to grab"}'::jsonb, NULL, NULL, 'Kata kerja pelapor ''remind + seseorang'' diikuti to-infinitive (''reminded me to grab'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000930', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Waspadai kontras ''advise'' (+ objek + to V1) vs ''suggest'': The career counselor ___ Clara to tailor her resume for each job description.', '{"options":["advised","suggested","said","explained"],"translation":"Konselor karier menyarankan Clara agar menyesuaikan resumenya untuk setiap deskripsi pekerjaan.","sentence_template":"The career counselor [blank] Clara to tailor her resume for each job description."}'::jsonb, '{"selected":"advised"}'::jsonb, NULL, NULL, 'Di antara pilihan tersebut, hanya ''advised'' yang sah diikuti ''[objek orang] + to V1'' (''suggested/said/explained'' tidak boleh diikuti ''Clara to tailor''!).', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000931', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan rangkuman hasil konsultasi mahasiswa dengan dokter klinik kampus berikut. Apa dua anjuran dokter kepadanya?', '{"options":[{"id":"opt_1","text":"Dokter menyuruhnya berhenti kuliah selama satu bulan"},{"id":"opt_2","text":"Dokter menyarankannya memakai tetikus ergonomis dan memintanya tidak mengetik lebih dari satu jam tanpa peregangan"},{"id":"opt_3","text":"Dokter mengatakan pergelangan tangannya harus segera dioperasi"},{"id":"opt_4","text":"Dokter menyarankannya membeli laptop yang lebih berat"}],"audio_text":"What did Dr. Evans say about your wrist pain? — She advised me to use an ergonomic mouse and told me not to type for more than an hour without stretching."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Merangkum saran positif (''advised me to use...'') dan larangan (''told me not to type...'') dalam satu kalimat yang sangat bersih.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000932', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan hasil negosiasi dengan pemilik gedung yang dilaporkan manajer kantor ini. Komitmen apa yang disetujui pemilik gedung?', '{"options":[{"id":"opt_1","text":"Pemilik gedung menaikkan biaya sewa sebesar sepuluh persen"},{"id":"opt_2","text":"Pemilik gedung setuju mengganti karpet lobi lama bulan depan tanpa biaya tambahan bagi penyewa"},{"id":"opt_3","text":"Penyewa diminta membeli karpet baru dengan biaya sendiri"},{"id":"opt_4","text":"Renovasi lobi ditolak oleh pengelola gedung"}],"audio_text":"Great news from the building management meeting—the landlord agreed to replace the old lobby carpets next month at no extra cost to us!"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Agreed to replace...'' merangkum kesepakatan langsung tanpa perlu klausa panjang.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000933', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan permintaan sopan klien: "Klien meminta kami mengirimkan faktur terbarunya hari ini."', '{"romaji":"/ðə ˈklaɪənt æskt ʌs tə send ði ʌpˈdeɪtɪd ˈɪnvɔɪs təˈdeɪ/","tokens":["The client","asked us","invoice today.","asked to us","sending","the updated","to send"],"target_translation":"Klien meminta kami mengirimkan faktur terbarunya hari ini."}'::jsonb, '["The client","asked us","to send","the updated","invoice today."]'::jsonb, NULL, NULL, '''Asked us to send...'' (tanpa ''to'' sebelum ''us''!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000934', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan peringatan keselamatan: "Pemandu taman nasional memperingatkan pengunjung agar tidak memberi makan satwa liar."', '{"romaji":"/ðə pɑːrk ˈreɪndʒər wɔːrnd ˈvɪzɪtərz nɑːt tə fiːd ðə ˈwaɪldlaɪf/","tokens":["wildlifes.","to feed","the wildlife.","visitors not","ranger warned","The park","to don''t"],"target_translation":"Pemandu taman nasional memperingatkan pengunjung agar tidak memberi makan satwa liar."}'::jsonb, '["The park","ranger warned","visitors not","to feed","the wildlife."]'::jsonb, NULL, NULL, 'Di taman nasional AS (seperti Yellowstone), petugasnya disebut ''park ranger'', dan ''wildlife'' adalah uncountable noun!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000935', 'e4100001-0000-4000-8000-000000000114', 'e2000001-0000-4000-8000-000000000028', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pelaporan komitmen rekan ini dengan jelas: "Evan menawarkan diri untuk menjemput pembicara tamu di bandara."', '{"romaji":"/ˈevən ˈɔːfərd tə pɪk ʌp ðə ɡest ˈspiːkər æt ði ˈerpɔːrt/","display_text":"Evan offered to pick up the guest speaker at the airport.","phonetic_breakdown":["ˈe-vən","ˈɔː-fərd","tə","pɪk","ʌp","ðə","ɡest","ˈspiː-kər","æt","ði","ˈer-pɔːrt"]}'::jsonb, '{"expected_transcript":"Evan offered to pick up the guest speaker at the airport."}'::jsonb, NULL, NULL, '''Offered to pick up...'' melaporkan tawaran bantuan (''I''ll pick up...'') secara ringkas.', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000936', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Uji susunan kata Reported Question: After the demo, the product director asked how long ___ to build the offline mode.', '{"options":["it would take","would it take","will it take","did it take"],"translation":"Setelah sesi demo, direktur produk bertanya berapa lama waktu yang akan dibutuhkan untuk membangun mode luring.","sentence_template":"After the demo, the product director asked how long [blank] to build the offline mode."}'::jsonb, '{"selected":"it would take"}'::jsonb, NULL, NULL, 'Urutan lurus pernyataan (Subjek ''it'' + backshift ''would take''), tanpa inversi tanya ''would it take''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000937', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Pilih kata kerja pelapor yang tepat sebelum klausa tanpa objek orang: In her email this morning, Laras ___ she had already booked the conference booths.', '{"options":["said","told","reminded","advised"],"translation":"Dalam emailnya pagi ini, Laras berkata bahwa ia sudah memesan stan konferensi tersebut.","sentence_template":"In her email this morning, Laras [blank] she had already booked the conference booths."}'::jsonb, '{"selected":"said"}'::jsonb, NULL, NULL, '''Told'', ''reminded'', dan ''advised'' semuanya wajib diikuti objek orang terlebih dahulu; tanpa objek orang, gunakan ''said''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000938', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'reading', 'fill_blank', 'Pilih pelaporan larangan yang benar: The exam proctor reminded everyone ___ their test booklets before the bell rang.', '{"options":["not to open","don''t open","to not opening","that don''t open"],"translation":"Pengawas ujian mengingatkan semua peserta agar tidak membuka buku soal ujian mereka sebelum bel berbunyi.","sentence_template":"The exam proctor reminded everyone [blank] their test booklets before the bell rang."}'::jsonb, '{"selected":"not to open"}'::jsonb, NULL, NULL, '''Reminded everyone not to open...''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000939', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan mengenai pesan suara dari bagian TI berikut. Apa yang diminta oleh teknisi TI?', '{"options":[{"id":"opt_1","text":"Meminta karyawan membeli baterai laptop sendiri di toko"},{"id":"opt_2","text":"Marcus menelepon dan menanyakan apakah ia bisa membawa laptopnya ke meja bantuan TI lantai empat untuk penggantian baterai"},{"id":"opt_3","text":"Menyuruh karyawan memformat ulang seluruh isi hard disk"},{"id":"opt_4","text":"Memberi tahu bahwa meja bantuan TI tutup hari ini"}],"audio_text":"Did IT call while I was at lunch? — Yes, Marcus called and asked if you could bring your laptop to the fourth-floor help desk so he could replace the battery."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Asked if you could bring... so he could replace...'' meneruskan permintaan teknis dengan sangat akurat.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000940', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'listening', 'listening_choice', 'Dengarkan cerita mahasiswa yang baru saja keluar dari ruangan dosen pembimbing ini. Mengapa dosen meminta ia merevisi bab ketiganya?', '{"options":[{"id":"opt_1","text":"Topik risetnya ditolak total dan harus ganti judul"},{"id":"opt_2","text":"Pertanyaan risetnya kuat, tetapi ukuran sampelnya agak terlalu kecil sehingga dosen mendorongnya menyurvei 20 responden lagi"},{"id":"opt_3","text":"Bab ketiganya sudah sempurna tanpa perlu revisi apa pun"},{"id":"opt_4","text":"Dosen memintanya mengurangi jumlah responden menjadi lima orang"}],"audio_text":"Professor Kim told me my research question was strong, but he said my sample size was a bit too small and encouraged me to survey twenty more participants."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Tiga struktur pelaporan berpadu alami: ''told me [clause]'', ''said [clause]'', dan ''encouraged me to survey...''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000941', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan pertanyaan Yes/No: "Mereka bertanya kepada kami apakah kami membutuhkan penerjemah untuk rapat itu."', '{"romaji":"/ðeɪ æskt ʌs ˈweðər wiː ˈniːdɪd ən ɪnˈtɜːrprətər fɔːr ðæt ˈmiːtɪŋ/","tokens":["an interpreter","for that meeting.","we needed","did we need","us whether","that we","They asked"],"target_translation":"Mereka bertanya kepada kami apakah kami membutuhkan penerjemah untuk rapat itu."}'::jsonb, '["They asked","us whether","we needed","an interpreter","for that meeting."]'::jsonb, NULL, NULL, 'Catatan kosakata profesional: penerjemah LISAN disebut ''interpreter'', sedangkan penerjemah TULISAN disebut ''translator''!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000942', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat pelaporan janji rekan: "Dia berjanji untuk mengirimkan angka anggaran yang telah diperbarui sebelum hari Jumat."', '{"romaji":"/ʃiː ˈprɑːmɪst tə send ði ʌpˈdeɪtɪd ˈbʌdʒɪt ˈfɪɡjərz bɪˈfɔːr ˈfraɪdeɪ/","tokens":["budget figures","sending","She promised","promised me send","to send","the updated","before Friday."],"target_translation":"Dia berjanji untuk mengirimkan angka anggaran yang telah diperbarui sebelum hari Jumat."}'::jsonb, '["She promised","to send","the updated","budget figures","before Friday."]'::jsonb, NULL, NULL, '''Promised + to V1'' (''promised to send'').', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000943', 'e4100001-0000-4000-8000-000000000115', 'e2000001-0000-4000-8000-000000000028', 'speaking', 'speaking_repeat', 'Ucapkan kalimat pelaporan hasil rapat ini dengan jelas: "Manajer kami memberi tahu kami bahwa tenggatnya telah diundur ke minggu depan."', '{"romaji":"/ˈaʊər ˈmænɪdʒər toʊld ʌs ðæt ðə ˈdedlaɪn hæd bɪn pʊʃt tə nekst wiːk/","display_text":"Our manager told us that the deadline had been pushed to next week.","phonetic_breakdown":["ˈaʊ-ər","ˈmæ-nɪ-dʒər","toʊld","ʌs","ðæt","ðə","ˈded-laɪn","hæd","bɪn","pʊʃt","tə","nekst","wiːk"]}'::jsonb, '{"expected_transcript":"Our manager told us that the deadline had been pushed to next week."}'::jsonb, NULL, NULL, '''Told us that...'' + Past Perfect Passive ''had been pushed''!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000944', 'e4100001-0000-4000-8000-000000000116', NULL, 'reading', 'fill_blank', 'Terapkan aturan tanpa inversi kedua untuk pertanyaan langsung ''Where is the international student office?'': Excuse me, could you tell me where ___?', '{"options":["the international student office is","is the international student office","does the international student office","be the international student office"],"translation":"Permisi, bisakah Anda memberi tahu saya di mana letak kantor mahasiswa internasional?","sentence_template":"Excuse me, could you tell me where [blank]?"}'::jsonb, '{"selected":"the international student office is"}'::jsonb, NULL, NULL, 'Setelah pembuka ''could you tell me where'', gunakan urutan lurus Subjek + Kata Kerja (''the international student office is'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000945', 'e4100001-0000-4000-8000-000000000116', NULL, 'reading', 'fill_blank', 'Hapus kata bantu ''does'' dan kembalikan akhiran ''-s'' untuk pertanyaan ''What time does the pharmacy close?'': Do you know what time ___ tonight?', '{"options":["the pharmacy closes","does the pharmacy close","closes the pharmacy","the pharmacy close"],"translation":"Apakah Anda tahu jam berapa apoteknya tutup malam ini?","sentence_template":"Do you know what time [blank] tonight?"}'::jsonb, '{"selected":"the pharmacy closes"}'::jsonb, NULL, NULL, 'Tanpa kata bantu ''does'', subjek tunggal ''the pharmacy'' langsung diikuti Present Simple berakhiran ''-s'' (''closes'').', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000946', 'e4100001-0000-4000-8000-000000000116', NULL, 'reading', 'fill_blank', 'Ingat aturan kata kerja ''explain'' (tidak boleh ''explain me'' tanpa ''to''!): Could you ___ how the tuition installment plan works?', '{"options":["explain to me","explain me","told me","saying"],"translation":"Bisakah Anda menjelaskan kepada saya bagaimana skema cicilan uang kuliah ini bekerja?","sentence_template":"Could you [blank] how the tuition installment plan works?"}'::jsonb, '{"selected":"explain to me"}'::jsonb, NULL, NULL, 'Berbeda dari ''tell me'', kata kerja ''explain'' wajib memakai preposisi ''to'' jika menyebut orang (''explain to me how...'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000947', 'e4100001-0000-4000-8000-000000000116', NULL, 'listening', 'listening_choice', 'Dengarkan pertanyaan pengunjung baru kepada petugas keamanan gedung di Seattle ini. Informasi apa yang sedang ia cari?', '{"options":[{"id":"opt_1","text":"Mencari pintu keluar menuju parkiran bawah tanah"},{"id":"opt_2","text":"Menanyakan lift mana yang naik sampai lantai dua puluh empat"},{"id":"opt_3","text":"Melaporkan bahwa lift gedung sedang macet"},{"id":"opt_4","text":"Menanyakan jam tutup kedai kopi di lobi"}],"audio_text":"Good morning! Could you tell me which elevator goes up to the twenty-fourth floor? The ones over here only go to fifteen."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan di sini ''which elevator'' bertindak sebagai subjek langsung dari ''goes up to...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000948', 'e4100001-0000-4000-8000-000000000116', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan insinyur mengenai kegagalan pengujian otomatis berikut. Apa yang ditanyakan oleh pembicara wanita?', '{"options":[{"id":"opt_1","text":"Mengapa Sam menghapus server staging tadi pagi"},{"id":"opt_2","text":"Apakah Sam punya gambaran mengapa pengujian integrasi gagal di server staging padahal lulus di komputer lokalnya"},{"id":"opt_3","text":"Kapan Sam akan membeli laptop kerja baru"},{"id":"opt_4","text":"Bagaimana cara menginstal sistem operasi dari awal"}],"audio_text":"Hey Sam, do you have any idea why the integration test failed on staging? Everything passed on my local machine ten minutes ago."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perhatikan susunan rapi ''why [the integration test] [failed]'' (bukan ''why did the integration test fail'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000949', 'e4100001-0000-4000-8000-000000000116', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan sopan kepada petugas tiket: "Bisakah Anda memberi tahu saya berapa lama perjalanan keretanya?"', '{"romaji":"/ˈkʊdʒuː tel miː haʊ lɔːŋ ðə treɪn raɪd teɪks/","tokens":["take?","tell me","the train ride","does take?","how long","takes?","Could you"],"target_translation":"Bisakah Anda memberi tahu saya berapa lama perjalanan keretanya?"}'::jsonb, '["Could you","tell me","how long","the train ride","takes?"]'::jsonb, NULL, NULL, '''How long [the train ride] [takes]?'' (subjek tunggal -> ''takes'', dengan tanda tanya milik ''Could you'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000950', 'e4100001-0000-4000-8000-000000000116', NULL, 'writing', 'sentence_builder', 'Susun pertanyaan mencari tahu penyebab perubahan jadwal: "Apakah kamu tahu mengapa rapat umum tadi ditunda?"', '{"romaji":"/də juː noʊ waɪ ðə taʊn hɔːl wʌz poʊstˈpoʊnd/","tokens":["postpone?","the town hall","postponed?","was the","know why","was","Do you"],"target_translation":"Apakah kamu tahu mengapa rapat umum tadi ditunda?"}'::jsonb, '["Do you","know why","the town hall","was","postponed?"]'::jsonb, NULL, NULL, 'Di perusahaan AS, rapat seluruh karyawan disebut ''town hall'' atau ''all-hands meeting''!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000951', 'e4100001-0000-4000-8000-000000000116', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan sopan di meja informasi kampus ini dengan lancar: "Permisi, bisakah Anda memberi tahu saya di mana saya bisa mengambil kartu identitas saya?"', '{"romaji":"/ɪkˈskjuːz miː, ˈkʊdʒuː tel miː wer aɪ kən pɪk ʌp maɪ ˌaɪˈdiː kɑːrd/","display_text":"Excuse me, could you tell me where I can pick up my ID card?","phonetic_breakdown":["ɪk-ˈskjuːz","miː","ˈkʊdʒ-uː","tel","miː","wer","aɪ","kən","pɪk","ʌp","maɪ","ˌaɪ-ˈdiː","kɑːrd"]}'::jsonb, '{"expected_transcript":"Excuse me, could you tell me where I can pick up my ID card?"}'::jsonb, NULL, NULL, 'Urutan lurus ''where I can pick up'' (bukan ''where can I'') adalah ciri khas pembicara B1+ yang terlatih!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000952', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih jembatan yang tepat untuk mengubah Yes/No Question (''Are vegetarian meals available?'') menjadi Indirect Question: Do you know ___ vegetarian meals are available at the conference?', '{"options":["whether","that","what","where"],"translation":"Apakah Anda tahu apakah makanan vegetarian tersedia di konferensi tersebut?","sentence_template":"Do you know [blank] vegetarian meals are available at the conference?"}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, 'Indirect Yes/No question menggunakan penghubung ''if'' atau ''whether'' diikuti subjek + kata kerja.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000953', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih pembuka paling santun dan diplomatis saat meminta kesediaan mentor di LinkedIn (diakhiri tanda titik): Hi Maya, ___ if you might be open to a fifteen-minute informational interview.', '{"options":["I was wondering","Could you tell","Did I wonder","Am wondering"],"translation":"Hai Maya, saya ingin menanyakan apakah kira-kira Anda berkenan meluangkan lima belas menit untuk wawancara informasional.","sentence_template":"Hi Maya, [blank] if you might be open to a fifteen-minute informational interview."}'::jsonb, '{"selected":"I was wondering"}'::jsonb, NULL, NULL, '''I was wondering if...'' adalah standar emas networking profesional di AS untuk meminta waktu seseorang tanpa terkesan memaksa (''informational interview'' = obrolan santai menggali wawasan karier).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000954', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih kata yang sah berpasangan langsung dengan ''or not'': Let''s check the syllabus to see ___ or not laptops are allowed during the midterm.', '{"options":["whether","if","that","which"],"translation":"Mari periksa silabus untuk melihat apakah laptop diperbolehkan atau tidak selama ujian tengah semester.","sentence_template":"Let''s check the syllabus to see [blank] or not laptops are allowed during the midterm."}'::jsonb, '{"selected":"whether"}'::jsonb, NULL, NULL, 'Ketika ''or not'' diletakkan langsung tepat setelah kata hubung (''___ or not''), tata bahasa standar mewajibkan ''whether or not'' (bukan ''if or not'').', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000955', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan mahasiswa yang menghampiri meja dosen seusai kuliah ini. Permintaan halus apa yang ia sampaikan?', '{"options":[{"id":"opt_1","text":"Meminta nilai tambahan tanpa mengerjakan tugas"},{"id":"opt_2","text":"Menanyakan dengan sopan apakah profesor memiliki bacaan rekomendasi mengenai sistem bus raya terpadu (BRT) Jakarta"},{"id":"opt_3","text":"Meminta izin membatalkan mata kuliah transportasi perkotaan"},{"id":"opt_4","text":"Mengundang profesor datang ke Jakarta minggu depan"}],"audio_text":"Hi Professor Alvarez, I really enjoyed today''s lecture on urban transit. I was wondering if you had any recommended readings on Jakarta''s BRT system."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Strategi klasik membangun hubungan akademik di kampus AS: apresiasi spesifik kuliah hari itu, lalu ajukan pertanyaan riset dengan ''I was wondering if...''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000956', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan pesan tindak lanjut perekrut kepada kandidat berikut. Konfirmasi apa yang diminta perekrut?', '{"options":[{"id":"opt_1","text":"Apakah Raka bersedia pindah rumah hari Rabu ini"},{"id":"opt_2","text":"Mengabari paling lambat hari Rabu apakah jadwal Kamis pukul 10.00 pagi Waktu Pasifik cocok untuk wawancara babak akhir"},{"id":"opt_3","text":"Mengirimkan ulang ijazah SMA yang dilegalisasi"},{"id":"opt_4","text":"Membatalkan wawancara babak akhir"}],"audio_text":"Hi Raka, could you let us know by Wednesday whether Thursday at ten a.m. Pacific Time works for your final-round interview?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Could you let us know ... whether [time] works for...'' adalah kalimat penjadwalan paling lazim di email rekrutmen AS.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000957', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun pertanyaan mengecek ketersediaan stopkontak di kafe: "Apakah kamu tahu apakah kedai kopi ini punya banyak stopkontak?"', '{"romaji":"/də juː noʊ ɪf ðɪs kæˈfeɪ hæz ˈplenti ʌv ˈaʊtlets/","tokens":["that this","know if","has plenty","this café","does have","Do you","of outlets?"],"target_translation":"Apakah kamu tahu apakah kedai kopi ini punya banyak stopkontak?"}'::jsonb, '["Do you","know if","this café","has plenty","of outlets?"]'::jsonb, NULL, NULL, 'Urutan lurus ''if [this café] [has]...'' (tunggal ''has'', tanpa ''does'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000958', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat permintaan halus lewat email (akhiri dengan titik): "Saya ingin tahu apakah sekiranya Anda bisa meninjau portofolio saya."', '{"romaji":"/aɪ wʌz ˈwʌndərɪŋ ɪf juː kʊd rɪˈvjuː maɪ pɔːrtˈfoʊlioʊ/","tokens":["portfolio.","portfolio?","could you","wondering if","review my","you could","I was"],"target_translation":"Saya ingin tahu apakah sekiranya Anda bisa meninjau portofolio saya."}'::jsonb, '["I was","wondering if","you could","review my","portfolio."]'::jsonb, NULL, NULL, 'Pernyataan halus ''I was wondering if you could...'' menggunakan urutan S + V dan diakhiri tanda titik.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000959', 'e4100001-0000-4000-8000-000000000117', 'e2000001-0000-4000-8000-000000000029', 'speaking', 'speaking_repeat', 'Ucapkan kalimat konfirmasi jadwal email ini dengan intonasi ramah: "Bisakah Anda mengabari saya apakah hari Selasa pukul dua cocok untuk Anda?"', '{"romaji":"/ˈkʊdʒuː let miː noʊ ˈweðər ˈtuːzdeɪ æt tuː wɜːrks fɔːr juː/","display_text":"Could you let me know whether Tuesday at two works for you?","phonetic_breakdown":["ˈkʊdʒ-uː","let","miː","noʊ","ˈweð-ər","ˈtuːz-deɪ","æt","tuː","wɜːrks","fɔːr","juː"]}'::jsonb, '{"expected_transcript":"Could you let me know whether Tuesday at two works for you?"}'::jsonb, NULL, NULL, 'Ungkapan ''Does Tuesday at two work for you?'' / ''...whether Tuesday at two works for you?'' adalah cara paling natural menyepakati jam rapat di AS!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000960', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Susun klausa setelah ''depends on how much'' tanpa inversi tanya: Our cloud bill depends on how much storage ___ each month.', '{"options":["our app uses","does our app use","uses our app","our app use"],"translation":"Tagihan cloud kita bergantung pada seberapa besar ruang penyimpanan yang digunakan aplikasi kita setiap bulan.","sentence_template":"Our cloud bill depends on how much storage [blank] each month."}'::jsonb, '{"selected":"our app uses"}'::jsonb, NULL, NULL, 'Di dalam noun clause setelah ''depends on how much storage'', gunakan urutan lurus Subjek tunggal (''our app'') + Kata Kerja (''uses'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000961', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih preposisi wajib setelah kata kerja ''depend'': Whether we hold the graduation ceremony outdoors ___ entirely on Sunday''s forecast.', '{"options":["depends","depend","depending","is depend"],"translation":"Apakah kita mengadakan upacara wisuda di luar ruangan atau tidak bergantung sepenuhnya pada prakiraan cuaca hari Minggu.","sentence_template":"Whether we hold the graduation ceremony outdoors [blank] entirely on Sunday''s forecast."}'::jsonb, '{"selected":"depends"}'::jsonb, NULL, NULL, 'Seluruh klausa benda ''Whether we hold...'' di awal kalimat selalu dihitung sebagai SATU kesatuan subjek TUNGGAL, sehingga kata kerjanya memakai ''-s'' (''depends'')!', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000962', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat penekanan pembuka presentasi (''What-clause'' tunggal): What our customers value most ___ transparent pricing with no hidden fees.', '{"options":["is","are","were","be"],"translation":"Hal yang paling dihargai pelanggan kita adalah penetapan harga transparan tanpa biaya tersembunyi.","sentence_template":"What our customers value most [blank] transparent pricing with no hidden fees."}'::jsonb, '{"selected":"is"}'::jsonb, NULL, NULL, 'Klausa ''What our customers value most'' (= satu hal utama) + komplemen tunggal ''transparent pricing'' menggunakan kata kerja tunggal ''is''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000963', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan diskusi pemecahan masalah antara manajer produk dan insinyur berikut. Apa langkah selanjutnya yang mereka sepakati?', '{"options":[{"id":"opt_1","text":"Menghapus aplikasi seluler secara permanen"},{"id":"opt_2","text":"Melihat rekaman sesi interaksi untuk mencari tahu di bagian mana pengguna seluler mengalami kebuntuan"},{"id":"opt_3","text":"Menaikkan harga langganan bulanan"},{"id":"opt_4","text":"Mengganti seluruh warna logo perusahaan"}],"audio_text":"I''m still not sure why mobile users are dropping off on step two—let''s look at the session recordings to figure out where they''re getting stuck."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Dua noun clause berurutan yang sangat alami: ''not sure why mobile users are dropping off'' dan ''figure out where they''re getting stuck''.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000964', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan penjelasan petugas admisi universitas saat sesi tanya jawab daring ini. Berapa lama proses peninjauan berkas pendaftaran?', '{"options":[{"id":"opt_1","text":"Semua berkas selesai diperiksa dalam waktu dua hari"},{"id":"opt_2","text":"Lama peninjauan bergantung pada kapan pelamar mengumpulkan berkas; jalur Early Action diputuskan dalam enam minggu"},{"id":"opt_3","text":"Peninjauan berkas memakan waktu satu tahun penuh"},{"id":"opt_4","text":"Universitas tidak menerima pendaftaran daring"}],"audio_text":"How long the review takes depends on when you submit your application—early action files are decided within six weeks."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Di universitas AS, jalur pendaftaran awal bulan November disebut ''Early Action''; perhatikan noun clause sebagai subjek (''How long the review takes'') maupun objek preposisi (''depends on when you submit'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000965', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat diskusi tim: "Mari kita cari tahu bagaimana kita bisa menyederhanakan alur orientasi ini."', '{"romaji":"/lets ˈfɪɡjər aʊt haʊ wiː kən ˈsɪmplɪfaɪ ðɪs ˈɑːnbɔːrdɪŋ floʊ/","tokens":["out how","Let''s figure","can we","onboarding flow.","simplify this","we can","simplifies"],"target_translation":"Mari kita cari tahu bagaimana kita bisa menyederhanakan alur orientasi ini."}'::jsonb, '["Let''s figure","out how","we can","simplify this","onboarding flow."]'::jsonb, NULL, NULL, '''Let''s figure out how [we can]...'' (bukan ''how can we'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000966', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat klarifikasi jujur saat rapat: "Saya kurang yakin kapan laporan audit akhirnya akan terbit."', '{"romaji":"/aɪm nɑːt ʃʊr wen ðə ˈfaɪnəl ˈɔːdɪt rɪˈpɔːrt wɪl kʌm aʊt/","tokens":["audit report","sure when","I''m not","will the","the final","comes out.","will come out."],"target_translation":"Saya kurang yakin kapan laporan audit akhirnya akan terbit."}'::jsonb, '["I''m not","sure when","the final","audit report","will come out."]'::jsonb, NULL, NULL, 'Catatan penting: berbeda dari klausa waktu (''When it comes out''), di dalam NOUN CLAUSE ketidaktahuan (''I''m not sure when...''), kata ''will'' TETAP DIPAKAI untuk arti masa depan (''when the report will come out'')!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000967', 'e4100001-0000-4000-8000-000000000118', 'e2000001-0000-4000-8000-000000000029', 'speaking', 'speaking_repeat', 'Ucapkan kalimat retoris presentasi yang kuat ini: "Hal terpenting adalah seberapa cepat tim kita belajar dari masukan pengguna."', '{"romaji":"/wʌt ˈmætərz moʊst ɪz haʊ ˈkwɪkli ˈaʊər tiːm lɜːrnz frʌm ˈjuːzər ˈfiːdbæk/","display_text":"What matters most is how quickly our team learns from user feedback.","phonetic_breakdown":["wʌt","ˈmæ-tərz","moʊst","ɪz","haʊ","ˈkwɪk-li","ˈaʊ-ər","tiːm","lɜːrnz","frʌm","ˈjuː-zər","ˈfiːd-bæk"]}'::jsonb, '{"expected_transcript":"What matters most is how quickly our team learns from user feedback."}'::jsonb, NULL, NULL, 'Kalimat penutup presentasi tingkat eksekutif yang memadukan dua noun clause secara elegan!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000968', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih susunan kata yang tepat untuk Indirect Question: Could you tell me how much ___ per semester for grad students?', '{"options":["campus housing costs","does campus housing cost","costs campus housing","is campus housing cost"],"translation":"Bisakah Anda memberi tahu saya berapa biaya tempat tinggal asrama kampus per semester bagi mahasiswa pascasarjana?","sentence_template":"Could you tell me how much [blank] per semester for grad students?"}'::jsonb, '{"selected":"campus housing costs"}'::jsonb, NULL, NULL, 'Hapus ''does'' dan gunakan susunan lurus Subjek tunggal (''campus housing'') + Present Simple (''costs'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000969', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih tanda baca dan susunan yang tepat setelah ''Do you have any idea'': Do you have any idea where ___ the spare HDMI cable?', '{"options":["Kevin put","did Kevin put","puts Kevin","was Kevin putting"],"translation":"Apakah kamu tahu kira-kira di mana Kevin menaruh kabel HDMI cadangannya?","sentence_template":"Do you have any idea where [blank] the spare HDMI cable?"}'::jsonb, '{"selected":"Kevin put"}'::jsonb, NULL, NULL, 'Kata bantu lampau ''did'' dihilangkan dan langsung memakai Subjek + V2 (''where Kevin put'' — V2 dari ''put'' tetap ''put''!).', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000970', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'reading', 'fill_blank', 'Pilih kata kerja tunggal untuk subjek berupa klausa ''Where we open our next branch'': Where we open our next branch ___ on this quarter''s logistics data.', '{"options":["depends","depend","are depending","depending"],"translation":"Di mana kita membuka cabang berikutnya bergantung pada data logistik kuartal ini.","sentence_template":"Where we open our next branch [blank] on this quarter''s logistics data."}'::jsonb, '{"selected":"depends"}'::jsonb, NULL, NULL, 'Subjek berupa satu klausa utuh (''Where we open our next branch'') diperlakukan tunggal -> ''depends''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000971', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan percakapan penumpang di meja layanan pelanggan bandara Chicago O''Hare ini. Apa yang ditanyakan oleh penumpang?', '{"options":[{"id":"opt_1","text":"Meminta pengembalian uang tiket hotel tahun lalu"},{"id":"opt_2","text":"Menanyakan dengan sopan apakah ia sudah otomatis dipindahkan ke penerbangan pukul 17.30 setelah pesawatnya dibatalkan"},{"id":"opt_3","text":"Menanyakan lokasi restoran cepat saji terdekat"},{"id":"opt_4","text":"Membeli tiket kelas bisnis tambahan ke New York"}],"audio_text":"Excuse me, my flight to Denver was just canceled—could you tell me whether I''ve been rebooked on the five-thirty flight automatically?"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Could you tell me whether I''ve been rebooked...'' memadukan Indirect Question dengan Present Perfect Passive.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000972', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'listening', 'listening_choice', 'Dengarkan pesan email lisan dari mahasiswa kepada koordinator laboratorium berikut. Apa tujuan mahasiswa tersebut menghubungi koordinator?', '{"options":[{"id":"opt_1","text":"Melaporkan mikroskop rusak di laboratorium"},{"id":"opt_2","text":"Menanyakan secara halus apakah masih ada kursi kosong di kelas praktikum Rabu siang"},{"id":"opt_3","text":"Mengundurkan diri dari jurusan biologi"},{"id":"opt_4","text":"Melamar pekerjaan penuh waktu sebagai kepala lab"}],"audio_text":"Hi Mr. Carter, I''m enrolled in Bio 202, and I was wondering if there were still any open spots in the Wednesday afternoon lab section."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''I was wondering if there were still any open spots...'' adalah cara paling sopan mengecek ketersediaan kuota kelas.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000973', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun pertanyaan sopan kepada resepsionis gedung: "Apakah Anda tahu apakah ruang konferensi lantai tiga sedang kosong?"', '{"romaji":"/də juː noʊ ɪf ðə θɜːrd flɔːr ˈkɑːnfərəns ruːm ɪz friː/","tokens":["know if","conference room","Do you","is the","is free?","the third-floor","third-floors"],"target_translation":"Apakah Anda tahu apakah ruang konferensi lantai tiga sedang kosong?"}'::jsonb, '["Do you","know if","the third-floor","conference room","is free?"]'::jsonb, NULL, NULL, '''If [the third-floor conference room] [is] free?'' (kata sifat majemuk ''third-floor'' tanpa -s!).', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000974', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'writing', 'sentence_builder', 'Susun pernyataan halus meminta saran buku: "Saya ingin tahu apakah sekiranya Anda bisa merekomendasikan buku persiapan TOEFL yang bagus."', '{"romaji":"/aɪ wʌz ˈwʌndərɪŋ ɪf juː kʊd ˌrekəˈmend ə ɡʊd ˈtoʊfəl prep bʊk/","tokens":["TOEFL prep book.","recommend a good","I was","you could","could you","wondering if","book?"],"target_translation":"Saya ingin tahu apakah sekiranya Anda bisa merekomendasikan buku persiapan TOEFL yang bagus."}'::jsonb, '["I was","wondering if","you could","recommend a good","TOEFL prep book."]'::jsonb, NULL, NULL, '''I was wondering if you could recommend...'' diakhiri tanda titik.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000975', 'e4100001-0000-4000-8000-000000000119', 'e2000001-0000-4000-8000-000000000029', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan halus saat wawancara kerja ini dengan percaya diri: "Bisakah Anda menceritakan kepada saya bagaimana kesuksesan diukur pada peran ini?"', '{"romaji":"/ˈkʊdʒuː tel miː haʊ səkˈses ɪz ˈmeʒərd ɪn ðɪs roʊl/","display_text":"Could you tell me how success is measured in this role?","phonetic_breakdown":["ˈkʊdʒ-uː","tel","miː","haʊ","sək-ˈses","ɪz","ˈmeʒ-ərd","ɪn","ðɪs","roʊl"]}'::jsonb, '{"expected_transcript":"Could you tell me how success is measured in this role?"}'::jsonb, NULL, NULL, 'Salah satu pertanyaan penutup terbaik yang sangat disukai manajer perekrutan di Amerika Serikat!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000976', 'e4100001-0000-4000-8000-000000000120', NULL, 'reading', 'fill_blank', 'Lihat struktur setelah titik-titik (''the freezing wind'' = frasa kata benda tanpa kata kerja!): ___ the freezing wind, hundreds of runners finished the Boston charity race.', '{"options":["Despite","Although","Even though","Despite of"],"translation":"Meskipun angin sangat dingin membeku, ratusan pelari menyelesaikan lomba lari amal Boston tersebut.","sentence_template":"[blank] the freezing wind, hundreds of runners finished the Boston charity race."}'::jsonb, '{"selected":"Despite"}'::jsonb, NULL, NULL, '''The freezing wind'' adalah frasa benda murni tanpa kata kerja -> wajib memakai ''Despite'' (dan ''Despite of'' tidak pernah ada!).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000977', 'e4100001-0000-4000-8000-000000000120', NULL, 'reading', 'fill_blank', 'Sekarang lihat struktur setelah titik-titik (''she had only six months of experience'' = klausa lengkap S + V!): Nadia landed the junior developer role ___ she had only six months of experience.', '{"options":["even though","despite","in spite of","because of"],"translation":"Nadia berhasil mendapatkan posisi pengembang junior itu walaupun ia baru memiliki pengalaman enam bulan.","sentence_template":"Nadia landed the junior developer role [blank] she had only six months of experience."}'::jsonb, '{"selected":"even though"}'::jsonb, NULL, NULL, 'Diikuti subjek ''she'' + kata kerja ''had'', sehingga membutuhkan konjungsi klausa ''even though'' / ''although''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000978', 'e4100001-0000-4000-8000-000000000120', NULL, 'reading', 'fill_blank', 'Hindari jebakan interferensi Bahasa Indonesia (''Walaupun..., tetapi...''): Although the prototype had a few minor UI glitches, ___ the client loved the core workflow.', '{"options":["overall","but","yet however","and but"],"translation":"Meskipun prototipenya memiliki beberapa gangguan kecil antarmuka, secara keseluruhan klien menyukai alur kerja utamanya.","sentence_template":"Although the prototype had a few minor UI glitches, [blank] the client loved the core workflow."}'::jsonb, '{"selected":"overall"}'::jsonb, NULL, NULL, 'Karena kalimat sudah dibuka oleh ''Although'', dilarang keras menambahkan konjungsi ''but'' di klausa kedua; kata keterangan ''overall'' masuk dengan mulus.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000979', 'e4100001-0000-4000-8000-000000000120', NULL, 'listening', 'listening_choice', 'Dengarkan rangkuman laporan bisnis kuartalan berikut. Bagaimana kinerja divisi perangkat keras di tengah gangguan rantai pasok?', '{"options":[{"id":"opt_1","text":"Pendapatan divisi perangkat keras anjlok dua belas persen akibat kelangkaan cip"},{"id":"opt_2","text":"Meskipun terjadi kelangkaan cip global di awal tahun, divisi perangkat keras melampaui target pendapatannya sebesar 12%"},{"id":"opt_3","text":"Divisi perangkat keras ditutup sementara sepanjang tahun ini"},{"id":"opt_4","text":"Tidak ada kelangkaan komponen sama sekali tahun ini"}],"audio_text":"In spite of global chip shortages earlier this year, our hardware division exceeded its revenue target by twelve percent."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''In spite of global chip shortages'' (3 kata dengan ''of'' + Noun Phrase) mengontraskan kendala eksternal dengan capaian positif.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000980', 'e4100001-0000-4000-8000-000000000120', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dua mahasiswa seusai mencoba kafe baru dekat kampus ini. Apa pendapat pembicara pria tentang kafe tersebut?', '{"options":[{"id":"opt_1","text":"Wi-Fi-nya lambat namun kopinya sangat murah"},{"id":"opt_2","text":"Wi-Fi-nya sangat cepat dan kursinya nyaman, namun harga espressonya agak kemahalan"},{"id":"opt_3","text":"Kafenya tutup saat ia tiba di sana"},{"id":"opt_4","text":"Semua menu di kafe tersebut sempurna dan murah"}],"audio_text":"How was the new study café on Fifth Street? — The Wi-Fi was super fast and the armchairs were cozy. The espresso was a bit overpriced, though."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Penggunaan ''..., though'' di ujung kalimat lisan AS memberi catatan kontras halus (''tapi agak kemahalan sih'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000981', 'e4100001-0000-4000-8000-000000000120', NULL, 'writing', 'sentence_builder', 'Susun kalimat ketekunan belajar dengan Despite + V-ing: "Meskipun bekerja penuh waktu, dia menyelesaikan gelar magisternya tepat waktu."', '{"romaji":"/dɪˈspaɪt ˈwɜːrkɪŋ ˈfʊl taɪm, hiː kəmˈpliːtɪd hɪz ˈmæstərz dɪˈɡriː ɑːn taɪm/","tokens":["Although working","Despite of","full-time,","degree on time.","Despite working","his master''s","he completed"],"target_translation":"Meskipun bekerja penuh waktu, dia menyelesaikan gelar magisternya tepat waktu."}'::jsonb, '["Despite working","full-time,","he completed","his master''s","degree on time."]'::jsonb, NULL, NULL, 'Setelah preposisi ''Despite'', kata kerja langsung berbentuk Gerund (''Despite working full-time'').', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000982', 'e4100001-0000-4000-8000-000000000120', NULL, 'writing', 'sentence_builder', 'Susun kalimat kontras klausa lengkap: "Walaupun jadwalnya padat, tim kami tetap menjaga kualitas tinggi."', '{"romaji":"/ˈiːvən ðoʊ ðə ˈskedʒuːl wʌz taɪt, ˈaʊər tiːm meɪnˈteɪnd haɪ ˈkwɑːləti/","tokens":["was tight,","the schedule","Even though","but our","high quality.","our team maintained","Despite the schedule was"],"target_translation":"Walaupun jadwalnya padat, tim kami tetap menjaga kualitas tinggi."}'::jsonb, '["Even though","the schedule","was tight,","our team maintained","high quality."]'::jsonb, NULL, NULL, 'Ejaan dan pelafalan US ''schedule'' (/ˈskedʒuːl/ — diawali bunyi /sk/!), tanpa kata ''but'' di klausa kedua!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000983', 'e4100001-0000-4000-8000-000000000120', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat akademik setara TOEFL Speaking ini dengan jelas: "Meskipun menghadapi keterbatasan anggaran di awal, proyek tersebut berhasil diluncurkan."', '{"romaji":"/dɪˈspaɪt ɪˈnɪʃəl ˈbʌdʒɪt kənˈstreɪnts, ðə ˈprɑːdʒekt lɔːntʃt səkˈsesfəli/","display_text":"Despite initial budget constraints, the project launched successfully.","phonetic_breakdown":["dɪ-ˈspaɪt","ɪ-ˈnɪ-ʃəl","ˈbʌdʒ-ɪt","kən-ˈstreɪnts","ðə","ˈprɑː-dʒekt","lɔːntʃt","sək-ˈses-fə-li"]}'::jsonb, '{"expected_transcript":"Despite initial budget constraints, the project launched successfully."}'::jsonb, NULL, NULL, 'Kolokasi akademik bernilai tinggi untuk esai & presentasi: ''initial budget constraints'' (keterbatasan anggaran awal)!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000984', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Cek struktur setelah titik-titik (''severe turbulence over the Rockies'' = frasa kata benda!): The captain turned on the seatbelt sign ___ severe turbulence over the Rockies.', '{"options":["due to","because","since","although"],"translation":"Kapten menyalakan lampu tanda sabuk pengaman dikarenakan guncangan udara hebat di atas Pegunungan Rocky.","sentence_template":"The captain turned on the seatbelt sign [blank] severe turbulence over the Rockies."}'::jsonb, '{"selected":"due to"}'::jsonb, NULL, NULL, '''Severe turbulence over the Rockies'' adalah frasa kata benda tanpa kata kerja klausa -> wajib memakai ''due to'' atau ''because of''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000985', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih frasa penyebab yang bernuansa apresiasi POSITIF atas hasil yang menggembirakan: ___ generous alumni donations, the university opened a free food pantry for students.', '{"options":["Thanks to","Despite","Although","Even though"],"translation":"Berkat donasi alumni yang dermawan, universitas membuka ruang penyedia bahan pangan gratis bagi mahasiswa.","sentence_template":"[blank] generous alumni donations, the university opened a free food pantry for students."}'::jsonb, '{"selected":"Thanks to"}'::jsonb, NULL, NULL, '''Thanks to + Noun Phrase'' tepat digunakan untuk penyebab yang membuahkan hasil baik.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000986', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih konjungsi klausa (''Karena...'') saat diikuti Subjek + Kata Kerja (''the main auditorium is fully booked''): ___ the main auditorium is fully booked, Friday''s guest lecture will take place on Zoom.', '{"options":["Since","Due to","Because of","Despite"],"translation":"Karena auditorium utama sudah penuh dipesan, kuliah tamu hari Jumat akan diselenggarakan di Zoom.","sentence_template":"[blank] the main auditorium is fully booked, Friday''s guest lecture will take place on Zoom."}'::jsonb, '{"selected":"Since"}'::jsonb, NULL, NULL, 'Diikuti klausa lengkap ''the main auditorium is fully booked'', sehingga wajib memakai konjungsi ''Since'' (= Because), bukan preposisi ''Due to / Because of''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000987', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah sejarah lingkungan AS ala TOEFL berikut. Apa penyebab utama bencana badai debu ''Dust Bowl'' pada tahun 1930-an?', '{"options":[{"id":"opt_1","text":"Dikarenakan banjir bandang dari sungai besar"},{"id":"opt_2","text":"Terutama dikarenakan kekeringan berkepanjangan bertahun-tahun yang diperparah praktik pembajakan tanah dalam secara agresif"},{"id":"opt_3","text":"Dikarenakan letusan gunung berapi di pantai barat"},{"id":"opt_4","text":"Dikarenakan pembangunan gedung pencakar langit"}],"audio_text":"In the 1930s, massive dust storms swept across the Great Plains largely due to years of prolonged drought combined with aggressive deep-plowing farming practices."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Largely due to [Noun Phrase 1] combined with [Noun Phrase 2]'' adalah struktur penjelasan kausalitas khas buku teks universitas AS.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000988', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan pembaruan manajer operasional toko daring ini. Apa dampak dari penambahan metode pembayaran dompet digital?', '{"options":[{"id":"opt_1","text":"Pembelian lewat ponsel turun delapan belas persen"},{"id":"opt_2","text":"Akibatnya, tingkat pembatalan keranjang belanja di ponsel pintar turun sebesar 18%"},{"id":"opt_3","text":"Pelanggan tidak bisa lagi membayar dengan kartu kredit"},{"id":"opt_4","text":"Biaya pengiriman barang naik dua kali lipat"}],"audio_text":"Last month we added one-click mobile wallet checkout; as a result, cart abandonment on smartphones dropped by eighteen percent."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Transisi ''; as a result,'' menghubungkan tindakan produk dengan metrik dampak bisnis secara jernih.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000989', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat pengumuman pembatalan acara luar ruang: "Konser luar ruangan itu ditunda dikarenakan kualitas udara yang buruk."', '{"romaji":"/ði ˈaʊtdɔːr ˈkɑːnsərt wʌz poʊstˈpoʊnd duː tə pʊr er ˈkwɑːləti/","tokens":["air quality.","although","because poor","The outdoor","concert was","postponed due","to poor"],"target_translation":"Konser luar ruangan itu ditunda dikarenakan kualitas udara yang buruk."}'::jsonb, '["The outdoor","concert was","postponed due","to poor","air quality."]'::jsonb, NULL, NULL, '''Due to + Noun Phrase (poor air quality)''.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000990', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat kausalitas bersih tanpa kata so ganda: "Karena semua anggota berada di zona waktu berbeda, kami merekam setiap rapat."', '{"romaji":"/bɪˈkɔːz ˈevriwʌn ɪz ɪn ˈdɪfərənt taɪm zoʊnz, wiː rɪˈkɔːrd ˈevri ˈmiːtɪŋ/","tokens":["is in","different time","Because everyone","record every meeting.","Because of","so we","zones, we"],"target_translation":"Karena semua anggota berada di zona waktu berbeda, kami merekam setiap rapat."}'::jsonb, '["Because everyone","is in","different time","zones, we","record every meeting."]'::jsonb, NULL, NULL, 'Perhatikan pergeseran tekanan kata: kata kerja ''record'' ditekan di belakang (/rɪˈkɔːrd/), sedangkan kata benda ''a record'' ditekan di depan (/ˈrekərd/)!', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000991', 'e4100001-0000-4000-8000-000000000121', 'e2000001-0000-4000-8000-000000000030', 'speaking', 'speaking_repeat', 'Ucapkan kalimat apresiasi tim ini dengan jelas: "Berkat dokumentasi Anda yang jelas, peserta magang baru kami dapat beradaptasi hanya dalam dua hari."', '{"romaji":"/θæŋks tə jʊr klɪr ˌdɑːkjəmenˈteɪʃən, ˈaʊər nuː ˈɪntɜːrnz ræmpt ʌp ɪn tuː deɪz/","display_text":"Thanks to your clear documentation, our new interns ramped up in two days.","phonetic_breakdown":["θæŋks","tə","jʊr","klɪr","ˌdɑːk-jə-men-ˈteɪ-ʃən","ˈaʊ-ər","nuː","ˈɪn-tɜːrnz","ræmpt","ʌp","ɪn","tuː","deɪz"]}'::jsonb, '{"expected_transcript":"Thanks to your clear documentation, our new interns ramped up in two days."}'::jsonb, NULL, NULL, 'Phrasal verb dunia kerja teknologi AS: ''ramp up'' = mulai produktif dan menguasai alur kerja baru!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000992', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih penghubung kontras perbandingan langsung di tengah satu kalimat setelah koma: Undergraduate programs focus on broad foundations, ___ doctoral programs emphasize original research.', '{"options":["whereas","however","despite","therefore"],"translation":"Program sarjana S1 berfokus pada fondasi luas, sedangkan program doktoral S3 menekankan riset orisinal.","sentence_template":"Undergraduate programs focus on broad foundations, [blank] doctoral programs emphasize original research."}'::jsonb, '{"selected":"whereas"}'::jsonb, NULL, NULL, 'Untuk menyambung dua klausa kontras dengan satu koma di tengah kalimat (tanpa titik koma), gunakan konjungsi ''whereas'' atau ''while'' (''however'' butuh '';'' sebelumnya!).', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000993', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Perhatikan tanda baca titik koma (;) di depan dan koma (,) di belakang untuk menambahkan argumen pendukung kedua: Remote internships remove relocation costs; ___, they allow companies to recruit talent nationwide.', '{"options":["moreover","whereas","although","because of"],"translation":"Magang jarak jauh menghapus biaya pindah tempat tinggal; terlebih lagi, sistem itu memungkinkan perusahaan merekrut talenta dari seluruh penjuru negeri.","sentence_template":"Remote internships remove relocation costs; [blank], they allow companies to recruit talent nationwide."}'::jsonb, '{"selected":"moreover"}'::jsonb, NULL, NULL, 'Kedua gagasan bersifat searah saling menguatkan + diapit ''; ___,'', sehingga tepat menggunakan ''moreover''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000994', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih transisi kontras setelah titik koma (;): The new battery prototype holds twice as much charge; ___, it is still too expensive for mass production.', '{"options":["however","therefore","moreover","due to"],"translation":"Prototipe baterai baru itu menyimpan daya dua kali lebih besar; namun demikian, biayanya masih terlalu mahal untuk produksi massal.","sentence_template":"The new battery prototype holds twice as much charge; [blank], it is still too expensive for mass production."}'::jsonb, '{"selected":"however"}'::jsonb, NULL, NULL, 'Kelebihan kapasitas dikontraskan dengan kendala harga mahal menggunakan ''; however,''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000995', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan rangkuman dosen sosiologi yang membandingkan dua survei angkatan kerja berikut. Apa perbedaan utama antara responden Generasi Z dan pekerja senior dalam studi tersebut?', '{"options":[{"id":"opt_1","text":"Kedua kelompok sama-sama hanya mementingkan lokasi parkir gratis"},{"id":"opt_2","text":"Karyawan senior menempatkan tunjangan pensiun di urutan pertama, sedangkan lulusan baru kuliah memprioritaskan bimbingan mentor dan fleksibilitas jadwal"},{"id":"opt_3","text":"Lulusan baru kuliah tidak peduli pada bimbingan mentor"},{"id":"opt_4","text":"Studi tersebut hanya mewawancarai lima orang mahasiswa"}],"audio_text":"According to the national workplace study, senior employees ranked retirement benefits first, whereas recent college graduates prioritized mentorship and schedule flexibility."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kata ''whereas'' menandai titik balik perbandingan antara dua kelompok subjek di soal TOEFL Listening!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000996', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan kesimpulan akhir manajer produk pada rapat tinjauan kuartalan ini. Apa rekomendasi langkah selanjutnya?', '{"options":[{"id":"opt_1","text":"Menghentikan eksperimen karena tiket keluhan pelanggan melonjak"},{"id":"opt_2","text":"Secara keseluruhan aktivasi naik 14% tanpa kenaikan tiket bantuan; oleh karena itu, tim merekomendasikan peluncuran ke seluruh pengguna Senin depan"},{"id":"opt_3","text":"Menunda peluncuran selama enam bulan lagi"},{"id":"opt_4","text":"Membatasi fitur hanya untuk sepuluh pengguna internal"}],"audio_text":"Overall, our self-serve onboarding experiment boosted activation by fourteen percent with zero increase in support tickets; therefore, we recommend rolling it out to all users next Monday."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Phrasal verb produk AS ''roll out [a feature]'' = meluncurkan/menggelar fitur secara bertahap atau menyeluruh!', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000997', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat perbandingan iklim dua kota AS: "Musim dingin di Chicago membeku, sedangkan musim dingin di Miami hangat."', '{"romaji":"/ˈwɪntərz ɪn ʃɪˈkɑːɡoʊ ɑːr ˈfriːzɪŋ, werˈæz ˈwɪntərz ɪn maɪˈæmi ɑːr maɪld/","tokens":["Chicago are","winters in","Winters in","however winters","despite","Miami are mild.","freezing, whereas"],"target_translation":"Musim dingin di Chicago membeku, sedangkan musim dingin di Miami hangat sejuk."}'::jsonb, '["Winters in","Chicago are","freezing, whereas","winters in","Miami are mild."]'::jsonb, NULL, NULL, 'Perhatikan ''Chicago'' melafalkan ''ch'' sebagai bunyi /ʃ/ (''syikago'': /ʃɪˈkɑːɡoʊ/)!', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000998', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat sebab-akibat formal dengan therefore: "Sampelnya terkontaminasi; oleh karena itu, kami mengulangi percobaan tersebut."', '{"romaji":"/ðə ˈsæmpəl wʌz kənˈtæmɪneɪtɪd; ˈðerfɔːr, wiː rɪˈpiːtɪd ði ɪkˈsperɪmənt/","tokens":["therefore, we","repeated","was contaminated;","because therefore","the experiment.","repeats","The sample"],"target_translation":"Sampelnya terkontaminasi; oleh karena itu, kami mengulangi percobaan tersebut."}'::jsonb, '["The sample","was contaminated;","therefore, we","repeated","the experiment."]'::jsonb, NULL, NULL, 'Tanda titik koma sebelum ''therefore,'' diikuti klausa akibat yang mandiri.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000000999', 'e4100001-0000-4000-8000-000000000122', 'e2000001-0000-4000-8000-000000000030', 'speaking', 'speaking_repeat', 'Ucapkan kalimat penutup argumen yang sangat rapi ini: "Solusi tersebut memang membutuhkan investasi awal; namun demikian, itu menghemat biaya dalam jangka panjang."', '{"romaji":"/ðə səˈluːʃən rɪˈkwaɪərz ˌʌpˈfrʌnt ɪnˈvestmənt; haʊˈevər, ɪt seɪvz ˈmʌni ɪn ðə lɔːŋ rʌn/","display_text":"The solution requires upfront investment; however, it saves money in the long run.","phonetic_breakdown":["ðə","sə-ˈluː-ʃən","rɪ-ˈkwaɪ-ərz","ˌʌp-ˈfrʌnt","ɪn-ˈvest-mənt","haʊ-ˈev-ər","ɪt","seɪvz","ˈmʌ-ni","ɪn","ðə","lɔːŋ","rʌn"]}'::jsonb, '{"expected_transcript":"The solution requires upfront investment; however, it saves money in the long run."}'::jsonb, NULL, NULL, 'Kosakata bisnis AS penting: ''upfront investment / upfront cost'' = biaya modal di muka!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001000', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Uji ketelitian ''although'' vs ''despite'': ___ having jet lag from a twenty-hour flight, Raka delivered a sharp presentation at the Austin summit.', '{"options":["Despite","Although","Even though","Because"],"translation":"Meskipun mengalami jet lag dari penerbangan dua puluh jam, Raka membawakan presentasi yang tajam di konferensi Austin.","sentence_template":"[blank] having jet lag from a twenty-hour flight, Raka delivered a sharp presentation at the Austin summit."}'::jsonb, '{"selected":"Despite"}'::jsonb, NULL, NULL, 'Diikuti Gerund phrase (''having jet lag...''), bukan klausa S + Verb, sehingga wajib memakai preposisi ''Despite'' (atau ''In spite of'').', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001001', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih antara ''because'', ''due to'', dan ''whereas'': All evening classes were shifted online ___ an unexpected water main break near campus.', '{"options":["due to","because","since","although"],"translation":"Seluruh kelas malam dialihkan menjadi daring dikarenakan pecahnya pipa induk air secara tak terduga di dekat kampus.","sentence_template":"All evening classes were shifted online [blank] an unexpected water main break near campus."}'::jsonb, '{"selected":"due to"}'::jsonb, NULL, NULL, '''An unexpected water main break near campus'' adalah frasa benda murni -> gunakan ''due to''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001002', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'reading', 'fill_blank', 'Pilih konjungsi klausa kontras yang tepat sebelum Subjek + Kata Kerja (''the dataset was relatively small''): ___ the dataset was relatively small, the model achieved ninety-two percent accuracy.', '{"options":["Although","Despite","In spite of","Due to"],"translation":"Meskipun kumpulan datanya relatif kecil, model tersebut mencapai akurasi sembilan puluh dua persen.","sentence_template":"[blank] the dataset was relatively small, the model achieved ninety-two percent accuracy."}'::jsonb, '{"selected":"Although"}'::jsonb, NULL, NULL, 'Diikuti klausa lengkap ''the dataset was relatively small'' -> wajib memakai ''Although'' / ''Even though''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001003', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah ekologi hutan ala TOEFL berikut. Mengapa beberapa spesies pohon pinus justru membutuhkan kebakaran hutan alami berskala kecil?', '{"options":[{"id":"opt_1","text":"Semua pohon pinus musnah selamanya jika terkena udara hangat"},{"id":"opt_2","text":"Walaupun kebakaran hutan sering dipandang merusak semata, runjung pinus tertentu tertutup resin dan justru hanya melepaskan bijinya berkat panas tinggi"},{"id":"opt_3","text":"Pohon pinus hanya bisa tumbuh di rawa berair dingin"},{"id":"opt_4","text":"Manusia harus menanam setiap biji pinus secara manual"}],"audio_text":"Although forest fires are often viewed purely as destructive events, certain pine cones are sealed with resin and only release their seeds thanks to intense heat."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Perpaduan indah gaya akademik TOEFL: ''Although [passive clause], ... thanks to intense heat''!', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001004', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'listening', 'listening_choice', 'Dengarkan evaluasi direktur teknik atas proyek migrasi basis data selama enam bulan ini. Apa kesimpulan akhirnya?', '{"options":[{"id":"opt_1","text":"Migrasi basis data gagal dan anggaran membengkak"},{"id":"opt_2","text":"Meskipun sempat ada beberapa penarikan ulang di bulan kedua, migrasi cloud tuntas di bawah anggaran; oleh karena itu, mereka siap berekspansi ke pasar Asia di Q1"},{"id":"opt_3","text":"Ekspansi ke pasar Asia ditunda tanpa batas waktu"},{"id":"opt_4","text":"Seluruh server dikembalikan ke pusat data lokal lama"}],"audio_text":"Despite a few weekend rollbacks in month two, our engineering team completed the cloud migration under budget; therefore, we''re ready to scale to Asian markets in Q1."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Under budget'' = lebih hemat dari pagu anggaran! Kalimat ini menggabungkan ''Despite [Noun]'', Past Simple, dan ''; therefore,''.', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001005', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat kontras dengan jembatan despite the fact that: "Dia menerima tawaran kerja itu terlepas dari kenyataan bahwa gajinya sedikit lebih rendah."', '{"romaji":"/ʃiː əkˈseptɪd ði ˈɔːfər dɪˈspaɪt ðə fækt ðæt ðə peɪ wʌz ˈslaɪtli ˈloʊər/","tokens":["fact that","the offer","although the fact","despite that","the pay was slightly lower.","despite the","She accepted"],"target_translation":"Dia menerima tawaran kerja itu meskipun kenyataannya gajinya sedikit lebih rendah."}'::jsonb, '["She accepted","the offer","despite the","fact that","the pay was slightly lower."]'::jsonb, NULL, NULL, '''Despite the fact that + [S + V]'' memungkinkan ''despite'' diikuti klausa utuh secara formal.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001006', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat perbandingan dua moda transportasi: "Kereta api berangkat dari pusat kota, sedangkan bandara berada jauh di luar kota."', '{"romaji":"/treɪnz dɪˈpɑːrt frʌm ˈdaʊntaʊn, werˈæz ˈerpɔːrts ɑːr fɑːr ˌaʊtˈsaɪd ðə ˈsɪti/","tokens":["from downtown,","outside the city.","departs","Trains depart","however airports","whereas airports","are far"],"target_translation":"Kereta api berangkat dari pusat kota, sedangkan bandara berada jauh di luar kota."}'::jsonb, '["Trains depart","from downtown,","whereas airports","are far","outside the city."]'::jsonb, NULL, NULL, 'Kontras dua fakta seimbang dihubungkan dengan '', whereas ...''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001007', 'e4100001-0000-4000-8000-000000000123', 'e2000001-0000-4000-8000-000000000030', 'speaking', 'speaking_repeat', 'Ucapkan kalimat kelulusan tingkat menengah CEFR B1 ini dengan lantang dan bangga: "Berkat latihan yang konsisten, saya siap menghadapi diskusi akademik dan kerja global!"', '{"romaji":"/θæŋks tə kənˈsɪstənt ˈpræktɪs, aɪm ˈredi fɔːr ˌækəˈdemɪk ænd ˈɡloʊbəl ˈwɜːrkpleɪs dɪˈskʌʃənz/","display_text":"Thanks to consistent practice, I''m ready for academic and global workplace discussions!","phonetic_breakdown":["θæŋks","tə","kən-ˈsɪs-tənt","ˈpræk-tɪs","aɪm","ˈre-di","fɔːr","ˌæ-kə-ˈde-mɪk","ænd","ˈɡloʊ-bəl","ˈwɜːrk-pleɪs","dɪ-ˈskʌ-ʃənz"]}'::jsonb, '{"expected_transcript":"Thanks to consistent practice, I''m ready for academic and global workplace discussions!"}'::jsonb, NULL, NULL, 'Luar biasa! Kamu telah menuntaskan seluruh 10 Unit CEFR B1 dan siap menghadapi Simulasi Ujian Kesiapan B1!', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001008', 'e4100001-0000-4000-8000-000000000124', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat email profesional berikut: Please find ___ the Q3 financial summary for your review.', '{"options":["attached","attaching","attach","attachment"],"translation":"Terlampir ringkasan keuangan Kuartal 3 untuk Anda tinjau.","sentence_template":"Please find [blank] the Q3 financial summary for your review."}'::jsonb, '{"selected":"attached"}'::jsonb, NULL, NULL, 'Frasa baku email bisnis internasional adalah ''Please find attached + [nama dokumen]''.', 1, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001009', 'e4100001-0000-4000-8000-000000000124', NULL, 'reading', 'fill_blank', 'Pilih bentuk First Conditional yang tepat dalam negosiasi tenggat proyek: If the client approves the wireframe today, our engineers ___ coding tomorrow morning.', '{"options":["will start","would start","started","starts"],"translation":"Jika klien menyetujui kerangka desain hari ini, para insinyur kami akan mulai memprogram besok pagi.","sentence_template":"If the client approves the wireframe today, our engineers [blank] coding tomorrow morning."}'::jsonb, '{"selected":"will start"}'::jsonb, NULL, NULL, 'First Conditional untuk kemungkinan nyata di masa depan menggunakan ''If + Present Simple, Subject + will + V1''.', 2, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001010', 'e4100001-0000-4000-8000-000000000124', NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif lampau untuk laporan insiden teknis: Fortunately, the database outage ___ within twenty minutes by the DevOps team.', '{"options":["was resolved","resolved","were resolved","has resolving"],"translation":"Untungnya, gangguan basis data tersebut berhasil diselesaikan dalam dua puluh menit oleh tim DevOps.","sentence_template":"Fortunately, the database outage [blank] within twenty minutes by the DevOps team."}'::jsonb, '{"selected":"was resolved"}'::jsonb, NULL, NULL, 'Subjek tunggal (''the database outage'') yang dikenai tindakan di masa lampau membutuhkan ''was + V3 (resolved)''.', 3, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001011', 'e4100001-0000-4000-8000-000000000124', NULL, 'reading', 'fill_blank', 'Pilih ungkapan transisi kontras yang tepat dalam diskusi akademik: Online courses offer great flexibility; ___, many students still prefer in-person lab discussions.', '{"options":["however","therefore","moreover","for instance"],"translation":"Kelas daring menawarkan fleksibilitas tinggi; namun demikian, banyak mahasiswa tetap memilih diskusi lab tatap muka.","sentence_template":"Online courses offer great flexibility; [blank], many students still prefer in-person lab discussions."}'::jsonb, '{"selected":"however"}'::jsonb, NULL, NULL, '''However'' digunakan setelah titik koma (;) dan diikuti koma untuk mempertentangkan dua gagasan secara akademik.', 4, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001012', 'e4100001-0000-4000-8000-000000000124', NULL, 'listening', 'listening_choice', 'Dengarkan jawaban kandidat saat wawancara kerja berikut. Apa pencapaian terukur yang ditonjolkan kandidat?', '{"options":[{"id":"opt_1","text":"Mengelola tim beranggotakan dua puluh lima desainer baru"},{"id":"opt_2","text":"Merancang ulang alur onboarding hingga meningkatkan retensi pengguna sebesar 25% dalam enam bulan"},{"id":"opt_3","text":"Memangkas anggaran iklan perusahaan hingga setengahnya dalam setahun"},{"id":"opt_4","text":"Membuka kantor cabang baru di tiga kota besar Amerika Serikat"}],"audio_text":"In my previous role as a growth analyst, I redesigned our onboarding funnel, which increased user retention by twenty-five percent in six months."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Jawaban wawancara kerja bergaya AS yang kuat selalu menyertakan metrik hasil nyata (''increased user retention by 25%'').', 5, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001013', 'e4100001-0000-4000-8000-000000000124', NULL, 'listening', 'listening_choice', 'Dengarkan diskusi mahasiswa dengan dosen saat Office Hours ini. Mengapa mahasiswa meminta saran dosen?', '{"options":[{"id":"opt_1","text":"Ia belum memiliki topik sama sekali untuk tugas akhirnya"},{"id":"opt_2","text":"Ia kesulitan menemukan data jurnal ilmiah terverifikasi dari kawasan Asia Tenggara"},{"id":"opt_3","text":"Ia ingin pindah ke kelas mata kuliah pilihan yang lain"},{"id":"opt_4","text":"Ia kehilangan akses ke akun perpustakaan digital kampus"}],"audio_text":"Professor Lin, I narrowed my research topic down to urban solar grids, but I''m struggling to find peer-reviewed data from Southeast Asia."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '''Struggling to find peer-reviewed data from Southeast Asia'' menunjukkan kendala spesifik sumber literatur ilmiah.', 6, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001014', 'e4100001-0000-4000-8000-000000000124', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan kuliah biologi lingkungan setara TOEFL Listening berikut. Apa fungsi utama hutan bakau (mangrove) yang dijelaskan pembicara?', '{"options":[{"id":"opt_1","text":"Menyediakan kayu keras untuk industri konstruksi perkapalan"},{"id":"opt_2","text":"Menurunkan suhu air laut di wilayah kutub utara"},{"id":"opt_3","text":"Menyerap energi gelombang badai tropis dan mencegah erosi garis pantai yang parah"},{"id":"opt_4","text":"Mengubah air laut menjadi air tawar siap minum bagi penduduk kota"}],"audio_text":"Coastal mangroves act as a natural buffer zone; their dense root systems absorb wave energy during tropical storms and prevent severe shoreline erosion."}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Poin inti kuliah terdapat pada ''absorb wave energy during tropical storms and prevent severe shoreline erosion''.', 7, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001015', 'e4100001-0000-4000-8000-000000000124', NULL, 'listening', 'listening_choice', 'Dengarkan rangkuman presentasi data kuartalan ini. Tren apa yang terjadi pada langganan paket tahunan?', '{"options":[{"id":"opt_1","text":"Langganan paket bulanan dan tahunan sama-sama turun tajam"},{"id":"opt_2","text":"Langganan paket bulanan stabil, sedangkan pendaftaran paket tahunan melonjak 40% setelah kampanye Oktober"},{"id":"opt_3","text":"Kampanye bulan Oktober dibatalkan karena kendala anggaran"},{"id":"opt_4","text":"Seluruh pelanggan beralih ke paket uji coba gratis"}],"audio_text":"As shown in the bar chart on slide four, monthly subscriptions remained flat, whereas annual plan sign-ups surged by forty percent after our October campaign."}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Kata kerja data ''remained flat'' (mendatar/stabil) dikontraskan dengan ''surged by forty percent'' (melonjak 40%).', 8, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001016', 'e4100001-0000-4000-8000-000000000124', NULL, 'writing', 'sentence_builder', 'Susun kalimat penyampaian pendapat yang santun saat rapat: "Saya paham maksud Anda, namun kita perlu mempertimbangkan biayanya."', '{"romaji":"/aɪ siː jʊr pɔɪnt, bʌt wiː niːd tə kənˈsɪdər ðə kɔːst/","tokens":["but we","the cost.","considering","I see","your point,","points,","need to consider"],"target_translation":"Saya paham maksud Anda, namun kita perlu mempertimbangkan biayanya."}'::jsonb, '["I see","your point,","but we","need to consider","the cost."]'::jsonb, NULL, NULL, '''I see your point, but...'' adalah strategi diplomatis di budaya kerja AS untuk berbeda pendapat tanpa terdengar konfrontatif.', 9, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001017', 'e4100001-0000-4000-8000-000000000124', NULL, 'writing', 'sentence_builder', 'Susun kalimat laporan solusi teknis: "Kami mengatasi bug tersebut dengan memperbarui pengaturan tembolok server."', '{"romaji":"/wiː rɪˈzɑːlvd ðə bʌɡ baɪ ʌpˈdeɪtɪŋ ðə ˈsɜːrvər kæʃ ˈsetɪŋz/","tokens":["for update","by updating","the bug","cache settings.","resolved by","We resolved","the server"],"target_translation":"Kami mengatasi bug tersebut dengan memperbarui pengaturan tembolok server."}'::jsonb, '["We resolved","the bug","by updating","the server","cache settings."]'::jsonb, NULL, NULL, 'Pola ''by + verb-ing'' (''by updating'') menjelaskan metode atau cara penyelesaian masalah teknis.', 10, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001018', 'e4100001-0000-4000-8000-000000000124', NULL, 'writing', 'sentence_builder', 'Susun kalimat Second Conditional untuk saran strategis: "Seandainya saya menjadi Anda, saya akan menyoroti proyek kepemimpinan itu."', '{"romaji":"/ɪf aɪ wɜːr juː, aɪ wʊd ˈhaɪlaɪt ðæt ˈliːdərʃɪp ˈprɑːdʒekt/","tokens":["If I","I would","were you,","leadership project.","highlight that","was you,","will highlight"],"target_translation":"Seandainya saya menjadi Anda, saya akan menyoroti proyek kepemimpinan itu."}'::jsonb, '["If I","were you,","I would","highlight that","leadership project."]'::jsonb, NULL, NULL, 'Dalam bahasa Inggris standar & TOEFL, pengandaian ''If I were you'' selalu memakai subjunctive ''were'' (bukan ''was'').', 11, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001019', 'e4100001-0000-4000-8000-000000000124', NULL, 'writing', 'sentence_builder', 'Susun kalimat pembuka rangkuman grafik: "Grafik garis ini menggambarkan pertumbuhan pengguna aktif selama lima tahun."', '{"romaji":"/ðɪs laɪn ɡræf ˈɪləstreɪts ðə ɡroʊθ ʌv ˈæktɪv ˈjuːzərz ˈoʊvər faɪv jɪrz/","tokens":["the growth of","illustrates","illustrate","over five years.","active users","since five years.","This line graph"],"target_translation":"Grafik garis ini menggambarkan pertumbuhan pengguna aktif selama lima tahun."}'::jsonb, '["This line graph","illustrates","the growth of","active users","over five years."]'::jsonb, NULL, NULL, 'Subjek tunggal ''This line graph'' diikuti kata kerja akademik ''illustrates'' + rentang tren ''over five years''.', 12, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001020', 'e4100001-0000-4000-8000-000000000124', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pembaruan Daily Standup ini dengan ritme profesional: "Kemarin saya menyelesaikan desain API, dan hari ini saya sedang menulis pengujian unit."', '{"romaji":"/ˈjestərdeɪ aɪ kəmˈpliːtɪd ðə ˌeɪpiːˈaɪ dɪˈzaɪn, ænd təˈdeɪ aɪm ˈraɪtɪŋ ˈjuːnɪt tests/","display_text":"Yesterday I completed the API design, and today I''m writing unit tests.","phonetic_breakdown":["ˈjes-tər-deɪ","aɪ","kəm-ˈpliː-tɪd","ðə","ˌeɪ-piː-ˈaɪ","dɪ-ˈzaɪn","ænd","tə-ˈdeɪ","aɪm","ˈraɪ-tɪŋ","ˈjuː-nɪt","tests"]}'::jsonb, '{"expected_transcript":"Yesterday I completed the API design, and today I''m writing unit tests."}'::jsonb, NULL, NULL, 'Kontraskan Past Simple (''completed'') untuk pekerjaan kemarin dengan Present Continuous (''I''m writing'') untuk fokus hari ini.', 13, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001021', 'e4100001-0000-4000-8000-000000000124', NULL, 'speaking', 'speaking_repeat', 'Tirukan kalimat pembuka wawancara kerja berikut: "Saya memiliki pengalaman tiga tahun dalam membangun aplikasi web berskala besar."', '{"romaji":"/aɪ hæv θriː jɪrz ʌv ɪkˈspɪriəns ˈbɪldɪŋ ˈskeɪləbəl web ˌæplɪˈkeɪʃənz/","display_text":"I have three years of experience building scalable web applications.","phonetic_breakdown":["aɪ","hæv","θriː","jɪrz","ʌv","ɪk-ˈspɪr-i-əns","ˈbɪl-dɪŋ","ˈskeɪ-lə-bəl","web","ˌæp-lɪ-ˈkeɪ-ʃənz"]}'::jsonb, '{"expected_transcript":"I have three years of experience building scalable web applications."}'::jsonb, NULL, NULL, 'Pola natural wawancara AS adalah ''have [X] years of experience + verb-ing'' (tanpa preposisi ''in'' juga sangat lazim dan luwes).', 14, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001022', 'e4100001-0000-4000-8000-000000000124', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat diskusi akademik saat Office Hours ini: "Bolehkah saya meminta masukan Anda mengenai kerangka esai saya?"', '{"romaji":"/kʊd aɪ ɡet jʊr ˈfiːdbæk ɑːn maɪ ˈeseɪ ˈaʊtlaɪn, prəˈfesər/","display_text":"Could I get your feedback on my essay outline, Professor?","phonetic_breakdown":["kʊd","aɪ","ɡet","jʊr","ˈfiːd-bæk","ɑːn","maɪ","ˈe-seɪ","ˈaʊt-laɪn","prə-ˈfe-sər"]}'::jsonb, '{"expected_transcript":"Could I get your feedback on my essay outline, Professor?"}'::jsonb, NULL, NULL, 'Ingat bahwa ''feedback'' adalah uncountable noun—jangan pernah mengucapkan ''feedbacks''!', 15, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4200001-0000-4000-8000-000000001023', 'e4100001-0000-4000-8000-000000000124', NULL, 'speaking', 'speaking_repeat', 'Tirukan simpulan presentasi data berikut: "Secara keseluruhan, pendapatan kuartalan kita tumbuh delapan belas persen dibandingkan tahun lalu."', '{"romaji":"/ˌoʊvərˈɔːl, ˈaʊər ˈkwɔːrtərli ˈrevənuː ɡruː baɪ eɪˈtiːn pərˈsent jɪr ˈoʊvər jɪr/","display_text":"Overall, our quarterly revenue grew by eighteen percent year over year.","phonetic_breakdown":["ˌoʊ-vər-ˈɔːl","ˈaʊ-ər","ˈkwɔːr-tər-li","ˈre-və-nuː","ɡruː","baɪ","eɪ-ˈtiːn","pər-ˈsent","jɪr","ˈoʊ-vər","jɪr"]}'::jsonb, '{"expected_transcript":"Overall, our quarterly revenue grew by eighteen percent year over year."}'::jsonb, NULL, NULL, 'Dalam aksen Amerika, ''revenue'' dilafalkan /ˈrevənuː/ (bukan /ˈrevənjuː/), dan ''year over year'' adalah istilah bisnis standar AS.', 16, '2026-11-27T00:00:00+00:00') ON CONFLICT ("id") DO UPDATE SET "lesson_id" = EXCLUDED."lesson_id", "grammar_point_id" = EXCLUDED."grammar_point_id", "skill_pillar" = EXCLUDED."skill_pillar", "exercise_type" = EXCLUDED."exercise_type", "prompt" = EXCLUDED."prompt", "content" = EXCLUDED."content", "correct_answer" = EXCLUDED."correct_answer", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index";
